pub const testing = if (builtin.is_test) struct {
    pub const RetirementProjection = struct {
        connection_generation: u64,
        admission: AdmissionLifecycle,
        retirement: RetirementLifecycle,
        placeholder_generation: u64,
    };

    pub fn retirementProjection(slot: *ClientSlot) RetirementProjection {
        if (!slot.valid()) @panic("invalid ClientSlot retirement projection");
        return .{
            .connection_generation = slot.current.connection_generation,
            .admission = slot.current.admission_lifecycle,
            .retirement = slot.current.retirement_lifecycle,
            .placeholder_generation = slot.current.placeholder_generation,
        };
    }

    /// R3가 제품 reclaim owner를 제공하기 전 R2c fixture만 published old node를 정산한다.
    pub fn reclaimPublishedRetiredForTest(slot: *ClientSlot) void {
        var reclaim: PreparedRetiredClientReclaim = .{};
        slot.prepareRetiredClientReclaim(&reclaim) catch
            @panic("R2c retired fixture was not reclaimable");
        slot.commitRetiredClientReclaimNoFail(&reclaim);
    }

    pub fn prepareDetachedCleanupForReplacementForTest(
        slot: *ClientSlot,
        admission: *PreparedAdmissionClose,
        cleanup: *PreparedRetirementCleanup,
    ) !void {
        return prepareDetachedCleanupForGenerationForTest(slot, 1, 2, admission, cleanup);
    }

    pub fn prepareDetachedCleanupForGenerationForTest(
        slot: *ClientSlot,
        connection_generation: u64,
        placeholder_generation: u64,
        admission: *PreparedAdmissionClose,
        cleanup: *PreparedRetirementCleanup,
    ) !void {
        try slot.prepareAdmissionClose(connection_generation, admission);
        try slot.commitAdmissionClose(admission);
        try slot.prepareRetirementCleanup(admission, placeholder_generation, cleanup);
        try slot.preflightRetirementCleanup(admission, cleanup, placeholder_generation);
        try slot.preflightRetirementDetach(admission, connection_generation, placeholder_generation);
        slot.commitRetirementCleanupNoFail(admission, cleanup, placeholder_generation);
        slot.commitRetirementDetachNoFail(admission, connection_generation, placeholder_generation);
        try slot.finishRetirementCleanup(cleanup);
    }

    pub fn publishReplacementForGenerationForTest(
        slot: *ClientSlot,
        connection_generation: u64,
        placeholder_generation: u64,
        source: *client_mod.Client,
    ) !void {
        var admission: PreparedAdmissionClose = .{};
        var cleanup: PreparedRetirementCleanup = .{};
        try prepareDetachedCleanupForGenerationForTest(
            slot,
            connection_generation,
            placeholder_generation,
            &admission,
            &cleanup,
        );
        var replacement: PreparedClientReplacement = .{};
        try slot.prepareClientReplacement(&cleanup, source, &replacement);
        var prepared = true;
        defer if (prepared) slot.abortClientReplacement(&replacement) catch
            @panic("replacement fixture abort failed");
        slot.publishClientReplacementNoFail(&replacement);
        prepared = false;
    }

    pub fn enterExternalMode(slot: *ClientSlot) !void {
        if (!slot.valid()) return error.InvalidOwner;
        var allocator_scope: client_mod.Client.GenerationAllocatorScope = .{};
        const guard = &slot.current.guarded_allocator;
        const scope_ranges = [_]GenerationGuardedAllocator.OperationRangeInput{.{
            .start = @intFromPtr(&allocator_scope),
            .len = @sizeOf(client_mod.Client.GenerationAllocatorScope),
        }};
        if (!guard.beginOperationGuard(&scope_ranges)) return error.Busy;
        defer guard.endOperationGuard();
        try slot.current.client.beginGenerationAllocatorScope(
            guard.allocator(),
            .attachment_batch,
            &allocator_scope,
        );
        defer slot.current.client.restoreGenerationAllocatorScope(&allocator_scope) catch
            @panic("CR3b R2b external-mode test allocator scope drifted");
        try client_mod.retirement_cleanup_testing_api.enterExternalMode(&slot.current.client);
    }

    pub fn rpcDecoderCallbackActive() bool {
        return rpc_decoder_callback_active;
    }

    pub const AttachmentLease = lease_mod.ConnectionLease;
    pub const EventReleaseSourceSnapshot = struct {
        pin_count: usize,
        blocker_count: usize,
        quarantine_occupied: usize,
        quarantine_retained_bytes: usize,
    };
    pub const ForkRejectedClientProjection = struct {
        slot_self_addr: usize,
        slot_pid: u32,
        slot_incarnation: u64,
        node_incarnation: u64,
        slot_lifecycle_raw: u8,
        fd: std.c.fd_t,
        unusable: bool,
        first_reason_present: bool,
        first_reason_raw: u8,
        outbound_addr: usize,
        outbound_len: usize,
        outbound_offset: usize,
        outbound_stream_id: u64,
        outbound_byte_len: u8,
        outbound_bytes: [64]u8,
        pin_count: usize,
        pin_active_cleanup: u1,
        registry_live_count: usize,
        registry_blocker_count: usize,
        quarantine_occupied: usize,
        quarantine_retained_bytes: usize,
        global_generation: u64,
        callback_count: u64,
    };

    /// fork 뒤 PID 봉인이 불일치한 상태에서도 key 조회·lock·authority mint 없이 변경 0만 비교한다.
    pub fn forkRejectedClientProjection(slot: *const ClientSlot) ForkRejectedClientProjection {
        const node = slot.current;
        const client = &node.client;
        var result: ForkRejectedClientProjection = .{
            .slot_self_addr = slot.self_addr,
            .slot_pid = slot.pid,
            .slot_incarnation = slot.incarnation.tagged,
            .node_incarnation = node.incarnation.tagged,
            .slot_lifecycle_raw = @intFromEnum(slot.lifecycle),
            .fd = client.fd,
            .unusable = client.unusable,
            .first_reason_present = client.first_poison_reason != null,
            .first_reason_raw = if (client.first_poison_reason) |reason| @intCast(@intFromEnum(reason)) else 0,
            .outbound_addr = 0,
            .outbound_len = 0,
            .outbound_offset = 0,
            .outbound_stream_id = 0,
            .outbound_byte_len = 0,
            .outbound_bytes = [_]u8{0} ** 64,
            .pin_count = node.pin_owner.cleanup_pin_count,
            .pin_active_cleanup = node.pin_owner.active_cleanup,
            .registry_live_count = node.cleanup_registry.live_count,
            .registry_blocker_count = node.cleanup_registry.connection_ordering_blocker_count,
            .quarantine_occupied = if (generation_event_quarantine_registry) |*registry| registry.occupied_slots else 0,
            .quarantine_retained_bytes = if (generation_event_quarantine_registry) |*registry| registry.retained_bytes else 0,
            .global_generation = generation_response_incarnation_issuer.load(.acquire),
            .callback_count = pending_event_payload_callback_count,
        };
        if (client.pending_outbound) |outbound| {
            result.outbound_addr = @intFromPtr(outbound.frame.ptr);
            result.outbound_len = outbound.frame.len;
            result.outbound_offset = outbound.offset;
            result.outbound_stream_id = outbound.stream_id;
            result.outbound_byte_len = @intCast(@min(outbound.frame.len, result.outbound_bytes.len));
            @memcpy(result.outbound_bytes[0..result.outbound_byte_len], outbound.frame[0..result.outbound_byte_len]);
        }
        return result;
    }

    pub fn eventReleaseSourceSnapshot(slot: *ClientSlot) !EventReleaseSourceSnapshot {
        const quarantine = &(generation_event_quarantine_registry orelse return error.InvalidOwner);
        const snapshot = try quarantine.snapshot(currentPid(), @intCast(std.Thread.getCurrentId()));
        return .{
            .pin_count = slot.current.pin_owner.cleanup_pin_count,
            .blocker_count = try slot.current.cleanup_registry.connectionOrderingBlockerCount(),
            .quarantine_occupied = snapshot.occupied_slots,
            .quarantine_retained_bytes = snapshot.retained_bytes,
        };
    }

    pub fn takeEventReleasePostSnapshot() ?EventReleasePostSnapshot {
        const snapshot = event_release_post_snapshot;
        event_release_post_snapshot = null;
        return snapshot;
    }

    pub fn pendingEventPayloadCallbackCount() u64 {
        return pending_event_payload_callback_count;
    }

    pub fn armEventReleaseProofLossMarker(fd: std.c.fd_t, stage_raw: u8) void {
        if (event_release_proof_loss_marker_fd != null) @panic("event release proof-loss marker replayed");
        event_release_proof_loss_marker_fd = fd;
        event_release_death_stage_raw = stage_raw;
    }

    pub fn armTerminalDrainProofLoss(fd: std.c.fd_t, stage_raw: u8, callback_ordinal: u32) void {
        if (terminal_drain_test_hook.stage != .none or callback_ordinal == 0)
            @panic("terminal drain proof-loss hook replayed");
        if (event_release_proof_loss_marker_fd != null)
            @panic("terminal drain proof-loss marker replayed");
        event_release_proof_loss_marker_fd = fd;
        terminal_drain_test_hook = switch (stage_raw) {
            1 => .{ .stage = .pre_callback, .target_ordinal = callback_ordinal },
            2 => .{ .stage = .post_callback, .target_ordinal = callback_ordinal },
            3 => .{},
            else => @panic("terminal drain proof-loss stage is invalid"),
        };
    }

    pub fn rollbackGenerationEventPreparationPending(
        identity: GenerationEventIdentity,
        owner_addr: usize,
    ) GenerationEventError!void {
        return rollbackGenerationEventPreparationPendingForTest(identity, owner_addr);
    }

    pub fn armPreparationProjectionReentry(
        context: *anyopaque,
        callback: *const fn (*anyopaque, GenerationEventPreparationProjection) void,
    ) void {
        if (preparation_projection_test_hook.armed) @panic("preparation projection hook replayed");
        preparation_projection_test_hook = .{
            .context = context,
            .callback = callback,
            .armed = true,
        };
    }
} else struct {};

/// fork한 픽스처 자식을 거둘 때 쓰는 폴링 상한(1ms poll × 이 횟수 ≈ 벽시계 60초 이상).
///
/// **왜 이렇게 큰가**: fail-stop을 증명하는 픽스처의 자식은 **패닉으로 죽고**, Zig 패닉 핸들러는 이 거대한
/// 테스트 바이너리의 DWARF를 읽어 스택 트레이스를 심볼라이즈한다 — 그게 초 단위다. 실측: 로컬(한가한
/// M-계열) 1.5초, CI 러너 2.3~2.7초. 옛 상한 2000(≈2.3초)은 CI 실측치와 겹쳐 **여유가 0**이었고,
/// 2.70초가 걸린 런에서 만료돼 간헐 실패했다(2026-08-08 file explorer 잡).
///
/// 상한은 "자식이 걸렸을 때 CI를 영원히 붙잡지 않는다"는 목적만 하면 되므로 크게 잡는 값이 옳다 —
/// 자식이 정상적으로 죽으면 루프는 즉시 빠져나가므로 큰 값에 드는 비용은 0이다.
const fixture_child_wait_attempts: usize = 60_000;

test "CR3a-2c2b3b quarantine leaf participates in the session-host gate" {
    _ = ended_purge_quarantine;
}

test "CR3a-2c2b3b process runtime bootstrap is explicit and same-process idempotent" {
    try ClientSlot.initializeProcessRuntime();
    try ClientSlot.initializeProcessRuntime();
}

test "CR3a-2c2b3b fork child rejects bootstrap before inherited issuer mutex" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const ChildCleanup = struct {
        fn terminateAndReap(child_pid: std.c.pid_t) void {
            _ = std.c.kill(child_pid, std.c.SIG.KILL);
            var child_status: c_int = 0;
            while (true) {
                const waited = std.c.waitpid(child_pid, &child_status, 0);
                if (waited == child_pid or
                    (waited < 0 and std.posix.errno(waited) == .CHILD)) return;
                if (waited < 0 and std.posix.errno(waited) == .INTR) continue;
                return;
            }
        }
    };
    try ClientSlot.initializeProcessRuntime();
    while (!issuer_mutex.tryLock()) std.atomic.spinLoopHint();
    const child = std.c.fork();
    if (child < 0) {
        issuer_mutex.unlock();
        return error.TestUnexpectedResult;
    }
    if (child == 0) {
        ClientSlot.initializeProcessRuntime() catch |err|
            std.c._exit(if (err == error.ProcessDomainMismatch) 0 else 2);
        std.c._exit(3);
    }
    defer issuer_mutex.unlock();

    var status: c_int = 0;
    var attempts: usize = 0;
    while (attempts < fixture_child_wait_attempts) : (attempts += 1) {
        const waited = std.c.waitpid(child, &status, std.c.W.NOHANG);
        if (waited == child) {
            const wait_status: u32 = @bitCast(status);
            try std.testing.expect(std.c.W.IFEXITED(wait_status));
            try std.testing.expectEqual(@as(u8, 0), std.c.W.EXITSTATUS(wait_status));
            return;
        }
        if (waited < 0) {
            if (std.posix.errno(waited) == .INTR) continue;
            ChildCleanup.terminateAndReap(child);
            return error.TestUnexpectedResult;
        }
        var delay_fd = std.c.pollfd{ .fd = -1, .events = 0, .revents = 0 };
        _ = std.c.poll(@ptrCast(&delay_fd), 0, 1);
    }
    ChildCleanup.terminateAndReap(child);
    return error.TestUnexpectedResult;
}

fn rawRangesOverlap(a_start: usize, a_end: usize, b_start: usize, b_end: usize) bool {
    return a_start < b_end and b_start < a_end;
}

pub const Lifecycle = enum {
    live,
    deinit_reserved,
    dead,
};

