fn terminalDrainIdentitySealInput(
    continuation: *const TerminalDrainContinuation,
) process_seal_service.TerminalDrainIdentitySealInput {
    const identity = continuation.identity;
    return .{
        .self_addr = identity.self_addr,
        .thread_id = identity.thread_id,
        .node_addr = identity.node_addr,
        .node_incarnation = identity.node_incarnation,
        .registry_incarnation = identity.registry_incarnation,
        .handoff_identity_seal = identity.handoff_identity_seal,
        .handoff_state_seal = identity.handoff_state_seal,
        .handoff_state_generation = identity.handoff_state_generation,
        .row_slot = identity.row_slot,
        .row_kind_raw = identity.row_kind_raw,
        .row_generation = identity.row_generation,
        .accounting_client_addr = identity.accounting_client_addr,
        .accounting_transfer_id = identity.accounting_transfer_id,
        .accounting_byte_count = identity.accounting_byte_count,
        .payload_addr = identity.payload_addr,
        .payload_len = identity.payload_len,
        .allocator_ptr = identity.allocator_ptr,
        .allocator_vtable = identity.allocator_vtable,
        .callback_ordinal = identity.callback_ordinal,
    };
}

fn terminalDrainStateSealInput(
    continuation: *const TerminalDrainContinuation,
) process_seal_service.TerminalDrainStateSealInput {
    return .{
        .self_addr = continuation.identity.self_addr,
        .lifecycle_raw = continuation.state.lifecycle_raw,
        .state_generation = continuation.state.state_generation,
        .identity_seal = continuation.state.identity_seal,
    };
}

fn terminalDrainContinuationCurrent(
    continuation: *const TerminalDrainContinuation,
    expected: terminal_contract.TerminalDrainLifecycle,
    expected_generation: u64,
) bool {
    if (continuation.identity.self_addr != @intFromPtr(continuation) or
        continuation.identity.pid != currentPid() or
        continuation.identity.thread_id != @as(u64, @intCast(std.Thread.getCurrentId())) or
        continuation.identity.node_addr == 0 or continuation.identity.node_incarnation == 0 or
        continuation.identity.registry_incarnation == 0 or continuation.identity.row_generation == 0 or
        continuation.identity.accounting_client_addr == 0 or continuation.identity.accounting_transfer_id == 0 or
        continuation.identity.accounting_byte_count == 0 or continuation.identity.callback_ordinal == 0 or
        continuation.state.lifecycle_raw != @intFromEnum(expected) or
        continuation.state.state_generation != expected_generation) return false;
    const kind: terminal_contract.TerminalRowKind = switch (continuation.identity.row_kind_raw) {
        @intFromEnum(terminal_contract.TerminalRowKind.surviving_descriptor) => .surviving_descriptor,
        @intFromEnum(terminal_contract.TerminalRowKind.quarantined_no_free) => .quarantined_no_free,
        else => return false,
    };
    if (kind != continuation.descriptor.kind or continuation.descriptor.row_generation != continuation.identity.row_generation or
        continuation.descriptor.accounting.client_addr != continuation.identity.accounting_client_addr or
        continuation.descriptor.accounting.transfer_id != continuation.identity.accounting_transfer_id or
        continuation.descriptor.accounting.byte_count != continuation.identity.accounting_byte_count) return false;
    const expected_identity = process_seal_service.terminalDrainIdentitySeal(
        continuation.identity.pid,
        continuation.identity.process_nonce,
        terminalDrainIdentitySealInput(continuation),
    ) catch return false;
    if (!std.crypto.timing_safe.eql(terminal_contract.Digest, expected_identity, continuation.state.identity_seal)) return false;
    const expected_state = process_seal_service.terminalDrainStateSeal(
        continuation.identity.pid,
        continuation.identity.process_nonce,
        terminalDrainStateSealInput(continuation),
    ) catch return false;
    return std.crypto.timing_safe.eql(terminal_contract.Digest, expected_state, continuation.state.state_seal);
}

fn advanceTerminalDrainContinuationNoFail(
    continuation: *TerminalDrainContinuation,
    expected: terminal_contract.TerminalDrainLifecycle,
    next: terminal_contract.TerminalDrainLifecycle,
) void {
    if (!terminalDrainContinuationCurrent(continuation, expected, continuation.state.state_generation) or
        continuation.state.state_generation == std.math.maxInt(u64))
        terminalDrainProofLoss("terminal drain lifecycle preimage drifted");
    continuation.state.lifecycle_raw = @intFromEnum(next);
    continuation.state.state_generation += 1;
    continuation.state.state_seal = process_seal_service.terminalDrainStateSeal(
        continuation.identity.pid,
        continuation.identity.process_nonce,
        terminalDrainStateSealInput(continuation),
    ) catch terminalDrainProofLoss("terminal drain state seal failed");
}

fn terminalDrainProofLoss(comptime message: []const u8) noreturn {
    _ = message;
    if (builtin.is_test and event_release_proof_loss_marker_fd != null)
        writeEventReleaseDeathMarker(0x48);
    process_seal_service.fatalIntegrity(.proof_loss);
}
var alias_quarantine_events: std.atomic.Value(u64) = .init(0);
var generation_response_incarnation_issuer: std.atomic.Value(u64) = .init(1);

const max_live_client_slots = 4096;
const ClientSlotRegistryEntry = struct {
    live: bool = false,
    ready: bool = false,
    slot_addr: usize = 0,
    node_addr: usize = 0,
    slot_incarnation: u64 = 0,
    node_incarnation: u64 = 0,
    owner_thread_incarnation: u64 = 0,
};
var client_slot_registry_mutex: std.atomic.Mutex = .unlocked;
var client_slot_registry: [max_live_client_slots]ClientSlotRegistryEntry =
    [_]ClientSlotRegistryEntry{.{}} ** max_live_client_slots;

fn registerClientSlot(entry: ClientSlotRegistryEntry) error{IdentityExhausted}!void {
    while (!client_slot_registry_mutex.tryLock()) std.atomic.spinLoopHint();
    defer client_slot_registry_mutex.unlock();
    var free_index: ?usize = null;
    for (&client_slot_registry, 0..) |*candidate, index| {
        if (candidate.live and candidate.slot_addr == entry.slot_addr)
            return error.IdentityExhausted;
        if (!candidate.live and free_index == null) free_index = index;
    }
    const index = free_index orelse return error.IdentityExhausted;
    client_slot_registry[index] = entry;
}

fn clientSlotRegistryEntry(slot_addr: usize) ?ClientSlotRegistryEntry {
    while (!client_slot_registry_mutex.tryLock()) std.atomic.spinLoopHint();
    defer client_slot_registry_mutex.unlock();
    for (client_slot_registry) |entry| {
        client_idle_pump_evidence.recordRegistryVisit();
        if (entry.live and entry.ready and entry.slot_addr == slot_addr) return entry;
    }
    return null;
}

fn publishClientSlot(expected: ClientSlotRegistryEntry) void {
    while (!client_slot_registry_mutex.tryLock()) std.atomic.spinLoopHint();
    defer client_slot_registry_mutex.unlock();
    for (&client_slot_registry) |*entry| {
        if (entry.live and entry.slot_addr == expected.slot_addr and
            std.meta.eql(entry.*, expected))
        {
            entry.ready = true;
            return;
        }
    }
    @panic("reserved ClientSlot registry publication drifted");
}

fn unregisterClientSlot(expected: ClientSlotRegistryEntry) bool {
    while (!client_slot_registry_mutex.tryLock()) std.atomic.spinLoopHint();
    defer client_slot_registry_mutex.unlock();
    for (&client_slot_registry) |*entry| {
        if (entry.live and entry.slot_addr == expected.slot_addr) {
            if (!std.meta.eql(entry.*, expected)) return false;
            entry.* = .{};
            return true;
        }
    }
    return false;
}

fn publishClientSlotReplacement(
    slot: *ClientSlot,
    expected: ClientSlotRegistryEntry,
    replacement: ClientSlotRegistryEntry,
    new_node: *ClientNode,
) bool {
    if (!expected.live or expected.ready or !replacement.live or !replacement.ready or
        expected.slot_addr != replacement.slot_addr or
        expected.slot_incarnation != replacement.slot_incarnation or
        expected.owner_thread_incarnation != replacement.owner_thread_incarnation or
        expected.node_addr == replacement.node_addr or
        expected.node_incarnation == replacement.node_incarnation)
        return false;
    while (!client_slot_registry_mutex.tryLock()) std.atomic.spinLoopHint();
    defer client_slot_registry_mutex.unlock();
    for (&client_slot_registry) |*entry| {
        if (entry.live and entry.slot_addr == expected.slot_addr) {
            if (!std.meta.eql(entry.*, expected)) return false;
            if (slot.current != @as(*ClientNode, @ptrFromInt(expected.node_addr)) or
                slot.retiredClientCountUnchecked() >= max_retired_clients or
                new_node != @as(*ClientNode, @ptrFromInt(replacement.node_addr)))
                return false;
            const retired_index = slot.firstEmptyRetiredIndex() orelse return false;
            slot.retired[retired_index] = slot.current;
            slot.current = new_node;
            entry.* = replacement;
            return true;
        }
    }
    return false;
}

fn acquireOperationThreadIncarnation() error{IdentityExhausted}!u64 {
    return operation_thread_identity.acquire();
}

fn operationThreadMatches(incarnation: u64) bool {
    return operation_thread_identity.matches(incarnation);
}

const max_stream_operation_permits = 4096;
const StreamOperationRegistryEntry = struct {
    const State = enum(u8) { empty, live, consume_reserved, consumed };

    state: std.atomic.Value(u8) = .init(@intFromEnum(State.empty)),
    id: u64 = 0,
    permit: StreamOperationPermit = undefined,
};
var stream_operation_registry_mutex: std.atomic.Mutex = .unlocked;
var stream_operation_registry: [max_stream_operation_permits]StreamOperationRegistryEntry =
    [_]StreamOperationRegistryEntry{.{}} ** max_stream_operation_permits;
var next_stream_operation_registry_id: u64 = 1;

fn registerStreamOperationPermit(fields: StreamOperationPermit) error{ AdminBusy, IdentityExhausted }!StreamOperationPermit {
    while (!stream_operation_registry_mutex.tryLock()) std.atomic.spinLoopHint();
    defer stream_operation_registry_mutex.unlock();
    var index: usize = 0;
    while (index < stream_operation_registry.len and
        stream_operation_registry[index].state.load(.acquire) !=
            @intFromEnum(StreamOperationRegistryEntry.State.empty)) : (index += 1)
    {}
    if (index == stream_operation_registry.len) return error.AdminBusy;
    const id = next_stream_operation_registry_id;
    next_stream_operation_registry_id = std.math.add(u64, id, 1) catch
        return error.IdentityExhausted;
    var permit = fields;
    permit.registry_index = @intCast(index);
    permit.registry_id = id;
    const entry = &stream_operation_registry[index];
    entry.id = id;
    entry.permit = permit;
    entry.state.store(@intFromEnum(StreamOperationRegistryEntry.State.live), .release);
    return permit;
}

fn streamOperationPermitRegistryLive(permit: StreamOperationPermit) bool {
    const index: usize = permit.registry_index;
    if (index >= stream_operation_registry.len or permit.registry_id == 0) return false;
    while (!stream_operation_registry_mutex.tryLock()) std.atomic.spinLoopHint();
    defer stream_operation_registry_mutex.unlock();
    const entry = &stream_operation_registry[index];
    return entry.state.load(.acquire) == @intFromEnum(StreamOperationRegistryEntry.State.live) and
        entry.id == permit.registry_id and std.meta.eql(entry.permit, permit);
}

fn unregisterStreamOperationPermit(permit: StreamOperationPermit) error{InvalidStreamOperationPermit}!void {
    const index: usize = permit.registry_index;
    if (index >= stream_operation_registry.len or permit.registry_id == 0)
        return error.InvalidStreamOperationPermit;
    while (!stream_operation_registry_mutex.tryLock()) std.atomic.spinLoopHint();
    defer stream_operation_registry_mutex.unlock();
    const entry = &stream_operation_registry[index];
    if (entry.state.load(.acquire) != @intFromEnum(StreamOperationRegistryEntry.State.live) or
        entry.id != permit.registry_id or !std.meta.eql(entry.permit, permit))
        return error.InvalidStreamOperationPermit;
    if (entry.state.cmpxchgStrong(
        @intFromEnum(StreamOperationRegistryEntry.State.live),
        @intFromEnum(StreamOperationRegistryEntry.State.empty),
        .acq_rel,
        .acquire,
    ) != null) return error.InvalidStreamOperationPermit;
}

fn recordAliasQuarantine() bool {
    var observed = alias_quarantine_events.load(.acquire);
    while (true) {
        if (observed == std.math.maxInt(u64)) return false;
        if (alias_quarantine_events.cmpxchgWeak(
            observed,
            observed + 1,
            .acq_rel,
            .acquire,
        )) |actual| {
            observed = actual;
            continue;
        }
        return true;
    }
}

