fn incidentRepeatKeySeal(
    pid: u32,
    process_nonce: u64,
    key: incident_publication_contract.IncidentRepeatKey,
) [32]u8 {
    return process_seal_service.incidentRepeatKeySeal(pid, process_nonce, .{
        .self_addr = key.self_addr,
        .client_addr = key.client_addr,
        .connection_generation = key.connection_generation,
        .app_instance_nonce = key.incident_id.app_instance_nonce,
        .sequence = key.incident_id.sequence,
        .fingerprint = key.fingerprint,
        .binding_seal = key.binding_seal,
        .lifecycle_raw = key.lifecycle_raw,
    }) catch process_seal_service.fatalIntegrity(.incident_authority);
}

fn managedPoisonSeal(
    value: incident_publication_contract.PreparedManagedPoison,
    input_digest: incident_publication_contract.Digest,
) [32]u8 {
    return process_seal_service.preparedManagedPoisonSeal(value.pid, value.process_nonce, .{
        .self_addr = value.self_addr,
        .owner_thread = value.owner_thread,
        .slot_addr = value.slot_addr,
        .slot_generation = value.slot_generation,
        .node_addr = value.node_addr,
        .node_generation = value.node_generation,
        .binding_seal = value.binding_seal,
        .input_digest = input_digest,
        .lifecycle_raw = value.lifecycle_raw,
    }) catch process_seal_service.fatalIntegrity(.incident_authority);
}

/// Captures the canonical incident projection while the final Client node is pinned, then returns
/// only a sealed scalar handoff. Publication deliberately happens after this operation is released.
fn prepareManagedPoison(
    self: *ClientSlot,
    input: incident_publication_contract.IncidentInput,
    out: *incident_publication_contract.PreparedManagedPoison,
) ManagedPoisonError!void {
    if (!std.meta.eql(out.*, incident_publication_contract.PreparedManagedPoison{}) or
        rangesOverlapTyped(out, self) or rangesOverlapTyped(out, self.current) or
        rangesOverlapTyped(out, &self.current.client))
        return error.InvalidOwner;
    const operation = self.beginRegisteredClientOperation() catch |err| return switch (err) {
        error.MovedOrCopied => error.InvalidOwner,
        error.AdminBusy => error.Busy,
    };
    defer self.endRegisteredClientOperation(operation);
    if (!self.valid() or operation.node != self.current) return error.InvalidOwner;
    return prepareManagedPoisonPinned(self, operation.node, input, out);
}

/// Managed public caller의 최소 request와 owner clock을 Client-owned canonical projection으로
/// 확장한다. 모든 queue/parser read는 registered node pin 아래 끝나며 pointer는 handoff에 남지 않는다.
pub fn prepareManagedPoisonRequest(
    self: *ClientSlot,
    timestamp_ns: i128,
    request: incident_publication_contract.ManagedPoisonRequest,
    out: *incident_publication_contract.PreparedManagedPoison,
) ManagedPoisonError!void {
    if (timestamp_ns < 0 or !incident_publication_contract.validManagedPoisonRequest(request) or
        !std.meta.eql(out.*, incident_publication_contract.PreparedManagedPoison{}) or
        rangesOverlapTyped(out, self) or rangesOverlapTyped(out, self.current) or
        rangesOverlapTyped(out, &self.current.client))
        return error.InvalidInput;
    const operation = self.beginRegisteredClientOperation() catch |err| return switch (err) {
        error.MovedOrCopied => error.InvalidOwner,
        error.AdminBusy => error.Busy,
    };
    defer self.endRegisteredClientOperation(operation);
    if (!self.valid() or operation.node != self.current) return error.InvalidOwner;
    return prepareManagedPoisonRequestPinned(
        self,
        operation.node,
        timestamp_ns,
        request,
        out,
    );
}

fn prepareManagedPoisonRequestPinned(
    self: *ClientSlot,
    node: *ClientNode,
    timestamp_ns: i128,
    request: incident_publication_contract.ManagedPoisonRequest,
    out: *incident_publication_contract.PreparedManagedPoison,
) ManagedPoisonError!void {
    if (!self.valid() or node != self.current or timestamp_ns < 0 or
        !incident_publication_contract.validManagedPoisonRequest(request) or
        !std.meta.eql(out.*, incident_publication_contract.PreparedManagedPoison{}))
        return error.InvalidInput;
    const client = &node.client;
    const binding = client.incident_binding;
    if (!incident_binding_contract.validBindingShape(binding)) return error.InvalidOwner;
    const reason: connection_incident.ConnectionReason = @enumFromInt(request.reason_raw);
    const decision = connection_incident.decisionForReason(reason);
    const pending_stream_count = std.math.cast(u32, client.screen_inbox.pending_stream.items.len) orelse
        return error.InvalidInput;
    const pending_event_count = std.math.cast(u32, client.pending_events.items.len) orelse
        return error.InvalidInput;
    var queue_items = std.math.add(usize, client.screen_inbox.pending_stream.items.len, client.pending_events.items.len) catch
        return error.InvalidInput;
    queue_items = std.math.add(usize, queue_items, client.screen_inbox.pending_batches.items.len) catch
        return error.InvalidInput;
    queue_items = std.math.add(usize, queue_items, @intFromBool(client.screen_inbox.partial_batch != null)) catch
        return error.InvalidInput;
    queue_items = std.math.add(usize, queue_items, @intFromBool(client.pending_outbound != null)) catch
        return error.InvalidInput;
    var queue_bytes = std.math.add(usize, client.screen_inbox.pending_stream_bytes, client.pending_event_bytes) catch
        return error.InvalidInput;
    queue_bytes = std.math.add(usize, queue_bytes, client.screen_inbox.pending_batch_bytes) catch
        return error.InvalidInput;
    if (client.screen_inbox.partial_batch) |partial|
        queue_bytes = std.math.add(usize, queue_bytes, partial.bytes.items.len) catch
            return error.InvalidInput;
    var outbound_offset: u64 = 0;
    var outbound_length: u64 = 0;
    if (client.pending_outbound) |pending| {
        if (pending.offset > pending.frame.len) return error.InvalidInput;
        outbound_offset = std.math.cast(u64, pending.offset) orelse return error.InvalidInput;
        outbound_length = std.math.cast(u64, pending.frame.len) orelse return error.InvalidInput;
        queue_bytes = std.math.add(usize, queue_bytes, pending.frame.len - pending.offset) catch
            return error.InvalidInput;
    }
    const input: incident_publication_contract.IncidentInput = .{
        .timestamp_ns = timestamp_ns,
        .host_id = binding.host_id,
        .host_adapter_generation = binding.host_adapter_generation,
        .connection_generation = binding.connection_generation,
        .wire_major = binding.wire_major,
        .reason_raw = request.reason_raw,
        .scope_raw = @intFromEnum(connection_incident.Scope.connection),
        .disposition_raw = @intFromEnum(decision.disposition),
        .source_site_raw = request.source_site_raw,
        .host_class_raw = binding.host_class_raw,
        .parser_phase_raw = incidentParserPhase(client),
        .outbound_phase_raw = incidentOutboundPhase(client),
        .last_success_request_id = client.last_success_request_id,
        .pending_request_count = @intFromBool(client.prepared_request_execution_lease_addr != 0 or client.pending_outbound != null),
        .pending_stream_count = pending_stream_count,
        .pending_event_count = pending_event_count,
        .queue_item_count = std.math.cast(u32, queue_items) orelse return error.InvalidInput,
        .queue_bytes = std.math.cast(u64, queue_bytes) orelse return error.InvalidInput,
        .outbound_offset = outbound_offset,
        .outbound_length = outbound_length,
        .controller_generation = request.controller_generation,
        .upgrade_epoch = client.upgrade_epoch,
    };
    return prepareManagedPoisonPinned(self, node, input, out);
}

fn incidentParserPhase(client: *const client_mod.Client) u8 {
    if (client.unusable) return @intFromEnum(connection_incident.ParserPhase.terminal);
    const pending = client.parser.buf.items[client.parser.head..];
    if (pending.len == 0) return @intFromEnum(connection_incident.ParserPhase.idle);
    if (pending.len < protocol.header_size) return @intFromEnum(connection_incident.ParserPhase.header);
    const header_bytes: *const [protocol.header_size]u8 = @ptrCast(pending.ptr);
    _ = protocol.Header.decode(header_bytes) catch
        return @intFromEnum(connection_incident.ParserPhase.header);
    return @intFromEnum(connection_incident.ParserPhase.payload);
}

fn incidentOutboundPhase(client: *const client_mod.Client) u8 {
    const pending = client.pending_outbound orelse
        return @intFromEnum(connection_incident.OutboundPhase.idle);
    if (client.unusable) return @intFromEnum(connection_incident.OutboundPhase.terminal);
    return @intFromEnum(if (pending.offset == 0)
        connection_incident.OutboundPhase.queued
    else
        connection_incident.OutboundPhase.partial);
}

fn prepareManagedPoisonPinned(
    self: *ClientSlot,
    node: *ClientNode,
    input: incident_publication_contract.IncidentInput,
    out: *incident_publication_contract.PreparedManagedPoison,
) ManagedPoisonError!void {
    if (node != self.current) return error.InvalidOwner;
    const input_digest = incident_publication_contract.inputDigest(input) catch return error.InvalidInput;
    const binding = node.client.incident_binding;
    if (!incident_binding_contract.validBindingShape(binding) or
        binding.client_addr != @intFromPtr(&node.client) or
        binding.host_id != input.host_id or
        binding.host_adapter_generation != input.host_adapter_generation or
        binding.connection_generation != input.connection_generation or
        binding.wire_major != input.wire_major or
        binding.host_class_raw != input.host_class_raw)
        return error.InvalidInput;
    var candidate: incident_publication_contract.PreparedManagedPoison = .{
        .self_addr = @intFromPtr(out),
        .pid = self.pid,
        .process_nonce = self.process_nonce,
        .owner_thread = @intCast(std.Thread.getCurrentId()),
        .slot_addr = @intFromPtr(self),
        .slot_generation = self.incarnation.tagged,
        .node_addr = @intFromPtr(node),
        .node_generation = node.incarnation.tagged,
        .binding_seal = binding.seal,
        .input = input,
        .lifecycle_raw = @intFromEnum(incident_publication_contract.ManagedPoisonLifecycle.prepared),
    };
    candidate.seal = managedPoisonSeal(candidate, input_digest);
    out.* = candidate;
}

/// Revalidates the final slot/node/binding graph and yields the only query that the coordinator may
/// use. Raw query construction remains inside the ClientSlot owner boundary.
pub fn managedPoisonQuery(
    self: *ClientSlot,
    prepared: *const incident_publication_contract.PreparedManagedPoison,
) ManagedPoisonError!IncidentOperationQuery {
    if (!self.valid() or prepared.self_addr != @intFromPtr(prepared) or
        prepared.pid != self.pid or prepared.process_nonce != self.process_nonce or
        prepared.owner_thread != @as(u64, @intCast(std.Thread.getCurrentId())) or
        prepared.slot_addr != @intFromPtr(self) or prepared.slot_generation != self.incarnation.tagged or
        prepared.node_addr != @intFromPtr(self.current) or prepared.node_generation != self.current.incarnation.tagged or
        !incident_publication_contract.validManagedPoisonShape(prepared.*, @intFromPtr(prepared)))
        return error.InvalidOwner;
    const binding = self.current.client.incident_binding;
    if (!incident_binding_contract.validBindingShape(binding) or
        !std.mem.eql(u8, &binding.seal, &prepared.binding_seal) or
        binding.host_id != prepared.input.host_id or
        binding.host_adapter_generation != prepared.input.host_adapter_generation or
        binding.connection_generation != prepared.input.connection_generation or
        binding.wire_major != prepared.input.wire_major or
        binding.host_class_raw != prepared.input.host_class_raw)
        return error.InvalidOwner;
    const digest = incident_publication_contract.inputDigest(prepared.input) catch return error.InvalidInput;
    if (!std.mem.eql(u8, &prepared.seal, &managedPoisonSeal(prepared.*, digest)))
        return error.InvalidOwner;
    return .{
        .slot_addr = prepared.slot_addr,
        .slot_generation = prepared.slot_generation,
        .node_addr = prepared.node_addr,
    };
}

pub fn consumeManagedPoison(
    self: *ClientSlot,
    prepared: *incident_publication_contract.PreparedManagedPoison,
) ManagedPoisonError!void {
    _ = try managedPoisonQuery(self, prepared);
    const digest = incident_publication_contract.inputDigest(prepared.input) catch return error.InvalidInput;
    var consumed = prepared.*;
    consumed.lifecycle_raw = @intFromEnum(incident_publication_contract.ManagedPoisonLifecycle.consumed);
    consumed.seal = managedPoisonSeal(consumed, digest);
    prepared.* = consumed;
}

pub fn managedPoisonWillPublishFirst(
    self: *ClientSlot,
    prepared: *const incident_publication_contract.PreparedManagedPoison,
) ManagedPoisonError!bool {
    const query = try managedPoisonQuery(self, prepared);
    var operation: incident_publication_contract.PreparedIncidentClientOperation = .{};
    try beginIncidentClientOperation(query, &operation);
    defer finishIncidentClientOperationNoFail(&operation);
    const client: *const client_mod.Client = @ptrFromInt(operation.authority.client_addr);
    return client.first_poison_reason == null and client.first_incident_id.sequence == 0 and
        std.meta.eql(client.incident_repeat_key, incident_publication_contract.IncidentRepeatKey{});
}

/// First incident commit가 끝난 뒤 exact Client operation 아래 terminal state를 게시한다.
/// 반환된 fd는 operation release 뒤 상위 owner가 닫으며 repeat는 이 suffix에 들어오지 않는다.
pub fn terminalizeManagedPoisonNoFail(
    self: *ClientSlot,
    prepared: *const incident_publication_contract.PreparedManagedPoison,
    result: incident_publication_contract.IncidentCommitResult,
) ?std.c.fd_t {
    const query = managedPoisonQuery(self, prepared) catch incidentOperationProofLoss("managed terminal query");
    if (result.kind_raw != @intFromEnum(incident_publication_contract.PublicationKind.first) or
        result.publication.incident_id.app_instance_nonce == 0 or result.publication.incident_id.sequence == 0)
        incidentOperationProofLoss("managed terminal result");
    var operation: incident_publication_contract.PreparedIncidentClientOperation = .{};
    beginIncidentClientOperation(query, &operation) catch incidentOperationProofLoss("managed terminal begin");
    defer finishIncidentClientOperationNoFail(&operation);
    const client: *client_mod.Client = @ptrFromInt(operation.authority.client_addr);
    if (!std.meta.eql(client.first_incident_id, result.publication.incident_id) or
        client.first_poison_reason == null or
        @intFromEnum(client.first_poison_reason.?) != prepared.input.reason_raw)
        incidentOperationProofLoss("managed terminal commit");
    return client.terminalizePublishedIncidentChecked(client.first_poison_reason.?) catch
        incidentOperationProofLoss("managed terminal leaf");
}

fn incidentOperationProofLoss(comptime stage: []const u8) noreturn {
    _ = stage;
    process_seal_service.fatalIntegrity(.incident_authority);
}

fn incidentOperationOwner(query: IncidentOperationQuery) ?ClientSlotRegistryEntry {
    if (currentPid() == 0 or process_runtime_pid.load(.acquire) != currentPid()) return null;
    while (!client_slot_registry_mutex.tryLock()) std.atomic.spinLoopHint();
    defer client_slot_registry_mutex.unlock();
    for (client_slot_registry) |entry| {
        if (entry.live and entry.ready and entry.slot_addr == query.slot_addr and
            entry.slot_incarnation == query.slot_generation and entry.node_addr == query.node_addr and
            entry.node_incarnation != 0 and operationThreadMatches(entry.owner_thread_incarnation))
            return entry;
    }
    return null;
}

pub fn beginIncidentClientOperation(
    query: IncidentOperationQuery,
    out: *incident_publication_contract.PreparedIncidentClientOperation,
) IncidentOperationError!void {
    if (query.slot_addr == 0 or query.slot_generation == 0 or query.node_addr == 0)
        return error.InvalidOwner;
    const owner_before = incidentOperationOwner(query) orelse return error.InvalidOwner;
    const slot_before: *const ClientSlot = @ptrFromInt(owner_before.slot_addr);
    const node_before: *const ClientNode = @ptrFromInt(owner_before.node_addr);
    const client_before = &node_before.client;
    if (rangesOverlapTyped(out, slot_before) or rangesOverlapTyped(out, node_before) or
        rangesOverlapTyped(out, client_before) or rangesOverlapTyped(out, &client_before.incident_binding) or
        rangesOverlapTyped(out, &client_before.incident_repeat_key) or
        rangesOverlapTyped(out, &client_slot_registry) or
        rangesOverlapTyped(out, &registered_node_operations) or
        rangesOverlapTyped(out, &registered_node_operation_free_stack) or
        !std.meta.eql(out.*, incident_publication_contract.PreparedIncidentClientOperation{}))
        return error.InvalidOwner;
    const operation = beginRegisteredNodeOperation(.{
        .slot_addr = query.slot_addr,
        .slot_incarnation = query.slot_generation,
        .node = .{ .address = query.node_addr },
    }) catch |err| return switch (err) {
        error.Busy => error.Busy,
        else => error.InvalidOwner,
    };
    errdefer endRegisteredNodeOperation(operation);
    const owner = registeredNodeOperationOwnerEntry(operation) orelse return error.InvalidOwner;
    const slot: *const ClientSlot = @ptrFromInt(owner.slot_addr);
    const client = &operation.node.client;
    if (client.incident_binding.client_addr != @intFromPtr(client) or
        !incident_binding_contract.validBindingShape(client.incident_binding))
        return error.InvalidOwner;
    const receipt = incidentOperationReceiptDigest(operation.operation_id, owner.node_incarnation, slot.process_nonce);
    var candidate: incident_publication_contract.PreparedIncidentClientOperation = .{
        .self_addr = @intFromPtr(out),
        .authority = .{
            .slot_addr = owner.slot_addr,
            .slot_generation = owner.slot_incarnation,
            .node_addr = owner.node_addr,
            .node_generation = owner.node_incarnation,
            .client_addr = @intFromPtr(client),
            .connection_generation = operation.node.connection_generation,
            .operation_id = operation.operation_id,
            .operation_receipt_seal = receipt,
            .binding_seal = client.incident_binding.seal,
        },
        .registry_index = operation.registry_index,
        .pid = operation.pid,
        .owner_thread = @intCast(std.Thread.getCurrentId()),
        .lifecycle_raw = @intFromEnum(incident_publication_contract.ClientOperationLifecycle.held),
    };
    candidate.authority_digest = incidentAuthorityDigest(candidate.authority);
    candidate.seal = incidentOperationSeal(candidate, slot.process_nonce);
    out.* = candidate;
    traceIncidentPublication(1); // Client operation held
}

fn resolveIncidentClientOperation(
    prepared: *const incident_publication_contract.PreparedIncidentClientOperation,
) ?RegisteredNodeOperation {
    if (prepared.self_addr != @intFromPtr(prepared) or prepared.pid != currentPid() or
        prepared.owner_thread != @as(u64, @intCast(std.Thread.getCurrentId())) or
        (prepared.lifecycle_raw != @intFromEnum(incident_publication_contract.ClientOperationLifecycle.held) and
            prepared.lifecycle_raw != @intFromEnum(incident_publication_contract.ClientOperationLifecycle.bound)) or
        prepared.registry_index >= registered_node_operations.len)
        return null;
    const operation: RegisteredNodeOperation = .{
        .node = @ptrFromInt(prepared.authority.node_addr),
        .registry_index = prepared.registry_index,
        .operation_id = prepared.authority.operation_id,
        .pid = prepared.pid,
    };
    const owner = registeredNodeOperationOwnerEntry(operation) orelse return null;
    const slot: *const ClientSlot = @ptrFromInt(owner.slot_addr);
    const client = &operation.node.client;
    if (!std.mem.eql(u8, &prepared.authority_digest, &incidentAuthorityDigest(prepared.authority)) or
        !std.mem.eql(u8, &prepared.seal, &incidentOperationSeal(prepared.*, slot.process_nonce)) or
        owner.slot_addr != prepared.authority.slot_addr or
        owner.slot_incarnation != prepared.authority.slot_generation or
        owner.node_addr != prepared.authority.node_addr or
        owner.node_incarnation != prepared.authority.node_generation or
        operation.node.connection_generation != prepared.authority.connection_generation or
        @intFromPtr(client) != prepared.authority.client_addr or
        slot.pid != prepared.pid or client.incident_binding.client_addr != prepared.authority.client_addr or
        !std.mem.eql(u8, &client.incident_binding.seal, &prepared.authority.binding_seal))
        return null;
    const receipt = incidentOperationReceiptDigest(operation.operation_id, owner.node_incarnation, slot.process_nonce);
    if (!std.mem.eql(u8, &receipt, &prepared.authority.operation_receipt_seal)) return null;
    return operation;
}

pub fn bindIncidentClientPublication(
    prepared: *incident_publication_contract.PreparedIncidentClientOperation,
    commit: incident_publication_contract.FirstPublicationCommit,
) IncidentOperationError!void {
    const operation = resolveIncidentClientOperation(prepared) orelse return error.InvalidOwner;
    if (!std.meta.eql(commit.authority, prepared.authority) or
        std.mem.allEqual(u8, &commit.input_digest, 0) or
        commit.incident_id.app_instance_nonce == 0 or commit.incident_id.sequence == 0 or
        std.mem.allEqual(u8, &commit.fingerprint, 0) or
        std.enums.fromInt(client_poison.ConnectionReason, commit.reason_raw) == null)
        return error.InvalidOwner;
    const client = &operation.node.client;
    if (client.first_poison_reason != null or client.first_incident_id.sequence != 0 or
        !std.meta.eql(client.incident_repeat_key, incident_publication_contract.IncidentRepeatKey{}))
        return error.InvalidOwner;
    prepared.commit_digest = incidentCommitDigest(commit);
    const key: incident_publication_contract.IncidentRepeatKey = .{
        .self_addr = @intFromPtr(&client.incident_repeat_key),
        .pid = prepared.pid,
        .process_nonce = @as(*const ClientSlot, @ptrFromInt(prepared.authority.slot_addr)).process_nonce,
        .client_addr = prepared.authority.client_addr,
        .connection_generation = prepared.authority.connection_generation,
        .incident_id = commit.incident_id,
        .fingerprint = commit.fingerprint,
        .binding_seal = prepared.authority.binding_seal,
        .lifecycle_raw = @intFromEnum(incident_publication_contract.RepeatKeyLifecycle.published),
    };
    prepared.repeat_key_seal = incidentRepeatKeySeal(prepared.pid, key.process_nonce, key);
    prepared.lifecycle_raw = @intFromEnum(incident_publication_contract.ClientOperationLifecycle.bound);
    const slot: *const ClientSlot = @ptrFromInt(prepared.authority.slot_addr);
    prepared.seal = incidentOperationSeal(prepared.*, slot.process_nonce);
    traceIncidentPublication(2); // Client publication bound
}

pub fn bindIncidentClientRepeatPublication(
    prepared: *incident_publication_contract.PreparedIncidentClientOperation,
    commit: incident_publication_contract.RepeatPublicationCommit,
) IncidentOperationError!void {
    const operation = resolveIncidentClientOperation(prepared) orelse return error.InvalidOwner;
    if (!std.meta.eql(commit.authority, prepared.authority) or
        std.mem.allEqual(u8, &commit.input_digest, 0) or
        commit.incident_id.app_instance_nonce == 0 or commit.incident_id.sequence == 0 or
        std.mem.allEqual(u8, &commit.fingerprint, 0))
        return error.InvalidOwner;
    const client = &operation.node.client;
    const slot: *const ClientSlot = @ptrFromInt(prepared.authority.slot_addr);
    const key = client.incident_repeat_key;
    if (client.first_poison_reason == null or !std.meta.eql(client.first_incident_id, commit.incident_id) or
        !incident_publication_contract.validRepeatKeyShape(key, @intFromPtr(&client.incident_repeat_key)) or
        key.pid != prepared.pid or key.process_nonce != slot.process_nonce or
        key.client_addr != prepared.authority.client_addr or
        key.connection_generation != prepared.authority.connection_generation or
        !std.meta.eql(key.incident_id, commit.incident_id) or
        !std.mem.eql(u8, &key.fingerprint, &commit.fingerprint) or
        !std.mem.eql(u8, &key.binding_seal, &prepared.authority.binding_seal) or
        !std.mem.eql(u8, &key.seal, &incidentRepeatKeySeal(prepared.pid, slot.process_nonce, key)))
        return error.InvalidOwner;
    prepared.commit_digest = incidentRepeatCommitDigest(commit);
    prepared.repeat_key_seal = key.seal;
    prepared.lifecycle_raw = @intFromEnum(incident_publication_contract.ClientOperationLifecycle.bound);
    prepared.seal = incidentOperationSeal(prepared.*, slot.process_nonce);
    traceIncidentPublication(2);
}

pub fn commitFirstIncidentClientPublicationNoFail(
    prepared: *incident_publication_contract.PreparedIncidentClientOperation,
    commit: incident_publication_contract.FirstPublicationCommit,
) void {
    const operation = resolveIncidentClientOperation(prepared) orelse
        incidentOperationProofLoss("commit resolve");
    if (prepared.lifecycle_raw != @intFromEnum(incident_publication_contract.ClientOperationLifecycle.bound) or
        !std.mem.eql(u8, &prepared.commit_digest, &incidentCommitDigest(commit)))
        incidentOperationProofLoss("commit digest");
    const client = &operation.node.client;
    if (client.first_poison_reason != null or client.first_incident_id.sequence != 0 or
        !std.meta.eql(client.incident_repeat_key, incident_publication_contract.IncidentRepeatKey{}))
        incidentOperationProofLoss("commit destination");
    var key: incident_publication_contract.IncidentRepeatKey = .{
        .self_addr = @intFromPtr(&client.incident_repeat_key),
        .pid = prepared.pid,
        .process_nonce = @as(*const ClientSlot, @ptrFromInt(prepared.authority.slot_addr)).process_nonce,
        .client_addr = prepared.authority.client_addr,
        .connection_generation = prepared.authority.connection_generation,
        .incident_id = commit.incident_id,
        .fingerprint = commit.fingerprint,
        .binding_seal = prepared.authority.binding_seal,
        .lifecycle_raw = @intFromEnum(incident_publication_contract.RepeatKeyLifecycle.published),
        .seal = prepared.repeat_key_seal,
    };
    if (!std.mem.eql(u8, &key.seal, &incidentRepeatKeySeal(prepared.pid, key.process_nonce, key)))
        incidentOperationProofLoss("repeat key seal");
    client.first_incident_id = commit.incident_id;
    traceIncidentPublication(3); // first incident id stored
    if (builtin.is_test and IncidentPublicationTestHook.enabled)
        IncidentPublicationTestHook.id_only = client.first_incident_id.sequence != 0 and
            std.meta.eql(client.incident_repeat_key, incident_publication_contract.IncidentRepeatKey{}) and
            client.first_poison_reason == null;
    client.incident_repeat_key = key;
    traceIncidentPublication(4); // repeat key stored
    if (builtin.is_test and IncidentPublicationTestHook.enabled)
        IncidentPublicationTestHook.id_and_key = client.first_incident_id.sequence != 0 and
            client.incident_repeat_key.incident_id.sequence != 0 and client.first_poison_reason == null;
    client.first_poison_reason = @enumFromInt(commit.reason_raw);
    traceIncidentPublication(5); // first reason stored
    if (builtin.is_test and IncidentPublicationTestHook.enabled)
        IncidentPublicationTestHook.complete = client.first_incident_id.sequence != 0 and
            client.incident_repeat_key.incident_id.sequence != 0 and client.first_poison_reason != null;
}

/// repeat는 first Client 필드를 쓰지 않고 held operation 아래 key 권위만 재검증한다.
pub fn commitRepeatIncidentClientPublicationNoFail(
    prepared: *incident_publication_contract.PreparedIncidentClientOperation,
    commit: incident_publication_contract.RepeatPublicationCommit,
) void {
    const operation = resolveIncidentClientOperation(prepared) orelse
        incidentOperationProofLoss("repeat commit resolve");
    if (prepared.lifecycle_raw != @intFromEnum(incident_publication_contract.ClientOperationLifecycle.bound) or
        !std.mem.eql(u8, &prepared.commit_digest, &incidentRepeatCommitDigest(commit)))
        incidentOperationProofLoss("repeat commit digest");
    const client = &operation.node.client;
    const slot: *const ClientSlot = @ptrFromInt(prepared.authority.slot_addr);
    const key = client.incident_repeat_key;
    if (client.first_poison_reason == null or !std.meta.eql(client.first_incident_id, commit.incident_id) or
        !incident_publication_contract.validRepeatKeyShape(key, @intFromPtr(&client.incident_repeat_key)) or
        !std.mem.eql(u8, &key.fingerprint, &commit.fingerprint) or
        !std.mem.eql(u8, &key.seal, &prepared.repeat_key_seal) or
        !std.mem.eql(u8, &key.seal, &incidentRepeatKeySeal(prepared.pid, slot.process_nonce, key)))
        incidentOperationProofLoss("repeat key authority");
}

pub fn finishIncidentClientOperationNoFail(
    prepared: *incident_publication_contract.PreparedIncidentClientOperation,
) void {
    const operation = resolveIncidentClientOperation(prepared) orelse
        incidentOperationProofLoss("finish resolve");
    const slot: *const ClientSlot = @ptrFromInt(prepared.authority.slot_addr);
    var consumed = prepared.*;
    consumed.lifecycle_raw = @intFromEnum(incident_publication_contract.ClientOperationLifecycle.consumed);
    consumed.seal = incidentOperationSeal(consumed, slot.process_nonce);
    endRegisteredNodeOperation(operation);
    traceIncidentPublication(6); // Client operation released
    // Lifetime pin 반환 뒤에는 slot/node/client를 다시 읽지 않고 미리 봉인한 값만 게시한다.
    prepared.* = consumed;
}

const max_registered_node_operations = 4096;
const RegisteredNodeOperationEntry = struct {
    const State = enum(u8) { empty, reserved, live, releasing };

    state: State = .empty,
    operation_id: u64 = 0,
    slot_addr: usize = 0,
    slot_incarnation: u64 = 0,
    node_addr: usize = 0,
    node_incarnation: u64 = 0,
    pid: u32 = 0,
    owner_thread_incarnation: u64 = 0,
    final_admission_txn_addr: usize = 0,
    final_admission_owns_registered_operation_raw: u8 = 0,
};
var registered_node_operation_mutex: std.atomic.Mutex = .unlocked;
var registered_node_operations: [max_registered_node_operations]RegisteredNodeOperationEntry =
    [_]RegisteredNodeOperationEntry{.{}} ** max_registered_node_operations;
var registered_node_operation_free_stack: [max_registered_node_operations]u16 = blk: {
    @setEvalBranchQuota(max_registered_node_operations * 2);
    var indices: [max_registered_node_operations]u16 = undefined;
    for (&indices, 0..) |*entry, index| entry.* = @intCast(index);
    break :blk indices;
};
var registered_node_operation_free_count: usize = max_registered_node_operations;
var next_registered_node_operation_id: u64 = 1;

const RegisteredNodeOperationReservation = struct {
    index: usize,
    entry: RegisteredNodeOperationEntry,
};

fn reserveRegisteredNodeOperation(
    lookup: RegisteredNodeLookup,
) error{Busy}!RegisteredNodeOperationReservation {
    while (!registered_node_operation_mutex.tryLock()) std.atomic.spinLoopHint();
    defer registered_node_operation_mutex.unlock();
    const operation_id = next_registered_node_operation_id;
    if (operation_id == 0 or operation_id == std.math.maxInt(u64)) return error.Busy;
    if (registered_node_operation_free_count == 0) return error.Busy;
    registered_node_operation_free_count -= 1;
    const index: usize = registered_node_operation_free_stack[registered_node_operation_free_count];
    if (registered_node_operations[index].state != .empty)
        @panic("registered node operation free stack drifted");
    next_registered_node_operation_id = operation_id + 1;
    const entry: RegisteredNodeOperationEntry = .{
        .state = .reserved,
        .operation_id = operation_id,
        .slot_addr = lookup.slot_addr,
        .slot_incarnation = lookup.slot_incarnation,
        .pid = currentPid(),
        .owner_thread_incarnation = operation_thread_identity.current(),
    };
    registered_node_operations[index] = entry;
    return .{ .index = index, .entry = entry };
}

fn abortRegisteredNodeOperationReservation(reservation: RegisteredNodeOperationReservation) void {
    while (!registered_node_operation_mutex.tryLock()) std.atomic.spinLoopHint();
    defer registered_node_operation_mutex.unlock();
    const entry = &registered_node_operations[reservation.index];
    if (entry.state != .reserved or entry.operation_id != reservation.entry.operation_id)
        @panic("registered node operation reservation drifted");
    entry.* = .{};
    if (registered_node_operation_free_count >= registered_node_operation_free_stack.len)
        @panic("registered node operation free stack overflow");
    registered_node_operation_free_stack[registered_node_operation_free_count] =
        @intCast(reservation.index);
    registered_node_operation_free_count += 1;
}

fn publishRegisteredNodeOperation(
    reservation: RegisteredNodeOperationReservation,
    slot_entry: ClientSlotRegistryEntry,
) RegisteredNodeOperation {
    while (!registered_node_operation_mutex.tryLock()) std.atomic.spinLoopHint();
    defer registered_node_operation_mutex.unlock();
    const entry = &registered_node_operations[reservation.index];
    if (entry.state != .reserved or entry.operation_id != reservation.entry.operation_id or
        entry.slot_addr != slot_entry.slot_addr or entry.slot_incarnation != slot_entry.slot_incarnation or
        entry.pid != currentPid() or !operationThreadMatches(entry.owner_thread_incarnation))
        @panic("registered node operation publication drifted");
    entry.node_addr = slot_entry.node_addr;
    entry.node_incarnation = slot_entry.node_incarnation;
    entry.state = .live;
    return .{
        .node = @ptrFromInt(slot_entry.node_addr),
        .registry_index = @intCast(reservation.index),
        .operation_id = entry.operation_id,
        .pid = entry.pid,
    };
}

fn resolveRegisteredNodeOperation(operation: RegisteredNodeOperation) ?*ClientNode {
    const pid = currentPid();
    const index: usize = operation.registry_index;
    if (pid == 0 or operation.pid != pid or process_runtime_pid.load(.acquire) != pid or
        index >= registered_node_operations.len or operation.operation_id == 0 or
        @intFromPtr(operation.node) == 0)
        return null;
    var observed: ?RegisteredNodeOperationEntry = null;
    while (!registered_node_operation_mutex.tryLock()) std.atomic.spinLoopHint();
    const candidate = registered_node_operations[index];
    if (candidate.state == .live and candidate.operation_id == operation.operation_id and
        candidate.node_addr == @intFromPtr(operation.node) and candidate.pid == pid and
        operationThreadMatches(candidate.owner_thread_incarnation))
    {
        observed = candidate;
    }
    // Lock order invariant: never hold the operation registry while acquiring ClientSlot registry.
    registered_node_operation_mutex.unlock();
    const expected = observed orelse return null;
    while (!client_slot_registry_mutex.tryLock()) std.atomic.spinLoopHint();
    defer client_slot_registry_mutex.unlock();
    for (client_slot_registry) |entry| {
        if (entry.live and entry.ready and entry.slot_addr == expected.slot_addr and
            entry.slot_incarnation == expected.slot_incarnation and
            entry.node_addr == expected.node_addr and entry.node_incarnation == expected.node_incarnation and
            entry.owner_thread_incarnation == expected.owner_thread_incarnation)
            return @ptrFromInt(expected.node_addr);
    }
    return null;
}

fn registeredNodeOperationOwnerEntry(
    operation: RegisteredNodeOperation,
) ?RegisteredNodeOperationEntry {
    const pid = currentPid();
    const index: usize = operation.registry_index;
    if (pid == 0 or operation.pid != pid or process_runtime_pid.load(.acquire) != pid or
        index >= registered_node_operations.len or operation.operation_id == 0 or
        @intFromPtr(operation.node) == 0)
        return null;
    while (!registered_node_operation_mutex.tryLock()) std.atomic.spinLoopHint();
    defer registered_node_operation_mutex.unlock();
    const entry = registered_node_operations[index];
    if (entry.state != .live or entry.operation_id != operation.operation_id or
        entry.node_addr != @intFromPtr(operation.node) or entry.pid != pid or
        !operationThreadMatches(entry.owner_thread_incarnation))
        return null;
    return entry;
}

fn beginRegisteredNodeOperation(
    lookup: RegisteredNodeLookup,
) error{ InvalidOwner, Busy }!RegisteredNodeOperation {
    const pid = currentPid();
    if (pid == 0 or process_runtime_pid.load(.acquire) != pid or
        lookup.slot_addr == 0 or lookup.slot_incarnation == 0 or switch (lookup.node) {
        .incarnation => |value| value == 0,
        .address => |value| value == 0,
    })
        return error.InvalidOwner;
    const reservation = reserveRegisteredNodeOperation(lookup) catch return error.Busy;
    errdefer abortRegisteredNodeOperationReservation(reservation);
    // The sole nested order is ClientSlot registry -> operation registry publication.
    while (!client_slot_registry_mutex.tryLock()) std.atomic.spinLoopHint();
    defer client_slot_registry_mutex.unlock();
    for (client_slot_registry) |entry| {
        if (!entry.live or !entry.ready or entry.slot_addr != lookup.slot_addr or
            entry.slot_incarnation != lookup.slot_incarnation or
            entry.node_addr == 0 or entry.node_incarnation == 0 or
            switch (lookup.node) {
                .incarnation => |value| entry.node_incarnation != value,
                .address => |value| entry.node_addr != value,
            } or
            (lookup.owner_thread_incarnation != null and
                entry.owner_thread_incarnation != lookup.owner_thread_incarnation.?) or
            !operationThreadMatches(entry.owner_thread_incarnation))
            continue;
        const node: *ClientNode = @ptrFromInt(entry.node_addr);
        node.client.beginClientSlotOperation() catch |err| return switch (err) {
            error.AdminBusy => error.Busy,
            else => error.InvalidOwner,
        };
        return publishRegisteredNodeOperation(reservation, entry);
    }
    return error.InvalidOwner;
}

fn endRegisteredNodeOperation(operation: RegisteredNodeOperation) void {
    const pid = currentPid();
    const index: usize = operation.registry_index;
    if (pid == 0 or operation.pid != pid or process_runtime_pid.load(.acquire) != pid or
        index >= registered_node_operations.len or operation.operation_id == 0 or
        @intFromPtr(operation.node) == 0)
        @panic("invalid registered node operation process domain");
    var node_addr: usize = 0;
    while (!registered_node_operation_mutex.tryLock()) std.atomic.spinLoopHint();
    const candidate = &registered_node_operations[index];
    if (candidate.state == .live and candidate.operation_id == operation.operation_id and
        candidate.node_addr == @intFromPtr(operation.node) and candidate.pid == pid and
        operationThreadMatches(candidate.owner_thread_incarnation) and
        candidate.final_admission_txn_addr == 0 and
        candidate.final_admission_owns_registered_operation_raw == 0)
    {
        candidate.state = .releasing;
        node_addr = candidate.node_addr;
    }
    registered_node_operation_mutex.unlock();
    if (node_addr == 0) @panic("invalid registered node operation release");
    const node: *ClientNode = @ptrFromInt(node_addr);
    if (builtin.is_test) {
        const observer = &node.guarded_allocator.request_free_test_observer;
        const receipt = (@as(u128, operation.operation_id) << 64) |
            @as(u128, operation.registry_index + 1);
        if (observer.registered_operation_active_receipt != receipt or
            observer.registered_operation_begin_count == 0 or
            observer.registered_operation_end_count == std.math.maxInt(usize) or
            observer.registered_operation_begin_count != observer.registered_operation_end_count + 1 or
            observer.registered_operation_end_count >= observer.registered_operation_end_receipts.len or
            observer.registered_operation_begin_receipts[observer.registered_operation_end_count] != receipt)
            observer.registered_operation_receipt_drift = true;
        if (observer.registered_operation_end_count < observer.registered_operation_end_receipts.len)
            observer.registered_operation_end_receipts[observer.registered_operation_end_count] = receipt;
        observer.registered_operation_end_count +|= 1;
        observer.registered_operation_active_receipt = 0;
    }
    if (!node.client.endClientSlotOperation())
        @panic("ClientSlot registered node operation fence release failed");
    while (!registered_node_operation_mutex.tryLock()) std.atomic.spinLoopHint();
    defer registered_node_operation_mutex.unlock();
    const entry = &registered_node_operations[index];
    if (entry.state != .releasing or entry.operation_id != operation.operation_id or
        entry.node_addr != node_addr)
        @panic("registered node operation release publication drifted");
    entry.* = .{};
    if (registered_node_operation_free_count >= registered_node_operation_free_stack.len)
        @panic("registered node operation free stack overflow");
    registered_node_operation_free_stack[registered_node_operation_free_count] =
        operation.registry_index;
    registered_node_operation_free_count += 1;
}

fn bindFinalAdmissionTransactionNoFail(
    operation: RegisteredNodeOperation,
    transaction_addr: usize,
    owns_registered_operation: bool,
) void {
    while (!registered_node_operation_mutex.tryLock()) std.atomic.spinLoopHint();
    defer registered_node_operation_mutex.unlock();
    const entry = &registered_node_operations[operation.registry_index];
    if (transaction_addr == 0 or entry.state != .live or
        entry.operation_id != operation.operation_id or
        entry.node_addr != @intFromPtr(operation.node) or entry.pid != operation.pid or
        entry.final_admission_txn_addr != 0 or
        entry.final_admission_owns_registered_operation_raw != 0)
        @panic("final admission transaction bind drifted");
    entry.final_admission_txn_addr = transaction_addr;
    entry.final_admission_owns_registered_operation_raw = @intFromBool(owns_registered_operation);
}

const FinalAdmissionBindingStatus = enum { missing, foreign, drift, exact };

fn finalAdmissionOwnershipRawValid(raw: u8) bool {
    return raw <= 1;
}

fn finalAdmissionLifecycleRawValid(raw: u8) bool {
    return raw <= @intFromEnum(FinalAdmissionTransaction.Lifecycle.consumed);
}

fn finalAdmissionTransactionBindingStatus(
    operation: RegisteredNodeOperation,
    transaction_addr: usize,
    owns_registered_operation_raw: u8,
) FinalAdmissionBindingStatus {
    if (operation.registry_index >= registered_node_operations.len) return .missing;
    while (!registered_node_operation_mutex.tryLock()) std.atomic.spinLoopHint();
    defer registered_node_operation_mutex.unlock();
    const entry = registered_node_operations[operation.registry_index];
    if (entry.state != .live or entry.operation_id != operation.operation_id or
        entry.node_addr != @intFromPtr(operation.node) or entry.pid != operation.pid or
        entry.final_admission_txn_addr != transaction_addr)
        return .missing;
    if (operation.pid != currentPid() or
        !operationThreadMatches(entry.owner_thread_incarnation))
        return .foreign;
    if (!finalAdmissionOwnershipRawValid(entry.final_admission_owns_registered_operation_raw) or
        !finalAdmissionOwnershipRawValid(owns_registered_operation_raw) or
        entry.final_admission_owns_registered_operation_raw != owns_registered_operation_raw)
        return .drift;
    return .exact;
}

fn finalAdmissionTransactionAddressActive(transaction_addr: usize) bool {
    if (transaction_addr == 0) return false;
    while (!registered_node_operation_mutex.tryLock()) std.atomic.spinLoopHint();
    defer registered_node_operation_mutex.unlock();
    for (registered_node_operations) |entry| {
        if (entry.state == .live and entry.final_admission_txn_addr == transaction_addr)
            return true;
    }
    return false;
}

fn consumeFinalAdmissionTransactionNoFail(
    operation: RegisteredNodeOperation,
    transaction_addr: usize,
    owns_registered_operation_raw: u8,
) void {
    while (!registered_node_operation_mutex.tryLock()) std.atomic.spinLoopHint();
    defer registered_node_operation_mutex.unlock();
    const entry = &registered_node_operations[operation.registry_index];
    if (entry.state != .live or entry.operation_id != operation.operation_id or
        entry.node_addr != @intFromPtr(operation.node) or entry.pid != operation.pid or
        entry.final_admission_txn_addr != transaction_addr or
        !finalAdmissionOwnershipRawValid(entry.final_admission_owns_registered_operation_raw) or
        !finalAdmissionOwnershipRawValid(owns_registered_operation_raw) or
        entry.final_admission_owns_registered_operation_raw != owns_registered_operation_raw)
        @panic("final admission transaction consume drifted");
    entry.final_admission_txn_addr = 0;
    entry.final_admission_owns_registered_operation_raw = 0;
}

const FinalAdmissionDecision = enum { blocked, admitted };
const FinalAdmissionKind = enum { mutation, rx_demux };
const FinalAdmissionBlockers = struct {
    queued: bool = false,
    aggregate_count: usize = 0,
};
const FinalAdmissionProtectedRange = struct { start: usize, len: usize };
const max_final_admission_protected_ranges = 4;

fn mintRegisteredOperationExecutionReceipt(
    out: *client_mod.RegisteredOperationExecutionMintReceipt,
    operation: RegisteredNodeOperation,
    owner: RegisteredNodeOperationEntry,
) error{InvalidOwner}!void {
    if (!out.pristineExact() or owner.state != .live or
        owner.operation_id != operation.operation_id or owner.node_addr != @intFromPtr(operation.node) or
        owner.pid != currentPid() or !operationThreadMatches(owner.owner_thread_incarnation))
        return error.InvalidOwner;
    const slot: *const ClientSlot = @ptrFromInt(owner.slot_addr);
    if (slot.pid != owner.pid or slot.process_nonce == 0) return error.InvalidOwner;
    operation_thread_identity.issueMintReceipt(
        out,
        @intFromPtr(&operation.node.client),
        operation.operation_id,
        owner.pid,
        slot.process_nonce,
        owner.owner_thread_incarnation,
    ) catch return error.InvalidOwner;
}

const FinalAdmissionTransaction = struct {
    const Lifecycle = enum(u8) { pristine, active, consumed };

    self_addr: usize = 0,
    operation: RegisteredNodeOperation = undefined,
    mint_receipt: client_mod.RegisteredOperationExecutionMintReceipt = .{},
    execution_capability: client_mod.RegisteredOperationExecutionCapability = .{},
    execution_handle: ?client_mod.RegisteredOperationExecutionHandle = null,
    owns_registered_operation_raw: u8 = 0,
    lifecycle_raw: u8 = @intFromEnum(FinalAdmissionTransaction.Lifecycle.pristine),
    seal: owner_seal.Digest = [_]u8{0} ** 32,

    fn pristineExact(self: *const @This()) bool {
        return self.self_addr == 0 and self.owns_registered_operation_raw == 0 and
            self.lifecycle_raw == @intFromEnum(FinalAdmissionTransaction.Lifecycle.pristine) and
            self.mint_receipt.pristineExact() and
            self.execution_capability.pristineExact() and self.execution_handle == null;
    }

    fn finish(self: *@This()) error{InvalidOwner}!void {
        if (self.self_addr != @intFromPtr(self)) {
            if (finalAdmissionTransactionAddressActive(@intFromPtr(self)))
                @panic("active final admission transaction authority drifted");
            return error.InvalidOwner;
        }
        switch (finalAdmissionTransactionBindingStatus(
            self.operation,
            @intFromPtr(self),
            self.owns_registered_operation_raw,
        )) {
            .foreign => return error.InvalidOwner,
            .drift => @panic("active final admission transaction ownership drifted"),
            .missing => {
                if (finalAdmissionTransactionAddressActive(@intFromPtr(self)))
                    @panic("active final admission transaction authority drifted");
                return error.InvalidOwner;
            },
            .exact => {},
        }
        if (!finalAdmissionOwnershipRawValid(self.owns_registered_operation_raw) or
            !finalAdmissionLifecycleRawValid(self.lifecycle_raw) or
            self.lifecycle_raw != @intFromEnum(FinalAdmissionTransaction.Lifecycle.active) or
            !std.mem.eql(u8, &self.seal, &finalAdmissionTransactionSeal(self)))
            @panic("active final admission transaction content drifted");
        const operation = self.operation;
        const owns_registered_operation = self.owns_registered_operation_raw == 1;
        operation.node.client.endRegisteredOperationExecutionLease(self.execution_handle.?);
        consumeFinalAdmissionTransactionNoFail(
            operation,
            @intFromPtr(self),
            self.owns_registered_operation_raw,
        );
        self.lifecycle_raw = @intFromEnum(FinalAdmissionTransaction.Lifecycle.consumed);
        if (owns_registered_operation) endRegisteredNodeOperation(operation);
    }
};

const EventTakeActivationTransaction = struct {
    const Lifecycle = enum(u8) { pristine, active, consumed };

    self_addr: usize = 0,
    lifecycle_raw: u8 = @intFromEnum(EventTakeActivationTransaction.Lifecycle.pristine),
    admission: FinalAdmissionTransaction = .{},
    prepared_addr: usize = 0,
    permit_registry_id: u64 = 0,
    quarantine_live: bool = false,
    pin_live: bool = false,
    authority_live: bool = false,
    seal: owner_seal.Digest = [_]u8{0} ** 32,

    fn digest(self: *const @This()) owner_seal.Digest {
        var writer = owner_seal.Writer.init("maru.event-take-activation.v1");
        writer.writeUsize(self.self_addr);
        writer.writeU8(self.lifecycle_raw);
        writer.writeUsize(@intFromPtr(&self.admission));
        writer.writeUsize(self.prepared_addr);
        writer.writeU64(self.permit_registry_id);
        writer.writeU8(@intFromBool(self.quarantine_live));
        writer.writeU8(@intFromBool(self.pin_live));
        writer.writeU8(@intFromBool(self.authority_live));
        return writer.finish();
    }

    fn reseal(self: *@This()) void {
        self.seal = self.digest();
    }

    fn setQuarantineLive(self: *@This(), live: bool) void {
        self.quarantine_live = live;
        self.reseal();
    }

    fn setPinLive(self: *@This(), live: bool) void {
        self.pin_live = live;
        self.reseal();
    }

    fn setAuthorityLive(self: *@This(), live: bool) void {
        self.authority_live = live;
        self.reseal();
    }

    fn setResourceLive(self: *@This(), resource: enum { quarantine, pin, authority }, live: bool) void {
        switch (resource) {
            .quarantine => self.setQuarantineLive(live),
            .pin => self.setPinLive(live),
            .authority => self.setAuthorityLive(live),
        }
    }

    fn finish(self: *@This()) void {
        if (self.self_addr != @intFromPtr(self) or self.lifecycle_raw !=
            @intFromEnum(EventTakeActivationTransaction.Lifecycle.active) or
            !std.mem.eql(u8, &self.seal, &self.digest()) or self.quarantine_live or
            self.pin_live or self.authority_live)
            @panic("event take activation authority drifted");
        self.admission.finish() catch
            @panic("event take activation settlement failed");
        if (builtin.is_test and EventTakeActivationTestHook.probe_contention)
            EventTakeActivationTestHook.suffix_stage = 4;
        self.lifecycle_raw = @intFromEnum(EventTakeActivationTransaction.Lifecycle.consumed);
        self.reseal();
    }
};

fn beginEventTakeActivationTransaction(
    out: *EventTakeActivationTransaction,
    operation: *const RegisteredNodeOperation,
    prepared: *client_mod.PreparedGenerationEventTake,
    permit: StreamOperationPermit,
    protected_ranges: []const FinalAdmissionProtectedRange,
) error{ InvalidOwner, Busy }!void {
    if (out.self_addr != 0 or out.lifecycle_raw != @intFromEnum(EventTakeActivationTransaction.Lifecycle.pristine) or
        !out.admission.pristineExact()) return error.InvalidOwner;
    const node = resolveRegisteredNodeOperation(operation.*) orelse return error.InvalidOwner;
    const operation_owner = registeredNodeOperationOwnerEntry(operation.*) orelse
        return error.InvalidOwner;
    if (!finalAdmissionDestinationValid(&out.admission, operation.*, protected_ranges))
        return error.InvalidOwner;
    if (client_mod.generationAllocatorCallbackActive() or rpc_decoder_callback_active or
        batch_release_callback_active or
        anyGenerationEventReleaseCallbackActive())
        return error.Busy;
    mintRegisteredOperationExecutionReceipt(
        &out.admission.mint_receipt,
        operation.*,
        operation_owner,
    ) catch return error.InvalidOwner;
    errdefer _ = operation_thread_identity.abortMintReceipt(&out.admission.mint_receipt);
    out.admission.execution_handle = node.client.beginRegisteredOperationExecutionLease(
        &out.admission.execution_capability,
        &out.admission.mint_receipt,
    ) catch |err| return switch (err) {
        error.AdminBusy => error.Busy,
        else => error.InvalidOwner,
    };
    errdefer node.client.endRegisteredOperationExecutionLease(out.admission.execution_handle.?);
    bindFinalAdmissionTransactionNoFail(operation.*, @intFromPtr(&out.admission), false);
    out.admission.self_addr = @intFromPtr(&out.admission);
    out.admission.operation = operation.*;
    out.admission.owns_registered_operation_raw = 0;
    out.admission.lifecycle_raw = @intFromEnum(FinalAdmissionTransaction.Lifecycle.active);
    out.admission.seal = finalAdmissionTransactionSeal(&out.admission);
    out.self_addr = @intFromPtr(out);
    out.lifecycle_raw = @intFromEnum(EventTakeActivationTransaction.Lifecycle.active);
    out.prepared_addr = @intFromPtr(prepared);
    out.permit_registry_id = permit.registry_id;
    out.reseal();
}

fn finalAdmissionTransactionSeal(transaction: *const FinalAdmissionTransaction) owner_seal.Digest {
    var writer = owner_seal.Writer.init("maru.final-admission.transaction.v1");
    writer.writeUsize(transaction.self_addr);
    writer.writeUsize(@intFromPtr(transaction.operation.node));
    writer.writeU16(transaction.operation.registry_index);
    writer.writeU64(transaction.operation.operation_id);
    writer.writeU64(transaction.operation.pid);
    writer.writeUsize(@intFromPtr(&transaction.execution_capability));
    writer.writeU64(transaction.execution_capability.lease_identity);
    writer.writeU64(transaction.execution_capability.operation_identity);
    writer.writeU8(transaction.owns_registered_operation_raw);
    writer.writeU8(transaction.lifecycle_raw);
    return writer.finish();
}

fn finalAdmissionDestinationValid(
    out: *const FinalAdmissionTransaction,
    operation: RegisteredNodeOperation,
    protected_ranges: []const FinalAdmissionProtectedRange,
) bool {
    const owner = registeredNodeOperationOwnerEntry(operation) orelse return false;
    if (protected_ranges.len > max_final_admission_protected_ranges) return false;
    const out_addr = @intFromPtr(out);
    const out_len = @sizeOf(FinalAdmissionTransaction);
    if (byteRangesOverlap(out_addr, out_len, owner.slot_addr, @sizeOf(ClientSlot)) or
        byteRangesOverlap(out_addr, out_len, owner.node_addr, @sizeOf(ClientNode)) or
        byteRangesOverlap(
            out_addr,
            out_len,
            @intFromPtr(&registered_node_operations),
            @sizeOf(@TypeOf(registered_node_operations)),
        ))
        return false;
    for (protected_ranges) |range|
        if (byteRangesOverlap(out_addr, out_len, range.start, range.len)) return false;
    return true;
}

fn beginFinalAdmissionTransactionCore(
    out: *FinalAdmissionTransaction,
    operation: RegisteredNodeOperation,
    owns_registered_operation: bool,
    comptime admission_kind: FinalAdmissionKind,
    blockers: FinalAdmissionBlockers,
    protected_ranges: []const FinalAdmissionProtectedRange,
    exact_control_permit: ?StreamOperationPermit,
) error{ InvalidOwner, Busy }!FinalAdmissionDecision {
    const node = resolveRegisteredNodeOperation(operation) orelse return error.InvalidOwner;
    const operation_owner = registeredNodeOperationOwnerEntry(operation) orelse return error.InvalidOwner;
    if (!finalAdmissionDestinationValid(out, operation, protected_ranges) or !out.pristineExact())
        return error.InvalidOwner;
    const stream_operation_valid = if (exact_control_permit) |permit|
        permit.kind == .control and permit.slot.streamOperationPermitLive(permit) and
            @intFromPtr(permit.slot) == operation_owner.slot_addr and
            permit.slot.current.incarnation.tagged == operation.node.incarnation.tagged
    else
        streamOperationNodeIdle(node);
    if (client_mod.generationAllocatorCallbackActive() or batch_release_callback_active or
        anyGenerationEventReleaseCallbackActive() or !stream_operation_valid)
        return error.Busy;
    mintRegisteredOperationExecutionReceipt(&out.mint_receipt, operation, operation_owner) catch
        return error.InvalidOwner;
    errdefer _ = operation_thread_identity.abortMintReceipt(&out.mint_receipt);
    out.execution_handle = node.client.beginRegisteredOperationExecutionLease(
        &out.execution_capability,
        &out.mint_receipt,
    ) catch |err| return switch (err) {
        error.AdminBusy => error.Busy,
        else => error.InvalidOwner,
    };
    errdefer node.client.endRegisteredOperationExecutionLease(out.execution_handle.?);
    const queued = switch (admission_kind) {
        .mutation => node.client.bufferedControllerRevokeUnderRegisteredOperationExecutionLease(
            out.execution_handle.?,
        ) catch return error.InvalidOwner,
        // A queued revoke is itself RX state. It blocks every mutation admission but cannot stop
        // the same lease-held reader from draining later socket frames into bounded demux owners.
        .rx_demux => false,
    };
    bindFinalAdmissionTransactionNoFail(
        operation,
        @intFromPtr(out),
        owns_registered_operation,
    );
    out.self_addr = @intFromPtr(out);
    out.operation = operation;
    out.owns_registered_operation_raw = @intFromBool(owns_registered_operation);
    out.lifecycle_raw = @intFromEnum(FinalAdmissionTransaction.Lifecycle.active);
    out.seal = finalAdmissionTransactionSeal(out);
    if (queued or blockers.queued or blockers.aggregate_count != 0) {
        out.finish() catch @panic("validated blocked final admission settlement failed");
        return .blocked;
    }
    return .admitted;
}

fn finalAdmissionTransaction(
    request: GenerationTransportOwnerQuery,
    out: *FinalAdmissionTransaction,
    blockers: FinalAdmissionBlockers,
) error{ InvalidOwner, Busy }!FinalAdmissionDecision {
    if (request.slot_addr == 0 or request.slot_incarnation == 0 or
        request.node_incarnation == 0 or request.host_id == 0 or request.pid != currentPid() or
        request.process_nonce == 0 or request.owner_seal_addr == 0)
        return error.InvalidOwner;
    const operation = beginRegisteredNodeOperation(.{
        .slot_addr = request.slot_addr,
        .slot_incarnation = request.slot_incarnation,
        .node = .{ .incarnation = request.node_incarnation },
    }) catch |err| return err;
    errdefer endRegisteredNodeOperation(operation);
    const identity = request.reservation.identity;
    if (!identity.valid() or identity.slot_incarnation != request.slot_incarnation or
        identity.node_incarnation != request.node_incarnation or identity.host_id != request.host_id or
        identity.pid != request.pid or identity.process_nonce != request.process_nonce or
        operation.node.client.host_id != request.host_id)
        return error.InvalidOwner;
    const owner = operation.node.cleanup_registry.transportOwnerSeal(
        request.reservation.cleanup,
        identity,
    ) catch return error.InvalidOwner;
    if (@intFromPtr(owner) != request.owner_seal_addr or
        !owner.valid(request.transport_incarnation) or
        owner.owner_addr != request.owner_addr or owner.owner_size != request.owner_size or
        owner.transport_addr != request.transport_addr or
        owner.prepared_storage_addr != request.prepared_storage_addr)
        return error.InvalidOwner;
    const out_addr = @intFromPtr(out);
    const out_len = @sizeOf(FinalAdmissionTransaction);
    if (byteRangesOverlap(out_addr, out_len, request.owner_addr, request.owner_size) or
        byteRangesOverlap(
            out_addr,
            out_len,
            identity.binding_storage_addr,
            @sizeOf(contract.PreparedAttachmentBinding),
        ))
        return error.InvalidOwner;
    const protected_ranges = [_]FinalAdmissionProtectedRange{
        .{ .start = request.owner_addr, .len = request.owner_size },
        .{
            .start = identity.binding_storage_addr,
            .len = @sizeOf(contract.PreparedAttachmentBinding),
        },
    };
    return beginFinalAdmissionTransactionCore(
        out,
        operation,
        true,
        .mutation,
        blockers,
        &protected_ranges,
        null,
    );
}

fn finalAdmissionTransactionWithOperation(
    operation: *const RegisteredNodeOperation,
    out: *FinalAdmissionTransaction,
    blockers: FinalAdmissionBlockers,
    protected_ranges: []const FinalAdmissionProtectedRange,
) error{ InvalidOwner, Busy }!FinalAdmissionDecision {
    if (byteRangesOverlap(
        @intFromPtr(out),
        @sizeOf(FinalAdmissionTransaction),
        @intFromPtr(operation),
        @sizeOf(RegisteredNodeOperation),
    )) return error.InvalidOwner;
    return beginFinalAdmissionTransactionCore(
        out,
        operation.*,
        false,
        .mutation,
        blockers,
        protected_ranges,
        null,
    );
}

fn rxDemuxAdmissionTransactionWithOperation(
    operation: *const RegisteredNodeOperation,
    out: *FinalAdmissionTransaction,
) error{ InvalidOwner, Busy }!void {
    if (byteRangesOverlap(
        @intFromPtr(out),
        @sizeOf(FinalAdmissionTransaction),
        @intFromPtr(operation),
        @sizeOf(RegisteredNodeOperation),
    )) return error.InvalidOwner;
    const decision = try beginFinalAdmissionTransactionCore(
        out,
        operation.*,
        false,
        .rx_demux,
        .{},
        &.{},
        null,
    );
    if (decision != .admitted) unreachable;
}

fn finalAdmissionTransactionWithOperationPermitAndRegistry(
    operation: *const RegisteredNodeOperation,
    permit: StreamOperationPermit,
    out: *FinalAdmissionTransaction,
    protected_ranges: []const FinalAdmissionProtectedRange,
) error{ InvalidOwner, Busy }!FinalAdmissionDecision {
    if (byteRangesOverlap(
        @intFromPtr(out),
        @sizeOf(FinalAdmissionTransaction),
        @intFromPtr(operation),
        @sizeOf(RegisteredNodeOperation),
    )) return error.InvalidOwner;
    const decision = try beginFinalAdmissionTransactionCore(
        out,
        operation.*,
        false,
        .mutation,
        .{},
        protected_ranges,
        permit,
    );
    if (decision == .blocked) return .blocked;
    const blockers = operation.node.cleanup_registry.connectionOrderingBlockerCount() catch {
        out.finish() catch @panic("validated aggregate admission settlement failed");
        return error.InvalidOwner;
    };
    if (blockers != 0) {
        out.finish() catch @panic("validated aggregate blocker settlement failed");
        return .blocked;
    }
    return .admitted;
}

fn finalAdmissionTransactionWithOperationAndRegistry(
    operation: *const RegisteredNodeOperation,
    out: *FinalAdmissionTransaction,
    protected_ranges: []const FinalAdmissionProtectedRange,
) error{ InvalidOwner, Busy }!FinalAdmissionDecision {
    const decision = try finalAdmissionTransactionWithOperation(
        operation,
        out,
        .{},
        protected_ranges,
    );
    if (decision == .blocked) return .blocked;
    const blockers = operation.node.cleanup_registry.connectionOrderingBlockerCount() catch {
        out.finish() catch @panic("validated aggregate admission settlement failed");
        return error.InvalidOwner;
    };
    if (blockers != 0) {
        out.finish() catch @panic("validated aggregate blocker settlement failed");
        return .blocked;
    }
    return .admitted;
}

const GenerationRequestOwner = struct {
    operation: RegisteredNodeOperation,
    identity: contract.BindingIdentity,
    owner: *contract.TransportOwnerSeal,
};

/// Shared registry-first admission for every prepared-request transition. The returned operation
/// pins the canonical node until the caller settles both request backing and node authority.
fn beginGenerationRequestOwner(
    request: anytype,
    comptime allow_active_cleanup: bool,
) GenerationRequestError!GenerationRequestOwner {
    if (client_mod.generationAllocatorCallbackActive() or rpc_decoder_callback_active or
        batch_release_callback_active or
        anyGenerationEventReleaseCallbackActive())
        return error.Busy;
    if (request.slot_addr == 0 or request.slot_incarnation == 0 or
        request.node_incarnation == 0 or request.host_id == 0 or request.pid != currentPid() or
        request.process_nonce == 0 or request.transport_addr == 0 or
        request.transport_incarnation == 0 or request.owner_seal_addr == 0 or
        request.prepared_storage_addr == 0)
        return error.InvalidOwner;
    const operation = beginRegisteredNodeOperation(.{
        .slot_addr = request.slot_addr,
        .slot_incarnation = request.slot_incarnation,
        .node = .{ .incarnation = request.node_incarnation },
    }) catch |err| return switch (err) {
        error.Busy => error.Busy,
        error.InvalidOwner => error.InvalidOwner,
    };
    errdefer endRegisteredNodeOperation(operation);
    const node = operation.node;
    if (builtin.is_test) {
        const observer = &node.guarded_allocator.request_free_test_observer;
        const receipt = (@as(u128, operation.operation_id) << 64) |
            @as(u128, operation.registry_index + 1);
        if (observer.registered_operation_active_receipt != 0 or
            observer.registered_operation_begin_count != observer.registered_operation_end_count or
            observer.registered_operation_begin_count >= observer.registered_operation_begin_receipts.len)
            observer.registered_operation_receipt_drift = true;
        if (observer.registered_operation_begin_count < observer.registered_operation_begin_receipts.len)
            observer.registered_operation_begin_receipts[observer.registered_operation_begin_count] = receipt;
        observer.registered_operation_begin_count +|= 1;
        observer.registered_operation_active_receipt = receipt;
    }
    if (!streamOperationNodeIdle(node) or !node.rpc_free_evidence.emptyExact() or
        (node.pin_owner.active_cleanup != 0 and
            !(allow_active_cleanup and node.pin_owner.active_cleanup == 1)))
        return error.Busy;
    const identity = request.reservation.identity;
    if (!identity.valid() or identity.slot_incarnation != request.slot_incarnation or
        identity.node_incarnation != request.node_incarnation or identity.host_id != request.host_id or
        identity.connection_generation != node.connection_generation or identity.pid != request.pid or
        identity.process_nonce != request.process_nonce or node.client.host_id != request.host_id)
        return error.InvalidOwner;
    const owner = node.cleanup_registry.transportOwnerSeal(
        request.reservation.cleanup,
        identity,
    ) catch return error.InvalidOwner;
    if (@intFromPtr(owner) != request.owner_seal_addr or
        !owner.valid(request.transport_incarnation) or
        owner.transport_addr != request.transport_addr or
        owner.prepared_storage_addr != request.prepared_storage_addr)
        return error.InvalidOwner;
    if (comptime @hasField(@TypeOf(request), "owner_addr")) {
        if (owner.owner_addr != request.owner_addr or owner.owner_size != request.owner_size)
            return error.InvalidOwner;
    }
    return .{ .operation = operation, .identity = identity, .owner = owner };
}

/// Resolves an untrusted transport's scalar slot identity through the canonical registry before
/// converting any supplied address to a pointer. The registry lock pins the exact node operation,
/// so teardown cannot create an address ABA between resolution and capability projection.
pub fn projectGenerationCapabilities(
    request: CapabilityProjectionRequest,
) CapabilityProjectionError!contract.GenerationCapabilities {
    if (client_mod.generationAllocatorCallbackActive() or batch_release_callback_active)
        return error.Busy;
    if (request.slot_addr == 0 or request.slot_incarnation == 0 or
        request.node_incarnation == 0 or request.host_id == 0 or request.pid != currentPid() or
        request.process_nonce == 0 or request.transport_incarnation == 0 or
        request.owner_seal_addr == 0)
        return error.InvalidOwner;

    const operation = beginRegisteredNodeOperation(.{
        .slot_addr = request.slot_addr,
        .slot_incarnation = request.slot_incarnation,
        .node = .{ .incarnation = request.node_incarnation },
    }) catch |err| return switch (err) {
        error.Busy => error.Busy,
        error.InvalidOwner => error.InvalidOwner,
    };
    defer endRegisteredNodeOperation(operation);
    const node = operation.node;

    if (!streamOperationNodeIdle(node) or node.pin_owner.active_cleanup != 0)
        return error.Busy;
    const identity = request.reservation.identity;
    if (identity.slot_incarnation != request.slot_incarnation or
        identity.node_incarnation != request.node_incarnation or
        identity.host_id != request.host_id or identity.connection_generation != node.connection_generation or
        identity.pid != request.pid or identity.process_nonce != request.process_nonce)
        return error.InvalidOwner;
    const binding_owner_seal = node.cleanup_registry.transportOwnerSeal(
        request.reservation.cleanup,
        identity,
    ) catch return error.InvalidOwner;
    if (@intFromPtr(binding_owner_seal) != request.owner_seal_addr or
        !binding_owner_seal.valid(request.transport_incarnation))
        return error.InvalidOwner;
    if (node.client.host_id != request.host_id) return error.InvalidOwner;

    const profile = node.client.compatibility_profile orelse return error.InvalidOwner;
    const attach_schema_raw = @as(*const u8, @ptrCast(&profile.attach_schema)).*;
    const metadata_support_raw = @as(*const u8, @ptrCast(&node.client.metadata_support)).*;
    if (attach_schema_raw > @intFromEnum(compatibility.AttachSchema.granted_roles) or
        metadata_support_raw > @intFromEnum(contract.MetadataSupport.supported))
        return error.InvalidOwner;
    return .{
        .wire_major = node.client.wire_major,
        .screen_codec_version = node.client.screen_codec_version,
        .attach_schema = switch (profile.attach_schema) {
            .frozen_controller_only => .frozen_controller_only,
            .granted_roles => .granted_roles,
        },
        .metadata_support = switch (node.client.metadata_support) {
            .unsupported => .unsupported,
            .supported => .supported,
        },
        .peer_attach_generation = node.client.attachment_capabilities.peer_attach_generation,
        .controller_transfer = node.client.attachment_capabilities.negotiated_controller_transfer,
        .screen_viewport_scrolled = node.client.screen_viewport_scrolled_v1,
        .async_scroll_to_bottom = node.client.async_scroll_to_bottom_v1,
        .async_observation_probe = node.client.async_observation_probe_v1,
        .notification_stream_auth = node.client.notification_stream_auth_v1,
        .notification_delivery = node.client.notification_delivery_v1,
        .runtime_clipboard = node.client.runtime_clipboard_v1,
        .runtime_core_command = node.client.runtime_core_command_v1,
        .runtime_link_at = node.client.runtime_link_at_v1,
        .runtime_selected_text = node.client.runtime_selected_text_v1,
        .runtime_selection_state = node.client.runtime_selection_state_v1,
    };
}

fn stringifyGenerationParams(out: []u8, value: anytype) ?[]const u8 {
    var writer = std.Io.Writer.fixed(out);
    var json: std.json.Stringify = .{ .writer = &writer, .options = .{} };
    json.write(value) catch return null;
    return writer.buffered();
}

/// Canonical request encoder. Binding-owned runtime/stream identity is injected here exactly once;
/// no public request variant can carry a foreign identity or an encoded JSON discriminator.
fn encodeGenerationRequestParams(
    out: []u8,
    identity: contract.BindingIdentity,
    stream_id: u64,
    request: contract.ValidatedRuntimeRequest,
) ?[]const u8 {
    return encodeGenerationRequestParamsWithCapabilities(out, identity, stream_id, request, false);
}

fn encodeGenerationRequestParamsWithCapabilities(
    out: []u8,
    identity: contract.BindingIdentity,
    stream_id: u64,
    request: contract.ValidatedRuntimeRequest,
    notification_delivery_v1: bool,
) ?[]const u8 {
    return switch (request) {
        .spawn_full => null,
        .attach_controller => if (identity.role != .controller) null else std.fmt.bufPrint(
            out,
            "{{\"runtime_id\":\"{x:0>32}\",\"mode\":\"controller\"}}",
            .{identity.runtime_id},
        ) catch null,
        .attach_observer => if (identity.role != .observer) null else std.fmt.bufPrint(
            out,
            "{{\"runtime_id\":\"{x:0>32}\",\"mode\":\"observer\"}}",
            .{identity.runtime_id},
        ) catch null,
        .resize => |v| stringifyGenerationParams(out, .{
            .stream_id = stream_id,
            .cols = v.cols,
            .rows = v.rows,
            .client_sequence = v.client_sequence,
        }),
        .observation, .clipboard_write, .detach => stringifyGenerationParams(out, .{ .stream_id = stream_id }),
        .notification => if (notification_delivery_v1)
            stringifyGenerationParams(out, .{ .stream_id = stream_id, .delivery_version = @as(u8, 1) })
        else
            stringifyGenerationParams(out, .{ .stream_id = stream_id }),
        .notification_config_update => |v| stringifyGenerationParams(out, .{
            .stream_id = stream_id,
            .expected_controller_generation = v.expected_controller_generation,
            .config_generation = v.config_generation,
            .notifications_osc = v.notifications_osc,
            .display_label = v.label() orelse return null,
        }),
        .selected_text => |v| stringifyGenerationParams(out, .{
            .stream_id = stream_id,
            .sr = v.start_row,
            .sc = v.start_col,
            .er = v.end_row,
            .ec = v.end_col,
            .block = v.block,
            .all = v.all,
            .authoritative = v.authoritative,
        }),
        .link_at => |v| stringifyGenerationParams(out, .{
            .stream_id = stream_id,
            .row = v.row,
            .col = v.col,
            .scopes = v.scopes,
        }),
        .find => |v| blk: {
            const query = v.bytes() orelse break :blk null;
            var hex: [512]u8 = undefined;
            const digits = "0123456789abcdef";
            for (query, 0..) |byte, index| {
                hex[index * 2] = digits[byte >> 4];
                hex[index * 2 + 1] = digits[byte & 0x0f];
            }
            break :blk stringifyGenerationParams(out, .{
                .stream_id = stream_id,
                .q = hex[0 .. query.len * 2],
                .cur = v.current,
                .scroll = v.scroll,
            });
        },
        .select_op => |v| stringifyGenerationParams(out, .{
            .stream_id = stream_id,
            .op = switch (v.kind) {
                .word => "word",
                .line => "line",
                .all => "all",
            },
            .row = v.row,
            .col = v.col,
        }),
        .core_command => |v| encodeGenerationCoreCommand(out, stream_id, v),
        .report_mouse => |v| stringifyGenerationParams(out, .{
            .stream_id = stream_id,
            .button = v.button,
            .col = v.col,
            .row = v.row,
            .x_px = v.x_px,
            .y_px = v.y_px,
            .pressed = v.pressed,
            .motion = v.motion,
            .mods = v.mods,
        }),
        .terminate => std.fmt.bufPrint(
            out,
            "{{\"runtime_id\":\"{x:0>32}\"}}",
            .{identity.runtime_id},
        ) catch null,
    };
}

fn encodeGenerationCoreCommand(
    out: []u8,
    stream_id: u64,
    command: contract.CoreCommandRequest,
) ?[]const u8 {
    return switch (command) {
        .scroll => |arg| stringifyGenerationParams(out, .{ .stream_id = stream_id, .op = "scroll", .arg = arg }),
        .scroll_to_bottom => stringifyGenerationParams(out, .{ .stream_id = stream_id, .op = "scroll_to_bottom" }),
        .scroll_to_abs => |arg| stringifyGenerationParams(out, .{ .stream_id = stream_id, .op = "scroll_to_abs", .arg = arg }),
        .scroll_to_offset => |arg| stringifyGenerationParams(out, .{ .stream_id = stream_id, .op = "scroll_to_offset", .arg = arg }),
        .report_focus => |gained| stringifyGenerationParams(out, .{ .stream_id = stream_id, .op = "report_focus", .gained = gained }),
        .set_cell_metrics => |v| stringifyGenerationParams(out, .{ .stream_id = stream_id, .op = "set_cell_metrics", .width = v.width, .height = v.height }),
        .set_default_colors => |v| stringifyGenerationParams(out, .{ .stream_id = stream_id, .op = "set_default_colors", .foreground = v.foreground, .background = v.background }),
        .set_config_palette => |palette| stringifyGenerationParams(out, .{ .stream_id = stream_id, .op = "set_config_palette", .palette = palette }),
        .set_max_scrollback => |lines| stringifyGenerationParams(out, .{ .stream_id = stream_id, .op = "set_max_scrollback", .lines = lines }),
        .set_ambiguous_wide => |wide| stringifyGenerationParams(out, .{ .stream_id = stream_id, .op = "set_ambiguous_wide", .wide = wide }),
        .set_emoji_wide => |wide| stringifyGenerationParams(out, .{ .stream_id = stream_id, .op = "set_emoji_wide", .wide = wide }),
        .set_default_cursor_shape => |shape| stringifyGenerationParams(out, .{ .stream_id = stream_id, .op = "set_default_cursor_shape", .shape = shape }),
        .set_runtime_config => |v| stringifyGenerationParams(out, .{
            .stream_id = stream_id,
            .op = "set_runtime_config",
            .lines = v.max_scrollback,
            .ambiguous_wide = v.ambiguous_wide,
            .emoji_wide = v.emoji_wide,
            .palette = v.palette,
            .foreground = v.foreground,
            .background = v.background,
            .cell_width = v.cell_width,
            .cell_height = v.cell_height,
            .cursor_shape = v.cursor_shape,
        }),
        .jump_to_prompt => |direction| stringifyGenerationParams(out, .{ .stream_id = stream_id, .op = "jump_to_prompt", .direction = direction }),
        .clear_screen => stringifyGenerationParams(out, .{ .stream_id = stream_id, .op = "clear_screen" }),
        .reset_input_modes => stringifyGenerationParams(out, .{ .stream_id = stream_id, .op = "reset_input_modes" }),
        .selection_start => |v| stringifyGenerationParams(out, .{ .stream_id = stream_id, .op = "selection_start", .row = v.row, .col = v.col, .block = v.block }),
        .selection_extend => |v| stringifyGenerationParams(out, .{ .stream_id = stream_id, .op = "selection_extend", .row = v.row, .col = v.col }),
        .selection_extend_or_collapse => |v| stringifyGenerationParams(out, .{ .stream_id = stream_id, .op = "selection_extend_or_collapse", .row = v.row, .col = v.col }),
        .selection_scroll_and_extend => |v| stringifyGenerationParams(out, .{ .stream_id = stream_id, .op = "selection_scroll_and_extend", .row = v.row, .col = v.col, .delta = v.delta }),
        .selection_clear => stringifyGenerationParams(out, .{ .stream_id = stream_id, .op = "selection_clear" }),
    };
}

/// Canonical generation adapter for one response-free stream control.  It resolves the sealed
/// controller binding before reading capabilities, deriving the stream id, or touching Client.
pub fn sendGenerationControl(
    request: GenerationControlSend,
) GenerationControlError!void {
    const admission = try beginGenerationControlOwner(request);
    defer endRegisteredNodeOperation(admission.operation);
    const node = admission.operation.node;
    const control = request.control.decode() orelse return error.InvalidOwner;
    const slot: *ClientSlot = @ptrFromInt(request.slot_addr);
    const permit = slot.prepareStreamOperationPermit(
        .control,
        request.transport_addr,
        request.transport_incarnation,
        admission.identity,
    ) catch |err| return switch (err) {
        error.AdminBusy => error.Busy,
        error.InvalidStreamOperationPermit => error.InvalidOwner,
        error.IdentityExhausted => error.ProtocolError,
    };
    defer slot.abortStreamOperationPermit(permit) catch
        @panic("generation control stream-operation permit release drifted");
    switch (control) {
        .scroll_to_bottom => {
            if (!node.client.async_scroll_to_bottom_v1) return error.Unsupported;
            var transaction: FinalAdmissionTransaction = .{};
            const decision = try finalAdmissionTransactionWithOperationPermitAndRegistry(
                &admission.operation,
                permit,
                &transaction,
                &.{},
            );
            if (decision == .blocked) return error.Busy;
            defer transaction.finish() catch @panic("generation control admission settlement failed");
            node.client.sendScrollToBottomUnderRegisteredOperationExecutionLease(
                transaction.execution_handle.?,
                request.bound_stream_id,
            ) catch |err|
                return mapGenerationControlClientError(err);
        },
        .core_command => |command| {
            if (!node.client.runtime_core_command_v1) return error.Unsupported;
            if (command == .clear_screen and !node.client.runtime_clear_screen_v1) return error.Unsupported;
            var params: [4096]u8 = undefined;
            const encoded = encodeGenerationCoreCommand(&params, request.bound_stream_id, command) orelse
                return error.ResourceExhausted;
            var transaction: FinalAdmissionTransaction = .{};
            const protected = [_]FinalAdmissionProtectedRange{.{
                .start = @intFromPtr(encoded.ptr),
                .len = encoded.len,
            }};
            const decision = try finalAdmissionTransactionWithOperationPermitAndRegistry(
                &admission.operation,
                permit,
                &transaction,
                &protected,
            );
            if (decision == .blocked) return error.Busy;
            defer transaction.finish() catch @panic("generation control admission settlement failed");
            node.client.sendCoreCommandUnderRegisteredOperationExecutionLease(
                transaction.execution_handle.?,
                request.bound_stream_id,
                encoded,
            ) catch |err|
                return mapGenerationControlClientError(err);
        },
        .observation_probe => return error.Unsupported,
    }
}

/// Nonblocking admission returns false only while an older outbound frame retains the Client
/// slot. Unsupported capability is a distinct typed result so callers cannot spin forever.
pub fn sendGenerationControlNonBlocking(
    request: GenerationControlSend,
) GenerationControlError!bool {
    const admission = try beginGenerationControlOwner(request);
    defer endRegisteredNodeOperation(admission.operation);
    const node = admission.operation.node;
    const control = request.control.decode() orelse return error.InvalidOwner;
    const slot: *ClientSlot = @ptrFromInt(request.slot_addr);
    const permit = slot.prepareStreamOperationPermit(
        .control,
        request.transport_addr,
        request.transport_incarnation,
        admission.identity,
    ) catch |err| return switch (err) {
        error.AdminBusy => error.Busy,
        error.InvalidStreamOperationPermit => error.InvalidOwner,
        error.IdentityExhausted => error.ProtocolError,
    };
    defer slot.abortStreamOperationPermit(permit) catch
        @panic("generation control stream-operation permit release drifted");
    return switch (control) {
        .scroll_to_bottom => blk: {
            if (!node.client.async_scroll_to_bottom_v1) return error.Unsupported;
            var transaction: FinalAdmissionTransaction = .{};
            const decision = try finalAdmissionTransactionWithOperationPermitAndRegistry(
                &admission.operation,
                permit,
                &transaction,
                &.{},
            );
            if (decision == .blocked) break :blk false;
            defer transaction.finish() catch @panic("generation nonblocking control admission settlement failed");
            break :blk node.client.sendScrollToBottomNonBlockingUnderRegisteredOperationExecutionLease(
                transaction.execution_handle.?,
                request.bound_stream_id,
            ) catch |err|
                return mapGenerationControlClientError(err);
        },
        .core_command => |command| blk: {
            if (!node.client.runtime_core_command_v1) return error.Unsupported;
            if (command == .clear_screen and !node.client.runtime_clear_screen_v1) return error.Unsupported;
            var params: [4096]u8 = undefined;
            const encoded = encodeGenerationCoreCommand(&params, request.bound_stream_id, command) orelse
                return error.ResourceExhausted;
            var transaction: FinalAdmissionTransaction = .{};
            const protected = [_]FinalAdmissionProtectedRange{.{
                .start = @intFromPtr(encoded.ptr),
                .len = encoded.len,
            }};
            const decision = try finalAdmissionTransactionWithOperationPermitAndRegistry(
                &admission.operation,
                permit,
                &transaction,
                &protected,
            );
            if (decision == .blocked) break :blk false;
            defer transaction.finish() catch @panic("generation nonblocking control admission settlement failed");
            break :blk node.client.sendCoreCommandNonBlockingUnderRegisteredOperationExecutionLease(
                transaction.execution_handle.?,
                request.bound_stream_id,
                encoded,
            ) catch |err|
                return mapGenerationControlClientError(err);
        },
        .observation_probe => |nonce| blk: {
            if (!node.client.async_observation_probe_v1) return error.Unsupported;
            var transaction: FinalAdmissionTransaction = .{};
            const decision = try finalAdmissionTransactionWithOperationPermitAndRegistry(
                &admission.operation,
                permit,
                &transaction,
                &.{},
            );
            if (decision == .blocked) break :blk false;
            defer transaction.finish() catch @panic("generation observation probe admission settlement failed");
            break :blk node.client.sendObservationProbeNonBlockingUnderRegisteredOperationExecutionLease(
                transaction.execution_handle.?,
                request.bound_stream_id,
                nonce,
            ) catch |err| return mapGenerationControlClientError(err);
        },
    };
}

fn beginGenerationControlOwner(
    request: GenerationControlSend,
) GenerationControlError!GenerationRequestOwner {
    // Decode before registry resolution so corrupt outer/nested tags cannot authorize a Client read.
    _ = request.control.decode() orelse return error.InvalidOwner;
    return beginBoundControllerMutationOwner(request, request.bound_stream_id) catch |err|
        return switch (err) {
            error.Busy => error.Busy,
            error.InvalidOwner => error.InvalidOwner,
            error.Unauthorized => error.Unauthorized,
        };
}

fn mapGenerationControlClientError(err: client_mod.ClientError) GenerationControlError {
    return switch (err) {
        error.AdminBusy => error.Busy,
        error.Unauthorized => error.Unauthorized,
        error.OutOfMemory, error.EventQueueFull => error.ResourceExhausted,
        error.ConnectionClosed, error.WriteFailed => error.ConnectionClosed,
        error.EndpointAbsent,
        error.EndpointDenied,
        error.EndpointTransient,
        error.HandshakeFailed,
        error.IncompatibleVersion,
        error.ProtocolError,
        error.ExternalMode,
        => error.ProtocolError,
    };
}

test "CR3a-2c3b typed request encoder injects only canonical binding identities" {
    var identity: contract.BindingIdentity = .{
        .binding_incarnation = 1,
        .binding_storage_addr = 2,
        .destination_addr = 3,
        .binding_reservation_id = 4,
        .slot_incarnation = 5,
        .node_incarnation = 6,
        .host_id = 7,
        .connection_generation = 1,
        .runtime_id = 0xaa,
        .role = .controller,
        .pid = 8,
        .process_nonce = 9,
    };
    var buffer: [4096]u8 = undefined;
    try std.testing.expectEqualStrings(
        "{\"runtime_id\":\"000000000000000000000000000000aa\",\"mode\":\"controller\"}",
        encodeGenerationRequestParams(&buffer, identity, 77, .attach_controller).?,
    );
    try std.testing.expect(encodeGenerationRequestParams(
        &buffer,
        identity,
        77,
        .attach_observer,
    ) == null);
    identity.role = .observer;
    try std.testing.expectEqualStrings(
        "{\"runtime_id\":\"000000000000000000000000000000aa\",\"mode\":\"observer\"}",
        encodeGenerationRequestParams(&buffer, identity, 77, .attach_observer).?,
    );
    try std.testing.expect(encodeGenerationRequestParams(
        &buffer,
        identity,
        77,
        .attach_controller,
    ) == null);
    identity.role = .controller;
    try std.testing.expectEqualStrings(
        "{\"stream_id\":77,\"q\":\"61ed959c\",\"cur\":2,\"scroll\":true}",
        encodeGenerationRequestParams(&buffer, identity, 77, .{
            .find = contract.FindRequest.init("a한", 2, true).?,
        }).?,
    );
    try std.testing.expectEqualStrings(
        "{\"stream_id\":77,\"delivery_version\":1}",
        encodeGenerationRequestParamsWithCapabilities(&buffer, identity, 77, .notification, true).?,
    );
    try std.testing.expectEqualStrings(
        "{\"stream_id\":77}",
        encodeGenerationRequestParamsWithCapabilities(&buffer, identity, 77, .notification, false).?,
    );
    try std.testing.expectEqualStrings(
        "{\"runtime_id\":\"000000000000000000000000000000aa\"}",
        encodeGenerationRequestParams(&buffer, identity, 77, .terminate).?,
    );
    try std.testing.expect(encodeGenerationRequestParams(
        &buffer,
        identity,
        77,
        .spawn_full,
    ) == null);
}

