/// All-or-none request-side transaction. Untrusted transport addresses remain scalars until the
/// live ClientSlot registry pins the canonical node and its owner seal proves the exact transport
/// and opaque storage destinations.
pub fn prepareGenerationRequest(
    request: GenerationRequestPrepare,
) GenerationRequestError!GenerationPreparedRequest {
    const decoded = request.request.decode() orelse return error.InvalidOwner;
    if (request.owner_addr == 0 or request.owner_size == 0)
        return error.InvalidOwner;
    _ = std.math.add(usize, request.owner_addr, request.owner_size) catch
        return error.InvalidOwner;
    const tag = std.meta.activeTag(decoded);
    const family = decoded.family();
    if (family == .connection_only_denied) return error.Unauthorized;
    const admission = try beginGenerationRequestOwner(request, false);
    defer endRegisteredNodeOperation(admission.operation);
    const node = admission.operation.node;
    const identity = admission.identity;
    const decision = node.cleanup_registry.requestDecision(
        request.reservation.cleanup,
        identity,
        family,
        tag,
        request.bound_stream_id,
    ) catch return error.InvalidOwner;
    switch (decision) {
        .allowed => {},
        .unauthorized => return error.Unauthorized,
        .busy => return error.Busy,
    }

    const storage: *client_mod.PreparedBlockingRpcStorage =
        @ptrFromInt(request.prepared_storage_addr);
    var allocator_scope: client_mod.Client.GenerationAllocatorScope = .{};
    const request_ranges = [_]GenerationGuardedAllocator.OperationRangeInput{
        .{ .start = request.owner_addr, .len = request.owner_size },
        .{ .start = identity.binding_storage_addr, .len = @sizeOf(contract.PreparedAttachmentBinding) },
        .{ .start = request.prepared_storage_addr, .len = @sizeOf(client_mod.PreparedBlockingRpcStorage) },
        .{ .start = request.owner_seal_addr, .len = @sizeOf(contract.TransportOwnerSeal) },
        .{ .start = @intFromPtr(&allocator_scope), .len = @sizeOf(client_mod.Client.GenerationAllocatorScope) },
    };
    const guard = &node.guarded_allocator;
    if (!guard.beginOperationGuard(&request_ranges)) return error.InvalidOwner;
    defer guard.endOperationGuard();
    node.client.beginGenerationAllocatorScope(
        guard.allocator(),
        .rpc_prepare,
        &allocator_scope,
    ) catch |err| {
        return switch (err) {
            error.IdentityExhausted => blk: {
                node.client.poison(.local_invariant_violation);
                break :blk error.IdentityExhausted;
            },
            error.AdminBusy => error.Busy,
            error.ConnectionClosed, error.WriteFailed => error.ConnectionClosed,
            error.OutOfMemory, error.EventQueueFull, error.CapacityExhausted => error.ResourceExhausted,
            error.Unauthorized => error.Unauthorized,
            error.MovedOrCopied,
            error.InvalidIdentity,
            error.InvalidReservation,
            error.InvalidState,
            error.InvalidStream,
            error.InvalidDescriptor,
            => error.InvalidOwner,
            error.EndpointAbsent,
            error.EndpointDenied,
            error.EndpointTransient,
            error.HandshakeFailed,
            error.IncompatibleVersion,
            error.ProtocolError,
            error.ExternalMode,
            error.DestinationOccupied,
            => error.ProtocolError,
        };
    };
    defer node.client.restoreGenerationAllocatorScope(&allocator_scope) catch
        @panic("generation allocator scope restore drifted");
    var params_buffer: [4096]u8 = undefined;
    const params_json = encodeGenerationRequestParamsWithCapabilities(
        &params_buffer,
        identity,
        request.bound_stream_id,
        decoded,
        node.client.notification_delivery_v1,
    ) orelse return error.ResourceExhausted;
    const prepared_identity = node.client.prepareBlockingRpcStorage(
        storage,
        contract.requestMethod(tag),
        params_json,
    ) catch |err| {
        if (guard.operation_alias_rejected) {
            node.client.poison(.local_invariant_violation);
            return error.ProtocolError;
        }
        return mapGenerationRequestClientError(err);
    };
    const receipt = contract.PreparedCallReceipt.init(.{
        .transport_incarnation = request.transport_incarnation,
        .request_id = prepared_identity.request_id,
        .request_digest = prepared_identity.frame_digest,
    }) orelse {
        _ = node.client.abortPreparedBlockingRpcStorageCanonical(
            storage,
            prepared_identity,
        ) catch @panic("canonical prepared request receipt rollback failed");
        return error.ProtocolError;
    };
    const canonical: prepared_request_authority.Prepared = .{
        .transport_addr = request.transport_addr,
        .transport_incarnation = request.transport_incarnation,
        .binding = identity,
        .tag = tag,
        .family = family,
        .receipt = receipt,
        .descriptor = prepared_identity.descriptor,
    };
    node.cleanup_registry.publishPreparedRequest(
        request.reservation.cleanup,
        identity,
        canonical,
    ) catch {
        const outcome = node.client.abortPreparedBlockingRpcStorageCanonical(
            storage,
            prepared_identity,
        ) catch @panic("canonical prepared request publication rollback failed");
        if (outcome == .terminal) node.client.poison(.local_invariant_violation);
        return error.ProtocolError;
    };
    return .{ .receipt = receipt, .canonical = canonical };
}

pub fn abortGenerationRequest(request: GenerationRequestAbort) GenerationRequestError!void {
    if (!request.receipt.valid()) return error.InvalidOwner;
    const admission = try beginGenerationRequestOwner(request, false);
    defer endRegisteredNodeOperation(admission.operation);
    const node = admission.operation.node;
    const identity = admission.identity;
    const maybe_canonical = node.cleanup_registry.preparedRequestForReceipt(
        request.reservation.cleanup,
        identity,
        request.transport_addr,
        request.transport_incarnation,
        request.receipt,
    ) catch return error.InvalidOwner;
    const canonical = maybe_canonical orelse return error.InvalidReceipt;
    const storage: *client_mod.PreparedBlockingRpcStorage =
        @ptrFromInt(request.prepared_storage_addr);
    const prepared_identity: client_mod.PreparedBlockingRpcIdentity = .{
        .request_id = canonical.receipt.request_id,
        .frame_digest = canonical.receipt.request_digest,
        .descriptor = canonical.descriptor,
    };
    const outcome = node.client.abortPreparedBlockingRpcStorageCanonical(
        storage,
        prepared_identity,
    ) catch |err| switch (err) {
        error.AdminBusy => return error.Busy,
        else => {
            node.cleanup_registry.settlePreparedRequest(
                request.reservation.cleanup,
                identity,
                canonical,
                true,
            ) catch @panic("ambiguous prepared request authority terminalization failed");
            node.client.poison(.local_invariant_violation);
            return error.ProtocolError;
        },
    };
    node.cleanup_registry.settlePreparedRequest(
        request.reservation.cleanup,
        identity,
        canonical,
        outcome == .terminal,
    ) catch @panic("prepared request authority settlement drifted");
    if (outcome == .terminal) {
        node.client.poison(.local_invariant_violation);
        return error.ProtocolError;
    }
}

const PreparedExecutionPhase = enum(u8) {
    prepared_unbegun,
    pre_wire_backing_live,
    post_execute_backing_settled,
    settled,
};

const FailStopReason = enum(u8) {
    authority_drift,
    backing_ambiguous,
    duplicate_settlement,
    cleanup_failure,
};

const PreparedExecutionSettlementTag = enum(u8) {
    pending,
    reusable,
    terminal,
    fail_stop_required,
};

const PreparedExecutionSettlement = struct {
    tag: PreparedExecutionSettlementTag = .pending,
    reason_raw: u8 = 0,

    fn rawValid(self: *const @This()) bool {
        const tag_raw = @as(*const u8, @ptrCast(&self.tag)).*;
        if (tag_raw > @intFromEnum(PreparedExecutionSettlementTag.fail_stop_required)) return false;
        return switch (self.tag) {
            .pending, .reusable => self.reason_raw == 0,
            .terminal => self.reason_raw < std.meta.fields(client_poison.ConnectionReason).len,
            .fail_stop_required => self.reason_raw < std.meta.fields(FailStopReason).len,
        };
    }

    fn pendingExact(self: *const @This()) bool {
        return self.rawValid() and self.tag == .pending;
    }

    fn terminalReason(self: *const @This()) ?client_poison.ConnectionReason {
        if (!self.rawValid() or self.tag != .terminal) return null;
        return @enumFromInt(self.reason_raw);
    }

    fn failStopReason(self: *const @This()) ?FailStopReason {
        if (!self.rawValid() or self.tag != .fail_stop_required) return null;
        return @enumFromInt(self.reason_raw);
    }

    fn reusable() @This() {
        return .{ .tag = .reusable };
    }

    fn terminal(reason: client_poison.ConnectionReason) @This() {
        return .{ .tag = .terminal, .reason_raw = @intFromEnum(reason) };
    }

    fn failStop(reason: FailStopReason) @This() {
        return .{ .tag = .fail_stop_required, .reason_raw = @intFromEnum(reason) };
    }
};

const SettlementOutcome = union(enum) {
    reusable,
    terminal: client_poison.ConnectionReason,
    fail_stop_required: FailStopReason,
};

const PreparedExecutionSnapshot = struct {
    txn_addr: usize,
    node_addr: usize,
    operation_id: u64,
    reservation: AttachmentBindingReservation,
    binding_identity: contract.BindingIdentity,
    canonical_prepared: prepared_request_authority.Prepared,
    prepared_identity: client_mod.PreparedBlockingRpcIdentity,
    phase: PreparedExecutionPhase,
    settlement: PreparedExecutionSettlement,
};

const PreparedExecutionCanonical = struct {
    node: *ClientNode,
    snapshot: PreparedExecutionSnapshot,
    canonical: prepared_request_authority.Prepared,
};

const PreparedExecutionTxn = struct {
    self_addr: usize = 0,
    node_addr: usize = 0,
    operation_id: u64 = 0,
    reservation: AttachmentBindingReservation = std.mem.zeroes(AttachmentBindingReservation),
    binding_identity: contract.BindingIdentity = std.mem.zeroes(contract.BindingIdentity),
    canonical_prepared: prepared_request_authority.Prepared = std.mem.zeroes(prepared_request_authority.Prepared),
    prepared_identity: client_mod.PreparedBlockingRpcIdentity = std.mem.zeroes(client_mod.PreparedBlockingRpcIdentity),
    phase: PreparedExecutionPhase = .prepared_unbegun,
    settlement: PreparedExecutionSettlement = .{},

    const InitError = error{ InvalidOwner, InvalidReceipt, ProtocolError };
    const SettlementError = error{ProtocolError};

    fn initBeforeBeginExecute(
        self: *PreparedExecutionTxn,
        operation: RegisteredNodeOperation,
        request: GenerationRequestAbort,
        identity: contract.BindingIdentity,
        canonical: prepared_request_authority.Prepared,
    ) PreparedExecutionTxn.InitError!void {
        if (!self.semanticPristine()) return error.InvalidOwner;
        const node = resolveRegisteredNodeOperation(operation) orelse return error.InvalidOwner;
        if (!identity.valid() or !canonical.valid() or
            !std.meta.eql(request.reservation.identity, identity) or
            !std.meta.eql(canonical.binding, identity) or
            canonical.transport_addr != request.transport_addr or
            canonical.transport_incarnation != request.transport_incarnation or
            !canonical.receipt.matches(request.receipt) or
            canonical.descriptor.storage_addr != request.prepared_storage_addr or
            canonical.descriptor.client_addr != @intFromPtr(&node.client))
            return error.InvalidOwner;
        const present = node.cleanup_registry.preparedRequestForReceipt(
            request.reservation.cleanup,
            identity,
            request.transport_addr,
            request.transport_incarnation,
            request.receipt,
        ) catch return error.InvalidOwner;
        if (present == null or !std.meta.eql(present.?, canonical)) return error.InvalidReceipt;
        const prepared_identity = identityFromCanonical(canonical);
        const request_storage: *client_mod.PreparedBlockingRpcStorage =
            @ptrFromInt(canonical.descriptor.storage_addr);
        if (!node.client.preparedBlockingRpcStorageMatches(request_storage, prepared_identity))
            return error.ProtocolError;
        self.node_addr = @intFromPtr(node);
        self.operation_id = operation.operation_id;
        self.reservation = request.reservation;
        self.binding_identity = identity;
        self.canonical_prepared = canonical;
        self.prepared_identity = prepared_identity;
        self.phase = .prepared_unbegun;
        self.settlement = .{};
        self.self_addr = @intFromPtr(self);
    }

    fn commitBeginExecute(self: *PreparedExecutionTxn, operation: RegisteredNodeOperation) void {
        const node = self.ownerNode(operation) orelse
            @panic("prepared execution transaction begin owner drifted");
        if (self.phase != .prepared_unbegun or !self.settlement.pendingExact())
            @panic("prepared execution transaction begin drifted");
        node.cleanup_registry.beginPreparedRequestExecute(
            self.reservation.cleanup,
            self.binding_identity,
            self.canonical_prepared,
        ) catch {
            node.cleanup_registry.settlePreparedRequest(
                self.reservation.cleanup,
                self.binding_identity,
                self.canonical_prepared,
                true,
            ) catch {};
            node.client.poison(.local_invariant_violation);
            self.settlement = PreparedExecutionSettlement.failStop(.authority_drift);
            self.phase = .settled;
            failStopPreparedExecution(.authority_drift);
        };
        self.phase = .pre_wire_backing_live;
    }

    fn settleUnbegun(
        self: *PreparedExecutionTxn,
        operation: RegisteredNodeOperation,
        terminal: bool,
    ) SettlementError!SettlementOutcome {
        const node = self.ownerNode(operation) orelse return error.ProtocolError;
        if (self.phase != .prepared_unbegun or !self.settlement.pendingExact())
            return error.ProtocolError;
        const present = node.cleanup_registry.preparedRequestForReceipt(
            self.reservation.cleanup,
            self.binding_identity,
            self.canonical_prepared.transport_addr,
            self.canonical_prepared.transport_incarnation,
            self.canonical_prepared.receipt,
        ) catch return error.ProtocolError;
        if (present == null or !std.meta.eql(present.?, self.canonical_prepared))
            return error.ProtocolError;
        const outcome = node.client.abortPreparedBlockingRpcStorageCanonical(
            @ptrFromInt(self.canonical_prepared.descriptor.storage_addr),
            self.prepared_identity,
        ) catch return error.ProtocolError;
        const must_terminal = terminal or outcome == .terminal;
        node.cleanup_registry.settlePreparedRequest(
            self.reservation.cleanup,
            self.binding_identity,
            self.canonical_prepared,
            must_terminal,
        ) catch return error.ProtocolError;
        self.phase = .post_execute_backing_settled;
        if (must_terminal) {
            node.client.poison(.local_invariant_violation);
            return self.publishTerminal(node.client.firstPoisonReason().?);
        }
        return self.publishReusable();
    }

    fn revalidatePreWire(
        self: *PreparedExecutionTxn,
        operation: RegisteredNodeOperation,
    ) error{ InvalidOwner, InvalidReceipt }!void {
        if (self.ownerNode(operation) == null) return error.InvalidOwner;
        const expected = self.canonicalExecuting(operation) orelse return error.InvalidReceipt;
        if (!expected.node.client.preparedBlockingRpcStorageMatches(
            canonicalStorage(expected),
            expected.snapshot.prepared_identity,
        ))
            return error.InvalidReceipt;
    }

    fn rollbackPreWire(
        self: *PreparedExecutionTxn,
        operation: RegisteredNodeOperation,
    ) SettlementError!SettlementOutcome {
        return self.rollbackPreWireWithLease(operation, null);
    }

    fn rollbackPreWireWithLease(
        self: *PreparedExecutionTxn,
        operation: RegisteredNodeOperation,
        lease: ?*client_mod.PreparedRequestExecutionLease,
    ) SettlementError!SettlementOutcome {
        try self.requireCleanupClosed(operation);
        const expected = self.canonicalExecuting(operation) orelse return error.ProtocolError;
        const abort_outcome = if (lease) |held|
            expected.node.client.abortPreparedBlockingRpcStorageUnderExecutionLease(
                canonicalStorage(expected),
                expected.snapshot.prepared_identity,
                held,
            )
        else
            expected.node.client.abortPreparedBlockingRpcStorageCanonical(
                canonicalStorage(expected),
                expected.snapshot.prepared_identity,
            );
        const settled = abort_outcome catch {
            self.failStopAfterCallbackDrift(operation, expected, .backing_ambiguous);
            return error.ProtocolError;
        };
        const node = self.canonicalStillExact(operation, expected) orelse {
            self.failStopAfterCallbackDrift(operation, expected, .authority_drift);
            return error.ProtocolError;
        };
        self.phase = .post_execute_backing_settled;
        const terminal = settled == .terminal;
        node.cleanup_registry.settlePreparedRequest(
            expected.snapshot.reservation.cleanup,
            expected.snapshot.binding_identity,
            expected.canonical,
            terminal,
        ) catch {
            self.failStopSettlement(node, .authority_drift);
            return error.ProtocolError;
        };
        if (terminal) {
            const reason: client_poison.ConnectionReason = .local_invariant_violation;
            if (lease) |held|
                node.client.poisonPreparedRequestExecution(held, reason) catch {
                    self.failStopSettlement(node, .authority_drift);
                    return error.ProtocolError;
                }
            else
                node.client.poison(reason);
            const published_reason = if (lease) |held|
                node.client.preparedRequestExecutionPoisonReason(held) catch
                    return error.ProtocolError
            else
                node.client.firstPoisonReason();
            return self.publishTerminal(published_reason orelse reason);
        }
        return self.publishReusable();
    }

    fn settlePreWireTerminal(
        self: *PreparedExecutionTxn,
        operation: RegisteredNodeOperation,
        reason: client_poison.ConnectionReason,
    ) SettlementError!SettlementOutcome {
        return self.settlePreWireTerminalWithLease(operation, reason, null);
    }

    fn settlePreWireTerminalWithLease(
        self: *PreparedExecutionTxn,
        operation: RegisteredNodeOperation,
        reason: client_poison.ConnectionReason,
        lease: ?*client_mod.PreparedRequestExecutionLease,
    ) SettlementError!SettlementOutcome {
        return self.settlePreWireTerminalWithLeaseImpl(operation, reason, lease, false);
    }

    fn settlePreWireTerminalForDeferredPublication(
        self: *PreparedExecutionTxn,
        operation: RegisteredNodeOperation,
        reason: client_poison.ConnectionReason,
        lease: ?*client_mod.PreparedRequestExecutionLease,
    ) SettlementError!SettlementOutcome {
        return self.settlePreWireTerminalWithLeaseImpl(operation, reason, lease, true);
    }

    fn settlePreWireTerminalWithLeaseImpl(
        self: *PreparedExecutionTxn,
        operation: RegisteredNodeOperation,
        reason: client_poison.ConnectionReason,
        lease: ?*client_mod.PreparedRequestExecutionLease,
        defer_client_terminalization: bool,
    ) SettlementError!SettlementOutcome {
        try self.requireCleanupClosed(operation);
        const expected = self.canonicalExecuting(operation) orelse return error.ProtocolError;
        const abort_result = if (lease) |held|
            expected.node.client.abortPreparedBlockingRpcStorageUnderExecutionLease(
                canonicalStorage(expected),
                expected.snapshot.prepared_identity,
                held,
            )
        else
            expected.node.client.abortPreparedBlockingRpcStorageCanonical(
                canonicalStorage(expected),
                expected.snapshot.prepared_identity,
            );
        _ = abort_result catch {
            self.failStopAfterCallbackDrift(operation, expected, .backing_ambiguous);
            return error.ProtocolError;
        };
        const node = self.canonicalStillExact(operation, expected) orelse {
            self.failStopAfterCallbackDrift(operation, expected, .authority_drift);
            return error.ProtocolError;
        };
        self.phase = .post_execute_backing_settled;
        node.cleanup_registry.settlePreparedRequest(
            expected.snapshot.reservation.cleanup,
            expected.snapshot.binding_identity,
            expected.canonical,
            true,
        ) catch {
            self.failStopSettlement(node, .authority_drift);
            return error.ProtocolError;
        };
        if (!defer_client_terminalization) {
            if (lease) |held|
                node.client.poisonPreparedRequestExecution(held, reason) catch {
                    self.failStopSettlement(node, .authority_drift);
                    return error.ProtocolError;
                }
            else
                node.client.poison(reason);
        }
        const published_reason = if (defer_client_terminalization)
            reason
        else if (lease) |held|
            (node.client.preparedRequestExecutionPoisonReason(held) catch
                return error.ProtocolError) orelse reason
        else
            node.client.firstPoisonReason() orelse reason;
        return self.publishTerminal(published_reason);
    }

    fn retireIssuerExhausted(self: *PreparedExecutionTxn, operation: RegisteredNodeOperation) SettlementError!SettlementOutcome {
        try self.requireCleanupClosed(operation);
        const expected = self.canonicalExecuting(operation) orelse return error.ProtocolError;
        const abort_outcome = expected.node.client.abortPreparedBlockingRpcStorageCanonical(
            canonicalStorage(expected),
            expected.snapshot.prepared_identity,
        ) catch {
            self.failStopAfterCallbackDrift(operation, expected, .backing_ambiguous);
            return error.ProtocolError;
        };
        const node = self.canonicalStillExact(operation, expected) orelse {
            self.failStopAfterCallbackDrift(operation, expected, .authority_drift);
            return error.ProtocolError;
        };
        self.phase = .post_execute_backing_settled;
        node.cleanup_registry.settlePreparedRequest(
            expected.snapshot.reservation.cleanup,
            expected.snapshot.binding_identity,
            expected.canonical,
            true,
        ) catch {
            self.failStopSettlement(node, .authority_drift);
            return error.ProtocolError;
        };
        node.client.poison(.local_invariant_violation);
        const outcome = self.publishTerminal(node.client.firstPoisonReason().?);
        if (abort_outcome == .terminal) return error.ProtocolError;
        return outcome;
    }

    fn settlePostExecuteReusable(self: *PreparedExecutionTxn, operation: RegisteredNodeOperation) SettlementError!SettlementOutcome {
        try self.requireCleanupClosed(operation);
        return self.settlePostExecuteReusableUnchecked(operation);
    }

    fn settlePostExecuteReusableUnderPublicationScope(
        self: *PreparedExecutionTxn,
        operation: RegisteredNodeOperation,
    ) SettlementError!SettlementOutcome {
        const node = self.ownerNode(operation) orelse return error.ProtocolError;
        if (!node.guarded_allocator.operation_guard_active) return error.ProtocolError;
        return self.settlePostExecuteReusableUnchecked(operation);
    }

    fn settlePostExecuteReusableUnchecked(
        self: *PreparedExecutionTxn,
        operation: RegisteredNodeOperation,
    ) SettlementError!SettlementOutcome {
        const expected = self.postExecuteReady(operation) orelse return error.ProtocolError;
        const node = expected.node;
        self.phase = .post_execute_backing_settled;
        node.cleanup_registry.settlePreparedRequest(
            expected.snapshot.reservation.cleanup,
            expected.snapshot.binding_identity,
            expected.canonical,
            false,
        ) catch {
            self.failStopSettlement(node, .authority_drift);
            return error.ProtocolError;
        };
        return self.publishReusable();
    }

    fn settlePostExecuteTerminal(
        self: *PreparedExecutionTxn,
        operation: RegisteredNodeOperation,
        fallback_reason: client_poison.ConnectionReason,
    ) SettlementError!SettlementOutcome {
        return self.settlePostExecuteTerminalWithLease(operation, fallback_reason, null);
    }

    fn settlePostExecuteTerminalWithLease(
        self: *PreparedExecutionTxn,
        operation: RegisteredNodeOperation,
        fallback_reason: client_poison.ConnectionReason,
        lease: ?*client_mod.PreparedRequestExecutionLease,
    ) SettlementError!SettlementOutcome {
        try self.requireCleanupClosed(operation);
        const expected = self.postExecuteReady(operation) orelse return error.ProtocolError;
        if (lease) |held|
            expected.node.client.poisonPreparedRequestExecution(held, fallback_reason) catch
                return error.ProtocolError
        else
            expected.node.client.poison(fallback_reason);
        const node = self.canonicalStillExact(operation, expected) orelse {
            self.failStopAfterCallbackDrift(operation, expected, .authority_drift);
            return error.ProtocolError;
        };
        const observed_reason = if (lease) |held|
            node.client.preparedRequestExecutionPoisonReason(held) catch
                return error.ProtocolError
        else
            node.client.firstPoisonReason();
        const canonical_reason = observed_reason orelse {
            self.failStopAfterCallbackDrift(operation, expected, .authority_drift);
            return error.ProtocolError;
        };
        self.phase = .post_execute_backing_settled;
        node.cleanup_registry.settlePreparedRequest(
            expected.snapshot.reservation.cleanup,
            expected.snapshot.binding_identity,
            expected.canonical,
            true,
        ) catch {
            self.failStopSettlement(node, .authority_drift);
            return error.ProtocolError;
        };
        return self.publishTerminal(canonical_reason);
    }

    /// Cleanup failure is process-fatal, so do not touch possibly ambiguous request backing.
    /// Retire only the canonical registry authority, poison the connection, and publish a closed
    /// fail-stop settlement before the caller panics.
    fn failStopCleanupFailure(
        self: *PreparedExecutionTxn,
        operation: RegisteredNodeOperation,
    ) SettlementOutcome {
        const node = self.ownerNode(operation) orelse
            failStopPreparedExecution(.authority_drift);
        var authority_terminal = false;
        if (self.phase == .pre_wire_backing_live) {
            const canonical = node.cleanup_registry.executingRequestForReceipt(
                self.reservation.cleanup,
                self.binding_identity,
                self.canonical_prepared.transport_addr,
                self.canonical_prepared.transport_incarnation,
                self.canonical_prepared.receipt,
            ) catch null;
            if (canonical != null and std.meta.eql(canonical.?, self.canonical_prepared)) {
                authority_terminal = blk: {
                    node.cleanup_registry.settlePreparedRequest(
                        self.reservation.cleanup,
                        self.binding_identity,
                        self.canonical_prepared,
                        true,
                    ) catch break :blk false;
                    break :blk true;
                };
            }
        }
        node.client.poison(.local_invariant_violation);
        self.settlement = PreparedExecutionSettlement.failStop(.cleanup_failure);
        self.phase = .settled;
        if (builtin.is_test and c.getenv("MARU_SESSION_HOST_RESPONSE_ALIAS_EXEC") != null and
            c.getenv("MARU_SESSION_HOST_RESPONSE_ALIAS_CASE") != null)
        {
            if (!authority_terminal or
                !node.guarded_allocator.request_free_test_observer.cleanup_drift_consumed)
                @panic("B3 strict cleanup terminal publication was not observed");
            const marker = "B3_CLEANUP_AUTHORITY_TERMINAL\n";
            _ = c.write(2, marker.ptr, marker.len);
        }
        return .{ .fail_stop_required = .cleanup_failure };
    }

    fn requireCleanupClosed(self: *PreparedExecutionTxn, operation: RegisteredNodeOperation) SettlementError!void {
        const node = self.ownerNode(operation) orelse return error.ProtocolError;
        if (node.guarded_allocator.operation_guard_active) {
            const outcome = self.failStopCleanupFailure(operation);
            self.finishOrFailStop(operation, outcome);
        }
    }

    fn finishOrFailStop(self: *PreparedExecutionTxn, operation: RegisteredNodeOperation, outcome: SettlementOutcome) void {
        if (self.ownerNode(operation) == null or self.phase != .settled or
            !settlementMatchesOutcome(self.settlement, outcome))
            @panic("prepared execution transaction finish drifted");
        switch (outcome) {
            .reusable, .terminal => {},
            .fail_stop_required => |reason| failStopPreparedExecution(reason),
        }
    }

    fn ensureSettledOrFailStop(self: *PreparedExecutionTxn, operation: RegisteredNodeOperation) void {
        if (self.self_addr == 0) {
            if (self.semanticPristine()) return;
            failStopPreparedExecution(.authority_drift);
        }
        if (self.ownerNode(operation) == null) @panic("prepared execution transaction moved, copied, or outlived its operation");
        if (self.phase == .settled) {
            if (!self.settlement.rawValid()) @panic("prepared execution transaction settlement corrupt");
            return switch (self.settlement.tag) {
                .reusable, .terminal => {},
                .pending => @panic("prepared execution transaction settled pending"),
                .fail_stop_required => failStopPreparedExecution(self.settlement.failStopReason().?),
            };
        }
        if (self.phase == .prepared_unbegun) {
            self.settlement = PreparedExecutionSettlement.reusable();
            self.phase = .settled;
            return;
        }
        _ = self.retireIssuerExhausted(operation) catch
            failStopPreparedExecution(.backing_ambiguous);
        failStopPreparedExecution(.duplicate_settlement);
    }

    fn rawTagsValid(self: *const PreparedExecutionTxn) bool {
        const phase_raw = @as(*const u8, @ptrCast(&self.phase)).*;
        return phase_raw <= @intFromEnum(PreparedExecutionPhase.settled) and
            self.settlement.rawValid() and self.rawEmbeddedTagsValid();
    }

    fn rawEmbeddedTagsValid(self: *const PreparedExecutionTxn) bool {
        return contract.attachmentRoleRawValid(&self.reservation.identity.role) and
            contract.attachmentRoleRawValid(&self.binding_identity.role) and
            contract.attachmentRoleRawValid(&self.canonical_prepared.binding.role) and
            contract.runtimeRequestTagRawValid(&self.canonical_prepared.tag) and
            contract.requestFamilyRawValid(&self.canonical_prepared.family);
    }

    fn semanticPristine(self: *const PreparedExecutionTxn) bool {
        return self.rawTagsValid() and self.self_addr == 0 and self.node_addr == 0 and
            self.operation_id == 0 and self.phase == .prepared_unbegun and
            self.settlement.pendingExact() and
            std.meta.eql(self.reservation, std.mem.zeroes(AttachmentBindingReservation)) and
            std.meta.eql(self.binding_identity, std.mem.zeroes(contract.BindingIdentity)) and
            std.meta.eql(self.canonical_prepared, std.mem.zeroes(prepared_request_authority.Prepared)) and
            std.meta.eql(self.prepared_identity, std.mem.zeroes(client_mod.PreparedBlockingRpcIdentity));
    }

    fn ownerNode(self: *const PreparedExecutionTxn, operation: RegisteredNodeOperation) ?*ClientNode {
        if (!self.rawTagsValid() or self.self_addr != @intFromPtr(self) or
            self.operation_id == 0 or self.operation_id != operation.operation_id)
            return null;
        if (!self.binding_identity.valid() or !self.reservation.identity.valid() or
            !self.canonical_prepared.valid())
            return null;
        const node = resolveRegisteredNodeOperation(operation) orelse return null;
        if (self.node_addr == @intFromPtr(node) and
            std.meta.eql(self.reservation.identity, self.binding_identity) and
            std.meta.eql(self.canonical_prepared.binding, self.binding_identity) and
            std.meta.eql(self.prepared_identity, identityFromCanonical(self.canonical_prepared)))
            return node;
        return null;
    }

    fn snapshot(self: *const PreparedExecutionTxn) PreparedExecutionSnapshot {
        return .{
            .txn_addr = @intFromPtr(self),
            .node_addr = self.node_addr,
            .operation_id = self.operation_id,
            .reservation = self.reservation,
            .binding_identity = self.binding_identity,
            .canonical_prepared = self.canonical_prepared,
            .prepared_identity = self.prepared_identity,
            .phase = self.phase,
            .settlement = self.settlement,
        };
    }

    fn matchesSnapshot(self: *const PreparedExecutionTxn, expected: PreparedExecutionSnapshot) bool {
        return self.rawTagsValid() and expected.txn_addr == @intFromPtr(self) and
            self.self_addr == expected.txn_addr and self.node_addr == expected.node_addr and
            self.operation_id == expected.operation_id and
            std.meta.eql(self.reservation, expected.reservation) and
            std.meta.eql(self.binding_identity, expected.binding_identity) and
            std.meta.eql(self.canonical_prepared, expected.canonical_prepared) and
            std.meta.eql(self.prepared_identity, expected.prepared_identity) and
            self.phase == expected.phase and std.meta.eql(self.settlement, expected.settlement);
    }

    fn canonicalExecuting(
        self: *PreparedExecutionTxn,
        operation: RegisteredNodeOperation,
    ) ?PreparedExecutionCanonical {
        const node = self.ownerNode(operation) orelse return null;
        if (self.phase != .pre_wire_backing_live or !self.settlement.pendingExact()) return null;
        const transcript = self.snapshot();
        const canonical = node.cleanup_registry.executingRequestForReceipt(
            transcript.reservation.cleanup,
            transcript.binding_identity,
            transcript.canonical_prepared.transport_addr,
            transcript.canonical_prepared.transport_incarnation,
            transcript.canonical_prepared.receipt,
        ) catch return null;
        const exact = canonical orelse return null;
        if (!std.meta.eql(exact, transcript.canonical_prepared) or
            !std.meta.eql(identityFromCanonical(exact), transcript.prepared_identity))
            return null;
        return .{ .node = node, .snapshot = transcript, .canonical = exact };
    }

    fn canonicalStillExact(
        self: *PreparedExecutionTxn,
        operation: RegisteredNodeOperation,
        expected: PreparedExecutionCanonical,
    ) ?*ClientNode {
        if (!self.matchesSnapshot(expected.snapshot) or
            operation.operation_id != expected.snapshot.operation_id)
            return null;
        const node = resolveRegisteredNodeOperation(operation) orelse return null;
        if (@intFromPtr(node) != expected.snapshot.node_addr) return null;
        const canonical = node.cleanup_registry.executingRequestForReceipt(
            expected.snapshot.reservation.cleanup,
            expected.snapshot.binding_identity,
            expected.canonical.transport_addr,
            expected.canonical.transport_incarnation,
            expected.canonical.receipt,
        ) catch return null;
        if (canonical == null or !std.meta.eql(canonical.?, expected.canonical)) return null;
        return node;
    }

    fn canonicalStorage(expected: PreparedExecutionCanonical) *client_mod.PreparedBlockingRpcStorage {
        return @ptrFromInt(expected.canonical.descriptor.storage_addr);
    }

    fn postExecuteReady(self: *PreparedExecutionTxn, operation: RegisteredNodeOperation) ?PreparedExecutionCanonical {
        const expected = self.canonicalExecuting(operation) orelse return null;
        if (!client_mod.Client.preparedBlockingRpcStorageSettled(canonicalStorage(expected))) return null;
        return expected;
    }

    fn publishReusable(self: *PreparedExecutionTxn) SettlementOutcome {
        self.settlement = PreparedExecutionSettlement.reusable();
        self.phase = .settled;
        return .reusable;
    }

    fn publishTerminal(
        self: *PreparedExecutionTxn,
        reason: client_poison.ConnectionReason,
    ) SettlementOutcome {
        self.settlement = PreparedExecutionSettlement.terminal(reason);
        self.phase = .settled;
        return .{ .terminal = reason };
    }

    fn failStopSettlement(
        self: *PreparedExecutionTxn,
        node: *ClientNode,
        reason: FailStopReason,
    ) void {
        node.client.poison(.local_invariant_violation);
        self.settlement = PreparedExecutionSettlement.failStop(reason);
        self.phase = .settled;
    }

    fn failStopAfterCallbackDrift(
        self: *PreparedExecutionTxn,
        operation: RegisteredNodeOperation,
        expected: PreparedExecutionCanonical,
        reason: FailStopReason,
    ) void {
        if (operation.operation_id == expected.snapshot.operation_id) {
            if (resolveRegisteredNodeOperation(operation)) |node| {
                if (@intFromPtr(node) == expected.snapshot.node_addr) {
                    const canonical = node.cleanup_registry.executingRequestForReceipt(
                        expected.snapshot.reservation.cleanup,
                        expected.snapshot.binding_identity,
                        expected.canonical.transport_addr,
                        expected.canonical.transport_incarnation,
                        expected.canonical.receipt,
                    ) catch null;
                    if (canonical != null and std.meta.eql(canonical.?, expected.canonical)) {
                        node.cleanup_registry.settlePreparedRequest(
                            expected.snapshot.reservation.cleanup,
                            expected.snapshot.binding_identity,
                            expected.canonical,
                            true,
                        ) catch {};
                    }
                    node.client.poison(.local_invariant_violation);
                }
            }
        }
        self.settlement = PreparedExecutionSettlement.failStop(reason);
        self.phase = .settled;
    }
};

const PreparedRpcExecutionPhase = enum(u8) {
    pristine,
    response_reserved,
    settled,
};

const RpcExecutedResponse = rpc_executed_response.RpcExecutedResponse;

fn responseDestinationSeal(destination_addr: usize) u64 {
    var hash = std.hash.Wyhash.init(0xB303_D357);
    hash.update(std.mem.asBytes(&destination_addr));
    const seal = hash.final();
    return if (seal == 0) 1 else seal;
}

/// B3-3-only composition owner. It adds only the response authority capability; request backing
/// and request-authority settlement remain delegated to PreparedExecutionTxn.
const PreparedRpcExecutionTxn = struct {
    self_addr: usize = 0,
    request: PreparedExecutionTxn = .{},
    response: rpc_response_authority.Canonical = std.mem.zeroes(rpc_response_authority.Canonical),
    response_destination_addr: usize = 0,
    response_destination_seal: u64 = 0,
    phase: PreparedRpcExecutionPhase = .pristine,

    fn initBeforeReserve(
        self: *@This(),
        operation: RegisteredNodeOperation,
        request: GenerationRequestAbort,
        identity: contract.BindingIdentity,
        canonical: prepared_request_authority.Prepared,
        destination: *RpcExecutedResponse,
    ) PreparedExecutionTxn.InitError!void {
        if (self.self_addr != 0 or self.phase != .pristine) return error.InvalidOwner;
        const node = resolveRegisteredNodeOperation(operation) orelse return error.InvalidOwner;
        const owner_entry = registeredNodeOperationOwnerEntry(operation) orelse return error.InvalidOwner;
        const destination_addr = @intFromPtr(destination);
        const destination_len = @sizeOf(RpcExecutedResponse);
        if (byteRangesOverlap(destination_addr, destination_len, @intFromPtr(self), @sizeOf(@This())) or
            byteRangesOverlap(destination_addr, destination_len, @intFromPtr(&operation), @sizeOf(RegisteredNodeOperation)) or
            byteRangesOverlap(destination_addr, destination_len, @intFromPtr(&request), @sizeOf(GenerationRequestAbort)) or
            byteRangesOverlap(destination_addr, destination_len, owner_entry.slot_addr, @sizeOf(ClientSlot)) or
            byteRangesOverlap(destination_addr, destination_len, @intFromPtr(&registered_node_operations[operation.registry_index]), @sizeOf(RegisteredNodeOperationEntry)) or
            byteRangesOverlap(destination_addr, destination_len, @intFromPtr(node), @sizeOf(ClientNode)) or
            byteRangesOverlap(destination_addr, destination_len, canonical.descriptor.storage_addr, @sizeOf(client_mod.PreparedBlockingRpcStorage)) or
            byteRangesOverlap(destination_addr, destination_len, canonical.descriptor.frame_addr, canonical.descriptor.frame_len) or
            byteRangesOverlap(destination_addr, destination_len, canonical.binding.binding_storage_addr, @sizeOf(contract.PreparedAttachmentBinding)) or
            byteRangesOverlap(destination_addr, destination_len, canonical.transport_addr, 1) or
            !destination.pristineExact()) return error.InvalidOwner;
        try self.request.initBeforeBeginExecute(operation, request, identity, canonical);
        self.self_addr = @intFromPtr(self);
        self.response_destination_addr = destination_addr;
        self.response_destination_seal = responseDestinationSeal(destination_addr);
    }

    fn responseDestinationStillPristine(self: *const @This()) bool {
        if (self.self_addr != @intFromPtr(self) or self.response_destination_addr == 0 or
            self.response_destination_seal != responseDestinationSeal(self.response_destination_addr))
            return false;
        const destination: *const RpcExecutedResponse = @ptrFromInt(self.response_destination_addr);
        return destination.pristineExact();
    }

    fn reserveResponse(
        self: *@This(),
        operation: RegisteredNodeOperation,
    ) !void {
        if (self.self_addr != @intFromPtr(self) or self.phase != .pristine)
            return error.InvalidOwner;
        const node = self.request.ownerNode(operation) orelse return error.InvalidOwner;
        self.response = try node.cleanup_registry.reserveRpcResponseExecution(
            self.request.reservation.cleanup,
            self.request.binding_identity,
            self.request.canonical_prepared,
            self.response_destination_addr,
        );
        self.phase = .response_reserved;
    }

    fn settleReserveFailure(
        self: *@This(),
        operation: RegisteredNodeOperation,
        terminal: bool,
    ) !SettlementOutcome {
        if (self.self_addr != @intFromPtr(self) or self.phase != .pristine)
            return error.ProtocolError;
        const outcome = try self.request.settleUnbegun(operation, terminal);
        self.phase = .settled;
        return outcome;
    }

    fn settleReservedUnbegun(
        self: *@This(),
        operation: RegisteredNodeOperation,
        terminal: bool,
    ) !SettlementOutcome {
        if (self.self_addr != @intFromPtr(self) or self.phase != .response_reserved or
            self.request.phase != .prepared_unbegun)
            return error.ProtocolError;
        const outcome = try self.request.settleUnbegun(operation, terminal);
        const node = self.request.ownerNode(operation) orelse return error.ProtocolError;
        switch (outcome) {
            .reusable => try node.cleanup_registry.rollbackRpcResponseExecution(
                self.request.reservation.cleanup,
                self.request.binding_identity,
                self.response,
            ),
            .terminal => try node.cleanup_registry.settleRpcResponseExecutionTerminal(
                self.request.reservation.cleanup,
                self.request.binding_identity,
                self.response,
            ),
            .fail_stop_required => return error.ProtocolError,
        }
        self.phase = .settled;
        return outcome;
    }

    fn settlePreWire(
        self: *@This(),
        operation: RegisteredNodeOperation,
    ) !SettlementOutcome {
        return self.settlePreWireWithLease(operation, null);
    }

    fn settlePreWireWithLease(
        self: *@This(),
        operation: RegisteredNodeOperation,
        lease: ?*client_mod.PreparedRequestExecutionLease,
    ) !SettlementOutcome {
        if (self.self_addr != @intFromPtr(self) or self.phase != .response_reserved)
            return error.ProtocolError;
        const node_before = self.request.ownerNode(operation) orelse return error.ProtocolError;
        const poison_reason = if (lease) |held|
            try node_before.client.preparedRequestExecutionPoisonReason(held)
        else
            node_before.client.firstPoisonReason();
        return self.settlePreWireWithResolvedReason(operation, lease, poison_reason, false);
    }

    fn settlePreWireForDeferredPublication(
        self: *@This(),
        operation: RegisteredNodeOperation,
        lease: ?*client_mod.PreparedRequestExecutionLease,
        poison_reason: ?client_poison.ConnectionReason,
    ) !SettlementOutcome {
        return self.settlePreWireWithResolvedReason(operation, lease, poison_reason, true);
    }

    fn settlePreWireWithResolvedReason(
        self: *@This(),
        operation: RegisteredNodeOperation,
        lease: ?*client_mod.PreparedRequestExecutionLease,
        poison_reason: ?client_poison.ConnectionReason,
        defer_client_terminalization: bool,
    ) !SettlementOutcome {
        if (self.self_addr != @intFromPtr(self) or self.phase != .response_reserved)
            return error.ProtocolError;
        const outcome = if (poison_reason) |reason| if (defer_client_terminalization)
            try self.request.settlePreWireTerminalForDeferredPublication(operation, reason, lease)
        else
            try self.request.settlePreWireTerminalWithLease(operation, reason, lease) else try self.request.rollbackPreWireWithLease(operation, lease);
        const node = self.request.ownerNode(operation) orelse return error.ProtocolError;
        switch (outcome) {
            .reusable => try node.cleanup_registry.rollbackRpcResponseExecution(
                self.request.reservation.cleanup,
                self.request.binding_identity,
                self.response,
            ),
            .terminal => try node.cleanup_registry.settleRpcResponseExecutionTerminal(
                self.request.reservation.cleanup,
                self.request.binding_identity,
                self.response,
            ),
            .fail_stop_required => return error.ProtocolError,
        }
        self.phase = .settled;
        return outcome;
    }

    fn settlePostWriteTerminal(
        self: *@This(),
        operation: RegisteredNodeOperation,
        reason: client_poison.ConnectionReason,
    ) !SettlementOutcome {
        return self.settlePostWriteTerminalWithLease(operation, reason, null);
    }

    fn settlePostWriteTerminalWithLease(
        self: *@This(),
        operation: RegisteredNodeOperation,
        reason: client_poison.ConnectionReason,
        lease: ?*client_mod.PreparedRequestExecutionLease,
    ) !SettlementOutcome {
        if (self.self_addr != @intFromPtr(self) or self.phase != .response_reserved)
            return error.ProtocolError;
        const destination_pristine_before = self.responseDestinationStillPristine();
        const outcome = try self.request.settlePostExecuteTerminalWithLease(
            operation,
            reason,
            lease,
        );
        const node = self.request.ownerNode(operation) orelse return error.ProtocolError;
        try node.cleanup_registry.settleRpcResponseExecutionTerminal(
            self.request.reservation.cleanup,
            self.request.binding_identity,
            self.response,
        );
        self.phase = .settled;
        if (!destination_pristine_before or !self.responseDestinationStillPristine()) {
            node.client.poison(.local_invariant_violation);
            return error.ProtocolError;
        }
        const destination: *RpcExecutedResponse = @ptrFromInt(self.response_destination_addr);
        destination.terminalNoFreeInPlace(
            rpcOwnerIdentity(self.response),
            rpcTerminalEvidence(self.response, reason),
        ) catch {
            node.client.poison(.local_invariant_violation);
            return error.ProtocolError;
        };
        return outcome;
    }

    fn settleRecoveredTerminal(
        self: *@This(),
        operation: RegisteredNodeOperation,
        reason: client_poison.ConnectionReason,
    ) !SettlementOutcome {
        if (self.self_addr != @intFromPtr(self) or self.phase != .response_reserved or
            !self.responseDestinationStillPristine() or self.request.phase != .pre_wire_backing_live or
            !self.request.settlement.pendingExact()) return error.ProtocolError;
        const node = self.request.ownerNode(operation) orelse return error.ProtocolError;
        const storage: *const client_mod.PreparedBlockingRpcStorage =
            @ptrFromInt(self.request.canonical_prepared.descriptor.storage_addr);
        if (!client_mod.Client.preparedBlockingRpcStorageSettled(storage) or
            !node.cleanup_registry.rpcExecutionRecoveryTerminalExact(
                self.request.reservation.cleanup,
                self.request.binding_identity,
            )) return error.ProtocolError;
        self.request.phase = .post_execute_backing_settled;
        const outcome = self.request.publishTerminal(reason);
        self.phase = .settled;
        return outcome;
    }

    fn ensureSettledOrFailStop(
        self: *@This(),
        operation: RegisteredNodeOperation,
    ) void {
        if (self.self_addr == 0) {
            if (self.phase == .pristine and self.request.semanticPristine() and
                self.response_destination_addr == 0 and self.response_destination_seal == 0)
                return;
            failStopPreparedExecution(.authority_drift);
        }
        if (self.self_addr != @intFromPtr(self) or self.request.ownerNode(operation) == null)
            failStopPreparedExecution(.authority_drift);
        if (self.phase == .settled) {
            self.request.ensureSettledOrFailStop(operation);
            return;
        }
        const outcome = switch (self.phase) {
            .pristine => self.settleReserveFailure(operation, false) catch
                failStopPreparedExecution(.cleanup_failure),
            .response_reserved => switch (self.request.phase) {
                .prepared_unbegun => self.settleReservedUnbegun(operation, false) catch
                    failStopPreparedExecution(.cleanup_failure),
                .pre_wire_backing_live => blk: {
                    const storage: *const client_mod.PreparedBlockingRpcStorage =
                        @ptrFromInt(self.request.canonical_prepared.descriptor.storage_addr);
                    if (client_mod.Client.preparedBlockingRpcStorageSettled(storage))
                        break :blk self.settlePostWriteTerminal(
                            operation,
                            self.request.ownerNode(operation).?.client.firstPoisonReason() orelse
                                .local_invariant_violation,
                        ) catch failStopPreparedExecution(.cleanup_failure);
                    break :blk self.settlePreWire(operation) catch
                        failStopPreparedExecution(.cleanup_failure);
                },
                .post_execute_backing_settled, .settled => failStopPreparedExecution(.duplicate_settlement),
            },
            .settled => unreachable,
        };
        self.request.finishOrFailStop(operation, outcome);
    }
};

fn rpcOwnerIdentity(canonical: rpc_response_authority.Canonical) rpc_executed_response.Identity {
    return .{
        .authority_addr = canonical.authority_addr,
        .registry_incarnation = canonical.registry_incarnation,
        .binding = canonical.binding,
        .transport_addr = canonical.transport_addr,
        .transport_incarnation = canonical.transport_incarnation,
        .family = canonical.family,
        .tag = canonical.tag,
        .request_id = canonical.request_id,
        .request_digest = canonical.request_digest,
        .response_epoch = canonical.response_epoch,
        .destination_addr = canonical.destination_addr,
    };
}

fn rpcAuthorityCanonical(identity: rpc_executed_response.Identity) rpc_response_authority.Canonical {
    return .{
        .authority_addr = identity.authority_addr,
        .registry_incarnation = identity.registry_incarnation,
        .binding = identity.binding,
        .transport_addr = identity.transport_addr,
        .transport_incarnation = identity.transport_incarnation,
        .family = identity.family,
        .tag = identity.tag,
        .request_id = identity.request_id,
        .request_digest = identity.request_digest,
        .response_epoch = identity.response_epoch,
        .destination_addr = identity.destination_addr,
    };
}

fn rpcTerminalEvidence(
    canonical: rpc_response_authority.Canonical,
    reason: client_poison.ConnectionReason,
) owner_seal.Digest {
    var writer = owner_seal.Writer.init("maru.rpc-response-publication-terminal.v1");
    writer.writeU64(canonical.registry_incarnation);
    writer.writeUsize(canonical.transport_addr);
    writer.writeU64(canonical.transport_incarnation);
    writer.writeU64(canonical.request_id);
    writer.writeU64(canonical.request_digest);
    writer.writeU64(canonical.response_epoch);
    writer.writeUsize(canonical.destination_addr);
    writer.writeU8(@intFromEnum(reason));
    return writer.finish();
}

fn identityFromCanonical(
    canonical: prepared_request_authority.Prepared,
) client_mod.PreparedBlockingRpcIdentity {
    return .{
        .request_id = canonical.receipt.request_id,
        .frame_digest = canonical.receipt.request_digest,
        .descriptor = canonical.descriptor,
    };
}

fn settlementMatchesOutcome(
    settlement: PreparedExecutionSettlement,
    outcome: SettlementOutcome,
) bool {
    if (!settlement.rawValid()) return false;
    return switch (settlement.tag) {
        .pending => false,
        .reusable => outcome == .reusable,
        .terminal => switch (outcome) {
            .terminal => |other| settlement.terminalReason().? == other,
            else => false,
        },
        .fail_stop_required => switch (outcome) {
            .fail_stop_required => |other| settlement.failStopReason().? == other,
            else => false,
        },
    };
}

fn failStopPreparedExecution(reason: FailStopReason) noreturn {
    switch (reason) {
        .authority_drift => @panic("prepared execution transaction authority drift"),
        .backing_ambiguous => @panic("prepared execution transaction backing ambiguous"),
        .duplicate_settlement => @panic("prepared execution transaction duplicate settlement"),
        .cleanup_failure => @panic("prepared execution transaction cleanup failed"),
    }
}

const ResponsePayloadObserverBridge = struct {
    ledger: *response_payload_allocation.Ledger,
    guard: *GenerationGuardedAllocator,

    fn observer(self: *@This()) framing.PayloadAllocationObserver {
        return .{
            .context = self,
            .reserve_fn = reserve,
            .commit_fn = commit,
            .abort_fn = abort,
            .discard_fn = discard,
        };
    }

    fn reserve(
        context: *anyopaque,
        len: usize,
        allocator: std.mem.Allocator,
    ) error{ OutOfMemory, IdentityExhausted, ProtocolError }!u64 {
        const self: *@This() = @ptrCast(@alignCast(context));
        return self.ledger.reserveObserved(len, allocator) catch |err| switch (err) {
            error.IdentityExhausted => error.IdentityExhausted,
            error.ObservationBusy => error.ProtocolError,
            else => error.ProtocolError,
        };
    }

    fn commit(
        context: *anyopaque,
        generation: u64,
        payload: []u8,
        allocator: std.mem.Allocator,
    ) error{ProtocolError}!void {
        const self: *@This() = @ptrCast(@alignCast(context));
        self.ledger.commitObserved(generation, payload, allocator) catch
            return error.ProtocolError;
        if (builtin.is_test) {
            self.guard.request_free_test_observer.response_payload_addr = @intFromPtr(payload.ptr);
            self.guard.request_free_test_observer.response_payload_len = payload.len;
        }
    }

    fn abort(context: *anyopaque, generation: u64) void {
        const self: *@This() = @ptrCast(@alignCast(context));
        self.ledger.abortObserved(generation) catch
            @panic("response payload observer abort drifted");
    }

    fn discard(context: *anyopaque, generation: u64) void {
        const self: *@This() = @ptrCast(@alignCast(context));
        self.ledger.discardObserved(generation) catch
            @panic("response payload observer discard drifted");
    }
};

const PreparedRpcPublicationScope = struct {
    self_addr: usize = 0,
    allocator_scope: client_mod.Client.GenerationAllocatorScope = .{},
    ledger: response_payload_allocation.Ledger = .{},
    bridge: ResponsePayloadObserverBridge = undefined,
    publish_permit: rpc_response_authority.PreparedRpcTransitionPermit = .{},
    guard_active: bool = false,
    allocator_active: bool = false,
    ledger_active: bool = false,

    fn begin(
        self: *@This(),
        node: *ClientNode,
        operation: RegisteredNodeOperation,
        request: GenerationRequestAbort,
        destination: *RpcExecutedResponse,
        txn: *PreparedRpcExecutionTxn,
        lease: *client_mod.PreparedRequestExecutionLease,
        payload_cleanup: *RpcPublicationPayloadCleanup,
        storage: *client_mod.PreparedBlockingRpcStorage,
    ) !void {
        if (self.self_addr != 0 or self.guard_active or self.allocator_active or self.ledger_active)
            return error.InvalidOwner;
        self.self_addr = @intFromPtr(self);
        const guard = &node.guarded_allocator;
        const ranges = [_]GenerationGuardedAllocator.OperationRangeInput{
            .{ .start = @intFromPtr(self), .len = @sizeOf(@This()) },
            .{ .start = @intFromPtr(destination), .len = @sizeOf(RpcExecutedResponse) },
            .{ .start = @intFromPtr(txn), .len = @sizeOf(PreparedRpcExecutionTxn) },
            .{ .start = @intFromPtr(lease), .len = @sizeOf(client_mod.PreparedRequestExecutionLease) },
            .{ .start = @intFromPtr(payload_cleanup), .len = @sizeOf(RpcPublicationPayloadCleanup) },
            .{ .start = @intFromPtr(storage), .len = @sizeOf(client_mod.PreparedBlockingRpcStorage) },
            .{ .start = @intFromPtr(node), .len = @sizeOf(ClientNode) },
            .{ .start = request.slot_addr, .len = @sizeOf(ClientSlot) },
            .{ .start = request.reservation.identity.binding_storage_addr, .len = @sizeOf(contract.PreparedAttachmentBinding) },
            .{ .start = txn.request.canonical_prepared.descriptor.frame_addr, .len = txn.request.canonical_prepared.descriptor.frame_len },
            .{ .start = request.transport_addr, .len = 1 },
        };
        if (!guard.beginOperationGuard(&ranges)) {
            self.* = .{};
            return error.InvalidOwner;
        }
        self.guard_active = true;
        node.client.beginGenerationAllocatorScope(
            guard.allocator(),
            .rpc_execute,
            &self.allocator_scope,
        ) catch |err| {
            guard.endOperationGuard();
            self.* = .{};
            return err;
        };
        self.allocator_active = true;
        response_payload_allocation.Ledger.initInPlace(
            &self.ledger,
            guard.allocator(),
            .{
                .guard_addr = @intFromPtr(guard),
                .node_addr = @intFromPtr(node),
                .operation_incarnation = operation.operation_id,
            },
            1,
        ) catch |err| {
            node.client.restoreGenerationAllocatorScope(&self.allocator_scope) catch
                @panic("RPC publication allocator scope rollback drifted");
            guard.endOperationGuard();
            self.* = .{};
            return err;
        };
        self.ledger_active = true;
        self.bridge = .{
            .ledger = &self.ledger,
            .guard = guard,
        };
        if (builtin.is_test) {
            const test_observer = &guard.request_free_test_observer;
            test_observer.rpc_publication_txn_addr = @intFromPtr(txn);
            test_observer.rpc_publication_lease_addr = @intFromPtr(lease);
            test_observer.rpc_publication_scope_addr = @intFromPtr(self);
        }
        const forbidden = [_]response_payload_allocation.ForbiddenRange{
            .{ .start = @intFromPtr(self), .len = @sizeOf(@This()) },
            .{ .start = @intFromPtr(destination), .len = @sizeOf(RpcExecutedResponse) },
            .{ .start = @intFromPtr(txn), .len = @sizeOf(PreparedRpcExecutionTxn) },
            .{ .start = @intFromPtr(lease), .len = @sizeOf(client_mod.PreparedRequestExecutionLease) },
            .{ .start = @intFromPtr(payload_cleanup), .len = @sizeOf(RpcPublicationPayloadCleanup) },
            .{ .start = @intFromPtr(storage), .len = @sizeOf(client_mod.PreparedBlockingRpcStorage) },
            .{ .start = @intFromPtr(node), .len = @sizeOf(ClientNode) },
            .{ .start = request.slot_addr, .len = @sizeOf(ClientSlot) },
            .{ .start = request.reservation.identity.binding_storage_addr, .len = @sizeOf(contract.PreparedAttachmentBinding) },
            .{ .start = txn.request.canonical_prepared.descriptor.frame_addr, .len = txn.request.canonical_prepared.descriptor.frame_len },
            .{ .start = request.transport_addr, .len = 1 },
        };
        self.ledger.bindForbiddenRanges(&forbidden) catch {
            self.finish(node, null);
            return error.InvalidOwner;
        };
    }

    fn afterRequestWrite(
        self: *@This(),
        node: *ClientNode,
        request: GenerationRequestAbort,
        destination: *RpcExecutedResponse,
        txn: *PreparedRpcExecutionTxn,
        lease: *client_mod.PreparedRequestExecutionLease,
        payload_cleanup: *RpcPublicationPayloadCleanup,
        storage: *client_mod.PreparedBlockingRpcStorage,
    ) void {
        if (self.self_addr == 0) return;
        if (!self.liveExact(node))
            @panic("RPC publication response-phase rebind drifted");

        // The request frame is settled by the successful write. Keeping its former heap
        // range guarded would reject a valid response allocation that reuses that address.
        node.guarded_allocator.endOperationGuard();
        self.guard_active = false;
        const ranges = [_]GenerationGuardedAllocator.OperationRangeInput{
            .{ .start = @intFromPtr(self), .len = @sizeOf(@This()) },
            .{ .start = @intFromPtr(destination), .len = @sizeOf(RpcExecutedResponse) },
            .{ .start = @intFromPtr(txn), .len = @sizeOf(PreparedRpcExecutionTxn) },
            .{ .start = @intFromPtr(lease), .len = @sizeOf(client_mod.PreparedRequestExecutionLease) },
            .{ .start = @intFromPtr(payload_cleanup), .len = @sizeOf(RpcPublicationPayloadCleanup) },
            .{ .start = @intFromPtr(storage), .len = @sizeOf(client_mod.PreparedBlockingRpcStorage) },
            .{ .start = @intFromPtr(node), .len = @sizeOf(ClientNode) },
            .{ .start = request.slot_addr, .len = @sizeOf(ClientSlot) },
            .{ .start = request.reservation.identity.binding_storage_addr, .len = @sizeOf(contract.PreparedAttachmentBinding) },
            .{ .start = request.transport_addr, .len = 1 },
        };
        if (!node.guarded_allocator.beginOperationGuard(&ranges))
            @panic("RPC publication response-phase guard rebind failed");
        self.guard_active = true;
        const forbidden = [_]response_payload_allocation.ForbiddenRange{
            .{ .start = @intFromPtr(self), .len = @sizeOf(@This()) },
            .{ .start = @intFromPtr(destination), .len = @sizeOf(RpcExecutedResponse) },
            .{ .start = @intFromPtr(txn), .len = @sizeOf(PreparedRpcExecutionTxn) },
            .{ .start = @intFromPtr(lease), .len = @sizeOf(client_mod.PreparedRequestExecutionLease) },
            .{ .start = @intFromPtr(payload_cleanup), .len = @sizeOf(RpcPublicationPayloadCleanup) },
            .{ .start = @intFromPtr(storage), .len = @sizeOf(client_mod.PreparedBlockingRpcStorage) },
            .{ .start = @intFromPtr(node), .len = @sizeOf(ClientNode) },
            .{ .start = request.slot_addr, .len = @sizeOf(ClientSlot) },
            .{ .start = request.reservation.identity.binding_storage_addr, .len = @sizeOf(contract.PreparedAttachmentBinding) },
            .{ .start = request.transport_addr, .len = 1 },
        };
        self.ledger.rebindForbiddenRangesBeforeObservation(&forbidden) catch
            @panic("RPC publication response-phase ledger rebind failed");
    }

    fn observer(self: *@This(), node: *ClientNode) framing.PayloadAllocationObserver {
        if (!self.liveExact(node)) @panic("RPC publication observer scope drifted");
        return self.bridge.observer();
    }

    fn liveExact(self: *const @This(), node: *const ClientNode) bool {
        return self.self_addr == @intFromPtr(self) and self.guard_active and
            self.allocator_active and self.ledger_active and
            node.guarded_allocator.operation_guard_active;
    }

    fn finish(
        self: *@This(),
        node: *ClientNode,
        lease: ?*client_mod.PreparedRequestExecutionLease,
    ) void {
        if (self.self_addr == 0) return;
        if (!self.liveExact(node)) @panic("RPC publication scope finish drifted");
        self.ledger.endOperation() catch
            @panic("RPC publication payload ledger did not settle");
        self.ledger_active = false;
        if (lease) |active_lease|
            node.client.restoreGenerationAllocatorScopeUnderExecutionLease(
                &self.allocator_scope,
                active_lease,
            ) catch @panic("RPC publication allocator scope restore drifted")
        else
            node.client.restoreGenerationAllocatorScope(&self.allocator_scope) catch
                @panic("RPC publication allocator scope restore drifted");
        self.allocator_active = false;
        node.guarded_allocator.endOperationGuard();
        self.guard_active = false;
        self.self_addr = 0;
        if (builtin.is_test) {
            const cleanup_observer = &node.guarded_allocator.request_free_test_observer;
            cleanup_observer.cleanup_count += 1;
            cleanup_observer.guard_inactive = !node.guarded_allocator.operation_guard_active;
            cleanup_observer.allocator_scope_restored = self.allocator_scope.lifecycle == .restored and
                self.allocator_scope.self_addr == 0;
            cleanup_observer.client_scope_restored = node.client.active_generation_allocator_scope == null;
            cleanup_observer.ledger_ended = self.ledger.self_addr == 0 and
                !self.ledger.active and self.ledger.entry_count == 0;
            cleanup_observer.cleanup_settled = true;
        }
    }
};

const RpcPublicationPayloadCleanup = struct {
    self_addr: usize = 0,
    receipt: response_payload_allocation.Receipt = std.mem.zeroes(response_payload_allocation.Receipt),
    failure_release: response_payload_allocation.Ledger.PreparedFailureRelease = .{},
    test_pre_release_stage_drift: if (builtin.is_test) u8 else void = if (builtin.is_test) 0 else {},
    armed: u8 = 0,
    seal: owner_seal.Digest = [_]u8{0} ** 32,

    fn arm(self: *@This(), receipt: response_payload_allocation.Receipt) !void {
        if (self.self_addr != 0 or self.armed != 0 or
            !std.meta.eql(self.receipt, std.mem.zeroes(response_payload_allocation.Receipt)) or
            !self.failure_release.pristineExact() or !std.mem.allEqual(u8, &self.seal, 0) or
            receipt.ledger_addr == 0 or receipt.generation == 0)
            return error.InvalidOwner;
        self.* = .{
            .self_addr = @intFromPtr(self),
            .receipt = receipt,
            .armed = 1,
        };
        self.seal = rpcPublicationPayloadCleanupSeal(self);
    }

    fn takeIfExact(self: *@This()) ?response_payload_allocation.Receipt {
        if (self.self_addr != @intFromPtr(self) or self.armed != 1 or
            !self.failure_release.pristineExact() or
            !std.mem.eql(u8, &self.seal, &rpcPublicationPayloadCleanupSeal(self))) return null;
        const receipt = self.receipt;
        self.* = .{};
        return receipt;
    }
};

fn rpcPublicationPayloadCleanupSeal(cleanup: *const RpcPublicationPayloadCleanup) owner_seal.Digest {
    var writer = owner_seal.Writer.init("maru.rpc-publication-payload-cleanup.v1");
    writer.writeUsize(cleanup.self_addr);
    writer.writeU8(cleanup.armed);
    writer.writeUsize(cleanup.receipt.ledger_addr);
    writer.writeU64(cleanup.receipt.generation);
    writer.writeU16(cleanup.receipt.index);
    writer.writeUsize(cleanup.receipt.addr);
    writer.writeUsize(cleanup.receipt.len);
    writer.writeBool(cleanup.receipt.zero_length);
    return writer.finish();
}

fn rpcPublicationFailureFreeEvidence(
    receipt: response_payload_allocation.Receipt,
    response_epoch: u64,
    reason: response_payload_allocation.PayloadFailStopReason,
) owner_seal.Digest {
    var writer = owner_seal.Writer.init("maru.rpc-publication-failure-free.v1");
    writer.writeU64(response_epoch);
    writer.writeUsize(receipt.ledger_addr);
    writer.writeU64(receipt.generation);
    writer.writeU16(receipt.index);
    writer.writeUsize(receipt.addr);
    writer.writeUsize(receipt.len);
    writer.writeU8(@intFromEnum(reason));
    return writer.finish();
}

const RpcPublicationFailureByteDisposition = enum {
    destination_exact_payload_freed_clean,
    destination_exact_payload_no_free,
    destination_exact_payload_freed_once_drifted,
    destination_invalid_payload_freed_once,
    destination_invalid_payload_no_free,
};

const RpcPublicationFailureByteOutcome = struct {
    disposition: RpcPublicationFailureByteDisposition,
    response_epoch: u64,
    free_evidence: owner_seal.Digest = [_]u8{0} ** 32,
    retire_clean_evidence: bool = false,
};

fn closeRpcPublicationDestinationNoFree(
    destination: *RpcExecutedResponse,
    identity: rpc_executed_response.Identity,
    response: rpc_response_authority.Canonical,
) bool {
    if (destination.pristineExact()) {
        destination.terminalNoFreeInPlace(
            identity,
            rpcTerminalEvidence(response, .local_invariant_violation),
        ) catch return false;
        return true;
    }
    if (destination.liveScalarIdentityExact(identity)) {
        destination.abandonLiveNoFree(identity) catch return false;
        return true;
    }
    return false;
}

fn settleRpcPublicationFailureBytes(
    free_record: *RpcFreeEvidenceRecord,
    payload_cleanup: *RpcPublicationPayloadCleanup,
    response: rpc_response_authority.Canonical,
    reason: response_payload_allocation.PayloadFailStopReason,
) RpcPublicationFailureByteOutcome {
    const test_pre_release_stage_drift = if (builtin.is_test)
        payload_cleanup.test_pre_release_stage_drift
    else
        0;
    const destination: *RpcExecutedResponse = @ptrFromInt(response.destination_addr);
    const identity = rpcOwnerIdentity(response);
    const destination_pristine = destination.pristineExact();
    const destination_live = destination.liveScalarIdentityExact(identity);
    const receipt = payload_cleanup.takeIfExact() orelse {
        if ((destination_pristine or destination_live) and
            closeRpcPublicationDestinationNoFree(destination, identity, response))
        {
            return .{
                .disposition = .destination_exact_payload_no_free,
                .response_epoch = response.response_epoch,
            };
        }
        return .{
            .disposition = .destination_invalid_payload_no_free,
            .response_epoch = response.response_epoch,
        };
    };
    const ledger: *response_payload_allocation.Ledger = @ptrFromInt(receipt.ledger_addr);
    if (!ledger.promotedReceiptExact(receipt) or destination_live) {
        if ((destination_pristine or destination_live) and
            closeRpcPublicationDestinationNoFree(destination, identity, response))
        {
            return .{
                .disposition = .destination_exact_payload_no_free,
                .response_epoch = response.response_epoch,
            };
        }
        return .{
            .disposition = .destination_invalid_payload_no_free,
            .response_epoch = response.response_epoch,
        };
    }
    ledger.preparePromotedFailureRelease(
        receipt,
        &payload_cleanup.failure_release,
    ) catch {
        if (closeRpcPublicationDestinationNoFree(destination, identity, response)) {
            return .{
                .disposition = .destination_exact_payload_no_free,
                .response_epoch = response.response_epoch,
            };
        }
        return .{
            .disposition = .destination_invalid_payload_no_free,
            .response_epoch = response.response_epoch,
        };
    };
    const free_evidence = rpcPublicationFailureFreeEvidence(
        receipt,
        response.response_epoch,
        reason,
    );
    if (!free_record.commitFreeCall(response.response_epoch, free_evidence)) {
        ledger.abandonPreparedFailureNoFree(&payload_cleanup.failure_release);
        if (closeRpcPublicationDestinationNoFree(destination, identity, response)) {
            return .{
                .disposition = .destination_exact_payload_no_free,
                .response_epoch = response.response_epoch,
            };
        }
        return .{
            .disposition = .destination_invalid_payload_no_free,
            .response_epoch = response.response_epoch,
        };
    }
    if (builtin.is_test and test_pre_release_stage_drift != 0)
        @as(*u8, @ptrCast(&payload_cleanup.failure_release.stage)).* = 0xFF;
    const release = ledger.releasePreparedFailure(&payload_cleanup.failure_release);
    if (release == .not_freed) {
        _ = free_record.retireFreeCall(response.response_epoch, free_evidence);
        if (closeRpcPublicationDestinationNoFree(destination, identity, response)) {
            return .{
                .disposition = .destination_exact_payload_no_free,
                .response_epoch = response.response_epoch,
            };
        }
        return .{
            .disposition = .destination_invalid_payload_no_free,
            .response_epoch = response.response_epoch,
        };
    }
    if (release == .freed_clean and destination_pristine and destination.pristineExact()) {
        destination.terminalCleanAfterPublicationFailureInPlace(
            identity,
            rpcTerminalEvidence(response, .local_invariant_violation),
        ) catch {};
        if (destination.terminalExact() and destination.settlement == .terminal_clean)
            return .{
                .disposition = .destination_exact_payload_freed_clean,
                .response_epoch = response.response_epoch,
                .free_evidence = free_evidence,
                .retire_clean_evidence = true,
            };
    }
    _ = free_record.commitTerminalFreedOnce(response.response_epoch, free_evidence);
    return .{
        .disposition = if (destination_pristine)
            .destination_exact_payload_freed_once_drifted
        else
            .destination_invalid_payload_freed_once,
        .response_epoch = response.response_epoch,
        .free_evidence = free_evidence,
    };
}

fn failStopResponsePayloadProvenance(
    reason: response_payload_allocation.PayloadFailStopReason,
) noreturn {
    switch (reason) {
        .allocator_drift => @panic("response payload provenance: allocator drift"),
        .range_overflow => @panic("response payload provenance: range overflow"),
        .owner_alias => @panic("response payload provenance: owner alias"),
        .ledger_drift => @panic("response payload provenance: ledger drift"),
    }
}

fn failStopResponsePayloadTransfer(
    reason: response_payload_allocation.PayloadFailStopReason,
) noreturn {
    switch (reason) {
        .allocator_drift => @panic("response payload transfer: allocator drift"),
        .range_overflow => @panic("response payload transfer: range overflow"),
        .owner_alias => @panic("response payload transfer: owner alias"),
        .ledger_drift => @panic("response payload transfer: ledger drift"),
    }
}

const PreparedExecutionCleanup = struct {
    const CleanupStage = enum(u8) { guard, allocator, ledger };
    const CleanupLifecycle = enum(u8) { pristine, live, finishing, settled, fail_stop };
    const CleanupFailure = enum(u8) { descriptor_drift, reentry, ledger_end, allocator_restore, guard_end };
    const CleanupOutcome = union(enum) { clean, deferred_reentry, fail_stop: CleanupFailure };

    self_addr: usize = 0,
    lifecycle: CleanupLifecycle = .pristine,
    stage: CleanupStage = .guard,
    first_failure_raw: u8 = 0,

    fn init(self: *PreparedExecutionCleanup) void {
        self.* = .{
            .self_addr = @intFromPtr(self),
            .lifecycle = .live,
        };
    }

    fn advance(self: *PreparedExecutionCleanup, from: CleanupStage, to: CleanupStage) bool {
        if (!self.rawValid() or self.self_addr != @intFromPtr(self) or
            self.lifecycle != .live or self.stage != from)
            return false;
        self.stage = to;
        return true;
    }

    fn finish(
        self: *PreparedExecutionCleanup,
        expected_stage: CleanupStage,
        client: *client_mod.Client,
        guard: *GenerationGuardedAllocator,
        allocator_scope: *client_mod.Client.GenerationAllocatorScope,
        payload_ledger: *response_payload_allocation.Ledger,
    ) CleanupOutcome {
        if (builtin.is_test) {
            const observer = &guard.request_free_test_observer;
            switch (observer.cleanup_drift_kind) {
                1 => self.self_addr = 1,
                2 => self.stage = .guard,
                3 => allocator_scope.self_addr = 1,
                4 => guard.operation_guard_active = false,
                5 => payload_ledger.self_addr = 1,
                else => {},
            }
            if (observer.cleanup_drift_kind >= 1 and observer.cleanup_drift_kind <= 5)
                observer.cleanup_drift_consumed = true;
        }
        if (self.rawValid() and self.self_addr == @intFromPtr(self) and
            self.lifecycle == .finishing and
            prepared_execution_cleanup_active_addr == @intFromPtr(self))
        {
            if (self.first_failure_raw == 0)
                self.first_failure_raw = @intFromEnum(CleanupFailure.reentry) + 1;
            return .deferred_reentry;
        }

        var first: ?CleanupFailure = null;
        if (!self.rawValid() or self.self_addr != @intFromPtr(self) or
            self.lifecycle != .live or self.stage != expected_stage or
            self.first_failure_raw != 0)
            first = .descriptor_drift;
        self.self_addr = @intFromPtr(self);
        self.lifecycle = .finishing;
        self.stage = expected_stage;
        self.first_failure_raw = 0;
        const prior_active_addr = prepared_execution_cleanup_active_addr;
        if (prior_active_addr != 0 and first == null) first = .reentry;
        prepared_execution_cleanup_active_addr = @intFromPtr(self);
        defer prepared_execution_cleanup_active_addr = prior_active_addr;
        if (expected_stage == .ledger) {
            payload_ledger.endOperation() catch {
                if (first == null) first = .ledger_end;
            };
            self.revalidateFinishing(expected_stage, &first);
        }
        if (expected_stage == .ledger or expected_stage == .allocator) {
            client.restoreGenerationAllocatorScope(allocator_scope) catch {
                if (first == null) first = .allocator_restore;
            };
            self.revalidateFinishing(expected_stage, &first);
        }
        guard.finishOperationGuard() catch {
            if (first == null) first = .guard_end;
        };
        self.revalidateFinishing(expected_stage, &first);
        if (first) |failure| {
            self.first_failure_raw = @intFromEnum(failure) + 1;
            self.lifecycle = .fail_stop;
            return .{ .fail_stop = failure };
        }
        self.lifecycle = .settled;
        if (builtin.is_test) {
            const observer = &guard.request_free_test_observer;
            observer.cleanup_count += 1;
            observer.guard_inactive = !guard.operation_guard_active;
            observer.allocator_scope_restored =
                allocator_scope.lifecycle == .restored and allocator_scope.self_addr == 0;
            observer.client_scope_restored = client.active_generation_allocator_scope == null;
            observer.ledger_ended = payload_ledger.self_addr == 0 and
                !payload_ledger.active and payload_ledger.entry_count == 0;
            observer.cleanup_settled = self.lifecycle == .settled and self.first_failure_raw == 0;
        }
        return .clean;
    }

    fn finishOrFailStop(
        self: *PreparedExecutionCleanup,
        txn: *PreparedExecutionTxn,
        operation: RegisteredNodeOperation,
        expected_stage: CleanupStage,
        completion: *u8,
        client: *client_mod.Client,
        guard: *GenerationGuardedAllocator,
        allocator_scope: *client_mod.Client.GenerationAllocatorScope,
        payload_ledger: *response_payload_allocation.Ledger,
    ) void {
        switch (self.finish(expected_stage, client, guard, allocator_scope, payload_ledger)) {
            .clean => completion.* = 1,
            .deferred_reentry => return,
            .fail_stop => {
                const outcome = txn.failStopCleanupFailure(operation);
                txn.finishOrFailStop(operation, outcome);
            },
        }
    }

    fn ensureFinishedOrFailStop(
        self: *PreparedExecutionCleanup,
        txn: *PreparedExecutionTxn,
        operation: RegisteredNodeOperation,
        expected_stage: CleanupStage,
        completion: *u8,
        client: *client_mod.Client,
        guard: *GenerationGuardedAllocator,
        allocator_scope: *client_mod.Client.GenerationAllocatorScope,
        payload_ledger: *response_payload_allocation.Ledger,
    ) void {
        if (completion.* == 1 and self.rawValid() and self.self_addr == @intFromPtr(self) and
            self.lifecycle == .settled and self.stage == expected_stage and self.first_failure_raw == 0)
            return;
        self.finishOrFailStop(txn, operation, expected_stage, completion, client, guard, allocator_scope, payload_ledger);
    }

    fn revalidateFinishing(
        self: *PreparedExecutionCleanup,
        expected_stage: CleanupStage,
        first: *?CleanupFailure,
    ) void {
        if (!self.rawValid() or self.self_addr != @intFromPtr(self) or
            self.lifecycle != .finishing or self.stage != expected_stage)
        {
            if (first.* == null) first.* = .descriptor_drift;
            self.self_addr = @intFromPtr(self);
            self.lifecycle = .finishing;
            self.stage = expected_stage;
        }
        if (self.first_failure_raw != 0) {
            const raw = self.first_failure_raw - 1;
            if (raw < std.meta.fields(CleanupFailure).len and first.* == null)
                first.* = @enumFromInt(raw);
            self.first_failure_raw = 0;
        }
    }

    fn rawValid(self: *const PreparedExecutionCleanup) bool {
        const lifecycle_raw = @as(*const u8, @ptrCast(&self.lifecycle)).*;
        const stage_raw = @as(*const u8, @ptrCast(&self.stage)).*;
        return lifecycle_raw <= @intFromEnum(CleanupLifecycle.fail_stop) and
            stage_raw <= @intFromEnum(CleanupStage.ledger) and
            self.first_failure_raw <= std.meta.fields(CleanupFailure).len;
    }
};

const ExecutionSettlementIntent = union(enum) {
    rollback_pre_wire,
    issuer_exhausted,
    post_execute_reusable,
    post_execute_terminal: client_poison.ConnectionReason,
};

fn settleExecutionAfterCleanup(
    cleanup: *PreparedExecutionCleanup,
    txn: *PreparedExecutionTxn,
    operation: RegisteredNodeOperation,
    expected_stage: PreparedExecutionCleanup.CleanupStage,
    completion: *u8,
    client: *client_mod.Client,
    guard: *GenerationGuardedAllocator,
    allocator_scope: *client_mod.Client.GenerationAllocatorScope,
    payload_ledger: *response_payload_allocation.Ledger,
    intent: ExecutionSettlementIntent,
) PreparedExecutionTxn.SettlementError!SettlementOutcome {
    cleanup.finishOrFailStop(
        txn,
        operation,
        expected_stage,
        completion,
        client,
        guard,
        allocator_scope,
        payload_ledger,
    );
    const outcome = switch (intent) {
        .rollback_pre_wire => try txn.rollbackPreWire(operation),
        .issuer_exhausted => try txn.retireIssuerExhausted(operation),
        .post_execute_reusable => try txn.settlePostExecuteReusable(operation),
        .post_execute_terminal => |reason| try txn.settlePostExecuteTerminal(operation, reason),
    };
    txn.finishOrFailStop(operation, outcome);
    return outcome;
}

fn finishPreparedRpcLeaseOrFailStop(
    node: *ClientNode,
    lease: *client_mod.PreparedRequestExecutionLease,
    txn: *PreparedRpcExecutionTxn,
    operation: RegisteredNodeOperation,
) void {
    node.client.finishPreparedRequestExecution(lease) catch {
        node.client.poison(.local_invariant_violation);
        txn.ensureSettledOrFailStop(operation);
        failStopPreparedExecution(.cleanup_failure);
    };
}

fn settlePreparedRpcLeaseOwnedAndReleaseOrFailStop(
    node: *ClientNode,
    lease: *client_mod.PreparedRequestExecutionLease,
    txn: *PreparedRpcExecutionTxn,
    operation: RegisteredNodeOperation,
) void {
    const poison_reason = node.client.preparedRequestExecutionPoisonReason(lease) catch
        failStopPreparedExecution(.authority_drift);
    settlePreparedRpcLeaseOwnedWithReasonAndReleaseOrFailStop(
        node,
        lease,
        txn,
        operation,
        poison_reason,
    );
}

fn settlePreparedRpcLeaseOwnedWithReasonAndReleaseOrFailStop(
    node: *ClientNode,
    lease: *client_mod.PreparedRequestExecutionLease,
    txn: *PreparedRpcExecutionTxn,
    operation: RegisteredNodeOperation,
    poison_reason: ?client_poison.ConnectionReason,
) void {
    const storage: *const client_mod.PreparedBlockingRpcStorage =
        @ptrFromInt(txn.request.canonical_prepared.descriptor.storage_addr);
    const outcome = if (client_mod.Client.preparedBlockingRpcStorageSettled(storage))
        txn.settlePostWriteTerminalWithLease(
            operation,
            poison_reason orelse .local_invariant_violation,
            lease,
        ) catch failStopPreparedExecution(.cleanup_failure)
    else
        txn.settlePreWireForDeferredPublication(operation, lease, poison_reason) catch
            failStopPreparedExecution(.cleanup_failure);
    txn.request.finishOrFailStop(operation, outcome);
    finishPreparedRpcLeaseOrFailStop(node, lease, txn, operation);
}

fn finalizePreparedExecutionPoisonCaptureNoFail(
    request: GenerationRequestAbort,
    operation: RegisteredNodeOperation,
    node: *ClientNode,
    lease: *client_mod.PreparedRequestExecutionLease,
    capture: *incident_publication_contract.PreparedExecutionPoisonCapture,
) bool {
    const lifecycle = std.enums.fromInt(
        incident_publication_contract.PreparedExecutionPoisonCaptureLifecycle,
        capture.lifecycle_raw,
    ) orelse failStopPreparedExecution(.authority_drift);
    if (lifecycle == .armed) return false;
    if (lifecycle != .captured or capture.operation_id != operation.operation_id or
        capture.client_addr != @intFromPtr(&node.client) or
        capture.lease_addr != @intFromPtr(lease) or
        std.enums.fromInt(connection_incident.SourceSite, capture.source_site_raw) == null or
        capture.allocator_source_site_raw != lease.poison_allocator_source_site_raw)
        failStopPreparedExecution(.authority_drift);
    const reason = (node.client.preparedRequestExecutionPoisonReason(lease) catch
        failStopPreparedExecution(.authority_drift)) orelse
        failStopPreparedExecution(.authority_drift);
    if (capture.reason_raw != @intFromEnum(reason))
        failStopPreparedExecution(.authority_drift);
    const slot: *ClientSlot = @ptrFromInt(request.slot_addr);
    const prepared: *incident_publication_contract.PreparedManagedPoison =
        @ptrFromInt(capture.prepared_addr);
    prepareManagedPoisonRequestPinned(
        slot,
        node,
        capture.timestamp_ns,
        .{
            .reason_raw = capture.reason_raw,
            .source_site_raw = capture.source_site_raw,
            .controller_generation = capture.controller_generation,
        },
        prepared,
    ) catch failStopPreparedExecution(.authority_drift);
    capture.lifecycle_raw = @intFromEnum(
        incident_publication_contract.PreparedExecutionPoisonCaptureLifecycle.finalized,
    );
    return true;
}

/// B3-3 product-shaped private caller. It deliberately has no public facade and publishes no
/// response payload; tests provide a peer that consumes the exact request and closes.
const PreparedRpcExecutionTestFailure = enum {
    none,
    after_response_reserve,
    after_execution_lease,
    response_epoch_exhausted,
};

const PreparedRpcExecutionMode = enum { terminal_sink, correlated_response };

const ResponseDestination = union(enum) {
    attach: *executed_response_mod.ExecutedResponse,
    rpc: void,
};

const RpcExecutionDestination = union(enum) {
    canonical: void,
    test_explicit: *RpcExecutedResponse,
};

fn resolveResponseDestination(
    owner: *const contract.TransportOwnerSeal,
    requested: ResponseDestination,
) error{InvalidResponseDestination}!ResponseDestination {
    return switch (requested) {
        .attach => |destination| blk: {
            const destination_addr = @intFromPtr(destination);
            if (!byteRangeFullyContained(
                destination_addr,
                @sizeOf(executed_response_mod.ExecutedResponse),
                owner.owner_addr,
                owner.owner_size,
            )) return error.InvalidResponseDestination;
            break :blk .{ .attach = destination };
        },
        .rpc => blk: {
            const response_addr = owner.rpc_response_addr;
            if (response_addr == 0 or response_addr % @alignOf(RpcExecutedResponse) != 0 or
                !byteRangeFullyContained(
                    response_addr,
                    @sizeOf(RpcExecutedResponse),
                    owner.owner_addr,
                    owner.owner_size,
                )) return error.InvalidResponseDestination;
            break :blk .{ .rpc = {} };
        },
    };
}

fn executePreparedRpcPrivate(
    request: GenerationRequestAbort,
    bound_stream_id: u64,
    requested_destination: RpcExecutionDestination,
    mode: PreparedRpcExecutionMode,
    test_failure: PreparedRpcExecutionTestFailure,
    poison_request: ?PreparedExecutionPoisonCaptureRequest,
) !void {
    const admission = try beginGenerationRequestOwner(request, false);
    defer endRegisteredNodeOperation(admission.operation);
    const node = admission.operation.node;
    const identity = admission.identity;
    const destination: *RpcExecutedResponse = switch (requested_destination) {
        .test_explicit => |explicit| explicit,
        .canonical => switch (try resolveResponseDestination(admission.owner, .{ .rpc = {} })) {
            .rpc => @ptrFromInt(admission.owner.rpc_response_addr),
            .attach => unreachable,
        },
    };
    const prepared_admission = try node.cleanup_registry.preparedRpcAdmission(
        request.reservation.cleanup,
        identity,
        request.transport_addr,
        request.transport_incarnation,
        request.receipt,
        bound_stream_id,
    );
    if (prepared_admission.decision != .allowed) return error.Unauthorized;
    if (test_failure == .response_epoch_exhausted) {
        if (!builtin.is_test) unreachable;
        try node.cleanup_registry.exhaustRpcResponseEpochForTest(
            request.reservation.cleanup,
            identity,
        );
    }

    var txn: PreparedRpcExecutionTxn = .{};
    try txn.initBeforeReserve(
        admission.operation,
        request,
        identity,
        prepared_admission.canonical,
        destination,
    );
    defer txn.ensureSettledOrFailStop(admission.operation);
    txn.reserveResponse(admission.operation) catch |err| {
        const outcome = try txn.settleReserveFailure(
            admission.operation,
            err == error.IdentityExhausted,
        );
        txn.request.finishOrFailStop(admission.operation, outcome);
        return err;
    };
    if (test_failure == .after_response_reserve) return error.InjectedFailure;
    txn.request.commitBeginExecute(admission.operation);

    const storage: *client_mod.PreparedBlockingRpcStorage =
        @ptrFromInt(request.prepared_storage_addr);
    var lease: client_mod.PreparedRequestExecutionLease = .{};
    var publication: PreparedRpcPublicationScope = .{};
    var payload_cleanup: RpcPublicationPayloadCleanup = .{};
    const poison_capture: ?*incident_publication_contract.PreparedExecutionPoisonCapture = if (poison_request) |capture_request| blk: {
        if (capture_request.timestamp_ns < 0 or capture_request.controller_generation == 0 or
            std.enums.fromInt(connection_incident.SourceSite, capture_request.source_site_raw) == null or
            std.enums.fromInt(connection_incident.SourceSite, capture_request.allocator_source_site_raw) == null or
            capture_request.source_site_raw == capture_request.allocator_source_site_raw or
            capture_request.capture_addr == 0 or capture_request.prepared_addr == 0)
            return error.InvalidOwner;
        const capture: *incident_publication_contract.PreparedExecutionPoisonCapture =
            @ptrFromInt(capture_request.capture_addr);
        const prepared: *incident_publication_contract.PreparedManagedPoison =
            @ptrFromInt(capture_request.prepared_addr);
        if (!std.meta.eql(capture.*, incident_publication_contract.PreparedExecutionPoisonCapture{}) or
            !std.meta.eql(prepared.*, incident_publication_contract.PreparedManagedPoison{}) or
            byteRangesOverlap(@intFromPtr(capture), @sizeOf(@TypeOf(capture.*)), @intFromPtr(prepared), @sizeOf(@TypeOf(prepared.*))) or
            rangesOverlapTyped(capture, node) or rangesOverlapTyped(capture, &node.client) or
            rangesOverlapTyped(prepared, node) or rangesOverlapTyped(prepared, &node.client) or
            rangesOverlapTyped(capture, &lease) or rangesOverlapTyped(prepared, &lease))
            return error.InvalidOwner;
        capture.* = .{
            .self_addr = @intFromPtr(capture),
            .prepared_addr = @intFromPtr(prepared),
            .client_addr = @intFromPtr(&node.client),
            .operation_id = admission.operation.operation_id,
            .lease_addr = @intFromPtr(&lease),
            .timestamp_ns = capture_request.timestamp_ns,
            .controller_generation = capture_request.controller_generation,
            .source_site_raw = capture_request.source_site_raw,
            .allocator_source_site_raw = capture_request.allocator_source_site_raw,
            .lifecycle_raw = @intFromEnum(incident_publication_contract.PreparedExecutionPoisonCaptureLifecycle.armed),
        };
        break :blk capture;
    } else null;
    defer {
        if (poison_capture) |capture| capture.* = .{};
    }
    if (mode == .correlated_response) publication.begin(
        node,
        admission.operation,
        request,
        destination,
        &txn,
        &lease,
        &payload_cleanup,
        storage,
    ) catch |err| {
        const outcome = try txn.settlePreWire(admission.operation);
        txn.request.finishOrFailStop(admission.operation, outcome);
        return err;
    };
    const response_allocator = node.client.beginPreparedRequestExecutionFromRegisteredOperation(
        storage,
        txn.request.prepared_identity,
        &lease,
        poison_capture,
    ) catch |err| {
        const lease_began = lease.wireProgress() != null;
        const frozen_reason = if (lease_began)
            node.client.preparedRequestExecutionPoisonReason(&lease) catch
                failStopPreparedExecution(.authority_drift)
        else
            null;
        if (poison_capture) |capture| {
            _ = finalizePreparedExecutionPoisonCaptureNoFail(
                request,
                admission.operation,
                node,
                &lease,
                capture,
            );
        }
        if (lease_began) {
            publication.finish(node, &lease);
            settlePreparedRpcLeaseOwnedWithReasonAndReleaseOrFailStop(
                node,
                &lease,
                &txn,
                admission.operation,
                frozen_reason,
            );
        } else {
            publication.finish(node, null);
            const outcome = try txn.settlePreWire(admission.operation);
            txn.request.finishOrFailStop(admission.operation, outcome);
        }
        return err;
    };
    var lease_active = true;
    defer if (lease_active) {
        publication.finish(node, &lease);
        if (txn.phase == .settled)
            finishPreparedRpcLeaseOrFailStop(node, &lease, &txn, admission.operation)
        else
            settlePreparedRpcLeaseOwnedAndReleaseOrFailStop(
                node,
                &lease,
                &txn,
                admission.operation,
            );
    };

    if (test_failure == .after_execution_lease) {
        publication.finish(node, &lease);
        settlePreparedRpcLeaseOwnedAndReleaseOrFailStop(node, &lease, &txn, admission.operation);
        lease_active = false;
        return error.InjectedFailure;
    }

    if (!txn.responseDestinationStillPristine()) {
        node.client.poison(.local_invariant_violation);
        publication.finish(node, &lease);
        settlePreparedRpcLeaseOwnedAndReleaseOrFailStop(node, &lease, &txn, admission.operation);
        lease_active = false;
        return error.InvalidOwner;
    }

    const executing_admission = node.cleanup_registry.executingRpcAdmission(
        request.reservation.cleanup,
        identity,
        request.transport_addr,
        request.transport_incarnation,
        request.receipt,
        bound_stream_id,
    ) catch |err| {
        publication.finish(node, &lease);
        settlePreparedRpcLeaseOwnedAndReleaseOrFailStop(node, &lease, &txn, admission.operation);
        lease_active = false;
        return err;
    };
    if (executing_admission.decision != .allowed or
        !std.meta.eql(executing_admission.canonical, prepared_admission.canonical))
    {
        publication.finish(node, &lease);
        settlePreparedRpcLeaseOwnedAndReleaseOrFailStop(node, &lease, &txn, admission.operation);
        lease_active = false;
        return error.Unauthorized;
    }
    if (!txn.responseDestinationStillPristine()) {
        node.client.poison(.local_invariant_violation);
        publication.finish(node, &lease);
        settlePreparedRpcLeaseOwnedAndReleaseOrFailStop(node, &lease, &txn, admission.operation);
        lease_active = false;
        return error.InvalidOwner;
    }

    node.client.writePreparedRequestExecution(
        storage,
        txn.request.prepared_identity,
        &lease,
    ) catch |err| {
        publication.finish(node, &lease);
        settlePreparedRpcLeaseOwnedAndReleaseOrFailStop(node, &lease, &txn, admission.operation);
        lease_active = false;
        return err;
    };
    publication.afterRequestWrite(
        node,
        request,
        destination,
        &txn,
        &lease,
        &payload_cleanup,
        storage,
    );
    if (mode == .correlated_response) {
        try node.cleanup_registry.armRpcExecutionRecovery(
            request.reservation.cleanup,
            identity,
            txn.request.canonical_prepared,
            txn.response,
        );
        try publishPreparedRpcResponse(
            request,
            admission.operation,
            identity,
            bound_stream_id,
            node,
            destination,
            &txn,
            &lease,
            response_allocator,
            &publication,
            &payload_cleanup,
            poison_capture,
        );
        lease_active = false;
        return;
    }
    node.client.observePreparedRequestTerminalSinkEof(&lease) catch |err| switch (err) {
        error.ConnectionClosed, error.ProtocolError => {},
        else => @panic("B3-3 terminal sink returned an unclassified failure"),
    };
    settlePreparedRpcLeaseOwnedAndReleaseOrFailStop(node, &lease, &txn, admission.operation);
    lease_active = false;
}

fn publishPreparedRpcResponse(
    request: GenerationRequestAbort,
    operation: RegisteredNodeOperation,
    identity: contract.BindingIdentity,
    bound_stream_id: u64,
    node: *ClientNode,
    destination: *RpcExecutedResponse,
    txn: *PreparedRpcExecutionTxn,
    lease: *client_mod.PreparedRequestExecutionLease,
    response_allocator: std.mem.Allocator,
    publication: *PreparedRpcPublicationScope,
    payload_cleanup: *RpcPublicationPayloadCleanup,
    poison_capture: ?*incident_publication_contract.PreparedExecutionPoisonCapture,
) !void {
    const response = node.client.readPreparedResponseUnderExecutionLease(
        lease,
        response_allocator,
        publication.observer(node),
    ) catch |err| switch (err) {
        // Peer framing/correlation failures and bounded local allocation exhaustion poison the
        // connection, but they do not prove local ownership drift. The caller's unwind owns the
        // publication scope and execution lease; close the armed recovery authority first so the
        // slot becomes a permanent tombstone without invoking the local-invariant fail-stop path.
        error.EndpointAbsent,
        error.EndpointDenied,
        error.EndpointTransient,
        error.HandshakeFailed,
        error.AdminBusy,
        error.Unauthorized,
        error.IncompatibleVersion,
        error.ProtocolError,
        error.WriteFailed,
        error.ConnectionClosed,
        error.EventQueueFull,
        error.ExternalMode,
        error.OutOfMemory,
        => {
            const reason = (node.client.preparedRequestExecutionPoisonReason(lease) catch
                failStopRpcPublication(node, payload_cleanup, .ledger_drift)) orelse
                failStopRpcPublication(node, payload_cleanup, .ledger_drift);
            node.cleanup_registry.commitRpcExecutionRecoveryTerminalNoFail();
            const outcome = txn.settleRecoveredTerminal(operation, reason) catch
                failStopRpcPublication(node, payload_cleanup, .ledger_drift);
            txn.request.finishOrFailStop(operation, outcome);
            if (poison_capture) |capture| {
                if (capture.reason_raw != @intFromEnum(reason) or
                    !finalizePreparedExecutionPoisonCaptureNoFail(
                        request,
                        operation,
                        node,
                        lease,
                        capture,
                    )) failStopRpcPublication(node, payload_cleanup, .ledger_drift);
            }
            return err;
        },
        error.PayloadProvenanceRejected, error.InvalidPreparedRpc => failStopRpcPublication(
            node,
            payload_cleanup,
            .ledger_drift,
        ),
    };
    const payload_receipt = switch (publication.ledger.classifyResponsePayloadProvenance(
        response.payload_observation_generation,
        response.payload,
        response.payload_allocator,
        response_allocator,
    )) {
        .promoted => |receipt| receipt,
        .fail_stop_required => |reason| failStopRpcPublication(
            node,
            payload_cleanup,
            reason,
        ),
    };
    payload_cleanup.arm(payload_receipt) catch failStopRpcPublication(
        node,
        payload_cleanup,
        .ledger_drift,
    );
    const executing_admission = node.cleanup_registry.executingRpcAdmission(
        request.reservation.cleanup,
        identity,
        request.transport_addr,
        request.transport_incarnation,
        request.receipt,
        bound_stream_id,
    ) catch {
        failStopRpcPublication(
            node,
            payload_cleanup,
            .ledger_drift,
        );
    };
    node.client.revalidatePreparedResponsePublication(lease, response_allocator) catch {
        failStopRpcPublication(
            node,
            payload_cleanup,
            .ledger_drift,
        );
    };
    if (!publication.liveExact(node) or !txn.responseDestinationStillPristine() or
        txn.request.postExecuteReady(operation) == null or executing_admission.decision != .allowed or
        !std.meta.eql(executing_admission.canonical, txn.request.canonical_prepared))
    {
        failStopRpcPublication(
            node,
            payload_cleanup,
            .ledger_drift,
        );
    }
    node.cleanup_registry.prepareRpcResponsePublished(
        request.reservation.cleanup,
        identity,
        txn.response,
        &publication.publish_permit,
    ) catch failStopRpcPublication(
        node,
        payload_cleanup,
        .ledger_drift,
    );
    switch (publication.ledger.transferPromotedRpcResponse(
        payload_receipt,
        destination,
        rpcOwnerIdentity(txn.response),
    )) {
        .transferred => {},
        .fail_stop_required => |reason| failStopRpcPublication(
            node,
            payload_cleanup,
            reason,
        ),
    }
    _ = payload_cleanup.takeIfExact() orelse
        @panic("RPC publication payload cleanup consumption drifted");
    node.cleanup_registry.commitRpcResponsePublished(
        request.reservation.cleanup,
        identity,
        txn.response,
        &publication.publish_permit,
    );
    node.cleanup_registry.commitRpcExecutionRecoveryDisarmNoFail();
    const outcome = txn.request.settlePostExecuteReusableUnderPublicationScope(operation) catch
        failStopPreparedExecution(.cleanup_failure);
    txn.request.finishOrFailStop(operation, outcome);
    publication.finish(node, lease);
    txn.phase = .settled;
    finishPreparedRpcLeaseOrFailStop(node, lease, txn, operation);
}

fn failStopRpcPublication(
    node: *ClientNode,
    payload_cleanup: *RpcPublicationPayloadCleanup,
    reason: response_payload_allocation.PayloadFailStopReason,
) noreturn {
    const recovery = node.cleanup_registry.rpcExecutionRecoveryCanonical() catch
        @panic("RPC publication canonical recovery drifted");
    const byte_outcome = settleRpcPublicationFailureBytes(
        &node.rpc_free_evidence,
        payload_cleanup,
        recovery.response,
        reason,
    );
    node.cleanup_registry.commitRpcExecutionRecoveryTerminalNoFail();
    node.client.commitPreparedExecutionRecoveryPoisonNoFail(.local_invariant_violation);
    node.client.commitPreparedExecutionRecoveryCleanupNoFail();
    if (byte_outcome.retire_clean_evidence and
        !node.rpc_free_evidence.retireFreeCall(
            byte_outcome.response_epoch,
            byte_outcome.free_evidence,
        )) @panic("RPC publication clean free evidence retire drifted");
    node.guarded_allocator.finishOperationGuard() catch
        @panic("RPC publication recovery operation guard drifted");
    if (builtin.is_test and
        node.guarded_allocator.request_free_test_observer.rpc_publication_drift_fired)
    {
        const evidence = node.cleanup_registry.rpcExecutionRecoveryEvidenceForTest(
            recovery.reservation,
            recovery.binding,
        ) catch @panic("RPC publication recovery evidence lookup failed");
        if (!evidence.request_terminal) {
            const diagnostic = "B3_RPC_RECOVERY_REQUEST_NOT_TERMINAL\n";
            _ = c.write(2, diagnostic.ptr, diagnostic.len);
        }
        if (!evidence.response_terminal) {
            const diagnostic = "B3_RPC_RECOVERY_RESPONSE_NOT_TERMINAL\n";
            _ = c.write(2, diagnostic.ptr, diagnostic.len);
        }
        if (!evidence.recovery_empty) {
            const diagnostic = "B3_RPC_RECOVERY_NOT_CONSUMED\n";
            _ = c.write(2, diagnostic.ptr, diagnostic.len);
        }
        if (!node.client.preparedExecutionRecoveryPoisonedForTest()) {
            const diagnostic = "B3_RPC_RECOVERY_NOT_POISONED\n";
            _ = c.write(2, diagnostic.ptr, diagnostic.len);
        }
        if (!evidence.request_terminal or !evidence.response_terminal or
            !evidence.recovery_empty or !node.client.preparedExecutionRecoveryPoisonedForTest())
            @panic("RPC publication recovery evidence was incomplete");
        const marker = "B3_RPC_PUBLICATION_RECOVERY_TERMINAL\n";
        _ = c.write(2, marker.ptr, marker.len);
    }
    @panic("RPC publication failed after terminal settlement");
}

fn executePreparedRpcTerminalSink(
    request: GenerationRequestAbort,
    bound_stream_id: u64,
    destination: *RpcExecutedResponse,
    test_failure: PreparedRpcExecutionTestFailure,
) !void {
    return executePreparedRpcPrivate(
        request,
        bound_stream_id,
        .{ .test_explicit = destination },
        .terminal_sink,
        test_failure,
        null,
    );
}

fn executePreparedRpcCorrelatedResponseForTest(
    request: GenerationRequestAbort,
    bound_stream_id: u64,
    destination: *RpcExecutedResponse,
) !void {
    return executePreparedRpcPrivate(
        request,
        bound_stream_id,
        .{ .test_explicit = destination },
        .correlated_response,
        .none,
        null,
    );
}

/// One ownership-only RPC cycle for GenerationTransport's canonical inline slot. Semantic
/// response bytes deliberately remain unread until the decoder slice owns that contract.
pub fn executeGenerationRpcSubstrate(execution: GenerationRpcSubstrateExecute) GenerationExecuteError!void {
    if (builtin.is_test) rpc_substrate_fail_stop_test_hook.activate();
    executePreparedRpcPrivate(
        execution.request,
        execution.bound_stream_id,
        .{ .canonical = {} },
        .correlated_response,
        .none,
        null,
    ) catch |err| {
        return switch (err) {
            error.CapacityExhausted,
            error.InvalidIdentity,
            error.InvalidReservation,
            error.InvalidState,
            error.InvalidStream,
            error.InvalidCanonical,
            error.InjectedFailure,
            error.InvalidDescriptor,
            error.ObservationBusy,
            => @panic("RPC substrate returned an internal-only execution error"),
            else => @errorCast(err),
        };
    };
    if (builtin.is_test) rpc_substrate_fail_stop_test_hook.writeStage(.response_published);
    const response_addr = canonicalRpcResponseAddress(execution.request) catch
        @panic("RPC substrate lost its canonical response address after publication");
    const response: *RpcExecutedResponse = @ptrFromInt(response_addr);
    var borrow: rpc_executed_response.RpcResponseBorrow = .{};
    beginRpcResponseBorrow(execution.request, response, &borrow) catch
        @panic("RPC substrate borrow settlement drifted");
    if (builtin.is_test) rpc_substrate_fail_stop_test_hook.writeStage(.response_borrowed);
    finishRpcResponseOwned(execution.request, response, &borrow, .reusable) catch
        @panic("RPC substrate reusable settlement drifted");
    if (!response.pristineExact()) @panic("RPC substrate reusable slot did not rearm");
}

/// C1 decoder bridge는 canonical inline response를 callback 동안만 빌리고 같은 stack에서
/// source-zero까지 끝낸다. decoder가 authority를 바꾸면 recoverable 오류로 되돌리지 않는다.
pub fn executeGenerationRpcDecoded(
    execution: GenerationRpcDecodedExecute,
) GenerationExecuteError!contract.RpcDecodeDisposition {
    if (builtin.is_test) rpc_substrate_fail_stop_test_hook.activate();
    executePreparedRpcPrivate(
        execution.request,
        execution.bound_stream_id,
        .{ .canonical = {} },
        .correlated_response,
        .none,
        execution.poison_capture,
    ) catch |err| {
        return switch (err) {
            error.CapacityExhausted,
            error.InvalidIdentity,
            error.InvalidReservation,
            error.InvalidState,
            error.InvalidStream,
            error.InvalidCanonical,
            error.InjectedFailure,
            error.InvalidDescriptor,
            error.ObservationBusy,
            => @panic("RPC decoder bridge returned an internal-only execution error"),
            else => @errorCast(err),
        };
    };
    const response_addr = canonicalRpcResponseAddress(execution.request) catch
        @panic("RPC decoder bridge lost its canonical response address after publication");
    const response: *RpcExecutedResponse = @ptrFromInt(response_addr);
    if (builtin.is_test) rpc_substrate_fail_stop_test_hook.writeStage(.response_published);
    switch (execution.pre_decode(execution.pre_decode_context)) {
        .proceed => {},
        .busy => {
            settlePublishedRpcResponseWithoutDecode(execution.request, response);
            return error.Busy;
        },
        .out_of_memory => {
            settlePublishedRpcResponseWithoutDecode(execution.request, response);
            return error.OutOfMemory;
        },
        .protocol_failure => {
            settlePublishedRpcResponseWithoutDecode(execution.request, response);
            return error.ProtocolError;
        },
        .connection_closed => {
            settlePublishedRpcResponseWithoutDecode(execution.request, response);
            return error.ConnectionClosed;
        },
        .stale => {
            settlePublishedRpcResponseWithoutDecode(execution.request, response);
            return error.Unauthorized;
        },
    }
    const admission = beginGenerationRequestOwner(execution.request, false) catch
        process_seal_service.fatalIntegrity(.proof_loss);
    defer endRegisteredNodeOperation(admission.operation);
    var borrow: rpc_executed_response.RpcResponseBorrow = .{};
    beginRpcResponseBorrowUnderOwner(execution.request, response, &borrow, &admission) catch
        process_seal_service.fatalIntegrity(.proof_loss);
    if (builtin.is_test) {
        rpc_substrate_fail_stop_test_hook.writeStage(.response_borrowed);
        if (rpc_substrate_fail_stop_test_hook.activeCase(.decoder_response_seal_drift)) {
            response.seal[0] ^= 1;
            rpc_substrate_fail_stop_test_hook.writeStage(.drift_injected);
        } else if (rpc_substrate_fail_stop_test_hook.activeCase(.decoder_borrow_seal_drift)) {
            rpc_executed_response.testing.armBorrowSealDriftAfterCallback(
                rpc_substrate_fail_stop_test_hook.nonce,
                rpc_substrate_fail_stop_test_hook.stage_fd,
            );
        }
    }
    if (rpc_decoder_callback_active) process_seal_service.fatalIntegrity(.proof_loss);
    rpc_decoder_callback_active = true;
    const decode_result = rpc_executed_response.decodeBorrowedRpcResponse(
        response,
        &borrow,
        execution.context,
        execution.decoder,
    );
    rpc_decoder_callback_active = false;
    const disposition = decode_result catch process_seal_service.fatalIntegrity(.proof_loss);
    finishRpcResponseOwnedUnderOwner(
        execution.request,
        response,
        &borrow,
        switch (disposition) {
            .reusable => .reusable,
            .protocol_failure => .protocol_failure,
        },
        &admission,
    ) catch process_seal_service.fatalIntegrity(.proof_loss);
    if (disposition == .reusable and !response.pristineExact())
        process_seal_service.fatalIntegrity(.proof_loss);
    return disposition;
}

/// The correlated response has already been published before the runtime-level pre-decode hook
/// drains interleaved events.  A hook failure must therefore release that exact response owner
/// before returning its typed error; otherwise window teardown observes a permanently live RPC
/// owner even though no caller remains that can borrow or finish it.  The response bytes were not
/// decoded, so this is a reusable response-owner settlement.  Any connection poison established
/// by the hook remains independently latched on Client.
fn settlePublishedRpcResponseWithoutDecode(
    request: GenerationRequestAbort,
    response: *RpcExecutedResponse,
) void {
    const admission = beginGenerationRequestOwner(request, false) catch
        process_seal_service.fatalIntegrity(.proof_loss);
    defer endRegisteredNodeOperation(admission.operation);
    var borrow: rpc_executed_response.RpcResponseBorrow = .{};
    beginRpcResponseBorrowUnderOwner(request, response, &borrow, &admission) catch
        process_seal_service.fatalIntegrity(.proof_loss);
    finishRpcResponseOwnedUnderOwner(
        request,
        response,
        &borrow,
        .reusable,
        &admission,
    ) catch process_seal_service.fatalIntegrity(.proof_loss);
    if (!response.pristineExact()) process_seal_service.fatalIntegrity(.proof_loss);
}

/// Arms one destructive, process-local B3-6 fixture. The hook is deliberately scalar-only and
/// one-shot: the external test owns the pipe capability and the canonical product stack consumes
/// the case. Case ids are 1=response seal, 2=allocator transcript, 3=authority permit, 4=rearm
/// permit. Production builds cannot call or carry this authority.
pub fn armRpcSubstrateFailStopForTest(case_id: u8, nonce: u64, stage_fd: c.fd_t) void {
    if (!builtin.is_test) @compileError("test-only RPC substrate fail-stop hook");
    if (rpc_substrate_fail_stop_test_hook.lifecycle != .pristine or nonce == 0 or stage_fd < 3)
        @panic("invalid RPC substrate fail-stop hook authority");
    const case = std.enums.fromInt(RpcSubstrateFailStopTestHook.Case, case_id) orelse
        @panic("invalid RPC substrate fail-stop case");
    rpc_substrate_fail_stop_test_hook = .{
        .lifecycle = .armed,
        .case = case,
        .nonce = nonce,
        .stage_fd = stage_fd,
    };
    rpc_substrate_fail_stop_test_hook.writeStage(.armed);
}

test "B3-6 RPC substrate fail-stop stage record is fixed and case-bound" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    try std.testing.expectEqual(@as(usize, 11), RpcSubstrateFailStopTestHook.record_size);
    var fds: [2]c.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), c.pipe(&fds));
    defer _ = c.close(fds[0]);
    var hook: RpcSubstrateFailStopTestHook = .{
        .lifecycle = .armed,
        .case = .authority_permit_drift,
        .nonce = 0xB306_F17E_D00D,
        .stage_fd = fds[1],
    };
    hook.writeStage(.permits_prepared);
    _ = c.close(fds[1]);
    var bytes: [RpcSubstrateFailStopTestHook.record_size]u8 = undefined;
    try std.testing.expectEqual(
        @as(isize, @intCast(bytes.len)),
        c.read(fds[0], &bytes, bytes.len),
    );
    try std.testing.expectEqual(RpcSubstrateFailStopTestHook.version, bytes[0]);
    try std.testing.expectEqual(@as(u8, 3), bytes[1]);
    try std.testing.expectEqual(@as(u64, 0xB306_F17E_D00D), std.mem.readInt(u64, bytes[2..10], .little));
    try std.testing.expectEqual(@as(u8, 7), bytes[10]);
}

fn canonicalRpcResponseAddress(request: GenerationRequestAbort) GenerationRequestError!usize {
    const admission = try beginGenerationRequestOwner(request, false);
    defer endRegisteredNodeOperation(admission.operation);
    const response_addr = admission.owner.rpc_response_addr;
    if (response_addr == 0 or response_addr % @alignOf(RpcExecutedResponse) != 0 or
        !byteRangeFullyContained(
            response_addr,
            @sizeOf(RpcExecutedResponse),
            admission.owner.owner_addr,
            admission.owner.owner_size,
        )) return error.InvalidOwner;
    return response_addr;
}

test "B3-4/5 RPC substrate rejects uncontained destination before request admission" {
    var invalid_request: GenerationRequestAbort = undefined;
    @memset(std.mem.asBytes(&invalid_request), 0);
    try std.testing.expectError(error.InvalidOwner, executeGenerationRpcSubstrate(.{
        .request = invalid_request,
        .bound_stream_id = 1,
    }));
}

const RpcResponseDisposition = enum { reusable, protocol_failure };

fn failStopPermitAliasPreflight() noreturn {
    // This fixed, allocation-free write is the parent-observable sentinel. A subprocess gate can
    // bind stderr before entry without requiring env lookup or capability resolution here.
    const marker = "permit-alias-preflight-rejected\n";
    _ = c.write(2, marker.ptr, marker.len);
    @panic("permit-alias-preflight-rejected");
}

const FinishPermitRawStorage = struct {
    const TransitionPermit = rpc_response_authority.PreparedRpcTransitionPermit;
    const EvidencePermit = PreparedRpcFreeEvidenceRetirePermit;
    const RearmPermit = rpc_executed_response.PreparedReusableRearmPermit;

    const Range = struct {
        start: usize,
        len: usize,
    };

    releasing: [@sizeOf(TransitionPermit)]u8 align(@alignOf(TransitionPermit)) = undefined,
    finish_authority: [@sizeOf(TransitionPermit)]u8 align(@alignOf(TransitionPermit)) = undefined,
    evidence_retire: [@sizeOf(EvidencePermit)]u8 align(@alignOf(EvidencePermit)) = undefined,
    rearm: [@sizeOf(RearmPermit)]u8 align(@alignOf(RearmPermit)) = undefined,

    const Typed = struct {
        releasing: *TransitionPermit,
        finish_authority: *TransitionPermit,
        evidence_retire: *EvidencePermit,
        rearm: *RearmPermit,
    };

    fn ranges(self: *@This()) [4]Range {
        return .{
            .{ .start = @intFromPtr(&self.releasing), .len = @sizeOf(TransitionPermit) },
            .{ .start = @intFromPtr(&self.finish_authority), .len = @sizeOf(TransitionPermit) },
            .{ .start = @intFromPtr(&self.evidence_retire), .len = @sizeOf(EvidencePermit) },
            .{ .start = @intFromPtr(&self.rearm), .len = @sizeOf(RearmPermit) },
        };
    }

    /// This preflight reads only scalar addresses and extents. The four raw reservations remain
    /// undefined until every pair and every caller-owned range has proved disjoint.
    fn disjointFrom(self: *@This(), payload: Range, forbidden: []const Range) bool {
        _ = std.math.add(usize, payload.start, payload.len) catch return false;
        const permit_ranges = self.ranges();
        for (permit_ranges, 0..) |permit_range, index| {
            _ = std.math.add(usize, permit_range.start, permit_range.len) catch return false;
            if (byteRangesOverlap(payload.start, payload.len, permit_range.start, permit_range.len))
                return false;
            for (forbidden) |range| {
                if (byteRangesOverlap(permit_range.start, permit_range.len, range.start, range.len))
                    return false;
            }
            for (permit_ranges[index + 1 ..]) |other| {
                if (byteRangesOverlap(permit_range.start, permit_range.len, other.start, other.len))
                    return false;
            }
        }
        return true;
    }

    fn initializeDisjoint(self: *@This()) Typed {
        @memset(&self.releasing, 0);
        @memset(&self.finish_authority, 0);
        @memset(&self.evidence_retire, 0);
        @memset(&self.rearm, 0);
        return .{
            .releasing = @ptrCast(&self.releasing),
            .finish_authority = @ptrCast(&self.finish_authority),
            .evidence_retire = @ptrCast(&self.evidence_retire),
            .rearm = @ptrCast(&self.rearm),
        };
    }

    fn initializeAfterPreflightOrFail(
        self: *@This(),
        payload: Range,
        forbidden: []const Range,
    ) Typed {
        if (!self.disjointFrom(payload, forbidden)) failStopPermitAliasPreflight();
        return self.initializeDisjoint();
    }
};

pub fn armFinishPermitAliasForTest(range_index: u8) void {
    if (!builtin.is_test) @compileError("test-only finish permit alias trigger");
    if (range_index >= 4 or finish_permit_alias_case_for_test != 0)
        @panic("invalid finish permit alias test range");
    finish_permit_alias_case_for_test = range_index + 1;
}

test "B3-4/5 finish permit raw storage rejects alias and overflow before typed init" {
    var storage: FinishPermitRawStorage = undefined;
    const ranges = storage.ranges();
    const first = ranges[0];
    try std.testing.expect(!storage.disjointFrom(
        .{ .start = first.start, .len = first.len },
        &.{},
    ));
    try std.testing.expect(!storage.disjointFrom(
        .{ .start = first.start - 1, .len = 2 },
        &.{},
    ));
    try std.testing.expect(!storage.disjointFrom(
        .{ .start = first.start + first.len - 1, .len = 2 },
        &.{},
    ));
    try std.testing.expect(!storage.disjointFrom(
        .{ .start = std.math.maxInt(usize), .len = 2 },
        &.{},
    ));
    try std.testing.expect(!storage.disjointFrom(
        .{ .start = 1, .len = 1 },
        &.{.{ .start = first.start, .len = first.len }},
    ));
    try std.testing.expect(storage.disjointFrom(.{ .start = 1, .len = 1 }, &.{}));

    const typed = storage.initializeDisjoint();
    try std.testing.expect(typed.releasing.pristineExact());
    try std.testing.expect(typed.finish_authority.pristineExact());
    try std.testing.expect(typed.evidence_retire.pristineExact());
    try std.testing.expect(typed.rearm.pristineExact());
}

fn beginRpcResponseBorrow(
    request: GenerationRequestAbort,
    response: *RpcExecutedResponse,
    out: *rpc_executed_response.RpcResponseBorrow,
) !void {
    const admission = try beginGenerationRequestOwner(request, false);
    defer endRegisteredNodeOperation(admission.operation);
    return beginRpcResponseBorrowUnderOwner(request, response, out, &admission);
}

fn beginRpcResponseBorrowUnderOwner(
    request: GenerationRequestAbort,
    response: *RpcExecutedResponse,
    out: *rpc_executed_response.RpcResponseBorrow,
    admission: *const GenerationRequestOwner,
) !void {
    const node = admission.operation.node;
    const identity = response.identity;
    const canonical = rpcAuthorityCanonical(identity);
    if (!std.meta.eql(identity.binding, admission.identity) or
        canonical.destination_addr != @intFromPtr(response)) return error.InvalidOwner;
    var permit: rpc_response_authority.PreparedRpcTransitionPermit = .{};
    var borrow_init: rpc_executed_response.PreparedBorrowInit = .{};
    const payload_addr = response.payload_addr;
    const payload_len = response.payload_len;
    inline for (.{
        .{ @intFromPtr(&admission.operation), @sizeOf(RegisteredNodeOperation) },
        .{ @intFromPtr(&permit), @sizeOf(rpc_response_authority.PreparedRpcTransitionPermit) },
        .{ @intFromPtr(&borrow_init), @sizeOf(rpc_executed_response.PreparedBorrowInit) },
        .{ @intFromPtr(out), @sizeOf(rpc_executed_response.RpcResponseBorrow) },
        .{ @intFromPtr(node), @sizeOf(ClientNode) },
    }) |range| if (byteRangesOverlap(payload_addr, payload_len, range[0], range[1]))
        return error.InvalidOwner;
    try node.cleanup_registry.prepareRpcResponseBorrowed(
        request.reservation.cleanup,
        admission.identity,
        canonical,
        &permit,
    );
    try response.prepareBorrowInit(identity, out, &borrow_init);
    node.cleanup_registry.commitRpcResponseBorrowed(
        request.reservation.cleanup,
        admission.identity,
        canonical,
        &permit,
    );
    response.commitBorrowReceiptNoFail(identity, out, &borrow_init);
}

fn finishRpcResponseOwned(
    request: GenerationRequestAbort,
    response: *RpcExecutedResponse,
    borrow: *rpc_executed_response.RpcResponseBorrow,
    disposition: RpcResponseDisposition,
) !void {
    const admission = try beginGenerationRequestOwner(request, false);
    defer endRegisteredNodeOperation(admission.operation);
    return finishRpcResponseOwnedUnderOwner(request, response, borrow, disposition, &admission);
}

fn finishRpcResponseOwnedUnderOwner(
    request: GenerationRequestAbort,
    response: *RpcExecutedResponse,
    borrow: *rpc_executed_response.RpcResponseBorrow,
    disposition: RpcResponseDisposition,
    admission: *const GenerationRequestOwner,
) !void {
    const node = admission.operation.node;
    const identity = response.identity;
    const canonical = rpcAuthorityCanonical(identity);
    if (!std.meta.eql(identity.binding, admission.identity) or
        canonical.destination_addr != @intFromPtr(response) or
        !node.rpc_free_evidence.emptyExact()) return error.InvalidOwner;
    var finish: rpc_executed_response.RpcResponseFinishTxn = undefined;
    var permit_storage: FinishPermitRawStorage = undefined;
    const payload_addr = response.payload_addr;
    const payload_len = response.payload_len;
    const forbidden = [_]FinishPermitRawStorage.Range{
        .{ .start = @intFromPtr(&admission.operation), .len = @sizeOf(RegisteredNodeOperation) },
        .{ .start = @intFromPtr(&finish), .len = @sizeOf(rpc_executed_response.RpcResponseFinishTxn) },
        .{ .start = @intFromPtr(borrow), .len = @sizeOf(rpc_executed_response.RpcResponseBorrow) },
        .{ .start = @intFromPtr(response), .len = @sizeOf(RpcExecutedResponse) },
        .{ .start = @intFromPtr(node), .len = @sizeOf(ClientNode) },
        .{ .start = admission.owner.owner_addr, .len = admission.owner.owner_size },
    };
    const payload_range = if (builtin.is_test and finish_permit_alias_case_for_test != 0) blk: {
        const range_index = finish_permit_alias_case_for_test - 1;
        finish_permit_alias_case_for_test = 0;
        break :blk permit_storage.ranges()[range_index];
    } else FinishPermitRawStorage.Range{ .start = payload_addr, .len = payload_len };
    const permits = permit_storage.initializeAfterPreflightOrFail(
        payload_range,
        &forbidden,
    );
    for (forbidden) |range| {
        if (byteRangesOverlap(payload_addr, payload_len, range.start, range.len)) {
            terminalizeBorrowedRpcResponseNoFree(
                node,
                request.reservation.cleanup,
                admission.identity,
                canonical,
                response,
                identity,
            );
        }
    }
    finish = .{};
    response.prepareFinish(identity, borrow, &finish) catch {
        terminalizeBorrowedRpcResponseNoFree(
            node,
            request.reservation.cleanup,
            admission.identity,
            canonical,
            response,
            identity,
        );
    };
    try node.cleanup_registry.prepareRpcResponseReleasing(
        request.reservation.cleanup,
        admission.identity,
        canonical,
        permits.releasing,
    );
    response.commitFreeNoFail(identity, borrow, &finish);
    if (builtin.is_test) rpc_substrate_fail_stop_test_hook.writeStage(.free_once);
    node.cleanup_registry.commitRpcResponseReleasing(
        request.reservation.cleanup,
        admission.identity,
        canonical,
        permits.releasing,
    );
    const evidence = finish.freeEvidenceDigest() orelse
        @panic("RPC response finish lost free evidence");
    if (!node.rpc_free_evidence.commitFreeCall(identity.response_epoch, evidence))
        @panic("RPC response node free evidence busy");
    if (!finish.freeCaptured())
        failStopFreedRpcResponse(
            node,
            request.reservation.cleanup,
            admission.identity,
            canonical,
            evidence,
            "RPC response allocator callback settlement drifted",
        );
    if (builtin.is_test) {
        rpc_substrate_fail_stop_test_hook.writeStage(.allocator_returned);
        if (rpc_substrate_fail_stop_test_hook.activeCase(.response_seal_drift)) {
            response.seal[0] ^= 1;
            rpc_substrate_fail_stop_test_hook.writeStage(.drift_injected);
        } else if (rpc_substrate_fail_stop_test_hook.activeCase(.allocator_transcript_drift)) {
            finish.terminal_evidence[0] ^= 1;
            rpc_substrate_fail_stop_test_hook.writeStage(.drift_injected);
        }
    }
    switch (disposition) {
        .reusable => node.cleanup_registry.prepareRpcResponseReusable(
            request.reservation.cleanup,
            admission.identity,
            canonical,
            permits.finish_authority,
        ) catch failStopFreedRpcResponse(
            node,
            request.reservation.cleanup,
            admission.identity,
            canonical,
            evidence,
            "RPC response reusable finish preflight drifted",
        ),
        .protocol_failure => node.cleanup_registry.prepareRpcResponseTerminal(
            request.reservation.cleanup,
            admission.identity,
            canonical,
            permits.finish_authority,
        ) catch failStopFreedRpcResponse(
            node,
            request.reservation.cleanup,
            admission.identity,
            canonical,
            evidence,
            "RPC response terminal finish preflight drifted",
        ),
    }
    if (!node.rpc_free_evidence.prepareRetireFreeCall(
        identity.response_epoch,
        evidence,
        permits.evidence_retire,
    )) failStopFreedRpcResponse(
        node,
        request.reservation.cleanup,
        admission.identity,
        canonical,
        evidence,
        "RPC response evidence retire preflight drifted",
    );
    if (disposition == .reusable) response.prepareReusableRearm(&finish, permits.rearm) catch
        failStopFreedRpcResponse(
            node,
            request.reservation.cleanup,
            admission.identity,
            canonical,
            evidence,
            "RPC response reusable rearm preflight drifted",
        );
    if (builtin.is_test) {
        rpc_substrate_fail_stop_test_hook.writeStage(.permits_prepared);
        if (rpc_substrate_fail_stop_test_hook.activeCase(.authority_permit_drift)) {
            permits.finish_authority.seal[0] ^= 1;
            rpc_substrate_fail_stop_test_hook.writeStage(.drift_injected);
        }
    }
    response.finishCleanNoFail(&finish);
    switch (disposition) {
        .reusable => node.cleanup_registry.commitRpcResponseReusable(
            request.reservation.cleanup,
            admission.identity,
            canonical,
            permits.finish_authority,
        ),
        .protocol_failure => node.cleanup_registry.commitRpcResponseTerminal(
            request.reservation.cleanup,
            admission.identity,
            canonical,
            permits.finish_authority,
        ),
    }
    if (builtin.is_test) rpc_substrate_fail_stop_test_hook.writeStage(.authority_idle);
    node.rpc_free_evidence.commitEvidenceRetireNoFail(permits.evidence_retire);
    if (builtin.is_test) rpc_substrate_fail_stop_test_hook.writeStage(.evidence_retired);
    if (disposition == .protocol_failure)
        node.client.poison(.peer_contract_violation);
    if (disposition == .reusable) {
        if (builtin.is_test) {
            rpc_substrate_fail_stop_test_hook.writeStage(.rearm_precondition);
            if (rpc_substrate_fail_stop_test_hook.activeCase(.rearm_permit_drift)) {
                permits.rearm.expected_consumed_finish_digest[0] ^= 1;
                rpc_substrate_fail_stop_test_hook.writeStage(.drift_injected);
            }
        }
        if (!response.reusableRearmReady(&finish, permits.rearm))
            process_seal_service.fatalIntegrity(.proof_loss);
        response.commitReusableRearmNoFail(&finish, permits.rearm);
    }
}

fn terminalizeBorrowedRpcResponseNoFree(
    node: *ClientNode,
    reservation: cleanup_registry_mod.Reservation,
    binding: contract.BindingIdentity,
    canonical: rpc_response_authority.Canonical,
    response: *RpcExecutedResponse,
    identity: rpc_executed_response.Identity,
) noreturn {
    var releasing: rpc_response_authority.PreparedRpcTransitionPermit = .{};
    var terminal: rpc_response_authority.PreparedRpcTransitionPermit = .{};
    node.cleanup_registry.prepareRpcResponseReleasing(
        reservation,
        binding,
        canonical,
        &releasing,
    ) catch @panic("RPC response no-free release preflight drifted");
    const owner_settled = if (response.abandonLiveNoFree(identity)) |_| true else |_| false;
    node.cleanup_registry.commitRpcResponseReleasing(
        reservation,
        binding,
        canonical,
        &releasing,
    );
    node.cleanup_registry.prepareRpcResponseTerminal(
        reservation,
        binding,
        canonical,
        &terminal,
    ) catch @panic("RPC response no-free terminal preflight drifted");
    node.cleanup_registry.commitRpcResponseTerminal(
        reservation,
        binding,
        canonical,
        &terminal,
    );
    node.client.poison(.local_invariant_violation);
    if (!owner_settled) @panic("RPC response no-free owner was already invalid");
    @panic("RPC response no-free terminal settlement");
}

fn failStopFreedRpcResponse(
    node: *ClientNode,
    reservation: cleanup_registry_mod.Reservation,
    identity: contract.BindingIdentity,
    canonical: rpc_response_authority.Canonical,
    evidence: owner_seal.Digest,
    message: []const u8,
) noreturn {
    if (!node.rpc_free_evidence.commitTerminalFreedOnce(canonical.response_epoch, evidence))
        @panic("RPC response terminal freed-once evidence drifted");
    var terminal: rpc_response_authority.PreparedRpcTransitionPermit = .{};
    node.cleanup_registry.prepareRpcResponseTerminal(
        reservation,
        identity,
        canonical,
        &terminal,
    ) catch {
        node.client.poison(.local_invariant_violation);
        @panic("RPC response releasing authority could not terminalize");
    };
    node.cleanup_registry.commitRpcResponseTerminal(
        reservation,
        identity,
        canonical,
        &terminal,
    );
    node.client.poison(.local_invariant_violation);
    @panic(message);
}

/// Executes the attach-compatible request while one registry operation pins the canonical
/// ClientSlot node. No node, Client, binding, or response-owner address escapes this scope.
pub fn executeGenerationRequest(
    execution: GenerationRequestExecute,
) GenerationExecuteError!contract.ExecuteResult {
    return executeGenerationRequestInternal(execution, null) catch |err| switch (err) {
        error.DeadlineExceeded => unreachable,
        else => |typed| typed,
    };
}

pub fn executeGenerationRequestUntil(
    execution: GenerationRequestExecute,
    deadline: client_deadline.AbsoluteDeadline,
) DeadlineGenerationExecuteError!contract.ExecuteResult {
    return executeGenerationRequestInternal(execution, deadline);
}

fn executeGenerationRequestInternal(
    execution: GenerationRequestExecute,
    deadline: ?client_deadline.AbsoluteDeadline,
) DeadlineGenerationExecuteError!contract.ExecuteResult {
    const request = execution.request;
    if (!request.receipt.valid() or execution.response_out_addr == 0 or
        execution.owner_addr == 0 or execution.owner_size == 0)
        return error.InvalidOwner;
    _ = std.math.add(usize, execution.owner_addr, execution.owner_size) catch
        return error.InvalidOwner;
    if (!byteRangeFullyContained(
        execution.response_out_addr,
        @sizeOf(executed_response_mod.ExecutedResponse),
        execution.owner_addr,
        execution.owner_size,
    )) return error.InvalidResponseDestination;

    const admission = try beginGenerationRequestOwner(request, false);
    defer endRegisteredNodeOperation(admission.operation);
    const node = admission.operation.node;
    const identity = admission.identity;
    if (execution.owner_addr != admission.owner.owner_addr or
        execution.owner_size != admission.owner.owner_size)
        return error.InvalidOwner;
    const response_out: *executed_response_mod.ExecutedResponse = @ptrFromInt(
        execution.response_out_addr,
    );
    _ = switch (try resolveResponseDestination(admission.owner, .{ .attach = response_out })) {
        .attach => |destination| destination,
        .rpc => unreachable,
    };
    const prepared_admission = node.cleanup_registry.preparedAttachAdmission(
        request.reservation.cleanup,
        identity,
        request.transport_addr,
        request.transport_incarnation,
        request.receipt,
        execution.bound_stream_id,
    ) catch |err| return switch (err) {
        error.InvalidOwner => error.InvalidOwner,
        error.InvalidReceipt => error.InvalidReceipt,
        error.InvalidResponseDestination => error.InvalidResponseDestination,
    };
    switch (prepared_admission.decision) {
        .allowed => {},
        .unauthorized => return error.Unauthorized,
        .busy => return error.Busy,
    }
    const canonical = prepared_admission.canonical;
    const storage: *client_mod.PreparedBlockingRpcStorage =
        @ptrFromInt(request.prepared_storage_addr);
    const prepared_identity: client_mod.PreparedBlockingRpcIdentity = .{
        .request_id = canonical.receipt.request_id,
        .frame_digest = canonical.receipt.request_digest,
        .descriptor = canonical.descriptor,
    };
    if (!node.client.preparedBlockingRpcStorageMatches(storage, prepared_identity)) {
        node.cleanup_registry.settlePreparedRequest(
            request.reservation.cleanup,
            identity,
            canonical,
            true,
        ) catch return error.ProtocolError;
        node.client.poison(.local_invariant_violation);
        return error.ProtocolError;
    }
    var execution_txn: PreparedExecutionTxn = .{};
    defer execution_txn.ensureSettledOrFailStop(admission.operation);
    try execution_txn.initBeforeBeginExecute(
        admission.operation,
        request,
        identity,
        canonical,
    );
    execution_txn.commitBeginExecute(admission.operation);

    const response_owner = node.cleanup_registry.responseOwnerSeal(
        request.reservation.cleanup,
        identity,
    ) catch {
        const outcome = try execution_txn.rollbackPreWire(admission.operation);
        execution_txn.finishOrFailStop(admission.operation, outcome);
        return error.InvalidOwner;
    };
    const binding: *contract.PreparedAttachmentBinding =
        @ptrFromInt(identity.binding_storage_addr);
    if (!responseDestinationValid(
        response_out,
        response_owner,
        binding,
        storage,
        execution.owner_addr,
        execution.owner_size,
        request.slot_addr,
        node,
    )) {
        const outcome = try execution_txn.rollbackPreWire(admission.operation);
        execution_txn.finishOrFailStop(admission.operation, outcome);
        return error.InvalidResponseDestination;
    }

    var allocator_scope: client_mod.Client.GenerationAllocatorScope = .{};
    var payload_ledger: response_payload_allocation.Ledger = .{};
    var execution_cleanup: PreparedExecutionCleanup = undefined;
    var cleanup_expected_stage: PreparedExecutionCleanup.CleanupStage = .guard;
    var cleanup_completion: u8 = 0;
    const response_ranges = [_]GenerationGuardedAllocator.OperationRangeInput{
        .{ .start = @intFromPtr(response_out), .len = @sizeOf(executed_response_mod.ExecutedResponse) },
        .{ .start = @intFromPtr(response_owner), .len = @sizeOf(contract.ExecutedResponseOwnerSeal) },
        .{ .start = @intFromPtr(binding), .len = @sizeOf(contract.PreparedAttachmentBinding) },
        .{ .start = @intFromPtr(storage), .len = @sizeOf(client_mod.PreparedBlockingRpcStorage) },
        .{ .start = request.transport_addr, .len = 1 },
        .{ .start = execution.owner_addr, .len = execution.owner_size },
        .{ .start = @intFromPtr(&allocator_scope), .len = @sizeOf(client_mod.Client.GenerationAllocatorScope) },
        .{ .start = @intFromPtr(&payload_ledger), .len = @sizeOf(response_payload_allocation.Ledger) },
        .{ .start = @intFromPtr(&execution_txn), .len = @sizeOf(PreparedExecutionTxn) },
        .{ .start = @intFromPtr(&execution_cleanup), .len = @sizeOf(PreparedExecutionCleanup) },
        .{ .start = @intFromPtr(&cleanup_expected_stage), .len = @sizeOf(PreparedExecutionCleanup.CleanupStage) },
        .{ .start = @intFromPtr(&cleanup_completion), .len = @sizeOf(u8) },
    };
    const forbidden_payload_ranges = [_]response_payload_allocation.ForbiddenRange{
        .{ .start = @intFromPtr(response_out), .len = @sizeOf(executed_response_mod.ExecutedResponse) },
        .{ .start = @intFromPtr(response_owner), .len = @sizeOf(contract.ExecutedResponseOwnerSeal) },
        .{ .start = @intFromPtr(binding), .len = @sizeOf(contract.PreparedAttachmentBinding) },
        .{ .start = @intFromPtr(storage), .len = @sizeOf(client_mod.PreparedBlockingRpcStorage) },
        .{ .start = request.transport_addr, .len = 1 },
        .{ .start = execution.owner_addr, .len = execution.owner_size },
        .{ .start = @intFromPtr(&allocator_scope), .len = @sizeOf(client_mod.Client.GenerationAllocatorScope) },
        .{ .start = @intFromPtr(&payload_ledger), .len = @sizeOf(response_payload_allocation.Ledger) },
        .{ .start = request.slot_addr, .len = @sizeOf(ClientSlot) },
        .{ .start = @intFromPtr(node), .len = @sizeOf(ClientNode) },
        .{ .start = @intFromPtr(&execution_txn), .len = @sizeOf(PreparedExecutionTxn) },
        .{ .start = @intFromPtr(&execution_cleanup), .len = @sizeOf(PreparedExecutionCleanup) },
        .{ .start = @intFromPtr(&cleanup_expected_stage), .len = @sizeOf(PreparedExecutionCleanup.CleanupStage) },
        .{ .start = @intFromPtr(&cleanup_completion), .len = @sizeOf(u8) },
    };
    const guard = &node.guarded_allocator;
    if (!guard.beginOperationGuard(&response_ranges)) {
        const outcome = try execution_txn.rollbackPreWire(admission.operation);
        execution_txn.finishOrFailStop(admission.operation, outcome);
        return error.InvalidOwner;
    }
    execution_cleanup.init();
    defer execution_cleanup.ensureFinishedOrFailStop(
        &execution_txn,
        admission.operation,
        cleanup_expected_stage,
        &cleanup_completion,
        &node.client,
        guard,
        &allocator_scope,
        &payload_ledger,
    );
    node.client.beginGenerationAllocatorScope(
        guard.allocator(),
        .rpc_execute,
        &allocator_scope,
    ) catch |err| {
        if (err == error.IdentityExhausted) {
            _ = try settleExecutionAfterCleanup(
                &execution_cleanup,
                &execution_txn,
                admission.operation,
                cleanup_expected_stage,
                &cleanup_completion,
                &node.client,
                guard,
                &allocator_scope,
                &payload_ledger,
                .issuer_exhausted,
            );
            return error.IdentityExhausted;
        }
        _ = try settleExecutionAfterCleanup(
            &execution_cleanup,
            &execution_txn,
            admission.operation,
            cleanup_expected_stage,
            &cleanup_completion,
            &node.client,
            guard,
            &allocator_scope,
            &payload_ledger,
            .rollback_pre_wire,
        );
        return error.Busy;
    };
    cleanup_expected_stage = .allocator;
    if (!execution_cleanup.advance(.guard, cleanup_expected_stage)) {
        execution_cleanup.finishOrFailStop(
            &execution_txn,
            admission.operation,
            cleanup_expected_stage,
            &cleanup_completion,
            &node.client,
            guard,
            &allocator_scope,
            &payload_ledger,
        );
        const outcome = execution_txn.failStopCleanupFailure(admission.operation);
        execution_txn.finishOrFailStop(admission.operation, outcome);
    }

    const response_incarnation = issueGenerationResponseIncarnation() catch {
        _ = try settleExecutionAfterCleanup(
            &execution_cleanup,
            &execution_txn,
            admission.operation,
            cleanup_expected_stage,
            &cleanup_completion,
            &node.client,
            guard,
            &allocator_scope,
            &payload_ledger,
            .issuer_exhausted,
        );
        return error.IdentityExhausted;
    };
    response_payload_allocation.Ledger.initInPlace(
        &payload_ledger,
        guard.allocator(),
        .{
            .guard_addr = @intFromPtr(guard),
            .node_addr = @intFromPtr(node),
            .operation_incarnation = response_incarnation,
        },
        1,
    ) catch |err| {
        _ = try settleExecutionAfterCleanup(
            &execution_cleanup,
            &execution_txn,
            admission.operation,
            cleanup_expected_stage,
            &cleanup_completion,
            &node.client,
            guard,
            &allocator_scope,
            &payload_ledger,
            .issuer_exhausted,
        );
        return switch (err) {
            error.IdentityExhausted => error.IdentityExhausted,
            else => error.ProtocolError,
        };
    };
    cleanup_expected_stage = .ledger;
    if (!execution_cleanup.advance(.allocator, cleanup_expected_stage)) {
        execution_cleanup.finishOrFailStop(
            &execution_txn,
            admission.operation,
            cleanup_expected_stage,
            &cleanup_completion,
            &node.client,
            guard,
            &allocator_scope,
            &payload_ledger,
        );
        const outcome = execution_txn.failStopCleanupFailure(admission.operation);
        execution_txn.finishOrFailStop(admission.operation, outcome);
    }
    payload_ledger.bindForbiddenRanges(&forbidden_payload_ranges) catch {
        _ = try settleExecutionAfterCleanup(
            &execution_cleanup,
            &execution_txn,
            admission.operation,
            cleanup_expected_stage,
            &cleanup_completion,
            &node.client,
            guard,
            &allocator_scope,
            &payload_ledger,
            .rollback_pre_wire,
        );
        node.client.poison(.local_invariant_violation);
        @panic("response payload forbidden owner inventory drifted");
    };
    var payload_observer = ResponsePayloadObserverBridge{
        .ledger = &payload_ledger,
        .guard = guard,
    };
    const executed = contract.ExecutedCallReceipt.fromPrepared(request.receipt) orelse {
        _ = try settleExecutionAfterCleanup(
            &execution_cleanup,
            &execution_txn,
            admission.operation,
            cleanup_expected_stage,
            &cleanup_completion,
            &node.client,
            guard,
            &allocator_scope,
            &payload_ledger,
            .rollback_pre_wire,
        );
        return error.InvalidReceipt;
    };
    const response_allocator = node.client.preflightPreparedBlockingRpcStorageExecution(
        storage,
    ) catch |err| {
        _ = try settleExecutionAfterCleanup(
            &execution_cleanup,
            &execution_txn,
            admission.operation,
            cleanup_expected_stage,
            &cleanup_completion,
            &node.client,
            guard,
            &allocator_scope,
            &payload_ledger,
            .rollback_pre_wire,
        );
        return err;
    };

    // The pending flush may invoke allocator callbacks. Revalidate every canonical authority
    // under the still-held registry operation immediately before the first request byte.
    if (!(node.cleanup_registry.executingRequestMatches(
        request.reservation.cleanup,
        identity,
        canonical,
    ) catch false) or
        !node.client.preparedBlockingRpcStorageMatches(storage, prepared_identity) or
        !responseDestinationValid(
            response_out,
            response_owner,
            binding,
            storage,
            execution.owner_addr,
            execution.owner_size,
            request.slot_addr,
            node,
        ))
    {
        _ = try settleExecutionAfterCleanup(
            &execution_cleanup,
            &execution_txn,
            admission.operation,
            cleanup_expected_stage,
            &cleanup_completion,
            &node.client,
            guard,
            &allocator_scope,
            &payload_ledger,
            .rollback_pre_wire,
        );
        return error.InvalidResponseDestination;
    }

    if (builtin.is_test and guard.request_free_test_observer.inject_pending_before_execute) {
        const observer = &guard.request_free_test_observer;
        if (observer.pending_frame_addr == 0 or observer.pending_frame_len == 0 or
            node.client.pending_outbound != null)
            @panic("B3 pending injection descriptor drifted");
        const frame: [*]u8 = @ptrFromInt(observer.pending_frame_addr);
        node.client.pending_outbound = .{
            .frame = frame[0..observer.pending_frame_len],
            .stream_id = 10,
        };
        observer.pending_injected = true;
        if (observer.drift_request_before_execute) {
            if (observer.target_addr == 0 or observer.target_len == 0)
                @panic("B3 request drift descriptor missing");
            const request_frame: [*]u8 = @ptrFromInt(observer.target_addr);
            request_frame[observer.target_len - 1] ^= 1;
        }
        if (observer.poison_before_execute) node.client.poison(.transport_read_failure);
    }
    const ExecutionResult = client_mod.DeadlineObservedPreparedBlockingRpcExecution;
    const execution_result: ExecutionResult =
        if (builtin.is_test and guard.request_free_test_observer.force_not_executed)
            .{ .not_executed = error.ConnectionClosed }
        else if (deadline) |absolute|
            node.client.executePreparedBlockingRpcStorageUntilObserved(
                storage,
                response_allocator,
                absolute,
                payload_observer.observer(),
            )
        else switch (node.client.executePreparedBlockingRpcStorageWithAllocatorObserved(
            storage,
            response_allocator,
            payload_observer.observer(),
        )) {
            .accepted => |value| .{ .accepted = value },
            .not_executed => |err| .{ .not_executed = err },
            .uncertain => |err| .{ .uncertain = err },
        };
    if (guard.operation_alias_rejected) {
        _ = try settleExecutionAfterCleanup(
            &execution_cleanup,
            &execution_txn,
            admission.operation,
            cleanup_expected_stage,
            &cleanup_completion,
            &node.client,
            guard,
            &allocator_scope,
            &payload_ledger,
            .{ .post_execute_terminal = .local_invariant_violation },
        );
        node.client.poison(.local_invariant_violation);
        if (builtin.is_test and c.getenv("MARU_SESSION_HOST_RESPONSE_ALIAS_EXEC") != null and
            if (c.getenv("MARU_SESSION_HOST_RESPONSE_ALIAS_CASE")) |raw|
                std.mem.eql(u8, std.mem.span(raw), "response_alias")
            else
                true)
        {
            const authority_terminal = if (node.cleanup_registry.publishPreparedRequest(
                request.reservation.cleanup,
                identity,
                canonical,
            )) false else |err| err == error.InvalidState;
            if (!client_mod.Client.preparedBlockingRpcStorageSettled(storage))
                @panic("B3 strict response-alias storage was not settled");
            if (!authority_terminal)
                @panic("B3 strict response-alias authority was not terminal");
            if (node.client.firstPoisonReason() != .local_invariant_violation)
                @panic("B3 strict response-alias poison drifted");
            const marker = "B3_STRICT_ROW request=exact_wire storage=settled authority=terminal connection=fail_stop outcome=fail_stop error=fail_stop poison=local_invariant response=terminal_no_free request_free=exact_once payload_free=no_free final_zero=false\n";
            _ = c.write(2, marker.ptr, marker.len);
        }
        @panic("response payload allocator returned a canonical owner alias");
    }
    const response = switch (execution_result) {
        .not_executed => |err| {
            return switch (err) {
                error.PayloadProvenanceRejected => {
                    _ = try settleExecutionAfterCleanup(
                        &execution_cleanup,
                        &execution_txn,
                        admission.operation,
                        cleanup_expected_stage,
                        &cleanup_completion,
                        &node.client,
                        guard,
                        &allocator_scope,
                        &payload_ledger,
                        .rollback_pre_wire,
                    );
                    node.client.poison(.local_invariant_violation);
                    @panic("response payload provenance failed before execution");
                },
                else => |execution_err| {
                    _ = try settleExecutionAfterCleanup(
                        &execution_cleanup,
                        &execution_txn,
                        admission.operation,
                        cleanup_expected_stage,
                        &cleanup_completion,
                        &node.client,
                        guard,
                        &allocator_scope,
                        &payload_ledger,
                        .rollback_pre_wire,
                    );
                    return execution_err;
                },
            };
        },
        .uncertain => |err| {
            if (err == error.PayloadProvenanceRejected) {
                _ = try settleExecutionAfterCleanup(
                    &execution_cleanup,
                    &execution_txn,
                    admission.operation,
                    cleanup_expected_stage,
                    &cleanup_completion,
                    &node.client,
                    guard,
                    &allocator_scope,
                    &payload_ledger,
                    .{ .post_execute_terminal = .local_invariant_violation },
                );
                node.client.poison(.local_invariant_violation);
                @panic("response payload allocator provenance became ambiguous");
            }
            node.client.poison(.transport_read_failure);
            const result: contract.ExecuteResult = .{
                .uncertain_or_connection_failure = executed,
            };
            response_out.initWithoutPayloadInPlace(
                response_owner,
                response_incarnation,
                result,
            ) catch {
                _ = try settleExecutionAfterCleanup(
                    &execution_cleanup,
                    &execution_txn,
                    admission.operation,
                    cleanup_expected_stage,
                    &cleanup_completion,
                    &node.client,
                    guard,
                    &allocator_scope,
                    &payload_ledger,
                    .{ .post_execute_terminal = .local_invariant_violation },
                );
                node.client.poison(.local_invariant_violation);
                return error.InvalidResponseDestination;
            };
            _ = try settleExecutionAfterCleanup(
                &execution_cleanup,
                &execution_txn,
                admission.operation,
                cleanup_expected_stage,
                &cleanup_completion,
                &node.client,
                guard,
                &allocator_scope,
                &payload_ledger,
                .{ .post_execute_terminal = .transport_read_failure },
            );
            return result;
        },
        .accepted => |value| value,
    };
    const payload_receipt = switch (payload_ledger.classifyResponsePayloadProvenance(
        response.payload_observation_generation,
        response.payload,
        response.payload_allocator,
        response_allocator,
    )) {
        .promoted => |receipt| receipt,
        .fail_stop_required => |reason| {
            _ = try settleExecutionAfterCleanup(
                &execution_cleanup,
                &execution_txn,
                admission.operation,
                cleanup_expected_stage,
                &cleanup_completion,
                &node.client,
                guard,
                &allocator_scope,
                &payload_ledger,
                .{ .post_execute_terminal = .local_invariant_violation },
            );
            node.client.poison(.local_invariant_violation);
            failStopResponsePayloadProvenance(reason);
        },
    };
    const canonical_owner_drift = !(node.cleanup_registry.executingRequestMatches(
        request.reservation.cleanup,
        identity,
        canonical,
    ) catch false) or
        !responseOwnerStillPristine(response_out, response_owner);
    if (canonical_owner_drift) {
        node.client.poison(.local_invariant_violation);
        payload_ledger.releasePromotedResponse(payload_receipt) catch
            @panic("safe response provenance release drifted");
        _ = try settleExecutionAfterCleanup(
            &execution_cleanup,
            &execution_txn,
            admission.operation,
            cleanup_expected_stage,
            &cleanup_completion,
            &node.client,
            guard,
            &allocator_scope,
            &payload_ledger,
            .{ .post_execute_terminal = .local_invariant_violation },
        );
        return error.InvalidResponseDestination;
    }
    const correlated = contract.CorrelatedExecutedCall.init(
        executed,
        response.response_request_id,
    ) orelse {
        node.client.poison(.local_invariant_violation);
        payload_ledger.releasePromotedResponse(payload_receipt) catch
            @panic("safe response provenance release drifted");
        _ = try settleExecutionAfterCleanup(
            &execution_cleanup,
            &execution_txn,
            admission.operation,
            cleanup_expected_stage,
            &cleanup_completion,
            &node.client,
            guard,
            &allocator_scope,
            &payload_ledger,
            .{ .post_execute_terminal = .local_invariant_violation },
        );
        return error.InvalidReceipt;
    };
    if (!correlated.responseMatchesPrepared()) {
        node.client.poison(.response_correlation_lost);
        payload_ledger.releasePromotedResponse(payload_receipt) catch
            @panic("safe response provenance release drifted");
        _ = try settleExecutionAfterCleanup(
            &execution_cleanup,
            &execution_txn,
            admission.operation,
            cleanup_expected_stage,
            &cleanup_completion,
            &node.client,
            guard,
            &allocator_scope,
            &payload_ledger,
            .{ .post_execute_terminal = .response_correlation_lost },
        );
        return error.InvalidReceipt;
    }
    const result: contract.ExecuteResult = .{ .accepted = correlated };
    switch (payload_ledger.transferPromotedResponse(
        payload_receipt,
        response_out,
        response_owner,
        response_incarnation,
        correlated,
    )) {
        .transferred => {},
        .rejected_safe_released => {
            node.client.poison(.local_invariant_violation);
            _ = try settleExecutionAfterCleanup(
                &execution_cleanup,
                &execution_txn,
                admission.operation,
                cleanup_expected_stage,
                &cleanup_completion,
                &node.client,
                guard,
                &allocator_scope,
                &payload_ledger,
                .{ .post_execute_terminal = .local_invariant_violation },
            );
            return error.InvalidResponseDestination;
        },
        .fail_stop_required => |reason| {
            _ = try settleExecutionAfterCleanup(
                &execution_cleanup,
                &execution_txn,
                admission.operation,
                cleanup_expected_stage,
                &cleanup_completion,
                &node.client,
                guard,
                &allocator_scope,
                &payload_ledger,
                .{ .post_execute_terminal = .local_invariant_violation },
            );
            node.client.poison(.local_invariant_violation);
            failStopResponsePayloadTransfer(reason);
        },
    }
    _ = try settleExecutionAfterCleanup(
        &execution_cleanup,
        &execution_txn,
        admission.operation,
        cleanup_expected_stage,
        &cleanup_completion,
        &node.client,
        guard,
        &allocator_scope,
        &payload_ledger,
        .post_execute_reusable,
    );
    return result;
}

fn responseDestinationValid(
    response_out: *executed_response_mod.ExecutedResponse,
    response_owner: *contract.ExecutedResponseOwnerSeal,
    binding: *contract.PreparedAttachmentBinding,
    storage: *client_mod.PreparedBlockingRpcStorage,
    owner_addr: usize,
    owner_size: usize,
    slot_addr: usize,
    node: *ClientNode,
) bool {
    const out_addr = @intFromPtr(response_out);
    const seal_addr = @intFromPtr(response_owner);
    // The existing attach destination is an owned field inside GenerationAttachment, so overlap
    // with the outer owner range is required to remain legal. It must still be disjoint from every
    // canonical node/binding/storage authority; the allocator guard separately rejects payloads
    // that alias any byte of the outer owner.
    if (byteRangesOverlap(out_addr, @sizeOf(executed_response_mod.ExecutedResponse), slot_addr, @sizeOf(ClientSlot)) or
        byteRangesOverlap(out_addr, @sizeOf(executed_response_mod.ExecutedResponse), @intFromPtr(node), @sizeOf(ClientNode)) or
        byteRangesOverlap(out_addr, @sizeOf(executed_response_mod.ExecutedResponse), @intFromPtr(binding), @sizeOf(contract.PreparedAttachmentBinding)) or
        byteRangesOverlap(out_addr, @sizeOf(executed_response_mod.ExecutedResponse), @intFromPtr(storage), @sizeOf(client_mod.PreparedBlockingRpcStorage)) or
        byteRangesOverlap(seal_addr, @sizeOf(contract.ExecutedResponseOwnerSeal), owner_addr, owner_size) or
        byteRangesOverlap(seal_addr, @sizeOf(contract.ExecutedResponseOwnerSeal), @intFromPtr(binding), @sizeOf(contract.PreparedAttachmentBinding)) or
        byteRangesOverlap(seal_addr, @sizeOf(contract.ExecutedResponseOwnerSeal), @intFromPtr(storage), @sizeOf(client_mod.PreparedBlockingRpcStorage)))
        return false;
    return response_out.canInitializeWithOwner(response_owner);
}

fn byteRangeFullyContained(
    inner_addr: usize,
    inner_len: usize,
    outer_addr: usize,
    outer_len: usize,
) bool {
    if (inner_len == 0 or outer_len == 0) return false;
    const inner_end = std.math.add(usize, inner_addr, inner_len) catch return false;
    const outer_end = std.math.add(usize, outer_addr, outer_len) catch return false;
    return inner_addr >= outer_addr and inner_end <= outer_end;
}

fn responseOwnerStillPristine(
    response_out: *const executed_response_mod.ExecutedResponse,
    response_owner: *const contract.ExecutedResponseOwnerSeal,
) bool {
    return response_out.canInitializeWithOwner(response_owner);
}

fn byteRangesOverlap(a_start: usize, a_len: usize, b_start: usize, b_len: usize) bool {
    const a_end = std.math.add(usize, a_start, a_len) catch return true;
    const b_end = std.math.add(usize, b_start, b_len) catch return true;
    return a_start < b_end and b_start < a_end;
}

fn issueGenerationResponseIncarnation() error{IdentityExhausted}!u64 {
    while (true) {
        const current = generation_response_incarnation_issuer.load(.monotonic);
        if (current == 0 or current == std.math.maxInt(u64)) return error.IdentityExhausted;
        if (generation_response_incarnation_issuer.cmpxchgWeak(
            current,
            current + 1,
            .monotonic,
            .monotonic,
        ) == null) return current;
    }
}

fn generationEventCorrupt(slot: *ClientSlot) GenerationEventError {
    slot.current.client.poison(.local_invariant_violation);
    return error.Corrupt;
}

fn armRegisteredOperationPoisonCapture(
    request: ?RegisteredOperationPoisonCaptureRequest,
    operation: RegisteredNodeOperation,
) GenerationEventError!?*incident_publication_contract.RegisteredOperationPoisonCapture {
    const input = request orelse return null;
    if (input.timestamp_ns < 0 or input.controller_generation == 0 or
        std.enums.fromInt(connection_incident.SourceSite, input.source_site_raw) == null or
        input.capture_addr == 0 or input.prepared_addr == 0)
        return error.InvalidOwner;
    const capture: *incident_publication_contract.RegisteredOperationPoisonCapture =
        @ptrFromInt(input.capture_addr);
    const prepared: *incident_publication_contract.PreparedManagedPoison =
        @ptrFromInt(input.prepared_addr);
    if (!std.meta.eql(capture.*, incident_publication_contract.RegisteredOperationPoisonCapture{}) or
        !std.meta.eql(prepared.*, incident_publication_contract.PreparedManagedPoison{}) or
        byteRangesOverlap(@intFromPtr(capture), @sizeOf(@TypeOf(capture.*)), @intFromPtr(prepared), @sizeOf(@TypeOf(prepared.*))) or
        rangesOverlapTyped(capture, operation.node) or rangesOverlapTyped(capture, &operation.node.client) or
        rangesOverlapTyped(prepared, operation.node) or rangesOverlapTyped(prepared, &operation.node.client))
        return error.InvalidOwner;
    capture.* = .{
        .self_addr = @intFromPtr(capture),
        .prepared_addr = @intFromPtr(prepared),
        .client_addr = @intFromPtr(&operation.node.client),
        .operation_id = operation.operation_id,
        .timestamp_ns = input.timestamp_ns,
        .controller_generation = input.controller_generation,
        .source_site_raw = input.source_site_raw,
        .lifecycle_raw = @intFromEnum(incident_publication_contract.RegisteredOperationPoisonCaptureLifecycle.armed),
    };
    return capture;
}

fn captureRegisteredOperationPoison(
    slot: *ClientSlot,
    operation: RegisteredNodeOperation,
    capture: ?*incident_publication_contract.RegisteredOperationPoisonCapture,
    reason: client_poison.ConnectionReason,
) GenerationEventError {
    const active = capture orelse {
        operation.node.client.poisonDuringClientSlotOperationNoFail(reason);
        return error.Corrupt;
    };
    if (active.self_addr != @intFromPtr(active) or
        active.client_addr != @intFromPtr(&operation.node.client) or
        active.operation_id != operation.operation_id or active.prepared_addr == 0 or
        active.lifecycle_raw != @intFromEnum(incident_publication_contract.RegisteredOperationPoisonCaptureLifecycle.armed))
        process_seal_service.fatalIntegrity(.incident_authority);
    active.reason_raw = @intFromEnum(reason);
    active.lifecycle_raw = @intFromEnum(incident_publication_contract.RegisteredOperationPoisonCaptureLifecycle.captured);
    const prepared: *incident_publication_contract.PreparedManagedPoison = @ptrFromInt(active.prepared_addr);
    prepareManagedPoisonRequestPinned(
        slot,
        operation.node,
        active.timestamp_ns,
        .{
            .reason_raw = active.reason_raw,
            .source_site_raw = active.source_site_raw,
            .controller_generation = active.controller_generation,
        },
        prepared,
    ) catch return error.Corrupt;
    active.lifecycle_raw = @intFromEnum(incident_publication_contract.RegisteredOperationPoisonCaptureLifecycle.finalized);
    return error.Corrupt;
}

pub fn takeGenerationEvent(
    request: GenerationEventTakeRequest,
) GenerationEventError!GenerationEventTakeOutcome {
    if (request.bound_stream_id == 0 or request.event_owner_addr == 0 or
        request.event_lease_addr == 0 or
        !byteRangeFullyContained(
            request.event_lease_addr,
            @sizeOf(lease_mod.ConnectionLease),
            request.owner.owner_addr,
            request.owner.owner_size,
        ))
        return error.InvalidOwner;
    const admission = beginGenerationRequestOwner(request.owner, false) catch |err| return switch (err) {
        error.Busy => error.Busy,
        else => error.InvalidOwner,
    };
    const slot: *ClientSlot = @ptrFromInt(request.owner.slot_addr);
    endRegisteredNodeOperation(admission.operation);

    const permit = slot.prepareStreamOperationPermit(
        .event,
        request.event_owner_addr,
        request.owner.transport_incarnation,
        request.owner.reservation.identity,
    ) catch |err| return switch (err) {
        error.AdminBusy => error.Busy,
        error.IdentityExhausted => error.Terminal,
        error.InvalidStreamOperationPermit => error.InvalidOwner,
    };
    var permit_live = true;
    defer if (permit_live) slot.abortStreamOperationPermit(permit) catch unreachable;

    var prepared: client_mod.PreparedGenerationEventTake = .{};
    const kind = slot.current.client.prepareGenerationEventTake(
        request.bound_stream_id,
        &prepared,
    ) catch |err| return switch (err) {
        error.Busy => error.Busy,
        error.Terminal => error.Terminal,
        error.Corrupt, error.DestinationOccupied => generationEventCorrupt(slot),
    };
    defer slot.current.client.abortGenerationEventTake(&prepared);
    switch (kind) {
        .idle => {
            slot.consumeStreamOperationPermitNoFail(permit);
            permit_live = false;
            return .idle;
        },
        .ended_pending => {
            slot.current.client.abortGenerationEventTake(&prepared);
            slot.consumeStreamOperationPermitNoFail(permit);
            permit_live = false;
            return .ended_pending;
        },
        .ordinary => {},
    }

    const operation = beginRegisteredNodeOperation(.{
        .slot_addr = request.owner.slot_addr,
        .slot_incarnation = request.owner.slot_incarnation,
        .node = .{ .incarnation = request.owner.node_incarnation },
    }) catch |err| return switch (err) {
        error.Busy => error.Busy,
        error.InvalidOwner => error.InvalidOwner,
    };
    const poison_capture = try armRegisteredOperationPoisonCapture(request.poison_capture, operation);
    defer if (poison_capture) |capture| {
        capture.* = .{};
    };
    defer {
        endRegisteredNodeOperation(operation);
        if (builtin.is_test and EventTakeActivationTestHook.probe_contention)
            EventTakeActivationTestHook.suffix_stage = 5;
    }
    const node = operation.node;
    if (!slot.streamOperationPermitLive(permit)) return error.Busy;
    const protected_ranges = [_]FinalAdmissionProtectedRange{
        .{ .start = request.owner.owner_addr, .len = request.owner.owner_size },
        .{ .start = request.event_lease_addr, .len = @sizeOf(lease_mod.ConnectionLease) },
        .{ .start = @intFromPtr(&prepared), .len = @sizeOf(client_mod.PreparedGenerationEventTake) },
    };
    var activation: EventTakeActivationTransaction = .{};
    beginEventTakeActivationTransaction(
        &activation,
        &operation,
        &prepared,
        permit,
        &protected_ranges,
    ) catch |err| {
        if (err == error.Busy)
            slot.current.client.abortGenerationEventTakeDuringRegisteredOperation(&prepared);
        return err;
    };
    defer activation.finish();
    defer slot.current.client.abortGenerationEventTakeUnderRegisteredOperationExecutionLease(
        activation.admission.execution_handle.?,
        &prepared,
    );
    var owned: ?client_mod.OwnedGenerationEvent = null;
    const validated = slot.current.client
        .validateGenerationEventTakeUnderRegisteredOperationExecutionLease(
        activation.admission.execution_handle.?,
        &prepared,
        &owned,
    ) catch |err| {
        if (err == error.Corrupt or err == error.InvalidPrepared) {
            return captureRegisteredOperationPoison(
                slot,
                operation,
                poison_capture,
                .local_invariant_violation,
            );
        }
        return switch (err) {
            error.Terminal => error.Terminal,
            error.Corrupt, error.InvalidPrepared => error.Corrupt,
        };
    };
    if (builtin.is_test and EventTakeActivationTestHook.managed_poison_after_validation)
        return captureRegisteredOperationPoison(
            slot,
            operation,
            poison_capture,
            .local_invariant_violation,
        );
    if (validated.payload.len == 0 or
        byteRangesOverlap(
            @intFromPtr(validated.payload.ptr),
            validated.payload.len,
            request.owner.owner_addr,
            request.owner.owner_size,
        ) or
        byteRangesOverlap(
            @intFromPtr(validated.payload.ptr),
            validated.payload.len,
            request.owner.slot_addr,
            @sizeOf(ClientSlot),
        ) or
        byteRangesOverlap(
            @intFromPtr(validated.payload.ptr),
            validated.payload.len,
            @intFromPtr(slot.current),
            @sizeOf(ClientNode),
        ) or
        byteRangesOverlap(
            @intFromPtr(validated.payload.ptr),
            validated.payload.len,
            request.event_lease_addr,
            @sizeOf(lease_mod.ConnectionLease),
        ))
    {
        return captureRegisteredOperationPoison(
            slot,
            operation,
            poison_capture,
            .local_invariant_violation,
        );
    }
    const trusted_admission = runtime_event_wire.preflightEvent(
        validated.payload,
        .{},
    );
    const TrustedAdmission = struct {
        tag: u8,
        digest: runtime_event_wire.Digest,
        ordering: cleanup_registry_mod.EventOrderingClass,
    };
    const trusted_admission_projection: TrustedAdmission = switch (trusted_admission) {
        .accepted => |accepted| .{
            .tag = 1,
            .digest = runtime_event_wire.eventPreflightProjectionDigest(accepted),
            .ordering = if (accepted.event == .revoked)
                .controller_revoke
            else
                .non_revoke_effect,
        },
        .unknown => .{
            .tag = 0,
            .digest = [_]u8{0} ** 32,
            .ordering = .non_revoke_effect,
        },
        else => {
            return captureRegisteredOperationPoison(
                slot,
                operation,
                poison_capture,
                .local_invariant_violation,
            );
        },
    };
    const quarantine = &(generation_event_quarantine_registry orelse return error.InvalidOwner);
    if (EventTakeActivationTestHook.failAt(.quarantine_reserve)) return error.Busy;
    const thread_id: u64 = @intCast(std.Thread.getCurrentId());
    const expected_major = slot.current.client.parser.expected_major;
    const metadata_support_raw = @as(*const u8, @ptrCast(&slot.current.client.metadata_support)).*;
    const quarantine_reservation = quarantine.reserveUnbound(
        currentPid(),
        thread_id,
        request.owner.node_incarnation,
        request.event_owner_addr,
        .{
            .payload_addr = prepared.payload_addr,
            .payload_len = prepared.payload_len,
            .payload_digest = prepared.payload_digest,
            .admission_projection_digest = trusted_admission_projection.digest,
            .wire_major = prepared.header.major,
            .expected_major = expected_major,
            .admission_tag = trusted_admission_projection.tag,
            .metadata_support_raw = metadata_support_raw,
            // Allocator context is deliberately not serialized: stateless allocators may carry
            // undefined/zero context bits. The typed allocator travels with EventOwner instead.
            .allocator_ptr = 0,
            .allocator_vtable = @intFromPtr(slot.current.client.allocator.vtable),
            .pin_owner_addr = @intFromPtr(&slot.current.pin_owner),
            .lease_addr = request.event_lease_addr,
            .slot_addr = request.owner.slot_addr,
            .slot_incarnation = request.owner.slot_incarnation,
            .node_addr = @intFromPtr(slot.current),
            .node_incarnation = request.owner.node_incarnation,
            .host_id = request.owner.host_id,
            .connection_generation = request.owner.reservation.identity.connection_generation,
            .stream_id = request.bound_stream_id,
            .process_nonce = request.owner.process_nonce,
            .owner_thread_id = thread_id,
        },
    ) catch |err| return switch (err) {
        error.CapacityExhausted, error.ByteCapacityExhausted, error.Busy => error.Busy,
        error.ProcessDomainMismatch,
        error.ThreadDomainMismatch,
        error.InvalidIdentity,
        error.InvalidState,
        => blk: {
            break :blk captureRegisteredOperationPoison(
                slot,
                operation,
                poison_capture,
                .local_invariant_violation,
            );
        },
    };
    var quarantine_live = true;
    activation.setQuarantineLive(true);
    defer if (quarantine_live) {
        quarantine.rollback(
            currentPid(),
            thread_id,
            quarantine_reservation,
        ) catch @panic("event quarantine rollback failed");
        activation.setResourceLive(.quarantine, false);
    };

    if (EventTakeActivationTestHook.failAt(.pin_reserve)) return error.Busy;
    const pin_projection = lease_mod.reserveCanonicalPin(
        &slot.current.pin_owner,
        request.event_lease_addr,
        request.bound_stream_id,
        currentPid(),
    ) catch |err| return switch (err) {
        error.PinOverflow => error.Terminal,
        error.InvalidOwner, error.InvalidStream => blk: {
            break :blk captureRegisteredOperationPoison(
                slot,
                operation,
                poison_capture,
                .local_invariant_violation,
            );
        },
    };
    var pin_live = true;
    activation.setPinLive(true);
    defer if (pin_live) {
        lease_mod.rollbackCanonicalPinUnchecked(
            pin_projection,
            &slot.current.pin_owner,
            currentPid(),
        );
        activation.setResourceLive(.pin, false);
    };
    if (EventTakeActivationTestHook.failAt(.authority_reserve)) return error.Busy;
    const receipt = node.cleanup_registry.reserveEventGenerationWithOrdering(
        request.owner.reservation.cleanup,
        request.owner.reservation.identity,
        request.bound_stream_id,
        request.event_owner_addr,
        trusted_admission_projection.ordering,
    ) catch |err| {
        return switch (err) {
            error.IdentityExhausted => error.Terminal,
            error.InvalidState => error.Busy,
            else => error.InvalidOwner,
        };
    };
    const correlation = mintEventCorrelation(.{
        .identity = .{ .owner = request.owner, .receipt = receipt },
        .ordering_class = trusted_admission_projection.ordering,
        .expected_major = expected_major,
        .metadata_support_raw = metadata_support_raw,
    });
    var reservation_live = true;
    activation.setAuthorityLive(true);
    if (builtin.is_test and EventTakeActivationTestHook.probe_contention) {
        batch_release_callback_active = true;
        EventTakeActivationTestHook.reentry_busy = if (takeGenerationEvent(request)) |_| false else |err| err == error.Busy;
        batch_release_callback_active = false;
        EventTakeActivationTestHook.teardown_busy = if (slot.current.client.tryAcquireClientSlotTeardownExclusive()) |_| false else |err| err == error.AdminBusy;
        const ForeignProbe = struct {
            fn run(client: *client_mod.Client, busy: *bool) void {
                busy.* = if (client.call("host.info", null)) |_| false else |err| err == error.AdminBusy;
            }
        };
        const thread = std.Thread.spawn(.{}, ForeignProbe.run, .{
            &slot.current.client,
            &EventTakeActivationTestHook.foreign_busy,
        }) catch @panic("C3-3a3 foreign probe spawn failed");
        thread.join();
    }
    defer if (reservation_live) {
        slot.current.cleanup_registry.rollbackEventGenerationBeforePublishNoFail(
            request.owner.reservation.cleanup,
            request.owner.reservation.identity,
            receipt,
        );
        activation.setResourceLive(.authority, false);
    };
    if (EventTakeActivationTestHook.failAt(.cleanup_bind)) return error.Busy;
    const quarantine_identity = quarantine.bind(
        currentPid(),
        thread_id,
        quarantine_reservation,
        receipt.event_generation,
    ) catch |err| {
        return switch (err) {
            error.CapacityExhausted, error.ByteCapacityExhausted, error.Busy => error.Busy,
            else => blk: {
                break :blk captureRegisteredOperationPoison(
                    slot,
                    operation,
                    poison_capture,
                    .local_invariant_violation,
                );
            },
        };
    };
    node.cleanup_registry.bindEventCleanupNoFail(
        request.owner.reservation.cleanup,
        request.owner.reservation.identity,
        receipt,
        quarantine_reservation.slot_index,
        quarantine_reservation.reservation_generation,
    );
    slot.current.client.commitGenerationEventTakeUnderRegisteredOperationExecutionLease(
        activation.admission.execution_handle.?,
        &prepared,
        &owned,
        validated,
    ) catch |err| return switch (err) {
        error.Terminal => error.Terminal,
        error.Corrupt, error.InvalidPrepared => blk: {
            break :blk captureRegisteredOperationPoison(
                slot,
                operation,
                poison_capture,
                .local_invariant_violation,
            );
        },
    };
    const event = owned orelse unreachable;
    slot.current.cleanup_registry.commitEventGenerationPublicationNoFail(
        request.owner.reservation.cleanup,
        request.owner.reservation.identity,
        receipt,
    );
    if (builtin.is_test) EventTakeActivationTestHook.suffix_stage = 1;
    slot.consumeStreamOperationPermitNoFail(permit);
    if (builtin.is_test) EventTakeActivationTestHook.suffix_stage = 2;
    permit_live = false;
    reservation_live = false;
    quarantine_live = false;
    pin_live = false;
    activation.setResourceLive(.authority, false);
    activation.setResourceLive(.quarantine, false);
    activation.setResourceLive(.pin, false);
    if (builtin.is_test) EventTakeActivationTestHook.suffix_stage = 3;
    return .{ .taken = .{
        .identity = .{ .owner = request.owner, .receipt = receipt },
        .correlation = correlation,
        .header = event.header,
        .payload = event.payload,
        .payload_allocator = event.payload_allocator,
        .admission = event.preflight,
        .quarantine_reservation = quarantine_reservation,
        .quarantine_identity = quarantine_identity,
        .pin_projection = pin_projection,
    } };
}

pub fn generationEventAttachmentReadiness(
    owner: GenerationTransportOwnerQuery,
    bound_stream_id: u64,
    event_owner_addr: usize,
    generation_mirror: u64,
) GenerationEventError!GenerationEventAttachmentReadiness {
    if (bound_stream_id == 0 or event_owner_addr == 0) return error.InvalidOwner;
    const operation = beginGenerationRequestOwner(owner, false) catch |err| return switch (err) {
        error.Busy => error.Busy,
        else => error.InvalidOwner,
    };
    defer endRegisteredNodeOperation(operation.operation);
    return operation.operation.node.cleanup_registry.eventAttachmentReadiness(
        owner.reservation.cleanup,
        owner.reservation.identity,
        event_owner_addr,
        generation_mirror,
    ) catch |err| switch (err) {
        error.InvalidState => error.Corrupt,
        else => error.InvalidOwner,
    };
}

pub fn pumpGenerationPendingOutput(
    owner: GenerationTransportOwnerQuery,
) GenerationEventError!bool {
    const admission = beginGenerationRequestOwner(owner, false) catch |err| return switch (err) {
        error.Busy => error.Busy,
        else => error.InvalidOwner,
    };
    defer endRegisteredNodeOperation(admission.operation);
    var transaction: FinalAdmissionTransaction = .{};
    const decision = finalAdmissionTransactionWithOperationAndRegistry(
        &admission.operation,
        &transaction,
        &.{},
    ) catch |err| return err;
    if (decision == .blocked) return false;
    defer transaction.finish() catch
        @panic("pending output final admission settlement failed");
    return admission.operation.node.client
        .pumpPendingOutputUnderRegisteredOperationExecutionLease(
        transaction.execution_handle.?,
    ) catch |err| return switch (err) {
        error.AdminBusy => error.Busy,
        error.ConnectionClosed => error.InvalidOwner,
        else => error.Terminal,
    };
}

/// RX is deliberately admitted without consulting the connection ordering blocker: a live event
/// owns that blocker precisely so TX cannot overtake it, while the shared socket must continue to
/// demultiplex sibling frames. The ordinary registered-operation and final-address execution
/// lease still exclude teardown, allocator reentry, copied owners, and concurrent wire readers.
pub fn pumpGenerationRxDemux(
    owner: GenerationTransportOwnerQuery,
) GenerationEventError!void {
    const admission = beginGenerationRequestOwner(owner, true) catch |err| return switch (err) {
        error.Busy => error.Busy,
        else => error.InvalidOwner,
    };
    defer endRegisteredNodeOperation(admission.operation);
    var transaction: FinalAdmissionTransaction = .{};
    rxDemuxAdmissionTransactionWithOperation(
        &admission.operation,
        &transaction,
    ) catch |err| return err;
    defer transaction.finish() catch
        @panic("RX demux final admission settlement failed");
    admission.operation.node.client
        .pumpRxDemuxUnderRegisteredOperationExecutionLease(
        transaction.execution_handle.?,
    ) catch |err| return switch (err) {
        error.AdminBusy => error.Busy,
        error.ConnectionClosed => error.Terminal,
        else => error.Corrupt,
    };
}

pub fn sendGenerationInput(
    owner: GenerationTransportOwnerQuery,
    stream_id: u64,
    bytes: []const u8,
) GenerationInputError!void {
    const admission = try beginGenerationInputOwner(owner, stream_id);
    defer endRegisteredNodeOperation(admission.operation);
    var transaction: FinalAdmissionTransaction = .{};
    const protected = [_]FinalAdmissionProtectedRange{.{
        .start = @intFromPtr(bytes.ptr),
        .len = bytes.len,
    }};
    const decision = try finalAdmissionTransactionWithOperationAndRegistry(
        &admission.operation,
        &transaction,
        &protected,
    );
    if (decision == .blocked) return error.Busy;
    defer transaction.finish() catch @panic("generation input admission settlement failed");
    return admission.operation.node.client.sendInputUnderRegisteredOperationExecutionLease(
        transaction.execution_handle.?,
        stream_id,
        bytes,
    );
}

pub fn sendGenerationInputNonBlocking(
    owner: GenerationTransportOwnerQuery,
    stream_id: u64,
    bytes: []const u8,
) GenerationInputError!usize {
    const admission = try beginGenerationInputOwner(owner, stream_id);
    defer endRegisteredNodeOperation(admission.operation);
    var transaction: FinalAdmissionTransaction = .{};
    const protected = [_]FinalAdmissionProtectedRange{.{
        .start = @intFromPtr(bytes.ptr),
        .len = bytes.len,
    }};
    const decision = try finalAdmissionTransactionWithOperationAndRegistry(
        &admission.operation,
        &transaction,
        &protected,
    );
    if (decision == .blocked) return 0;
    defer transaction.finish() catch @panic("generation nonblocking input admission settlement failed");
    return admission.operation.node.client
        .sendInputNonBlockingUnderRegisteredOperationExecutionLease(
        transaction.execution_handle.?,
        stream_id,
        bytes,
    );
}

fn beginGenerationInputOwner(
    owner: GenerationTransportOwnerQuery,
    stream_id: u64,
) GenerationInputError!GenerationRequestOwner {
    return beginBoundControllerMutationOwner(owner, stream_id) catch |err| return err;
}

fn beginBoundControllerMutationOwner(
    request: anytype,
    stream_id: u64,
) error{ Busy, InvalidOwner, Unauthorized }!GenerationRequestOwner {
    const admission = beginGenerationRequestOwner(request, false) catch |err| return switch (err) {
        error.Busy => error.Busy,
        else => error.InvalidOwner,
    };
    errdefer endRegisteredNodeOperation(admission.operation);
    const live = admission.operation.node.cleanup_registry.controllerAuthorityLive(
        request.reservation.cleanup,
        admission.identity,
        stream_id,
    ) catch return error.InvalidOwner;
    if (!live) return error.Unauthorized;
    return admission;
}

pub fn sendGenerationResyncNonBlocking(
    owner: GenerationTransportOwnerQuery,
    stream_id: u64,
) GenerationInputError!bool {
    const admission = beginGenerationRequestOwner(owner, false) catch |err| return switch (err) {
        error.Busy => error.Busy,
        else => error.InvalidOwner,
    };
    defer endRegisteredNodeOperation(admission.operation);
    var transaction: FinalAdmissionTransaction = .{};
    const decision = try finalAdmissionTransactionWithOperationAndRegistry(
        &admission.operation,
        &transaction,
        &.{},
    );
    if (decision == .blocked) return false;
    defer transaction.finish() catch @panic("generation resync admission settlement failed");
    const accepted = try admission.operation.node.client
        .sendResyncNonBlockingUnderRegisteredOperationExecutionLease(
        transaction.execution_handle.?,
        stream_id,
    );
    return accepted;
}

/// Lock-free notification projection used by the owner-thread frame pump. It validates the
/// stable slot/node identity but deliberately does not scan either 4,096-entry registry; false
/// means no recovery work and must remain the idle fast path.
pub fn generationScreenRecoveryState(
    owner: GenerationTransportOwnerQuery,
    stream_id: u64,
) GenerationInputError!client_mod.ScreenRecoveryState {
    if (stream_id == 0 or owner.slot_addr == 0 or owner.slot_incarnation == 0 or
        owner.node_incarnation == 0 or owner.host_id == 0 or owner.transport_addr == 0 or
        owner.transport_incarnation == 0 or owner.owner_addr == 0 or owner.owner_size == 0 or
        owner.pid != currentPid() or owner.process_nonce == 0 or
        client_mod.generationAllocatorCallbackActive())
        return error.InvalidOwner;
    const slot: *ClientSlot = @ptrFromInt(owner.slot_addr);
    if (slot.self_addr != owner.slot_addr or slot.lifecycle != .live or
        slot.pid != owner.pid or slot.process_nonce != owner.process_nonce or
        slot.incarnation.tagged != owner.slot_incarnation or
        slot.current.incarnation.tagged != owner.node_incarnation or
        slot.current.client.host_id != owner.host_id or
        slot.current.pin_owner.slot_addr != owner.slot_addr or
        slot.current.pin_owner.node_addr != @intFromPtr(slot.current) or
        !operationThreadMatches(slot.operation_owner_thread_incarnation))
        return error.InvalidOwner;
    return slot.current.client.screenRecoveryState(stream_id);
}

pub fn callGenerationRpc(
    owner: GenerationTransportOwnerQuery,
    method: []const u8,
    params_json: ?[]const u8,
) client_mod.ClientError![]u8 {
    const admission = beginGenerationRequestOwner(owner, false) catch |err| return switch (err) {
        error.Busy => error.AdminBusy,
        else => error.ProtocolError,
    };
    defer endRegisteredNodeOperation(admission.operation);
    var transaction: FinalAdmissionTransaction = .{};
    var protected: [2]FinalAdmissionProtectedRange = undefined;
    var protected_len: usize = 0;
    if (method.len != 0) {
        protected[protected_len] = .{ .start = @intFromPtr(method.ptr), .len = method.len };
        protected_len += 1;
    }
    if (params_json) |params| if (params.len != 0) {
        protected[protected_len] = .{ .start = @intFromPtr(params.ptr), .len = params.len };
        protected_len += 1;
    };
    const decision = finalAdmissionTransactionWithOperationAndRegistry(
        &admission.operation,
        &transaction,
        protected[0..protected_len],
    ) catch |err| return switch (err) {
        error.Busy => error.AdminBusy,
        error.InvalidOwner => error.ProtocolError,
    };
    if (decision == .blocked) return error.AdminBusy;
    defer transaction.finish() catch @panic("generation RPC admission settlement failed");
    return admission.operation.node.client.callUnderRegisteredOperationExecutionLease(
        transaction.execution_handle.?,
        method,
        params_json,
    );
}

/// Projects the existing ended-purge transaction through one sealed generation binding. The
/// fast path only peeks at the first target event; the slow path retains all queue ownership and
/// cleanup policy in Client/ClientSlot rather than exposing a stream id or scratch storage.
pub fn purgeGenerationEndedStream(
    owner: GenerationTransportOwnerQuery,
    bound_stream_id: u64,
) GenerationEndedPurgeError!GenerationEndedPurgeOutcome {
    if (bound_stream_id == 0) return error.InvalidOwner;
    const admission = beginGenerationRequestOwner(owner, false) catch |err| return switch (err) {
        error.Busy => error.Busy,
        else => error.InvalidOwner,
    };
    const slot: *ClientSlot = @ptrFromInt(owner.slot_addr);
    const event_readiness = admission.operation.node.cleanup_registry.eventPurgeReadiness(
        owner.reservation.cleanup,
        admission.identity,
        admission.owner.event_owner_addr,
    ) catch {
        admission.operation.node.client.poison(.local_invariant_violation);
        endRegisteredNodeOperation(admission.operation);
        return error.Corrupt;
    };
    if (event_readiness == .busy) {
        endRegisteredNodeOperation(admission.operation);
        return error.Busy;
    }
    if (event_readiness != .ready) {
        admission.operation.node.client.poison(.local_invariant_violation);
        endRegisteredNodeOperation(admission.operation);
        return error.Corrupt;
    }
    const peek = admission.operation.node.client.peekEndedEventForStream(bound_stream_id) catch {
        admission.operation.node.client.poison(.local_invariant_violation);
        endRegisteredNodeOperation(admission.operation);
        return error.Corrupt;
    };
    endRegisteredNodeOperation(admission.operation);
    const hint = switch (peek) {
        .not_ended => return .not_ended,
        .candidate => |candidate| candidate,
    };

    var scratch: client_mod.EndedPurgeScratch = .{};
    var preparation: EndedPurgePreparation = .{};
    slot.prepareEndedPurge(
        owner.transport_incarnation,
        owner.reservation,
        bound_stream_id,
        hint,
        &scratch,
        &preparation,
    ) catch |err| return switch (err) {
        error.Busy => error.Busy,
        error.InvalidOwner => error.InvalidOwner,
        error.Corrupt, error.DestinationOccupied => error.Corrupt,
        error.IdentityExhausted => error.Terminal,
    };
    var preparation_live = true;
    defer if (preparation_live and !preparation.abort(slot))
        @panic("generation ended purge rollback failed");
    _ = slot.commitEndedPurge(&scratch, &preparation) catch |err| return switch (err) {
        error.Busy, error.QuarantineUnavailable => error.Busy,
        error.InvalidOwner => error.InvalidOwner,
        error.InvalidState => error.Terminal,
        error.Corrupt, error.ArithmeticOverflow, error.DestinationOccupied => error.Corrupt,
    };
    preparation_live = false;
    return .purged;
}

pub fn generationEventOwnerCurrent(
    identity: GenerationEventIdentity,
    owner_addr: usize,
) GenerationEventError!void {
    if (owner_addr == 0 or identity.receipt.owner_addr != owner_addr)
        return error.InvalidOwner;
    const admission = beginGenerationRequestOwner(identity.owner, false) catch |err| return switch (err) {
        error.Busy => error.Busy,
        else => error.InvalidOwner,
    };
    defer endRegisteredNodeOperation(admission.operation);
    const current = admission.operation.node.cleanup_registry.eventGenerationCurrent(
        identity.owner.reservation.cleanup,
        identity.owner.reservation.identity,
        identity.receipt,
    ) catch return error.Corrupt;
    if (!current) return error.Terminal;
}

/// Atomically changes the exact registered event from ordinary live authority to preparation
/// pending.  The registered-node operation is the linearization boundary against release,
/// teardown, and ended purge; no Client graph pointer escapes it.
pub fn beginGenerationEventPreparationPending(
    identity: GenerationEventIdentity,
    owner_addr: usize,
) GenerationEventError!void {
    if (owner_addr == 0 or identity.receipt.owner_addr != owner_addr)
        return error.InvalidOwner;
    const admission = beginGenerationRequestOwner(identity.owner, false) catch |err| return switch (err) {
        error.Busy => error.Busy,
        else => error.InvalidOwner,
    };
    defer endRegisteredNodeOperation(admission.operation);
    admission.operation.node.cleanup_registry.beginEventPreparationPending(
        identity.owner.reservation.cleanup,
        identity.owner.reservation.identity,
        identity.receipt,
    ) catch |err| return switch (err) {
        error.InvalidState => error.Busy,
        else => error.InvalidOwner,
    };
}

fn rollbackGenerationEventPreparationPendingForTest(
    identity: GenerationEventIdentity,
    owner_addr: usize,
) GenerationEventError!void {
    if (!builtin.is_test) unreachable;
    if (owner_addr == 0 or identity.receipt.owner_addr != owner_addr)
        return error.InvalidOwner;
    const admission = beginGenerationRequestOwner(identity.owner, false) catch |err| return switch (err) {
        error.Busy => error.Busy,
        else => error.InvalidOwner,
    };
    defer endRegisteredNodeOperation(admission.operation);
    cleanup_registry_mod.testing.rollbackEventPreparationPending(
        &admission.operation.node.cleanup_registry,
        identity.owner.reservation.cleanup,
        identity.owner.reservation.identity,
        identity.receipt,
    ) catch return error.InvalidOwner;
}

const GenerationEventEvidence = struct {
    trusted_view: GenerationEventTrustedView,
    preparation: ?GenerationEventPreparationProjection,
};

const TrustedGenerationEventEvidence = struct {
    event: cleanup_registry_mod.EventGenerationReceipt,
    quarantine_slot_index: u16,
    quarantine_reservation_generation: u64,
    ordering_class: cleanup_registry_mod.EventOrderingClass,
};

fn validatedGenerationEventEvidence(
    identity: GenerationEventIdentity,
    owner_addr: usize,
    correlation: ?EventCorrelation,
) GenerationEventError!GenerationEventEvidence {
    if (owner_addr == 0 or identity.receipt.owner_addr != owner_addr)
        return error.InvalidOwner;
    const admission = beginGenerationRequestOwner(identity.owner, false) catch |err| return switch (err) {
        error.Busy => error.Busy,
        else => error.InvalidOwner,
    };
    defer endRegisteredNodeOperation(admission.operation);
    const trusted: TrustedGenerationEventEvidence = if (correlation != null) pending: {
        const value = admission.operation.node.cleanup_registry.trustedEventPreparation(
            identity.owner.reservation.cleanup,
            identity.owner.reservation.identity,
            owner_addr,
        ) catch return error.Corrupt;
        break :pending .{
            .event = value.event,
            .quarantine_slot_index = value.quarantine_slot_index,
            .quarantine_reservation_generation = value.quarantine_reservation_generation,
            .ordering_class = value.ordering_class,
        };
    } else cleanup: {
        const value = admission.operation.node.cleanup_registry.trustedEventCleanup(
            identity.owner.reservation.cleanup,
            identity.owner.reservation.identity,
            owner_addr,
        ) catch return error.Corrupt;
        break :cleanup .{
            .event = value.event,
            .quarantine_slot_index = value.quarantine_slot_index,
            .quarantine_reservation_generation = value.quarantine_reservation_generation,
            .ordering_class = value.ordering_class,
        };
    };
    if (!std.meta.eql(trusted.event, identity.receipt)) return error.Corrupt;
    const reservation: GenerationEventQuarantine.Reservation = .{
        .slot_index = trusted.quarantine_slot_index,
        .reservation_generation = trusted.quarantine_reservation_generation,
        .node_incarnation = trusted.event.node_incarnation,
        .owner_addr = trusted.event.owner_addr,
    };
    const quarantine_identity: GenerationEventQuarantine.Identity = .{
        .node_incarnation = trusted.event.node_incarnation,
        .event_generation = trusted.event.event_generation,
        .owner_addr = trusted.event.owner_addr,
    };
    const quarantine = &(generation_event_quarantine_registry orelse return error.InvalidOwner);
    const mirror = quarantine.trustedMirror(
        currentPid(),
        @intCast(std.Thread.getCurrentId()),
        reservation,
        quarantine_identity,
    ) catch return error.Corrupt;
    const correlation_input: EventCorrelationInput = .{
        .identity = identity,
        .ordering_class = trusted.ordering_class,
        .expected_major = mirror.expected_major,
        .metadata_support_raw = mirror.metadata_support_raw,
    };
    const correlation_binding_digest: ?runtime_event_wire.Digest = if (correlation) |value| digest: {
        if (!eventCorrelationMatches(value, correlation_input)) return error.Corrupt;
        break :digest eventCorrelationDigest(correlation_input);
    } else null;
    if (builtin.is_test and preparation_projection_test_hook.armed) {
        const callback = preparation_projection_test_hook.callback orelse
            @panic("preparation projection hook lost callback");
        const context = preparation_projection_test_hook.context orelse
            @panic("preparation projection hook lost context");
        preparation_projection_test_hook = .{};
        callback(context, .{
            .expected_major = mirror.expected_major,
            .metadata_support_raw = mirror.metadata_support_raw,
            .correlation_binding_digest = correlation_binding_digest orelse
                @panic("preparation projection hook requires correlation"),
            .payload_digest = mirror.payload_digest,
            .admission_projection_digest = mirror.admission_projection_digest,
            .wire_major = mirror.wire_major,
            .admission_tag = mirror.admission_tag,
            .registry_incarnation = trusted.event.registry_incarnation,
            .binding_reservation_id = trusted.event.binding_reservation_id,
            .event_node_incarnation = trusted.event.node_incarnation,
            .stream_id = trusted.event.stream_id,
            .event_generation = trusted.event.event_generation,
            .event_owner_addr = @intCast(trusted.event.owner_addr),
            .slot_incarnation = identity.owner.slot_incarnation,
            .owner_node_incarnation = identity.owner.node_incarnation,
            .transport_incarnation = identity.owner.transport_incarnation,
            .host_id = identity.owner.host_id,
            .runtime_id = identity.owner.reservation.identity.runtime_id,
            .connection_generation = identity.owner.reservation.identity.connection_generation,
            .pid = identity.owner.reservation.identity.pid,
            .process_nonce = identity.owner.reservation.identity.process_nonce,
        });
    }
    // Materialize only pointer-free evidence while the registered-node operation pins the graph.
    return .{
        .trusted_view = .{
            .payload_digest = mirror.payload_digest,
            .admission_projection_digest = mirror.admission_projection_digest,
            .wire_major = mirror.wire_major,
            .admission_tag = mirror.admission_tag,
        },
        .preparation = if (correlation_binding_digest) |correlation_digest| .{
            .expected_major = mirror.expected_major,
            .metadata_support_raw = mirror.metadata_support_raw,
            .correlation_binding_digest = correlation_digest,
            .payload_digest = mirror.payload_digest,
            .admission_projection_digest = mirror.admission_projection_digest,
            .wire_major = mirror.wire_major,
            .admission_tag = mirror.admission_tag,
            .registry_incarnation = trusted.event.registry_incarnation,
            .binding_reservation_id = trusted.event.binding_reservation_id,
            .event_node_incarnation = trusted.event.node_incarnation,
            .stream_id = trusted.event.stream_id,
            .event_generation = trusted.event.event_generation,
            .event_owner_addr = @intCast(trusted.event.owner_addr),
            .slot_incarnation = identity.owner.slot_incarnation,
            .owner_node_incarnation = identity.owner.node_incarnation,
            .transport_incarnation = identity.owner.transport_incarnation,
            .host_id = identity.owner.host_id,
            .runtime_id = identity.owner.reservation.identity.runtime_id,
            .connection_generation = identity.owner.reservation.identity.connection_generation,
            .pid = identity.owner.reservation.identity.pid,
            .process_nonce = identity.owner.reservation.identity.process_nonce,
        } else null,
    };
}

pub fn generationEventTrustedView(
    identity: GenerationEventIdentity,
    owner_addr: usize,
) GenerationEventError!GenerationEventTrustedView {
    const evidence = try validatedGenerationEventEvidence(identity, owner_addr, null);
    return evidence.trusted_view;
}

pub fn generationEventPreparationProjection(
    identity: GenerationEventIdentity,
    correlation: EventCorrelation,
    owner_addr: usize,
) GenerationEventError!GenerationEventPreparationProjection {
    return (try validatedGenerationEventEvidence(identity, owner_addr, correlation)).preparation orelse
        return error.Corrupt;
}

/// Package verdict for a preparation allocator candidate. Private ClientSlot/ClientNode and
/// registered-operation addresses never escape this boundary.
pub fn generationEventPreparationCandidateAllowed(
    identity: GenerationEventIdentity,
    owner_addr: usize,
    start: usize,
    len: usize,
) GenerationEventError!bool {
    if (owner_addr == 0 or identity.receipt.owner_addr != owner_addr or start == 0 or len == 0)
        return false;
    _ = std.math.add(usize, start, len) catch return false;
    const admission = beginGenerationRequestOwner(identity.owner, false) catch |err| return switch (err) {
        error.Busy => error.Busy,
        else => error.InvalidOwner,
    };
    defer endRegisteredNodeOperation(admission.operation);
    const trusted = admission.operation.node.cleanup_registry.trustedEventPreparation(
        identity.owner.reservation.cleanup,
        identity.owner.reservation.identity,
        owner_addr,
    ) catch return error.Corrupt;
    if (!std.meta.eql(trusted.event, identity.receipt)) return error.Corrupt;
    const operation_entry = &registered_node_operations[admission.operation.registry_index];
    return !byteRangesOverlap(start, len, identity.owner.slot_addr, @sizeOf(ClientSlot)) and
        !byteRangesOverlap(start, len, @intFromPtr(admission.operation.node), @sizeOf(ClientNode)) and
        !byteRangesOverlap(start, len, @intFromPtr(operation_entry), @sizeOf(RegisteredNodeOperationEntry));
}

pub fn prepareGenerationEventRelease(
    request: GenerationEventReleaseRequest,
    correlation: EventCorrelation,
    projection: GenerationEventReleaseProjection,
    out: *PreparedGenerationEventRelease,
) GenerationEventError!GenerationEventReleasePrepared {
    if (request.bound_stream_id == 0 or request.event_owner_addr == 0 or
        projection.owner_addr != request.event_owner_addr or
        !out.pristineExact())
        return error.InvalidOwner;
    if (generation_event_release_callback_active_addr != 0) {
        const active_out: *PreparedGenerationEventRelease =
            @ptrFromInt(generation_event_release_callback_active_addr);
        const active = preparedEventRelease(active_out);
        if (active.self_addr == generation_event_release_callback_active_addr and
            active.lifecycle == .callback_active and
            active.request.event_owner_addr == request.event_owner_addr and
            active.request.bound_stream_id == request.bound_stream_id and
            std.meta.eql(active.request.owner, request.owner))
            return error.Terminal;
        return error.Busy;
    }
    // pending-settlement callback은 다른 continuation type이다. 그 주소를
    // `PreparedGenerationEventRelease`로 재해석하지 않으며, ordinary 동일 대상/형제 release는
    // callback이 반환할 때까지 registered operation을 Busy로만 관찰한다.
    if (pending_event_release_callback_binding.begun_addr != 0) return error.Busy;
    const admission = beginGenerationRequestOwner(request.owner, false) catch |err| return switch (err) {
        error.Busy => error.Busy,
        else => error.InvalidOwner,
    };
    var operation_live = true;
    defer if (operation_live) endRegisteredNodeOperation(admission.operation);
    const slot: *ClientSlot = @ptrFromInt(request.owner.slot_addr);
    switch (admission.operation.node.cleanup_registry.eventReleaseReadiness(
        request.owner.reservation.cleanup,
        request.owner.reservation.identity,
    ) catch return error.InvalidOwner) {
        .live => {},
        .busy => return error.Busy,
        .terminal => return error.Terminal,
    }
    var permit: ?StreamOperationPermit = slot.prepareStreamOperationPermit(
        .event,
        request.event_owner_addr,
        request.owner.transport_incarnation,
        request.owner.reservation.identity,
    ) catch |err| switch (err) {
        error.AdminBusy => return error.Busy,
        // Identity exhaustion is absorbing, but it must not strand an already-live event. The
        // registered-node operation above is sufficient to perform the same trusted no-free
        // recovery handoff used for corrupt public owner state.
        error.IdentityExhausted => null,
        error.InvalidStreamOperationPermit => return error.InvalidOwner,
    };
    defer if (permit) |live| slot.abortStreamOperationPermit(live) catch unreachable;

    const trusted = admission.operation.node.cleanup_registry.trustedEventCleanup(
        request.owner.reservation.cleanup,
        request.owner.reservation.identity,
        request.event_owner_addr,
    ) catch return error.InvalidOwner;
    if (trusted.state != .live) @panic("live event readiness drifted before trusted cleanup");
    const quarantine_reservation: GenerationEventQuarantine.Reservation = .{
        .slot_index = trusted.quarantine_slot_index,
        .reservation_generation = trusted.quarantine_reservation_generation,
        .node_incarnation = trusted.event.node_incarnation,
        .owner_addr = trusted.event.owner_addr,
    };
    const quarantine_identity: GenerationEventQuarantine.Identity = .{
        .node_incarnation = trusted.event.node_incarnation,
        .event_generation = trusted.event.event_generation,
        .owner_addr = trusted.event.owner_addr,
    };
    const quarantine = &(generation_event_quarantine_registry orelse return error.InvalidOwner);
    const thread_id: u64 = @intCast(std.Thread.getCurrentId());
    const mirror = quarantine.trustedMirror(
        currentPid(),
        thread_id,
        quarantine_reservation,
        quarantine_identity,
    ) catch @panic("canonical event quarantine mirror drifted");
    var corrupt = permit == null or !projection.valid or
        !std.meta.eql(trusted.event, projection.identity.receipt) or
        !std.meta.eql(projection.identity.owner, request.owner) or
        !eventCorrelationMatches(correlation, .{
            .identity = projection.identity,
            .ordering_class = trusted.ordering_class,
            .expected_major = mirror.expected_major,
            .metadata_support_raw = mirror.metadata_support_raw,
        }) or
        projection.self_addr != request.event_owner_addr or
        projection.lease_projection == null or
        projection.payload_addr != mirror.payload_addr or projection.payload_len != mirror.payload_len or
        projection.wire_major != mirror.wire_major or projection.admission_tag != mirror.admission_tag or
        projection.payload_len == 0;
    if (!corrupt) {
        const payload = @as([*]const u8, @ptrFromInt(mirror.payload_addr))[0..mirror.payload_len];
        const payload_digest = runtime_event_wire.payloadDigest(payload);
        corrupt = !std.mem.eql(u8, &payload_digest, &mirror.payload_digest);
    }
    const pin_projection = pinProjectionFromMirror(mirror);
    if (!corrupt)
        corrupt = !std.meta.eql(projection.lease_projection.?, pin_projection);
    const state = preparedEventRelease(out);
    state.* = .{
        .self_addr = @intFromPtr(out),
        .operation = admission.operation,
        .permit_state = if (permit != null) .consume_prepared else .identity_exhausted,
        .request = request,
        .trusted = trusted,
        .quarantine_reservation = quarantine_reservation,
        .quarantine_identity = quarantine_identity,
        .mirror = mirror,
        .lifecycle = .pristine,
    };
    @memset(out.storage[@sizeOf(PreparedEventReleaseInternal)..], 0);
    if (permit) |live| {
        slot.prepareStreamOperationPermitConsume(live, &state.permit_consume) catch
            @panic("preflighted event release permit consume drifted");
        permit = null;
    }
    if (corrupt) {
        _ = quarantine.beginTransfer(
            currentPid(),
            thread_id,
            quarantine_reservation,
            quarantine_identity,
        ) catch @panic("preflighted event quarantine transfer drifted");
        state.recovery_permit = admission.operation.node.cleanup_registry
            .terminalizeLiveEventForRecoveryNoFail(
            request.owner.reservation.cleanup,
            request.owner.reservation.identity,
            trusted.event,
            @intFromPtr(out),
            admission.operation.operation_id,
        );
        if (!std.meta.eql(state.recovery_permit.event, trusted.event) or
            state.recovery_permit.permit_generation != trusted.event.event_generation)
            @panic("generation event recovery permit drifted");
        state.disposition = .corrupt;
    } else {
        const lease: *lease_mod.ConnectionLease = @ptrFromInt(mirror.lease_addr);
        if (!lease_mod.prepareCanonicalPinRelease(
            lease,
            pin_projection,
            &admission.operation.node.pin_owner,
            &state.pin_release,
            currentPid(),
        )) @panic("validated event pin release preparation drifted");
        var pin_prepared = true;
        defer if (pin_prepared) lease_mod.abortPreparedPinReleaseUnchecked(
            &state.pin_release,
            &admission.operation.node.pin_owner,
            currentPid(),
        );
        _ = quarantine.beginRelease(
            currentPid(),
            thread_id,
            quarantine_reservation,
            quarantine_identity,
        ) catch @panic("preflighted event quarantine release drifted");
        state.continuation = admission.operation.node.cleanup_registry.beginEventReleaseNoFail(
            request.owner.reservation.cleanup,
            request.owner.reservation.identity,
            trusted.event,
            @intFromPtr(out),
            admission.operation.operation_id,
        );
        pin_prepared = false;
    }
    state.lifecycle = .prepared;
    operation_live = false;
    return if (corrupt)
        .corrupt
    else
        .{ .clean = .{ .owner_seal = projection.owner_seal } };
}

pub fn commitGenerationEventRelease(
    out: *PreparedGenerationEventRelease,
    payload_allocator: ?std.mem.Allocator,
    payload: ?[]u8,
) void {
    const state = preparedEventRelease(out);
    if (state.self_addr != @intFromPtr(out) or state.lifecycle != .prepared or
        anyGenerationEventReleaseCallbackActive() or
        (state.disposition == .clean and state.permit_state != .consume_prepared) or
        (state.permit_state == .identity_exhausted and state.disposition != .corrupt))
        @panic("generation event release continuation drifted");
    const quarantine = &(generation_event_quarantine_registry orelse
        @panic("generation event quarantine disappeared"));
    switch (state.disposition) {
        .clean => {
            state.operation.node.cleanup_registry.consumeEventReleaseContinuationNoFail(
                state.request.owner.reservation.cleanup,
                state.request.owner.reservation.identity,
                state.continuation,
            );
            const allocator = payload_allocator orelse
                @panic("generation event cleanup authority missing");
            const owned_payload = payload orelse
                @panic("generation event cleanup payload missing");
            if (@intFromPtr(owned_payload.ptr) != state.mirror.payload_addr or
                owned_payload.len != state.mirror.payload_len or
                @intFromPtr(allocator.vtable) != state.mirror.allocator_vtable)
                @panic("generation event cleanup authority drifted");
            state.lifecycle = .callback_active;
            generation_event_release_callback_active_addr = @intFromPtr(out);
            allocator.free(owned_payload);
            generation_event_release_callback_active_addr = 0;
            _ = quarantine.settleRelease(
                currentPid(),
                @intCast(std.Thread.getCurrentId()),
                state.quarantine_reservation,
                state.quarantine_identity,
            ) catch @panic("generation event quarantine release settlement drifted");
            state.operation.node.cleanup_registry.finishEventReleaseNoFail(
                state.request.owner.reservation.cleanup,
                state.request.owner.reservation.identity,
                state.continuation,
            );
        },
        .corrupt => {
            if (payload_allocator != null or payload != null)
                @panic("corrupt event release received cleanup authority");
            if (!std.meta.eql(state.recovery_permit.event, state.trusted.event) or
                state.recovery_permit.permit_generation != state.trusted.event.event_generation)
                @panic("generation event recovery permit replayed or drifted");
            state.operation.node.cleanup_registry.consumeEventPinRecoveryPermitNoFail(
                state.request.owner.reservation.cleanup,
                state.request.owner.reservation.identity,
                state.recovery_permit,
            );
            lease_mod.consumeCanonicalPinUnchecked(
                pinProjectionFromMirror(state.mirror),
                &state.operation.node.pin_owner,
                currentPid(),
            );
            quarantine.settleTransfer(
                currentPid(),
                @intCast(std.Thread.getCurrentId()),
                state.quarantine_reservation,
                state.quarantine_identity,
            ) catch @panic("generation event quarantine transfer settlement drifted");
            state.operation.node.client.poisonDuringClientSlotOperationNoFail(
                .local_invariant_violation,
            );
            state.recovery_permit = undefined;
        },
    }
    switch (state.permit_state) {
        .identity_exhausted => {},
        .consume_prepared => {
            const slot: *ClientSlot = @ptrFromInt(state.request.owner.slot_addr);
            if (!slot.consumeStreamOperationPermitUnchecked(&state.permit_consume))
                @panic("generation event release permit drifted");
        },
    }
    if (state.disposition == .clean)
        lease_mod.commitPreparedPinReleaseUnchecked(
            &state.pin_release,
            &state.operation.node.pin_owner,
            currentPid(),
        );
    endRegisteredNodeOperation(state.operation);
    state.lifecycle = if (state.disposition == .clean) .consumed else .terminal;
}

pub fn discardGenerationEventForTest(
    identity: GenerationEventIdentity,
    payload: []u8,
) GenerationEventError!void {
    if (!builtin.is_test) return error.InvalidOwner;
    try generationEventOwnerCurrent(identity, identity.receipt.owner_addr);
    const operation = beginRegisteredNodeOperation(.{
        .slot_addr = identity.owner.slot_addr,
        .slot_incarnation = identity.owner.slot_incarnation,
        .node = .{ .incarnation = identity.owner.node_incarnation },
    }) catch return error.InvalidOwner;
    defer endRegisteredNodeOperation(operation);
    const quarantine = &(generation_event_quarantine_registry orelse return error.InvalidOwner);
    const thread_id: u64 = @intCast(std.Thread.getCurrentId());
    const trusted = operation.node.cleanup_registry.trustedEventCleanup(
        identity.owner.reservation.cleanup,
        identity.owner.reservation.identity,
        identity.receipt.owner_addr,
    ) catch return error.Corrupt;
    const quarantine_reservation: GenerationEventQuarantine.Reservation = .{
        .slot_index = trusted.quarantine_slot_index,
        .reservation_generation = trusted.quarantine_reservation_generation,
        .node_incarnation = trusted.event.node_incarnation,
        .owner_addr = trusted.event.owner_addr,
    };
    const quarantine_identity: GenerationEventQuarantine.Identity = .{
        .node_incarnation = trusted.event.node_incarnation,
        .event_generation = trusted.event.event_generation,
        .owner_addr = trusted.event.owner_addr,
    };
    const mirror = quarantine.beginRelease(
        currentPid(),
        thread_id,
        quarantine_reservation,
        quarantine_identity,
    ) catch return error.Corrupt;
    const continuation = operation.node.cleanup_registry.beginEventReleaseNoFail(
        identity.owner.reservation.cleanup,
        identity.owner.reservation.identity,
        trusted.event,
        @intFromPtr(&identity),
        operation.operation_id,
    );
    operation.node.cleanup_registry.consumeEventReleaseContinuationNoFail(
        identity.owner.reservation.cleanup,
        identity.owner.reservation.identity,
        continuation,
    );
    operation.node.client.allocator.free(payload);
    _ = quarantine.settleRelease(
        currentPid(),
        thread_id,
        quarantine_reservation,
        quarantine_identity,
    ) catch @panic("test event quarantine settlement failed");
    operation.node.cleanup_registry.finishEventReleaseNoFail(
        identity.owner.reservation.cleanup,
        identity.owner.reservation.identity,
        continuation,
    );
    lease_mod.consumeCanonicalPinUnchecked(
        pinProjectionFromMirror(mirror),
        &operation.node.pin_owner,
        currentPid(),
    );
}

fn pinProjectionFromMirror(
    mirror: GenerationEventQuarantine.CleanupMirror,
) lease_mod.CanonicalPinProjection {
    return .{
        .pin_owner_addr = mirror.pin_owner_addr,
        .lease_addr = mirror.lease_addr,
        .slot_addr = mirror.slot_addr,
        .node_addr = mirror.node_addr,
        .slot_incarnation = mirror.slot_incarnation,
        .node_incarnation = mirror.node_incarnation,
        .host_id = mirror.host_id,
        .connection_generation = mirror.connection_generation,
        .stream_id = mirror.stream_id,
        .pid = currentPid(),
        .process_nonce = mirror.process_nonce,
    };
}

pub fn preflightGenerationTransportTerminalize(
    request: GenerationTransportOwnerQuery,
) error{ Busy, InvalidOwner }!void {
    const admission = beginGenerationRequestOwner(request, true) catch |err| return switch (err) {
        error.Busy => error.Busy,
        else => error.InvalidOwner,
    };
    defer endRegisteredNodeOperation(admission.operation);
    const readiness = admission.operation.node.cleanup_registry
        .transportTerminalizeReadiness(
        request.reservation.cleanup,
        admission.identity,
        admission.operation.node.pin_owner.active_cleanup == 1,
    ) catch return error.InvalidOwner;
    return switch (readiness) {
        .settled => {},
        .busy => error.Busy,
        .invalid => error.InvalidOwner,
    };
}

pub fn terminalizeGenerationTransportOwner(
    request: GenerationTransportOwnerQuery,
) error{ Busy, InvalidOwner }!void {
    const admission = beginGenerationRequestOwner(request, true) catch |err| return switch (err) {
        error.Busy => error.Busy,
        else => error.InvalidOwner,
    };
    defer endRegisteredNodeOperation(admission.operation);
    const readiness = admission.operation.node.cleanup_registry
        .transportTerminalizeReadiness(
        request.reservation.cleanup,
        admission.identity,
        admission.operation.node.pin_owner.active_cleanup == 1,
    ) catch return error.InvalidOwner;
    switch (readiness) {
        .settled => {},
        .busy => return error.Busy,
        .invalid => return error.InvalidOwner,
    }
    admission.owner.terminalize(request.transport_incarnation) catch
        return error.InvalidOwner;
}

/// Confirmed generation poison is admitted through the registered node owner, rather than a raw
/// Client receiver. Before admission every rejection is mutation-free. After admission, pending
/// outbound ownership is disposed under the Client-wide allocator callback latch and the blocking
/// descriptor is detached exactly once; therefore success proves that later generation I/O cannot
/// use this connection. A previously deferred blocking poison converges through the same suffix.
pub fn poisonGenerationConnection(
    request: GenerationTransportOwnerQuery,
    reason: client_poison.ConnectionReason,
) GenerationPoisonError!void {
    const admission = beginGenerationRequestOwner(request, false) catch |err| return switch (err) {
        error.Busy => error.Busy,
        else => error.InvalidOwner,
    };
    defer endRegisteredNodeOperation(admission.operation);
    const client = &admission.operation.node.client;
    if (client.ownership == .moved) return error.ConnectionClosed;
    if (client.io_mode != .blocking) return error.InvalidOwner;
    client.beginConfirmedGenerationPoisonExclusive() catch |err| return switch (err) {
        error.AdminBusy => error.Busy,
        else => error.ConnectionClosed,
    };
    defer client.endConfirmedGenerationPoisonExclusive();

    if (client.first_poison_reason == null) client.first_poison_reason = reason;
    if (client.pending_outbound) |pending| {
        const allocator = client.allocator;
        client.pending_outbound = null;
        if (!client.enterGenerationAllocatorCallback())
            @panic("confirmed generation poison callback latch admission drifted");
        defer client.leaveGenerationAllocatorCallbackUnchecked();
        allocator.free(pending.frame);
    }
    client.unusable = true;
    const fd = client.fd;
    client.fd = -1;
    if (fd >= 0) _ = c.close(fd);
    if (client.first_poison_reason == null or !client.unusable or client.fd != -1 or
        client.pending_outbound != null or client.io_mode != .blocking)
        @panic("confirmed generation poison postcondition drifted");
}

fn reasonProjection(reason: ?client_poison.ConnectionReason) settlement_contract.ReasonProjection {
    return if (reason) |value|
        .{ .present_raw = 1, .reason_raw = @intFromEnum(value) }
    else
        .{};
}

fn settlementDigest(comptime domain: []const u8, values: []const u64) settlement_contract.Digest {
    var hasher = std.crypto.hash.Blake3.init(.{});
    hasher.update(domain);
    for (values) |value| {
        var bytes: [8]u8 = undefined;
        std.mem.writeInt(u64, &bytes, value, .little);
        hasher.update(&bytes);
    }
    var digest: settlement_contract.Digest = undefined;
    hasher.final(&digest);
    return digest;
}

/// sealed request와 canonical PRE 상태에서 유일하게 허용되는 effect를 도출한다. commit은 이 값을
/// permit에 저장하고 POST를 대조하며, Client가 terminal이 된 뒤 두 번째 plan을 도출하지 않는다.
fn deriveCanonicalEffectPlan(
    client: *const client_mod.Client,
    request: settlement_contract.EffectRequestProjection,
    target_stream_id: u64,
) error{InvalidOwner}!settlement_contract.CanonicalEffectPlan {
    if (client.ownership == .moved or client.io_mode != .blocking or
        std.enums.fromInt(settlement_contract.EffectRequestTag, request.tag_raw) == null)
        return error.InvalidOwner;
    const request_tag: settlement_contract.EffectRequestTag = @enumFromInt(request.tag_raw);
    if ((request_tag == .none and (request.requested_reason.present_raw != 0 or request.revoke_fence != 0)) or
        (request_tag == .poison and (request.requested_reason.present_raw != 1 or request.revoke_fence != 0 or
            std.enums.fromInt(client_poison.ConnectionReason, request.requested_reason.reason_raw) == null)) or
        (request_tag == .revoke_fence and
            (request.requested_reason.present_raw != 0 or request.revoke_fence == 0)))
        return error.InvalidOwner;
    if (client.fd < -1 or (!client.unusable and client.fd < 0)) return error.InvalidOwner;

    var plan: settlement_contract.CanonicalEffectPlan = .{
        .effect_request = request,
        .first_reason_before = reasonProjection(client.first_poison_reason),
        .first_reason_after = reasonProjection(client.first_poison_reason),
        .unusable_before_raw = @intFromBool(client.unusable),
        .unusable_after_raw = @intFromBool(client.unusable),
        .fd_before = client.fd,
        .fd_after = client.fd,
    };
    if (client.pending_outbound) |pending| {
        if (pending.frame.len == 0 or pending.offset >= pending.frame.len) return error.InvalidOwner;
        plan.outbound_relation_raw = @intFromEnum(if (pending.stream_id == target_stream_id)
            settlement_contract.OutboundRelation.target
        else
            settlement_contract.OutboundRelation.sibling);
        plan.outbound_disposition_raw = @intFromEnum(settlement_contract.OutboundDisposition.preserved);
        plan.outbound_offset = pending.offset;
        plan.outbound_len = pending.frame.len;
        plan.outbound_descriptor_digest = settlementDigest("maru.effect-outbound-descriptor.v1", &.{
            @intFromPtr(pending.frame.ptr),    pending.frame.len,                    pending.offset, pending.stream_id,
            @intFromPtr(client.allocator.ptr), @intFromPtr(client.allocator.vtable),
        });
    }

    const relation: settlement_contract.OutboundRelation = @enumFromInt(plan.outbound_relation_raw);
    if (client.unusable) {
        if (client.first_poison_reason == null) return error.InvalidOwner;
        plan.action_raw = @intFromEnum(settlement_contract.EffectAction.terminal_cleanup);
        plan.fd_after = -1;
        if (client.fd < 0) {
            plan.fd_disposition_raw = @intFromEnum(settlement_contract.FdDisposition.already_detached);
        } else {
            plan.fd_disposition_raw = @intFromEnum(settlement_contract.FdDisposition.detached_close_attempted);
            plan.close_attempt_count = 1;
        }
        if (relation != .absent) setPlanAllocatorCleanup(client, &plan, .freed);
    } else switch (request_tag) {
        .none => plan.action_raw = @intFromEnum(settlement_contract.EffectAction.none),
        .poison => {
            plan.action_raw = @intFromEnum(settlement_contract.EffectAction.poison);
            if (plan.first_reason_before.present_raw == 0)
                plan.first_reason_after = request.requested_reason;
            setPlanTerminalFd(&plan);
            if (relation != .absent) setPlanAllocatorCleanup(client, &plan, .freed);
        },
        .revoke_fence => if (relation != .target) {
            plan.action_raw = @intFromEnum(settlement_contract.EffectAction.revoke_clean);
        } else if (plan.outbound_offset == 0) {
            plan.action_raw = @intFromEnum(settlement_contract.EffectAction.revoke_cancel);
            setPlanAllocatorCleanup(client, &plan, .cancelled);
        } else {
            plan.action_raw = @intFromEnum(settlement_contract.EffectAction.revoke_partial_poison);
            if (plan.first_reason_before.present_raw == 0)
                plan.first_reason_after = reasonProjection(.outbound_partial_write);
            setPlanTerminalFd(&plan);
            setPlanAllocatorCleanup(client, &plan, .partial_poisoned);
        },
    }
    if (!settlement_contract.validCanonicalEffectPlanShape(&plan)) return error.InvalidOwner;
    return plan;
}

fn setPlanTerminalFd(plan: *settlement_contract.CanonicalEffectPlan) void {
    plan.unusable_after_raw = 1;
    plan.fd_after = -1;
    plan.fd_disposition_raw = @intFromEnum(settlement_contract.FdDisposition.detached_close_attempted);
    plan.close_attempt_count = 1;
}

fn setPlanAllocatorCleanup(
    client: *const client_mod.Client,
    plan: *settlement_contract.CanonicalEffectPlan,
    disposition: settlement_contract.OutboundDisposition,
) void {
    plan.outbound_disposition_raw = @intFromEnum(disposition);
    plan.cleanup_mode_raw = @intFromEnum(settlement_contract.CleanupMode.allocator_free);
    plan.cleanup_count = 1;
    plan.cleanup_callback_provenance_digest = settlementDigest("maru.effect-cleanup-callback.v1", &.{
        @intFromPtr(client.allocator.ptr),             @intFromPtr(client.allocator.vtable),
        @as(u64, @intCast(@intFromEnum(disposition))),
    });
}

fn descriptorMatchesPlan(
    client: *const client_mod.Client,
    pending: anytype,
    plan: settlement_contract.CanonicalEffectPlan,
    target_stream_id: u64,
) bool {
    const relation: settlement_contract.OutboundRelation = @enumFromInt(plan.outbound_relation_raw);
    const expected_relation: settlement_contract.OutboundRelation = if (pending.stream_id == target_stream_id) .target else .sibling;
    if (relation != expected_relation or pending.frame.len != plan.outbound_len or pending.offset != plan.outbound_offset)
        return false;
    const digest = settlementDigest("maru.effect-outbound-descriptor.v1", &.{
        @intFromPtr(pending.frame.ptr),    pending.frame.len,                    pending.offset, pending.stream_id,
        @intFromPtr(client.allocator.ptr), @intFromPtr(client.allocator.vtable),
    });
    return std.crypto.timing_safe.eql(settlement_contract.Digest, digest, plan.outbound_descriptor_digest);
}

fn validateCanonicalEffectPrestate(
    plan: settlement_contract.CanonicalEffectPlan,
    client: *const client_mod.Client,
    target_stream_id: u64,
) bool {
    if (!settlement_contract.validCanonicalEffectPlanShape(&plan) or
        !std.meta.eql(reasonProjection(client.first_poison_reason), plan.first_reason_before) or
        @intFromBool(client.unusable) != plan.unusable_before_raw or client.fd != plan.fd_before)
        return false;
    const relation: settlement_contract.OutboundRelation = @enumFromInt(plan.outbound_relation_raw);
    if (client.pending_outbound) |pending|
        return relation != .absent and descriptorMatchesPlan(client, pending, plan, target_stream_id);
    return relation == .absent and std.mem.allEqual(u8, &plan.outbound_descriptor_digest, 0);
}

fn validateCanonicalEffectPoststate(
    plan: settlement_contract.CanonicalEffectPlan,
    client: *const client_mod.Client,
    target_stream_id: u64,
) bool {
    if (!std.meta.eql(reasonProjection(client.first_poison_reason), plan.first_reason_after) or
        @intFromBool(client.unusable) != plan.unusable_after_raw or client.fd != plan.fd_after)
        return false;
    const disposition: settlement_contract.OutboundDisposition = @enumFromInt(plan.outbound_disposition_raw);
    return switch (disposition) {
        .absent, .freed, .cancelled, .partial_poisoned => client.pending_outbound == null,
        .preserved => if (client.pending_outbound) |pending|
            descriptorMatchesPlan(client, pending, plan, target_stream_id)
        else
            false,
    };
}

fn executeCanonicalEffectPlanNoFail(
    client: *client_mod.Client,
    plan: settlement_contract.CanonicalEffectPlan,
    target_stream_id: u64,
) void {
    if (!validateCanonicalEffectPrestate(plan, client, target_stream_id))
        @panic("C3-3b3 effect PRE state drifted after admission");

    const disposition: settlement_contract.OutboundDisposition = @enumFromInt(plan.outbound_disposition_raw);
    const releases_outbound = switch (disposition) {
        .freed, .cancelled, .partial_poisoned => true,
        .absent, .preserved => false,
    };
    const moved_outbound = if (releases_outbound) client.pending_outbound else null;

    // 첫 external close/free 전에 모든 semantic/store-only publication을 끝낸다.
    if (plan.first_reason_after.present_raw == 1 and client.first_poison_reason == null)
        client.first_poison_reason = @enumFromInt(plan.first_reason_after.reason_raw);
    client.unusable = plan.unusable_after_raw == 1;
    if (releases_outbound) client.pending_outbound = null;
    const detached_fd = if (plan.fd_disposition_raw == @intFromEnum(settlement_contract.FdDisposition.detached_close_attempted))
        client.fd
    else
        -1;
    client.fd = plan.fd_after;

    // callback proof loss가 열린 descriptor를 고아로 남기지 않도록 close를 allocator callback보다 먼저 한다.
    if (detached_fd >= 0) _ = c.close(detached_fd);
    if (moved_outbound) |pending| {
        if (builtin.is_test and event_release_death_stage_raw == 3) {
            writeEventReleaseDeathMarker(0x44);
            writeEventReleaseDeathMarker(0x45);
        }
        if (!client.enterGenerationAllocatorCallback())
            @panic("C3-3b3 allocator callback latch admission drifted");
        client.allocator.free(pending.frame);
        client.leaveGenerationAllocatorCallbackUnchecked();
        if (builtin.is_test and event_release_death_stage_raw == 3) {
            writeEventReleaseDeathMarker(0x46);
            client.unusable = !client.unusable;
            writeEventReleaseDeathMarker(0x47);
        }
    }
    if (!validateCanonicalEffectPoststate(plan, client, target_stream_id))
        effectProofLoss();
}

fn effectProofLoss() noreturn {
    if (builtin.is_test) if (event_release_proof_loss_marker_fd) |fd| {
        const marker: [1]u8 = .{0x48};
        while (true) {
            const written = std.c.write(fd, &marker, marker.len);
            if (written == 1) break;
            if (written < 0 and std.posix.errno(written) == .INTR) continue;
            std.c._exit(126);
        }
        event_release_proof_loss_marker_fd = null;
    };
    process_seal_service.fatalIntegrity(.proof_loss);
}

pub fn preflightPendingEffect(
    request: GenerationTransportOwnerQuery,
    input: settlement_contract.EffectPreflightInput,
    effect_out: *settlement_contract.EffectCommitEvidence,
    out: *settlement_contract.PreparedEffectPermit,
) error{ Busy, InvalidOwner }!void {
    if (!std.meta.eql(out.*, settlement_contract.PreparedEffectPermit{}) or
        !std.meta.eql(effect_out.*, settlement_contract.EffectCommitEvidence{}) or
        input.pending_owner_addr == 0 or input.owner_incarnation == 0 or input.attempt == 0 or
        input.event_generation == 0 or input.target_stream_id == 0 or
        std.mem.allEqual(u8, &input.correlation_digest, 0) or
        std.mem.allEqual(u8, &input.prepared_effect_digest, 0) or
        input.effect_out_addr != @intFromPtr(effect_out) or
        input.effect_out_extent != @sizeOf(settlement_contract.EffectCommitEvidence) or
        input.effect_out_alignment != @alignOf(settlement_contract.EffectCommitEvidence) or
        std.mem.allEqual(u8, &input.effect_out_pristine_digest, 0) or
        !settlement_contract.validRuntimeSettlementBinding(input.lease))
        return error.InvalidOwner;
    const admission = beginGenerationRequestOwner(request, false) catch |err| return switch (err) {
        error.Busy => error.Busy,
        else => error.InvalidOwner,
    };
    var operation_live = true;
    defer if (operation_live) endRegisteredNodeOperation(admission.operation);
    const plan = deriveCanonicalEffectPlan(
        &admission.operation.node.client,
        input.effect_request,
        input.target_stream_id,
    ) catch return error.InvalidOwner;
    out.* = .{
        .self_addr = @intFromPtr(out),
        .pid = currentPid(),
        .process_nonce = input.lease.operation_identity.process_nonce,
        .thread_id = @intCast(std.Thread.getCurrentId()),
        .pending_owner_addr = input.pending_owner_addr,
        .owner_incarnation = input.owner_incarnation,
        .attempt = input.attempt,
        .event_generation = input.event_generation,
        .correlation_digest = input.correlation_digest,
        .prepared_effect_digest = input.prepared_effect_digest,
        .slot_incarnation = request.slot_incarnation,
        .node_incarnation = request.node_incarnation,
        .binding_incarnation = request.reservation.identity.binding_incarnation,
        .transport_incarnation = request.transport_incarnation,
        .operation_node_addr = @intFromPtr(admission.operation.node),
        .operation_id = admission.operation.operation_id,
        .operation_registry_index = admission.operation.registry_index,
        .target_stream_id = input.target_stream_id,
        .effect_out_addr = input.effect_out_addr,
        .effect_out_extent = input.effect_out_extent,
        .effect_out_alignment = input.effect_out_alignment,
        .effect_out_pristine_digest = input.effect_out_pristine_digest,
        .scratch_ranges_digest = input.lease.ranges_digest,
        .scratch_pristine_digest = input.lease.pristine_digest,
        .preflight_proof_seal_digest = input.lease.preflight_proof_seal_digest,
        .lease_seal_digest = input.lease.lease_seal_digest,
    };
    settlement_contract.applyEffectPlanToPermit(out, plan);
    out.preflight_authority_digest = settlement_contract.preflightEffectAuthorityDigest(
        plan,
        input.lease,
        input.effect_out_addr,
        input.effect_out_extent,
        input.effect_out_alignment,
        input.effect_out_pristine_digest,
    );
    out.seal = settlement_contract.sealPreparedEffectPermit(out.*) catch return error.InvalidOwner;
    out.lifecycle_raw = @intFromEnum(settlement_contract.AuthorityLifecycle.prepared);
    if (!settlement_contract.validPreparedEffectPermit(out)) return error.InvalidOwner;
    operation_live = false;
}

fn operationFromEffectPermit(permit: *const settlement_contract.PreparedEffectPermit) RegisteredNodeOperation {
    return .{
        .node = @ptrFromInt(permit.operation_node_addr),
        .registry_index = permit.operation_registry_index,
        .operation_id = permit.operation_id,
        .pid = permit.pid,
    };
}

pub fn abortPendingEffectPreAdmissionNoFail(permit: *settlement_contract.PreparedEffectPermit) void {
    if (!settlement_contract.validPreparedEffectPermit(permit)) effectProofLoss();
    const operation = operationFromEffectPermit(permit);
    if (resolveRegisteredNodeOperation(operation) != operation.node) effectProofLoss();
    endRegisteredNodeOperation(operation);
    permit.* = .{};
}

pub fn commitPendingEffectNoFail(
    permit: *settlement_contract.PreparedEffectPermit,
    binding: settlement_contract.RuntimeSettlementLeaseBinding,
    effect_out: *settlement_contract.EffectCommitEvidence,
) void {
    if (!settlement_contract.validPreparedEffectPermit(permit) or
        !settlement_contract.validRuntimeSettlementBinding(binding) or
        !std.crypto.timing_safe.eql(settlement_contract.Digest, permit.lease_seal_digest, binding.lease_seal_digest))
        effectProofLoss();
    const operation = operationFromEffectPermit(permit);
    const client = resolveRegisteredNodeOperation(operation) orelse effectProofLoss();
    if (client != operation.node or @intFromPtr(client) != permit.operation_node_addr) effectProofLoss();
    const plan = settlement_contract.effectPlanFromPermit(permit);
    if (!validateCanonicalEffectPrestate(plan, &client.client, permit.target_stream_id)) effectProofLoss();
    executeCanonicalEffectPlanNoFail(&client.client, plan, permit.target_stream_id);
    if (!validateCanonicalEffectPoststate(plan, &client.client, permit.target_stream_id)) effectProofLoss();
    settlement_contract.publishEffectCommitEvidenceNoFail(permit, binding, effect_out);
    if (!settlement_contract.validEffectCommitEvidenceFor(permit, binding, effect_out)) effectProofLoss();
}

pub fn preflightPendingEventReleaseUnderEffect(
    request: GenerationTransportOwnerQuery,
    effect_permit: *const settlement_contract.PreparedEffectPermit,
    pending: settlement_contract.PendingRegistryReleaseReceipt,
    event_projection: GenerationEventReleaseProjection,
    binding: settlement_contract.RuntimeSettlementLeaseBinding,
    completion_out: *settlement_contract.EventReleaseCompletion,
    permit_out: *settlement_contract.PreparedEventReleasePermit,
    begun: *PendingEventReleaseBegun,
) error{InvalidOwner}!void {
    if (!settlement_contract.validPreparedEffectPermit(effect_permit) or
        request.slot_incarnation != effect_permit.slot_incarnation or
        request.node_incarnation != effect_permit.node_incarnation or
        request.transport_incarnation != effect_permit.transport_incarnation or
        request.reservation.identity.binding_incarnation != effect_permit.binding_incarnation or
        !begun.pristineExact())
        return error.InvalidOwner;
    const operation = operationFromEffectPermit(effect_permit);
    const node = resolveRegisteredNodeOperation(operation) orelse return error.InvalidOwner;
    if (node != operation.node) return error.InvalidOwner;
    if (!event_projection.valid or event_projection.owner_addr != pending.event_identity.event_owner_addr or
        event_projection.self_addr != pending.event_identity.event_owner_addr or
        event_projection.payload_addr == 0 or event_projection.payload_len == 0)
        return error.InvalidOwner;
    const receipt: cleanup_registry_mod.EventGenerationReceipt = .{
        .registry_incarnation = pending.event_identity.registry_incarnation,
        .binding_reservation_id = pending.event_identity.binding_reservation_id,
        .node_incarnation = pending.event_identity.event_node_incarnation,
        .stream_id = pending.event_identity.stream_id,
        .event_generation = pending.event_identity.event_generation,
        .owner_addr = pending.event_identity.event_owner_addr,
    };
    var registry_permit: cleanup_registry_mod.PreparedRegistryEventRelease = .{};
    node.cleanup_registry.preflightPreparedEventRelease(
        request.reservation.cleanup,
        request.reservation.identity,
        receipt,
        pending,
        binding,
        &registry_permit,
    ) catch return error.InvalidOwner;
    permit_out.* = .{
        .self_addr = @intFromPtr(permit_out),
        .pid = effect_permit.pid,
        .process_nonce = effect_permit.process_nonce,
        .thread_id = effect_permit.thread_id,
        .registry_addr = registry_permit.registry_addr,
        .registry_incarnation = registry_permit.registry_incarnation,
        .binding_reservation_id = registry_permit.binding_reservation_id,
        .entry_index = registry_permit.entry_index,
        .event_node_incarnation = registry_permit.event_node_incarnation,
        .stream_id = registry_permit.stream_id,
        .event_generation = registry_permit.event_generation,
        .event_owner_addr = registry_permit.event_owner_addr,
        .pending_owner_addr = pending.pending_owner_addr,
        .pending_owner_incarnation = pending.pending_owner_incarnation,
        .source_lease_incarnation = pending.source_lease_incarnation,
        .attempt = pending.attempt,
        .ordering_class_raw = registry_permit.ordering_class_raw,
        .expected_blocker_count = registry_permit.expected_blocker_count,
        .completion_addr = @intFromPtr(completion_out),
        .completion_extent = @sizeOf(settlement_contract.EventReleaseCompletion),
        .completion_alignment = @alignOf(settlement_contract.EventReleaseCompletion),
        .completion_pristine_digest = settlement_contract.pristineEventReleaseCompletionDigest(),
        .begun_addr = @intFromPtr(begun),
        .begun_extent = @sizeOf(PendingEventReleaseBegun),
        .begun_alignment = @alignOf(PendingEventReleaseBegun),
        .begun_pristine_digest = pristinePendingEventReleaseBegunDigest(),
        .scratch_ranges_digest = binding.ranges_digest,
        .scratch_pristine_digest = binding.pristine_digest,
        .preflight_proof_seal_digest = binding.preflight_proof_seal_digest,
        .lease_seal_digest = binding.lease_seal_digest,
        .release_receipt_digest = pending.release_seal,
    };
    errdefer permit_out.* = .{};
    const trusted = node.cleanup_registry.trustedEventPreparation(
        request.reservation.cleanup,
        request.reservation.identity,
        pending.event_identity.event_owner_addr,
    ) catch return error.InvalidOwner;
    if (!std.meta.eql(trusted.event, receipt) or
        trusted.quarantine_reservation_generation == 0 or
        event_projection.payload_addr == 0 or event_projection.payload_len == 0 or
        event_projection.lease_projection == null)
        return error.InvalidOwner;
    const quarantine_reservation: GenerationEventQuarantine.Reservation = .{
        .slot_index = trusted.quarantine_slot_index,
        .reservation_generation = trusted.quarantine_reservation_generation,
        .node_incarnation = trusted.event.node_incarnation,
        .owner_addr = trusted.event.owner_addr,
    };
    const quarantine_identity: GenerationEventQuarantine.Identity = .{
        .node_incarnation = trusted.event.node_incarnation,
        .event_generation = trusted.event.event_generation,
        .owner_addr = trusted.event.owner_addr,
    };
    const quarantine = &(generation_event_quarantine_registry orelse return error.InvalidOwner);
    const mirror = quarantine.trustedMirror(
        currentPid(),
        @intCast(std.Thread.getCurrentId()),
        quarantine_reservation,
        quarantine_identity,
    ) catch return error.InvalidOwner;
    const pin_projection = pinProjectionFromMirror(mirror);
    if (!std.meta.eql(event_projection.lease_projection.?, pin_projection) or
        event_projection.payload_addr != mirror.payload_addr or
        event_projection.payload_len != mirror.payload_len or
        !std.crypto.timing_safe.eql(settlement_contract.Digest, pending.event_identity.payload_digest, mirror.payload_digest))
        return error.InvalidOwner;
    permit_out.event_owner_seal = event_projection.owner_seal;
    permit_out.payload_addr = mirror.payload_addr;
    permit_out.payload_len = mirror.payload_len;
    permit_out.payload_digest = mirror.payload_digest;
    permit_out.allocator_ptr = mirror.allocator_ptr;
    permit_out.allocator_vtable = mirror.allocator_vtable;
    permit_out.pin_owner_addr = pin_projection.pin_owner_addr;
    permit_out.lease_addr = pin_projection.lease_addr;
    permit_out.slot_addr = pin_projection.slot_addr;
    permit_out.node_addr = pin_projection.node_addr;
    permit_out.pin_slot_incarnation = pin_projection.slot_incarnation;
    permit_out.pin_node_incarnation = pin_projection.node_incarnation;
    permit_out.host_id = pin_projection.host_id;
    permit_out.connection_generation = pin_projection.connection_generation;
    permit_out.pin_process_nonce = pin_projection.process_nonce;
    permit_out.quarantine_slot_index = quarantine_reservation.slot_index;
    permit_out.quarantine_reservation_generation = quarantine_reservation.reservation_generation;
    permit_out.source_authority_digest = settlement_contract.eventReleaseSourceAuthorityDigest(permit_out.*);
    permit_out.seal = settlement_contract.sealPreparedEventReleasePermit(permit_out.*) catch return error.InvalidOwner;
    // seal은 lifecycle을 제외한다. registry/payload/pin/quarantine 필드가 모두 final address에
    // 고정된 뒤에만 완성된 composite를 게시한다.
    permit_out.lifecycle_raw = @intFromEnum(settlement_contract.AuthorityLifecycle.prepared);
    if (!settlement_contract.validPreparedEventReleasePermit(permit_out)) return error.InvalidOwner;
}

const PendingEventReleaseBegunLifecycle = enum(u8) {
    pristine,
    prepared,
    owner_tombstoned,
    resources_begun,
    correlation_tombstoned,
    mirror_tombstoned,
    callback_active,
    callback_returned,
    sources_settled,
    finished,
};

pub const PendingEventReleaseBegun = struct {
    self_addr: usize = 0,
    pid: u32 = 0,
    process_nonce: u64 = 0,
    thread_id: u64 = 0,
    effect_permit_addr: usize = 0,
    release_permit_addr: usize = 0,
    operation_id: u64 = 0,
    event_owner_addr: usize = 0,
    event_generation: u64 = 0,
    pin_count_before: u64 = 0,
    correlation_digest: settlement_contract.Digest = settlement_contract.zero_digest,
    effect_permit_seal: settlement_contract.Digest = settlement_contract.zero_digest,
    release_permit_seal: settlement_contract.Digest = settlement_contract.zero_digest,
    pin_receipt: settlement_contract.EventReleaseLeafReceipt = .{},
    owner_tombstone_receipt: settlement_contract.EventReleasePhaseReceipt = .{},
    correlation_tombstone_receipt: settlement_contract.EventReleasePhaseReceipt = .{},
    mirror_tombstone_receipt: settlement_contract.EventReleasePhaseReceipt = .{},
    callback_returned_receipt: settlement_contract.EventReleasePhaseReceipt = .{},
    lifecycle_raw: u8 = @intFromEnum(PendingEventReleaseBegunLifecycle.pristine),
    callback_active_raw: u8 = 0,
    seal: settlement_contract.Digest = settlement_contract.zero_digest,

    pub fn pristineExact(self: *const PendingEventReleaseBegun) bool {
        return std.meta.eql(self.*, PendingEventReleaseBegun{});
    }
};

pub fn pristinePendingEventReleaseBegunDigest() settlement_contract.Digest {
    var hasher = std.crypto.hash.Blake3.init(.{});
    hasher.update("maru.pending-event-release-begun.pristine.v1\x00");
    hashInt(&hasher, u64, @sizeOf(PendingEventReleaseBegun));
    hashInt(&hasher, u64, @alignOf(PendingEventReleaseBegun));
    hashInt(&hasher, u64, std.meta.fields(PendingEventReleaseBegun).len);
    var result: settlement_contract.Digest = undefined;
    hasher.final(&result);
    return result;
}

fn pendingEventReleaseBegunSeal(value: PendingEventReleaseBegun) settlement_contract.Digest {
    return process_seal_service.pendingEventReleaseBegunSeal(value.pid, value.process_nonce, .{
        .self_addr = value.self_addr,
        .thread_id = value.thread_id,
        .effect_permit_addr = value.effect_permit_addr,
        .release_permit_addr = value.release_permit_addr,
        .operation_id = value.operation_id,
        .event_owner_addr = value.event_owner_addr,
        .event_generation = value.event_generation,
        .pin_count_before = value.pin_count_before,
        .correlation_digest = value.correlation_digest,
        .effect_permit_seal = value.effect_permit_seal,
        .release_permit_seal = value.release_permit_seal,
        .pin_receipt_seal = value.pin_receipt.seal,
        .owner_tombstone_receipt = value.owner_tombstone_receipt.seal,
        .correlation_tombstone_receipt = value.correlation_tombstone_receipt.seal,
        .mirror_tombstone_receipt = value.mirror_tombstone_receipt.seal,
        .callback_returned_receipt = value.callback_returned_receipt.seal,
        .lifecycle_raw = value.lifecycle_raw,
        .callback_active_raw = value.callback_active_raw,
    }) catch effectProofLoss();
}

fn validPendingEventReleaseBegun(value: *const PendingEventReleaseBegun) bool {
    const lifecycle = std.enums.fromInt(PendingEventReleaseBegunLifecycle, value.lifecycle_raw) orelse return false;
    if (lifecycle == .pristine or value.self_addr != @intFromPtr(value) or value.pid != currentPid() or
        value.process_nonce == 0 or value.thread_id != @as(u64, @intCast(std.Thread.getCurrentId())) or
        value.effect_permit_addr == 0 or value.release_permit_addr == 0 or value.operation_id == 0 or
        value.event_owner_addr == 0 or value.event_generation == 0 or value.pin_count_before == 0 or
        std.mem.allEqual(u8, &value.correlation_digest, 0) or
        std.mem.allEqual(u8, &value.effect_permit_seal, 0) or
        std.mem.allEqual(u8, &value.release_permit_seal, 0) or
        value.callback_active_raw != @intFromBool(lifecycle == .callback_active)) return false;
    const expected = pendingEventReleaseBegunSeal(value.*);
    if (!std.crypto.timing_safe.eql(settlement_contract.Digest, expected, value.seal)) return false;
    const ordinal = @intFromEnum(lifecycle);
    if (ordinal >= @intFromEnum(PendingEventReleaseBegunLifecycle.owner_tombstoned) and
        !settlement_contract.validEventReleasePhaseReceipt(value.owner_tombstone_receipt, .owner)) return false;
    if (ordinal >= @intFromEnum(PendingEventReleaseBegunLifecycle.resources_begun)) {
        if (!settlement_contract.validEventReleaseLeafReceipt(value.pin_receipt, .pin)) return false;
    }
    if (ordinal >= @intFromEnum(PendingEventReleaseBegunLifecycle.correlation_tombstoned) and
        !settlement_contract.validEventReleasePhaseReceipt(value.correlation_tombstone_receipt, .correlation)) return false;
    if (ordinal >= @intFromEnum(PendingEventReleaseBegunLifecycle.mirror_tombstoned) and
        !settlement_contract.validEventReleasePhaseReceipt(value.mirror_tombstone_receipt, .mirror)) return false;
    if (ordinal >= @intFromEnum(PendingEventReleaseBegunLifecycle.callback_returned) and
        !settlement_contract.validEventReleasePhaseReceipt(value.callback_returned_receipt, .callback)) return false;
    return true;
}

fn advancePendingEventReleaseBegunNoFail(
    value: *PendingEventReleaseBegun,
    expected: PendingEventReleaseBegunLifecycle,
    next: PendingEventReleaseBegunLifecycle,
) void {
    if (!validPendingEventReleaseBegun(value) or value.lifecycle_raw != @intFromEnum(expected))
        effectProofLoss();
    value.lifecycle_raw = @intFromEnum(next);
    value.callback_active_raw = @intFromBool(next == .callback_active);
    value.seal = pendingEventReleaseBegunSeal(value.*);
}

/// effect callback 뒤 payload-source tombstone 전에 수행하는 마지막 fallible/read-only 검사다.
/// 여기서는 권위를 얻지 않으며, 이미 보유한 registered operation과 admitted runtime settlement
/// lease가 바로 이어지는 no-fail suffix를 직렬화한다.
pub fn validatePendingEventReleaseFinal(
    effect_permit: *const settlement_contract.PreparedEffectPermit,
    effect_out: *const settlement_contract.EffectCommitEvidence,
    release_permit: *const settlement_contract.PreparedEventReleasePermit,
    event_projection: GenerationEventReleaseProjection,
    binding: settlement_contract.RuntimeSettlementLeaseBinding,
    completion_out: *const settlement_contract.EventReleaseCompletion,
) bool {
    if (!settlement_contract.validPreparedEffectPermit(effect_permit) or
        !settlement_contract.validEffectCommitEvidenceFor(effect_permit, binding, effect_out) or
        !settlement_contract.validPreparedEventReleasePermit(release_permit) or
        release_permit.completion_addr != @intFromPtr(completion_out) or
        !std.meta.eql(completion_out.*, settlement_contract.EventReleaseCompletion{}) or
        !std.crypto.timing_safe.eql(
            settlement_contract.Digest,
            release_permit.completion_pristine_digest,
            settlement_contract.pristineEventReleaseCompletionDigest(),
        ) or
        !event_projection.valid or event_projection.self_addr != release_permit.event_owner_addr or
        event_projection.owner_addr != release_permit.event_owner_addr or
        event_projection.payload_addr != release_permit.payload_addr or
        event_projection.payload_len != release_permit.payload_len or
        !std.crypto.timing_safe.eql(settlement_contract.Digest, event_projection.owner_seal, release_permit.event_owner_seal))
        return false;
    const operation = operationFromEffectPermit(effect_permit);
    const node = resolveRegisteredNodeOperation(operation) orelse return false;
    if (node != operation.node or
        !validateCanonicalEffectPoststate(
            settlement_contract.effectPlanFromPermit(effect_permit),
            &node.client,
            effect_permit.target_stream_id,
        )) return false;
    const registry_permit = registryEventReleaseFromComposite(release_permit);
    if (!node.cleanup_registry.preparedEventReleaseCurrent(registry_permit)) return false;
    const quarantine = &(generation_event_quarantine_registry orelse return false);
    const reservation: GenerationEventQuarantine.Reservation = .{
        .slot_index = release_permit.quarantine_slot_index,
        .reservation_generation = release_permit.quarantine_reservation_generation,
        .node_incarnation = release_permit.event_node_incarnation,
        .owner_addr = release_permit.event_owner_addr,
    };
    const identity: GenerationEventQuarantine.Identity = .{
        .node_incarnation = release_permit.event_node_incarnation,
        .event_generation = release_permit.event_generation,
        .owner_addr = release_permit.event_owner_addr,
    };
    const mirror = quarantine.trustedMirror(
        currentPid(),
        @intCast(std.Thread.getCurrentId()),
        reservation,
        identity,
    ) catch return false;
    if (mirror.payload_addr != release_permit.payload_addr or mirror.payload_len != release_permit.payload_len or
        mirror.allocator_ptr != release_permit.allocator_ptr or mirror.allocator_vtable != release_permit.allocator_vtable or
        !std.crypto.timing_safe.eql(settlement_contract.Digest, mirror.payload_digest, release_permit.payload_digest))
        return false;
    const pin_projection = pinProjectionFromEventReleasePermit(release_permit);
    return event_projection.lease_projection != null and
        std.meta.eql(event_projection.lease_projection.?, pin_projection) and
        lease_mod.canonicalPinReleaseReady(pin_projection, &node.pin_owner, currentPid());
}

pub fn preparePendingEventReleaseBegunNoFail(
    effect_permit: *settlement_contract.PreparedEffectPermit,
    release_permit: *settlement_contract.PreparedEventReleasePermit,
    begun: *PendingEventReleaseBegun,
) void {
    if (!settlement_contract.validPreparedEffectPermit(effect_permit) or
        !settlement_contract.validPreparedEventReleasePermit(release_permit) or
        release_permit.begun_addr != @intFromPtr(begun) or
        release_permit.begun_extent != @sizeOf(PendingEventReleaseBegun) or
        release_permit.begun_alignment != @alignOf(PendingEventReleaseBegun) or
        !std.crypto.timing_safe.eql(
            settlement_contract.Digest,
            release_permit.begun_pristine_digest,
            pristinePendingEventReleaseBegunDigest(),
        ) or !begun.pristineExact()) effectProofLoss();
    const operation = operationFromEffectPermit(effect_permit);
    const node = resolveRegisteredNodeOperation(operation) orelse effectProofLoss();
    if (node != operation.node) effectProofLoss();
    begun.* = .{
        .self_addr = @intFromPtr(begun),
        .pid = effect_permit.pid,
        .process_nonce = effect_permit.process_nonce,
        .thread_id = effect_permit.thread_id,
        .effect_permit_addr = @intFromPtr(effect_permit),
        .release_permit_addr = @intFromPtr(release_permit),
        .operation_id = operation.operation_id,
        .event_owner_addr = release_permit.event_owner_addr,
        .event_generation = release_permit.event_generation,
        .pin_count_before = node.pin_owner.cleanup_pin_count,
        .correlation_digest = effect_permit.correlation_digest,
        .effect_permit_seal = effect_permit.seal,
        .release_permit_seal = release_permit.seal,
        .lifecycle_raw = @intFromEnum(PendingEventReleaseBegunLifecycle.prepared),
    };
    begun.seal = pendingEventReleaseBegunSeal(begun.*);
    if (!validPendingEventReleaseBegun(begun)) effectProofLoss();
}

pub fn markPendingEventOwnerTombstonedNoFail(begun: *PendingEventReleaseBegun, receipt: settlement_contract.EventReleasePhaseReceipt) void {
    if (!settlement_contract.validEventReleasePhaseReceipt(receipt, .owner)) effectProofLoss();
    begun.owner_tombstone_receipt = receipt;
    begun.seal = pendingEventReleaseBegunSeal(begun.*);
    advancePendingEventReleaseBegunNoFail(begun, .prepared, .owner_tombstoned);
}

pub fn beginPendingEventReleaseResourcesNoFail(
    effect_permit: *settlement_contract.PreparedEffectPermit,
    release_permit: *settlement_contract.PreparedEventReleasePermit,
    begun: *PendingEventReleaseBegun,
) void {
    if (!validPendingEventReleaseBegun(begun) or
        begun.lifecycle_raw != @intFromEnum(PendingEventReleaseBegunLifecycle.owner_tombstoned) or
        begun.effect_permit_addr != @intFromPtr(effect_permit) or
        begun.release_permit_addr != @intFromPtr(release_permit) or
        !std.crypto.timing_safe.eql(settlement_contract.Digest, begun.effect_permit_seal, effect_permit.seal) or
        !std.crypto.timing_safe.eql(settlement_contract.Digest, begun.release_permit_seal, release_permit.seal))
        effectProofLoss();
    const operation = operationFromEffectPermit(effect_permit);
    const node = resolveRegisteredNodeOperation(operation) orelse effectProofLoss();
    if (node != operation.node or operation.operation_id != begun.operation_id) effectProofLoss();
    const quarantine = &(generation_event_quarantine_registry orelse effectProofLoss());
    const reservation: GenerationEventQuarantine.Reservation = .{
        .slot_index = release_permit.quarantine_slot_index,
        .reservation_generation = release_permit.quarantine_reservation_generation,
        .node_incarnation = release_permit.event_node_incarnation,
        .owner_addr = release_permit.event_owner_addr,
    };
    const identity: GenerationEventQuarantine.Identity = .{
        .node_incarnation = release_permit.event_node_incarnation,
        .event_generation = release_permit.event_generation,
        .owner_addr = release_permit.event_owner_addr,
    };
    node.cleanup_registry.beginPreparedEventReleaseNoFail(registryEventReleaseFromComposite(release_permit));
    const mirror = quarantine.beginRelease(
        currentPid(),
        @intCast(std.Thread.getCurrentId()),
        reservation,
        identity,
    ) catch effectProofLoss();
    if (mirror.payload_addr != release_permit.payload_addr or mirror.payload_len != release_permit.payload_len or
        mirror.allocator_ptr != release_permit.allocator_ptr or mirror.allocator_vtable != release_permit.allocator_vtable or
        !std.crypto.timing_safe.eql(settlement_contract.Digest, mirror.payload_digest, release_permit.payload_digest))
        effectProofLoss();
    begun.pin_receipt = lease_mod.consumeCanonicalPinWithReceiptUnchecked(
        pinProjectionFromEventReleasePermit(release_permit),
        &node.pin_owner,
        currentPid(),
    );
    if (!settlement_contract.validEventReleaseLeafReceipt(begun.pin_receipt, .pin)) effectProofLoss();
    begun.seal = pendingEventReleaseBegunSeal(begun.*);
    advancePendingEventReleaseBegunNoFail(begun, .owner_tombstoned, .resources_begun);
}

pub fn markPendingEventCorrelationTombstonedNoFail(begun: *PendingEventReleaseBegun, receipt: settlement_contract.EventReleasePhaseReceipt) void {
    if (!settlement_contract.validEventReleasePhaseReceipt(receipt, .correlation)) effectProofLoss();
    begun.correlation_tombstone_receipt = receipt;
    begun.seal = pendingEventReleaseBegunSeal(begun.*);
    advancePendingEventReleaseBegunNoFail(begun, .resources_begun, .correlation_tombstoned);
}

pub fn markPendingEventMirrorTombstonedNoFail(begun: *PendingEventReleaseBegun, receipt: settlement_contract.EventReleasePhaseReceipt) void {
    if (!settlement_contract.validEventReleasePhaseReceipt(receipt, .mirror)) effectProofLoss();
    begun.mirror_tombstone_receipt = receipt;
    begun.seal = pendingEventReleaseBegunSeal(begun.*);
    advancePendingEventReleaseBegunNoFail(begun, .correlation_tombstoned, .mirror_tombstoned);
}

pub fn finishPendingEventReleaseNoFail(
    effect_permit: *settlement_contract.PreparedEffectPermit,
    release_permit: *settlement_contract.PreparedEventReleasePermit,
    begun: *PendingEventReleaseBegun,
    completion_out: *settlement_contract.EventReleaseCompletion,
    payload_allocator: std.mem.Allocator,
    payload: []u8,
) void {
    if (!settlement_contract.validPreparedEffectPermit(effect_permit) or
        !settlement_contract.validPreparedEventReleasePermit(release_permit) or
        release_permit.completion_addr != @intFromPtr(completion_out) or
        begun.self_addr != @intFromPtr(begun) or begun.effect_permit_addr != @intFromPtr(effect_permit) or
        begun.release_permit_addr != @intFromPtr(release_permit) or
        begun.operation_id != effect_permit.operation_id or
        !validPendingEventReleaseBegun(begun) or
        begun.lifecycle_raw != @intFromEnum(PendingEventReleaseBegunLifecycle.mirror_tombstoned) or
        !std.crypto.timing_safe.eql(settlement_contract.Digest, begun.effect_permit_seal, effect_permit.seal) or
        !std.crypto.timing_safe.eql(settlement_contract.Digest, begun.release_permit_seal, release_permit.seal) or
        !std.meta.eql(completion_out.*, settlement_contract.EventReleaseCompletion{})) effectProofLoss();
    const operation = operationFromEffectPermit(effect_permit);
    const node = resolveRegisteredNodeOperation(operation) orelse effectProofLoss();
    if (@intFromPtr(payload.ptr) != release_permit.payload_addr or
        payload.len != release_permit.payload_len or
        @intFromPtr(payload_allocator.vtable) != release_permit.allocator_vtable)
        effectProofLoss();
    if (!std.meta.eql(pending_event_release_callback_binding, PendingEventReleaseCallbackBinding{}))
        effectProofLoss();
    advancePendingEventReleaseBegunNoFail(begun, .mirror_tombstoned, .callback_active);
    if (builtin.is_test and event_release_death_stage_raw == 2) writeEventReleaseDeathMarker(0x43);
    pending_event_release_callback_binding = .{
        .begun_addr = @intFromPtr(begun),
        .begun_seal = begun.seal,
    };
    if (builtin.is_test) {
        pending_event_payload_callback_count += 1;
        if (event_release_death_stage_raw == 1 or
            (event_release_death_stage_raw == 2 and pending_event_payload_callback_count > 1))
            writeEventReleaseDeathMarker(0x49);
    }
    payload_allocator.free(payload);
    if (builtin.is_test and event_release_death_stage_raw == 2) {
        writeEventReleaseDeathMarker(0x47);
        begun.seal[0] ^= 1;
    }
    if (!validPendingEventReleaseBegun(begun) or
        pending_event_release_callback_binding.begun_addr != @intFromPtr(begun) or
        !std.crypto.timing_safe.eql(
            settlement_contract.Digest,
            pending_event_release_callback_binding.begun_seal,
            begun.seal,
        )) effectProofLoss();
    const returned_binding = pending_event_release_callback_binding;
    pending_event_release_callback_binding = .{};
    begun.callback_returned_receipt = settlement_contract.makeEventReleasePhaseReceipt(
        .callback,
        @intFromEnum(PendingEventReleaseBegunLifecycle.callback_active),
        @intFromEnum(PendingEventReleaseBegunLifecycle.callback_returned),
        begun.event_owner_addr,
        begun.event_generation,
        @intFromPtr(begun),
        returned_binding.begun_seal,
        settlement_contract.canonicalEventReleasePhaseAfterDigest(.callback, @intFromPtr(begun), begun.event_owner_addr, begun.event_generation, @intFromEnum(PendingEventReleaseBegunLifecycle.callback_returned)),
        begun.release_permit_seal,
        returned_binding.begun_seal,
    ) catch effectProofLoss();
    begun.seal = pendingEventReleaseBegunSeal(begun.*);
    advancePendingEventReleaseBegunNoFail(begun, .callback_active, .callback_returned);
    if (resolveRegisteredNodeOperation(operation) != node or
        !settlement_contract.validPreparedEventReleasePermit(release_permit)) effectProofLoss();
    const quarantine = &(generation_event_quarantine_registry orelse effectProofLoss());
    const quarantine_receipt = quarantine.settleRelease(
        currentPid(),
        @intCast(std.Thread.getCurrentId()),
        .{
            .slot_index = release_permit.quarantine_slot_index,
            .reservation_generation = release_permit.quarantine_reservation_generation,
            .node_incarnation = release_permit.event_node_incarnation,
            .owner_addr = release_permit.event_owner_addr,
        },
        .{
            .node_incarnation = release_permit.event_node_incarnation,
            .event_generation = release_permit.event_generation,
            .owner_addr = release_permit.event_owner_addr,
        },
    ) catch effectProofLoss();
    const permit_seal = release_permit.seal;
    const registry_receipt = node.cleanup_registry.finishPreparedEventReleaseNoFail(registryEventReleaseFromComposite(release_permit));
    advancePendingEventReleaseBegunNoFail(begun, .callback_returned, .sources_settled);
    if (!node.cleanup_registry.preparedEventReleaseSettled(registryEventReleaseFromComposite(release_permit)) or
        !lease_mod.canonicalPinConsumed(
            pinProjectionFromEventReleasePermit(release_permit),
            &node.pin_owner,
            begun.pin_count_before,
            currentPid(),
        )) effectProofLoss();
    if (!settlement_contract.validEventReleaseLeafReceipt(registry_receipt, .registry) or
        !settlement_contract.validEventReleaseLeafReceipt(quarantine_receipt, .quarantine) or
        !settlement_contract.validEventReleaseLeafReceipt(begun.pin_receipt, .pin)) effectProofLoss();
    const callback_count: u8 = begun.callback_returned_receipt.invocation_count;
    const source_count: u8 = @intFromBool(
        settlement_contract.validEventReleasePhaseReceipt(begun.owner_tombstone_receipt, .owner) and
            settlement_contract.validEventReleasePhaseReceipt(begun.correlation_tombstone_receipt, .correlation) and
            settlement_contract.validEventReleasePhaseReceipt(begun.mirror_tombstone_receipt, .mirror),
    );
    const post: settlement_contract.EventReleasePostProjection = .{
        .registry_closed_digest = registry_receipt.seal,
        .quarantine_closed_digest = quarantine_receipt.seal,
        .pin_consumed_digest = begun.pin_receipt.seal,
        .callback_invoked_digest = begun.callback_returned_receipt.seal,
        .owner_tombstoned_digest = begun.owner_tombstone_receipt.seal,
        .correlation_tombstoned_digest = begun.correlation_tombstone_receipt.seal,
        .mirror_tombstoned_digest = begun.mirror_tombstone_receipt.seal,
        .callback_invocation_count = callback_count,
        .source_tombstone_count = source_count,
    };
    const post_transcript_digest = settlement_contract.eventReleasePostTranscriptDigest(permit_seal, post) orelse
        effectProofLoss();
    release_permit.consumed_raw = 1;
    release_permit.lifecycle_raw = @intFromEnum(settlement_contract.AuthorityLifecycle.consumed);
    var completion: settlement_contract.EventReleaseCompletion = .{
        .self_addr = @intFromPtr(completion_out),
        .pid = release_permit.pid,
        .process_nonce = release_permit.process_nonce,
        .thread_id = release_permit.thread_id,
        .pending_owner_addr = release_permit.pending_owner_addr,
        .owner_incarnation = release_permit.pending_owner_incarnation,
        .attempt = release_permit.attempt,
        .event_generation = release_permit.event_generation,
        .registry_incarnation = release_permit.registry_incarnation,
        .binding_reservation_id = release_permit.binding_reservation_id,
        .event_node_incarnation = release_permit.event_node_incarnation,
        .stream_id = release_permit.stream_id,
        .event_owner_addr = release_permit.event_owner_addr,
        .source_lease_incarnation = release_permit.source_lease_incarnation,
        .ordering_class_raw = release_permit.ordering_class_raw,
        .release_receipt_digest = release_permit.release_receipt_digest,
        .permit_digest = permit_seal,
        .consumed_blocker_count = 1,
        .freed_payload_count = 1,
        .consumed_pin_count = 1,
        .settled_quarantine_count = 1,
        .post_transcript_digest = post_transcript_digest,
    };
    completion.authority_digest = settlement_contract.eventReleaseCompletionAuthorityDigest(completion);
    completion.seal = settlement_contract.sealEventReleaseCompletion(completion) catch effectProofLoss();
    const post_context: settlement_contract.EventReleasePostContext = .{
        .registry_incarnation = release_permit.registry_incarnation,
        .binding_reservation_id = release_permit.binding_reservation_id,
        .event_node_incarnation = release_permit.event_node_incarnation,
        .event_generation = release_permit.event_generation,
        .event_owner_addr = release_permit.event_owner_addr,
        .payload_len = release_permit.payload_len,
        .permit_seal = permit_seal,
        .begun_addr = @intFromPtr(begun),
        .quarantine_slot_index = release_permit.quarantine_slot_index,
        .quarantine_reservation_generation = release_permit.quarantine_reservation_generation,
        .pin_owner_addr = release_permit.pin_owner_addr,
        .lease_addr = release_permit.lease_addr,
        .pin_node_incarnation = release_permit.pin_node_incarnation,
        .pin_stream_id = release_permit.stream_id,
        .pin_slot_addr = release_permit.slot_addr,
        .pin_connection_generation = release_permit.connection_generation,
        .owner_pre_seal = release_permit.event_owner_seal,
        .correlation_pre_digest = begun.correlation_digest,
        .mirror_pre_digest = settlement_contract.canonicalEventReleaseMirrorBeforeDigest(begun.event_generation),
        .registry = registry_receipt,
        .quarantine = quarantine_receipt,
        .pin = begun.pin_receipt,
        .owner = begun.owner_tombstone_receipt,
        .correlation = begun.correlation_tombstone_receipt,
        .mirror = begun.mirror_tombstone_receipt,
        .callback = begun.callback_returned_receipt,
    };
    if (!settlement_contract.validEventReleasePostContext(post_context, post, completion)) effectProofLoss();
    if (builtin.is_test) event_release_post_snapshot = .{
        .permit_seal = permit_seal,
        .post = post,
        .transcript_digest = post_transcript_digest,
        .completion = completion,
        .context = post_context,
    };
    if (builtin.is_test and event_release_death_stage_raw != 0) writeEventReleaseDeathMarker(0x4A);
    completion_out.* = completion;
    completion_out.lifecycle_raw = @intFromEnum(settlement_contract.AuthorityLifecycle.prepared);
    advancePendingEventReleaseBegunNoFail(begun, .sources_settled, .finished);
    endRegisteredNodeOperation(operation);
}

