            .placeholder_generation = cleanup.placeholder_generation,
            .allocator_ptr = @intCast(cleanup.allocator_ptr),
            .allocator_vtable = @intCast(cleanup.allocator_vtable),
            .fd = cleanup.fd,
            .pending_frame_addr = @intCast(cleanup.pending_frame_addr),
