    pub fn prepareAdmissionClose(
        self: *ClientSlot,
        expected_generation: u64,
        out: *PreparedAdmissionClose,
    ) AdmissionCloseError!void {
        if (!self.valid() or !operationThreadMatches(self.operation_owner_thread_incarnation) or
            rangesOverlapTyped(out, self) or rangesOverlapTyped(out, self.current) or
            !std.meta.eql(out.*, PreparedAdmissionClose{}))
            return error.InvalidOwner;
        const operation = self.beginRegisteredClientOperation() catch |err| return switch (err) {
            error.MovedOrCopied => error.InvalidOwner,
            error.AdminBusy => error.Busy,
        };
        defer self.endRegisteredClientOperation(operation);
        if (operation.node != self.current) return error.InvalidOwner;
        if (expected_generation == 0 or expected_generation != operation.node.connection_generation)
            return error.GenerationMismatch;
        if (!admissionLifecycleRawValid(&operation.node.admission_lifecycle)) return error.InvalidOwner;
        if (operation.node.admission_lifecycle != .open or operation.node.stack_borrows != 0 or
            operation.node.active_operation_generation != 0 or operation.node.pin_owner.active_cleanup != 0)
            return error.Busy;
        const request_generation = operation.node.next_admission_close_request_generation;
        if (request_generation == 0 or request_generation == std.math.maxInt(u64))
            return error.RequestExhausted;
        operation.node.next_admission_close_request_generation = request_generation + 1;
        out.* = .{
            .self_addr = @intFromPtr(out),
            .pid = self.pid,
            .process_nonce = self.process_nonce,
            .owner_thread_incarnation = self.operation_owner_thread_incarnation,
            .slot_addr = @intFromPtr(self),
            .slot_incarnation = self.incarnation.tagged,
            .current_node_addr = @intFromPtr(operation.node),
            .current_node_incarnation = operation.node.incarnation.tagged,
            .expected_connection_generation = expected_generation,
            .request_generation = request_generation,
            .lifecycle = .prepared,
        };
        out.seal = self.admissionCloseSeal(out);
    }

    pub fn commitAdmissionClose(
        self: *ClientSlot,
        permit: *PreparedAdmissionClose,
    ) AdmissionCloseError!void {
        if (!self.admissionClosePermitValid(permit, .prepared)) return error.InvalidOwner;
        const operation = self.beginRegisteredClientOperation() catch |err| return switch (err) {
            error.MovedOrCopied => error.InvalidOwner,
            error.AdminBusy => error.Busy,
        };
        defer self.endRegisteredClientOperation(operation);
        if (!self.admissionClosePermitValid(permit, .prepared) or operation.node != self.current)
            return error.InvalidOwner;
        if (operation.node.stack_borrows != 0 or
            operation.node.admission_lifecycle != .open or operation.node.active_operation_generation != 0 or
            operation.node.pin_owner.active_cleanup != 0)
            return error.Busy;
        operation.node.admission_lifecycle = .closed;
        permit.lifecycle = .committed;
        permit.seal = self.admissionCloseSeal(permit);
    }

    pub fn cancelAdmissionClose(
        self: *ClientSlot,
        permit: *PreparedAdmissionClose,
    ) AdmissionCloseError!void {
        if (self.admissionClosePermitValid(permit, .prepared)) {
            permit.lifecycle = .consumed;
            permit.seal = self.admissionCloseSeal(permit);
            return;
        }
        if (!self.admissionClosePermitValid(permit, .committed)) return error.InvalidOwner;
        const operation = self.beginRegisteredClientOperation() catch |err| return switch (err) {
            error.MovedOrCopied => error.InvalidOwner,
            error.AdminBusy => error.Busy,
        };
        defer self.endRegisteredClientOperation(operation);
        if (!self.admissionClosePermitValid(permit, .committed) or operation.node != self.current)
            return error.InvalidOwner;
        if (!admissionLifecycleRawValid(&operation.node.admission_lifecycle)) return error.InvalidOwner;
        if (operation.node.admission_lifecycle != .closed or operation.node.stack_borrows != 0 or
            operation.node.active_operation_generation != 0 or operation.node.pin_owner.active_cleanup != 0)
            return error.Busy;
        operation.node.admission_lifecycle = .open;
        permit.lifecycle = .cancelled;
        permit.seal = self.admissionCloseSeal(permit);
        permit.lifecycle = .consumed;
        permit.seal = self.admissionCloseSeal(permit);
    }

    pub const RetirementCleanupError = error{ InvalidOwner, Busy, GenerationMismatch, OutOfMemory };

    pub fn prepareRetirementCleanup(
        self: *ClientSlot,
        permit: *PreparedAdmissionClose,
        placeholder_generation: u64,
        out: *PreparedRetirementCleanup,
    ) RetirementCleanupError!void {
        const admission_prepared = self.admissionClosePermitValid(permit, .prepared);
        const expected_admission_lifecycle: AdmissionLifecycle = if (admission_prepared) .open else .closed;
        if ((!admission_prepared and !self.admissionClosePermitValid(permit, .committed)) or
            placeholder_generation == 0 or
            rangesOverlapTyped(out, self) or rangesOverlapTyped(out, self.current) or
            rangesOverlapTyped(out, permit) or !std.meta.eql(out.*, PreparedRetirementCleanup{}))
            return error.InvalidOwner;
        {
            const operation = self.beginRegisteredClientOperation() catch |err| return switch (err) {
                error.MovedOrCopied => error.InvalidOwner,
                error.AdminBusy => error.Busy,
            };
            defer self.endRegisteredClientOperation(operation);
            if (!(if (admission_prepared)
                self.admissionClosePermitValid(permit, .prepared)
            else
                self.admissionClosePermitValid(permit, .committed)) or operation.node != self.current)
                return error.InvalidOwner;
            if (operation.node.connection_generation != permit.expected_connection_generation)
                return error.GenerationMismatch;
            if (operation.node.admission_lifecycle != expected_admission_lifecycle or
                operation.node.retirement_lifecycle != .live or
                operation.node.placeholder_generation != 0 or operation.node.stack_borrows != 0 or
                operation.node.active_operation_generation != 0 or
                operation.node.pin_owner.active_cleanup != 0)
                return error.Busy;
            operation.node.client.preflightExternalAdoptionDestination(
                out,
                @sizeOf(PreparedRetirementCleanup),
            ) catch |err| return switch (err) {
                error.OutOfMemory => error.OutOfMemory,
                else => error.InvalidOwner,
            };
            operation.node.client.preflightExternalAdoptionDestination(
                permit,
                @sizeOf(PreparedAdmissionClose),
            ) catch |err| return switch (err) {
                error.OutOfMemory => error.OutOfMemory,
                else => error.InvalidOwner,
            };
        }
        const external = self.current.client.reserveExternalModeDeinit();
        if (external == .busy) return error.Busy;
        var reservation_owned = external == .reserved;
        errdefer if (reservation_owned and !self.current.client.cancelReservedExternalModeDeinit())
            @panic("CR3b R2b external cleanup reservation rollback failed");
        const operation = self.beginRegisteredClientOperation() catch |err| return switch (err) {
            error.MovedOrCopied => error.InvalidOwner,
            error.AdminBusy => error.Busy,
        };
        defer self.endRegisteredClientOperation(operation);
        if (!(if (admission_prepared)
            self.admissionClosePermitValid(permit, .prepared)
        else
            self.admissionClosePermitValid(permit, .committed)) or operation.node != self.current)
            return error.InvalidOwner;
        if (operation.node.connection_generation != permit.expected_connection_generation)
            return error.GenerationMismatch;
        if (operation.node.admission_lifecycle != expected_admission_lifecycle or
            operation.node.retirement_lifecycle != .live or
            operation.node.placeholder_generation != 0 or operation.node.stack_borrows != 0 or
            operation.node.active_operation_generation != 0 or
            operation.node.pin_owner.active_cleanup != 0)
            return error.Busy;
        operation.node.client.preflightExternalAdoptionDestination(
            out,
            @sizeOf(PreparedRetirementCleanup),
        ) catch |err| return switch (err) {
            error.OutOfMemory => error.OutOfMemory,
            else => error.InvalidOwner,
        };
        operation.node.client.preflightExternalAdoptionDestination(
            permit,
            @sizeOf(PreparedAdmissionClose),
        ) catch |err| return switch (err) {
            error.OutOfMemory => error.OutOfMemory,
            else => error.InvalidOwner,
        };
        const pending = operation.node.client.pending_outbound;
        if (pending) |value| {
            if (value.frame.len == 0 or value.stream_id == 0 or value.offset > value.frame.len)
                return error.InvalidOwner;
        }
        out.* = .{
            .self_addr = @intFromPtr(out),
            .pid = self.pid,
            .process_nonce = self.process_nonce,
            .owner_thread_incarnation = self.operation_owner_thread_incarnation,
            .slot_addr = @intFromPtr(self),
            .slot_incarnation = self.incarnation.tagged,
            .current_node_addr = @intFromPtr(operation.node),
            .current_node_incarnation = operation.node.incarnation.tagged,
            .expected_connection_generation = operation.node.connection_generation,
            .admission_request_generation = permit.request_generation,
            .placeholder_generation = placeholder_generation,
            .allocator_ptr = @intFromPtr(operation.node.client.allocator.ptr),
            .allocator_vtable = @intFromPtr(operation.node.client.allocator.vtable),
            .fd = operation.node.client.fd,
            .pending_frame_addr = if (pending) |value| @intFromPtr(value.frame.ptr) else 0,
            .pending_frame_len = if (pending) |value| value.frame.len else 0,
            .pending_stream_id = if (pending) |value| value.stream_id else 0,
            .pending_offset = if (pending) |value| value.offset else 0,
            .external_deinit_reserved_raw = @intFromBool(external == .reserved),
            .lifecycle = .prepared,
        };
        out.seal = self.retirementCleanupSeal(out);
        reservation_owned = false;
    }

    fn retirementCleanupMatchesClient(
        cleanup: *const PreparedRetirementCleanup,
        client: *const client_mod.Client,
    ) bool {
        if (cleanup.allocator_ptr != @intFromPtr(client.allocator.ptr) or
            cleanup.allocator_vtable != @intFromPtr(client.allocator.vtable) or
            cleanup.fd != client.fd)
            return false;
        const pending = client.pending_outbound;
        return if (pending) |value|
            cleanup.pending_frame_addr == @intFromPtr(value.frame.ptr) and
                cleanup.pending_frame_len == value.frame.len and
                cleanup.pending_stream_id == value.stream_id and
                cleanup.pending_offset == value.offset
        else
            cleanup.pending_frame_addr == 0 and cleanup.pending_frame_len == 0 and
                cleanup.pending_stream_id == 0 and cleanup.pending_offset == 0;
    }

    pub fn preflightRetirementCleanupBeforeAdmissionClose(
        self: *ClientSlot,
        permit: *const PreparedAdmissionClose,
        cleanup: *const PreparedRetirementCleanup,
        placeholder_generation: u64,
    ) RetirementCleanupError!void {
        if (!self.admissionClosePermitValid(permit, .prepared) or
            !self.retirementCleanupValid(cleanup, .prepared) or
            cleanup.admission_request_generation != permit.request_generation or
            cleanup.placeholder_generation != placeholder_generation)
            return error.InvalidOwner;
        const operation = self.beginRegisteredClientOperation() catch |err| return switch (err) {
            error.MovedOrCopied => error.InvalidOwner,
            error.AdminBusy => error.Busy,
        };
        defer self.endRegisteredClientOperation(operation);
        if (!self.admissionClosePermitValid(permit, .prepared) or
            !self.retirementCleanupValid(cleanup, .prepared) or operation.node != self.current or
            operation.node.admission_lifecycle != .open or
            operation.node.retirement_lifecycle != .live or
            !retirementCleanupMatchesClient(cleanup, &operation.node.client))
            return error.InvalidOwner;
    }

    pub fn preflightRetirementCleanup(
        self: *ClientSlot,
        permit: *PreparedAdmissionClose,
        cleanup: *PreparedRetirementCleanup,
        placeholder_generation: u64,
    ) RetirementCleanupError!void {
        if (!self.admissionClosePermitValid(permit, .committed) or
            !self.retirementCleanupValid(cleanup, .prepared) or
            cleanup.admission_request_generation != permit.request_generation or
            cleanup.placeholder_generation != placeholder_generation)
            return error.InvalidOwner;
        const operation = self.beginRegisteredClientOperation() catch |err| return switch (err) {
            error.MovedOrCopied => error.InvalidOwner,
            error.AdminBusy => error.Busy,
        };
        defer self.endRegisteredClientOperation(operation);
        if (!self.admissionClosePermitValid(permit, .committed) or
            !self.retirementCleanupValid(cleanup, .prepared) or operation.node != self.current or
            !retirementCleanupMatchesClient(cleanup, &operation.node.client))
            return error.InvalidOwner;
    }

    pub fn abortRetirementCleanup(
        self: *ClientSlot,
        cleanup: *PreparedRetirementCleanup,
    ) RetirementCleanupError!void {
        if (!self.retirementCleanupValid(cleanup, .prepared)) return error.InvalidOwner;
        {
            const operation = self.beginRegisteredClientOperation() catch |err| return switch (err) {
                error.MovedOrCopied => error.InvalidOwner,
                error.AdminBusy => error.Busy,
            };
            defer self.endRegisteredClientOperation(operation);
            if (!self.retirementCleanupValid(cleanup, .prepared) or operation.node != self.current or
                !retirementCleanupMatchesClient(cleanup, &operation.node.client))
                return error.InvalidOwner;
        }
        if (cleanup.external_deinit_reserved_raw == 1 and
            !self.current.client.cancelReservedExternalModeDeinit())
            @panic("CR3b R2b reserved external cleanup abort did not converge");
        cleanup.lifecycle = .cancelled;
        cleanup.seal = self.retirementCleanupSeal(cleanup);
    }

    pub fn commitRetirementCleanupNoFail(
        self: *ClientSlot,
        permit: *PreparedAdmissionClose,
        cleanup: *PreparedRetirementCleanup,
        placeholder_generation: u64,
    ) void {
        self.preflightRetirementCleanup(permit, cleanup, placeholder_generation) catch
            @panic("CR3b R2b retirement cleanup authority drifted after preflight");
        const client = &self.current.client;
        client.fd = -1;
        client.pending_outbound = null;
        client.unusable = true;
        cleanup.lifecycle = .committed;
        cleanup.seal = self.retirementCleanupSeal(cleanup);
    }

    pub fn finishRetirementCleanup(
        self: *ClientSlot,
        cleanup: *PreparedRetirementCleanup,
    ) RetirementCleanupError!void {
        if (!self.retirementCleanupValid(cleanup, .committed)) return error.InvalidOwner;
        {
            const operation = self.beginRegisteredClientOperation() catch |err| return switch (err) {
                error.MovedOrCopied => error.InvalidOwner,
                error.AdminBusy => error.Busy,
            };
            defer self.endRegisteredClientOperation(operation);
            if (!self.retirementCleanupValid(cleanup, .committed) or operation.node != self.current or
                operation.node.retirement_lifecycle != .detached or
                operation.node.placeholder_generation != cleanup.placeholder_generation or
                operation.node.client.fd != -1 or operation.node.client.pending_outbound != null or
                !operation.node.client.unusable)
                return error.InvalidOwner;
            cleanup.lifecycle = .cleaning;
            cleanup.seal = self.retirementCleanupSeal(cleanup);
        }
        if (cleanup.external_deinit_reserved_raw == 1 and
            !self.current.client.finishReservedExternalModeDeinit())
            @panic("CR3b R2b reserved external cleanup did not converge");
        if (cleanup.fd >= 0) _ = c.close(cleanup.fd);
        if (cleanup.pending_frame_addr != 0) {
            const bytes: [*]u8 = @ptrFromInt(cleanup.pending_frame_addr);
            const allocator = std.mem.Allocator{
                .ptr = @ptrFromInt(cleanup.allocator_ptr),
                .vtable = @ptrFromInt(cleanup.allocator_vtable),
            };
            allocator.free(bytes[0..cleanup.pending_frame_len]);
        }
        cleanup.allocator_ptr = 0;
        cleanup.allocator_vtable = 0;
        cleanup.fd = -1;
        cleanup.pending_frame_addr = 0;
        cleanup.pending_frame_len = 0;
        cleanup.pending_stream_id = 0;
        cleanup.pending_offset = 0;
        cleanup.external_deinit_reserved_raw = 0;
        cleanup.lifecycle = .consumed;
        cleanup.seal = self.retirementCleanupSeal(cleanup);
    }

    pub const ClientReplacementError = error{
        InvalidOwner,
        Busy,
        GenerationMismatch,
        GenerationExhausted,
        RetiredCapacityExhausted,
        IdentityExhausted,
        OutOfMemory,
        AliasedAllocation,
    };

    /// CR5b reserves the only fallible replacement-node allocation while the shared old Client
    /// is still live. The node intentionally contains no Client payload until the host-wide
    /// no-fail suffix has terminalized every sibling attachment and consumed `cleanup`.
    pub fn reserveClientReplacementNode(
        self: *ClientSlot,
        cleanup: *const PreparedRetirementCleanup,
        source: *const client_mod.Client,
        out: *PreparedClientReplacement,
    ) ClientReplacementError!void {
        if (self.reserved_replacement_addr != 0) return error.Busy;
        if (!self.retirementCleanupValid(cleanup, .prepared) or
            !std.meta.eql(out.*, PreparedClientReplacement{}) or
            source.host_id == 0 or source.host_id != self.current.client.host_id or
            source.fd < 0 or source.unusable or !source.canMoveToGenerationNode() or
            !self.replacementIncidentIdentityPreflight(source) or
            rangesOverlapTyped(source, self) or rangesOverlapTyped(source, self.current) or
            rangesOverlapTyped(source, cleanup) or rangesOverlapTyped(source, out) or
            rangesOverlapTyped(out, self) or rangesOverlapTyped(out, self.current) or
            rangesOverlapTyped(out, cleanup) or self.overlapsRetiredNode(source) or
            self.overlapsRetiredNode(cleanup) or self.overlapsRetiredNode(out))
            return error.InvalidOwner;
        if (!self.retiredNodesValid()) return error.InvalidOwner;
        if (self.retiredClientCountUnchecked() >= max_retired_clients)
            return error.RetiredCapacityExhausted;
        const expected_generation = self.current.connection_generation;
        const next_generation = std.math.add(u64, expected_generation, 1) catch
            return error.GenerationExhausted;
        if (next_generation == 0) return error.GenerationExhausted;

        const issuer = productionIssuer() catch return error.InvalidOwner;
        const node_identity = issuer.reserve(.node, self.pid) catch |err| return switch (err) {
            error.IdentityExhausted => error.IdentityExhausted,
            error.ProcessDomainMismatch => error.InvalidOwner,
        };
        const node = self.node_allocator.create(ClientNode) catch return error.OutOfMemory;
        var destroyable = true;
        errdefer if (destroyable) self.node_allocator.destroy(node);
        const node_start = @intFromPtr(node);
        const node_end = std.math.add(usize, node_start, @sizeOf(ClientNode)) catch
            return error.AliasedAllocation;
        const protected = [_]struct { start: usize, end: usize }{
            .{ .start = @intFromPtr(self), .end = std.math.add(usize, @intFromPtr(self), @sizeOf(ClientSlot)) catch return error.AliasedAllocation },
            .{ .start = @intFromPtr(self.current), .end = std.math.add(usize, @intFromPtr(self.current), @sizeOf(ClientNode)) catch return error.AliasedAllocation },
            .{ .start = @intFromPtr(source), .end = std.math.add(usize, @intFromPtr(source), @sizeOf(client_mod.Client)) catch return error.AliasedAllocation },
            .{ .start = @intFromPtr(cleanup), .end = std.math.add(usize, @intFromPtr(cleanup), @sizeOf(PreparedRetirementCleanup)) catch return error.AliasedAllocation },
            .{ .start = @intFromPtr(out), .end = std.math.add(usize, @intFromPtr(out), @sizeOf(PreparedClientReplacement)) catch return error.AliasedAllocation },
        };
        for (protected) |range| if (rawRangesOverlap(node_start, node_end, range.start, range.end)) {
            destroyable = false;
            if (!recordAliasQuarantine()) @panic("CR5b replacement reservation alias quarantine exhausted");
            return error.AliasedAllocation;
        };
        for (self.retired) |entry| if (entry) |retired| {
            const retired_start = @intFromPtr(retired);
            const retired_end = std.math.add(usize, retired_start, @sizeOf(ClientNode)) catch
                return error.AliasedAllocation;
            if (rawRangesOverlap(node_start, node_end, retired_start, retired_end)) {
                destroyable = false;
                if (!recordAliasQuarantine()) @panic("CR5b replacement reservation retired alias quarantine exhausted");
                return error.AliasedAllocation;
            }
        };
        out.* = .{
            .self_addr = @intFromPtr(out),
            .pid = self.pid,
            .process_nonce = self.process_nonce,
            .owner_thread_incarnation = self.operation_owner_thread_incarnation,
            .slot_addr = @intFromPtr(self),
            .slot_incarnation = self.incarnation.tagged,
            .old_node_addr = @intFromPtr(self.current),
            .old_node_incarnation = self.current.incarnation.tagged,
            .new_node_addr = node_start,
            .new_node_incarnation = node_identity.tagged,
            .expected_connection_generation = expected_generation,
            .next_connection_generation = next_generation,
            .cleanup_seal = cleanup.seal,
            .lifecycle = .reserved,
        };
        out.seal = self.clientReplacementSeal(out);
        self.reserved_replacement_addr = @intFromPtr(out);
        destroyable = false;
    }

    pub fn preflightReservedClientReplacementNode(
        self: *ClientSlot,
        cleanup: *const PreparedRetirementCleanup,
        source: *const client_mod.Client,
        reserved: *const PreparedClientReplacement,
    ) ClientReplacementError!void {
        const next_generation = std.math.add(u64, self.current.connection_generation, 1) catch
            return error.GenerationExhausted;
        if (!preparedClientReplacementLifecycleRawValid(&reserved.lifecycle) or
            !self.retirementCleanupValid(cleanup, .prepared) or !self.valid() or
            !operationThreadMatches(self.operation_owner_thread_incarnation) or
            reserved.lifecycle != .reserved or reserved.self_addr != @intFromPtr(reserved) or
            self.reserved_replacement_addr != @intFromPtr(reserved) or
            reserved.pid != self.pid or reserved.process_nonce != self.process_nonce or
            reserved.owner_thread_incarnation != self.operation_owner_thread_incarnation or
            reserved.slot_addr != @intFromPtr(self) or reserved.slot_incarnation != self.incarnation.tagged or
            reserved.old_node_addr != @intFromPtr(self.current) or
            reserved.old_node_incarnation != self.current.incarnation.tagged or
            reserved.expected_connection_generation != self.current.connection_generation or
            reserved.next_connection_generation != next_generation or
            reserved.new_node_addr == 0 or reserved.new_node_incarnation == 0 or
            !std.mem.allEqual(u8, &reserved.candidate_digest, 0) or
            !std.mem.eql(u8, &reserved.cleanup_seal, &cleanup.seal) or
            source.host_id == 0 or source.host_id != self.current.client.host_id or
            source.fd < 0 or source.unusable or !source.canMoveToGenerationNode() or
            !self.replacementIncidentIdentityPreflight(source) or
            !std.mem.eql(u8, &reserved.seal, &self.clientReplacementSeal(reserved)))
            return error.InvalidOwner;
    }

    pub fn abortReservedClientReplacementNode(
        self: *ClientSlot,
        cleanup: *const PreparedRetirementCleanup,
        source: *const client_mod.Client,
        reserved: *PreparedClientReplacement,
    ) ClientReplacementError!void {
        try self.preflightReservedClientReplacementNode(cleanup, source, reserved);
        const node: *ClientNode = @ptrFromInt(reserved.new_node_addr);
        self.node_allocator.destroy(node);
        self.reserved_replacement_addr = 0;
        reserved.lifecycle = .cancelled;
        reserved.seal = self.clientReplacementSeal(reserved);
    }

    fn reservedClientReplacementReceiptValid(
        self: *const ClientSlot,
        reserved: *const PreparedClientReplacement,
    ) bool {
        if (!preparedClientReplacementLifecycleRawValid(&reserved.lifecycle) or !self.valid() or
            reserved.lifecycle != .reserved or reserved.self_addr != @intFromPtr(reserved) or
            self.reserved_replacement_addr != @intFromPtr(reserved) or reserved.pid != self.pid or
            reserved.process_nonce != self.process_nonce or
            reserved.owner_thread_incarnation != self.operation_owner_thread_incarnation or
            reserved.slot_addr != @intFromPtr(self) or reserved.slot_incarnation != self.incarnation.tagged or
            reserved.old_node_addr != @intFromPtr(self.current) or
            reserved.old_node_incarnation != self.current.incarnation.tagged or
            reserved.expected_connection_generation != self.current.connection_generation or
            reserved.next_connection_generation == 0 or
            reserved.next_connection_generation <= reserved.expected_connection_generation or
            reserved.new_node_addr == 0 or reserved.new_node_incarnation == 0 or
            !std.mem.allEqual(u8, &reserved.candidate_digest, 0)) return false;
        return std.crypto.timing_safe.eql(
            process_seal_service.CleanupSeal,
            self.clientReplacementSeal(reserved),
            reserved.seal,
        );
    }

    /// Consumes a preallocated empty node only after shared retirement cleanup is fully consumed.
    /// All arithmetic/allocation/identity work happened in `reserveClientReplacementNode`; any
    /// drift here is proof loss rather than a recoverable post-publication error.
    pub fn publishReservedClientReplacementAfterRetirementNoFail(
        self: *ClientSlot,
        cleanup: *const PreparedRetirementCleanup,
        source: *client_mod.Client,
        reserved: *PreparedClientReplacement,
    ) void {
        if (!self.consumedRetirementCleanupValid(cleanup) or
            !self.reservedClientReplacementReceiptValid(reserved) or
            source.host_id == 0 or source.host_id != self.current.client.host_id or
            source.fd < 0 or source.unusable or !source.canMoveToGenerationNode() or
            !self.replacementIncidentIdentityPreflight(source))
            process_seal_service.fatalIntegrity(.proof_loss);
        const exclusive = self.beginRegisteredExclusiveTeardown() catch
            process_seal_service.fatalIntegrity(.proof_loss);
        if (exclusive.node != self.current or !self.retiredNodesValid() or
            exclusive.node.retirement_lifecycle != .detached or
            exclusive.node.placeholder_generation != cleanup.placeholder_generation or
            exclusive.node.client.fd != -1 or exclusive.node.client.pending_outbound != null or
            !exclusive.node.client.unusable)
            process_seal_service.fatalIntegrity(.proof_loss);

        const node: *ClientNode = @ptrFromInt(reserved.new_node_addr);
        const node_identity: lease_mod.Identity = .{ .tagged = reserved.new_node_incarnation };
        if (node_identity.kind() != .node) process_seal_service.fatalIntegrity(.proof_loss);
        const node_start = reserved.new_node_addr;
        const node_end = std.math.add(usize, node_start, @sizeOf(ClientNode)) catch
            process_seal_service.fatalIntegrity(.proof_loss);
        const slot_start = @intFromPtr(self);
        const slot_end = std.math.add(usize, slot_start, @sizeOf(ClientSlot)) catch
            process_seal_service.fatalIntegrity(.proof_loss);
        const source_start = @intFromPtr(source);
        const source_end = std.math.add(usize, source_start, @sizeOf(client_mod.Client)) catch
            process_seal_service.fatalIntegrity(.proof_loss);
        const old_start = @intFromPtr(self.current);
        const old_end = std.math.add(usize, old_start, @sizeOf(ClientNode)) catch
            process_seal_service.fatalIntegrity(.proof_loss);
        var protected_retired_starts: [max_retired_clients]usize = .{0} ** max_retired_clients;
        var protected_retired_ends: [max_retired_clients]usize = .{0} ** max_retired_clients;
        var protected_index: usize = 0;
        for (self.retired) |entry| if (entry) |retired| {
            protected_retired_starts[protected_index] = @intFromPtr(retired);
            protected_retired_ends[protected_index] = std.math.add(
                usize,
                protected_retired_starts[protected_index],
                @sizeOf(ClientNode),
            ) catch process_seal_service.fatalIntegrity(.proof_loss);
            protected_index += 1;
        };
        protected_retired_starts[protected_index] = old_start;
        protected_retired_ends[protected_index] = old_end;

        node.cleanup_registry = .{};
        cleanup_registry_mod.AttachmentCleanupRegistry.initInPlace(
            &node.cleanup_registry,
            node_identity.tagged,
        ) catch unreachable;
        node.batch_registry = .{};
        batch_registry_mod.Registry.initInPlace(&node.batch_registry, node_identity.tagged) catch unreachable;
        node.accounting_ledger = .{};
        batch_registry_mod.AccountingLedger.initInPlace(&node.accounting_ledger) catch unreachable;
        node.next_operation_generation = 1;
        node.active_operation_generation = 0;
        node.active_operation_kind = .none;
        node.active_operation_owner_thread_incarnation = 0;
        node.active_operation_owner_addr = 0;
        node.active_operation_transport_incarnation = 0;
        node.active_operation_binding = std.mem.zeroes(contract.BindingIdentity);
        node.rpc_free_evidence = .{};
        node.connection_generation = reserved.next_connection_generation;
        node.admission_lifecycle = .open;
        node.stack_borrows = 0;
        node.next_admission_close_request_generation = 1;
        node.retirement_lifecycle = .live;
        node.placeholder_generation = 0;
        node.guarded_allocator = .{
            .parent = source.allocator,
            .node_start = node_start,
            .node_end = node_end,
            .slot_start = slot_start,
            .slot_end = slot_end,
            .source_start = source_start,
            .source_end = source_end,
            .retired_node_starts = protected_retired_starts,
            .retired_node_ends = protected_retired_ends,
        };
        source.moveToGenerationNode(&node.client);
        self.bindReplacementIncidentIdentityNoFail(
            &self.current.client,
            &node.client,
            reserved.next_connection_generation,
        );
        client_mod.ClientOperationFence.initInPlace(
            &node.operation_fence,
            @intFromPtr(&node.client),
            self.pid,
            self.process_nonce,
            self.incarnation.tagged,
            node_identity.tagged,
            node_identity.tagged,
        );
        if (!node.client.bindOperationFence(&node.operation_fence, node_identity.tagged))
            process_seal_service.fatalIntegrity(.proof_loss);
        node.guarded_allocator.client = &node.client;
        node.client.bindGenerationAccountingLedger(&node.accounting_ledger) catch unreachable;
        node.incarnation = node_identity;
        lease_mod.PinOwner.initInPlaceForGeneration(
            &node.pin_owner,
            @intFromPtr(self),
            node_start,
            self.incarnation,
            node_identity,
            node.client.host_id,
            reserved.next_connection_generation,
            self.pid,
            self.process_nonce,
        );
        reserved.cleanup_seal = cleanup.seal;
        reserved.candidate_digest = clientReplacementCandidateDigest(node);
        reserved.lifecycle = .prepared;
        reserved.seal = self.clientReplacementSeal(reserved);
        self.publishClientReplacementNoFail(reserved);
        self.reserved_replacement_addr = 0;
    }

    pub fn prepareClientReplacement(
        self: *ClientSlot,
        cleanup: *const PreparedRetirementCleanup,
        source: *client_mod.Client,
        out: *PreparedClientReplacement,
    ) ClientReplacementError!void {
        if (self.reserved_replacement_addr != 0) return error.Busy;
        if (!self.consumedRetirementCleanupValid(cleanup) or
            !std.meta.eql(out.*, PreparedClientReplacement{}) or
            source.host_id == 0 or source.host_id != self.current.client.host_id or
            source.fd < 0 or source.unusable or
            !source.canMoveToGenerationNode() or !self.replacementIncidentIdentityPreflight(source) or
            rangesOverlapTyped(source, self) or
            rangesOverlapTyped(source, self.current) or rangesOverlapTyped(source, cleanup) or
            rangesOverlapTyped(source, out) or rangesOverlapTyped(out, self) or
            rangesOverlapTyped(out, self.current) or rangesOverlapTyped(out, cleanup) or
            self.overlapsRetiredNode(source) or self.overlapsRetiredNode(cleanup) or
            self.overlapsRetiredNode(out))
            return error.InvalidOwner;
        if (!self.retiredNodesValid()) return error.InvalidOwner;
        if (self.retiredClientCountUnchecked() >= max_retired_clients)
            return error.RetiredCapacityExhausted;
        const expected_generation = self.current.connection_generation;
        const next_generation = std.math.add(u64, expected_generation, 1) catch
            return error.GenerationExhausted;
        if (next_generation == 0) return error.GenerationExhausted;

        const issuer = productionIssuer() catch return error.InvalidOwner;
        const node_identity = issuer.reserve(.node, self.pid) catch |err| return switch (err) {
            error.IdentityExhausted => error.IdentityExhausted,
            error.ProcessDomainMismatch => error.InvalidOwner,
        };
        const node = self.node_allocator.create(ClientNode) catch return error.OutOfMemory;
        var node_destroyable = false;
        errdefer if (node_destroyable) self.node_allocator.destroy(node);
        const node_start = @intFromPtr(node);
        const node_end = std.math.add(usize, node_start, @sizeOf(ClientNode)) catch
            return error.AliasedAllocation;
        const source_start = @intFromPtr(source);
        const source_end = std.math.add(usize, source_start, @sizeOf(client_mod.Client)) catch
            return error.AliasedAllocation;
        const slot_start = @intFromPtr(self);
        const slot_end = std.math.add(usize, slot_start, @sizeOf(ClientSlot)) catch
            return error.AliasedAllocation;
        const old_start = @intFromPtr(self.current);
        const old_end = std.math.add(usize, old_start, @sizeOf(ClientNode)) catch
            return error.AliasedAllocation;
        var protected_retired_starts: [max_retired_clients]usize = .{0} ** max_retired_clients;
        var protected_retired_ends: [max_retired_clients]usize = .{0} ** max_retired_clients;
        var protected_index: usize = 0;
        for (self.retired) |entry| if (entry) |retired| {
            protected_retired_starts[protected_index] = @intFromPtr(retired);
            protected_retired_ends[protected_index] = std.math.add(
                usize,
                protected_retired_starts[protected_index],
                @sizeOf(ClientNode),
            ) catch return error.AliasedAllocation;
            protected_index += 1;
        };
        protected_retired_starts[protected_index] = old_start;
        protected_retired_ends[protected_index] = old_end;
        const cleanup_start = @intFromPtr(cleanup);
        const cleanup_end = std.math.add(usize, cleanup_start, @sizeOf(PreparedRetirementCleanup)) catch
            return error.AliasedAllocation;
        const out_start = @intFromPtr(out);
        const out_end = std.math.add(usize, out_start, @sizeOf(PreparedClientReplacement)) catch
            return error.AliasedAllocation;
        if (rawRangesOverlap(node_start, node_end, source_start, source_end) or
            rawRangesOverlap(node_start, node_end, slot_start, slot_end) or
            rawRangesOverlap(node_start, node_end, old_start, old_end) or
            rawRangesOverlap(node_start, node_end, cleanup_start, cleanup_end) or
            rawRangesOverlap(node_start, node_end, out_start, out_end))
        {
            if (!recordAliasQuarantine()) @panic("Client replacement alias quarantine exhausted");
            return error.AliasedAllocation;
        }
        for (self.retired) |entry| if (entry) |retired| {
            const retired_start = @intFromPtr(retired);
            const retired_end = std.math.add(usize, retired_start, @sizeOf(ClientNode)) catch
                return error.AliasedAllocation;
            if (rawRangesOverlap(node_start, node_end, retired_start, retired_end)) {
                if (!recordAliasQuarantine()) @panic("Client replacement retired alias quarantine exhausted");
                return error.AliasedAllocation;
            }
        };
        node_destroyable = true;

        const reserved = self.beginRegisteredExclusiveTeardown() catch |err| return switch (err) {
            error.AdminBusy => error.Busy,
            error.MovedOrCopied => error.InvalidOwner,
        };
        var old_reserved = true;
        errdefer if (old_reserved) self.abortRegisteredExclusiveTeardown(reserved);
        if (reserved.node != self.current or !self.retiredNodesValid() or
            reserved.node.retirement_lifecycle != .detached or
            reserved.node.placeholder_generation != cleanup.placeholder_generation or
            reserved.node.client.fd != -1 or reserved.node.client.pending_outbound != null or
            !reserved.node.client.unusable)
            return error.InvalidOwner;

        // All fallible work is complete. The candidate becomes a fully formed final-address node,
        // while the old registry row stays closed until publish or abort settles this handle.
        node.cleanup_registry = .{};
        cleanup_registry_mod.AttachmentCleanupRegistry.initInPlace(
            &node.cleanup_registry,
            node_identity.tagged,
        ) catch unreachable;
        node.batch_registry = .{};
        batch_registry_mod.Registry.initInPlace(&node.batch_registry, node_identity.tagged) catch unreachable;
        node.accounting_ledger = .{};
        batch_registry_mod.AccountingLedger.initInPlace(&node.accounting_ledger) catch unreachable;
        node.next_operation_generation = 1;
        node.active_operation_generation = 0;
        node.active_operation_kind = .none;
        node.active_operation_owner_thread_incarnation = 0;
        node.active_operation_owner_addr = 0;
        node.active_operation_transport_incarnation = 0;
        node.active_operation_binding = std.mem.zeroes(contract.BindingIdentity);
        node.rpc_free_evidence = .{};
        node.connection_generation = next_generation;
        node.admission_lifecycle = .open;
        node.stack_borrows = 0;
        node.next_admission_close_request_generation = 1;
        node.retirement_lifecycle = .live;
        node.placeholder_generation = 0;
        node.guarded_allocator = .{
            .parent = source.allocator,
            .node_start = node_start,
            .node_end = node_end,
            .slot_start = slot_start,
            .slot_end = slot_end,
            .source_start = source_start,
            .source_end = source_end,
            .retired_node_starts = protected_retired_starts,
            .retired_node_ends = protected_retired_ends,
        };
        source.moveToGenerationNode(&node.client);
        self.bindReplacementIncidentIdentityNoFail(
            &self.current.client,
            &node.client,
            next_generation,
        );
        client_mod.ClientOperationFence.initInPlace(
            &node.operation_fence,
            @intFromPtr(&node.client),
            self.pid,
            self.process_nonce,
            self.incarnation.tagged,
            node_identity.tagged,
            node_identity.tagged,
        );
        if (!node.client.bindOperationFence(&node.operation_fence, node_identity.tagged))
            @panic("replacement Client operation fence binding failed");
        node.guarded_allocator.client = &node.client;
        node.client.bindGenerationAccountingLedger(&node.accounting_ledger) catch unreachable;
        node.incarnation = node_identity;
        lease_mod.PinOwner.initInPlaceForGeneration(
            &node.pin_owner,
            @intFromPtr(self),
            node_start,
            self.incarnation,
            node_identity,
            node.client.host_id,
            next_generation,
            self.pid,
            self.process_nonce,
        );
        const candidate_digest = clientReplacementCandidateDigest(node);
        out.* = .{
            .self_addr = @intFromPtr(out),
            .pid = self.pid,
            .process_nonce = self.process_nonce,
            .owner_thread_incarnation = self.operation_owner_thread_incarnation,
            .slot_addr = @intFromPtr(self),
            .slot_incarnation = self.incarnation.tagged,
            .old_node_addr = old_start,
            .old_node_incarnation = self.current.incarnation.tagged,
            .new_node_addr = node_start,
            .new_node_incarnation = node_identity.tagged,
            .expected_connection_generation = expected_generation,
            .next_connection_generation = next_generation,
            .cleanup_seal = cleanup.seal,
            .candidate_digest = candidate_digest,
            .lifecycle = .prepared,
        };
        out.seal = self.clientReplacementSeal(out);
        old_reserved = false;
        node_destroyable = false;
    }

    pub fn abortClientReplacement(
        self: *ClientSlot,
        prepared: *PreparedClientReplacement,
    ) ClientReplacementError!void {
        if (!self.preparedClientReplacementValid(prepared, .prepared)) return error.InvalidOwner;
        const candidate: *ClientNode = @ptrFromInt(prepared.new_node_addr);
        const candidate_digest = clientReplacementCandidateDigest(candidate);
        if (!std.crypto.timing_safe.eql(owner_seal.Digest, candidate_digest, prepared.candidate_digest) or
            candidate.incarnation.tagged != prepared.new_node_incarnation or
            candidate.connection_generation != prepared.next_connection_generation or
            candidate.admission_lifecycle != .open or candidate.retirement_lifecycle != .live or
            candidate.placeholder_generation != 0)
            return error.InvalidOwner;
        // The unpublished candidate has no external borrower that could make Busy recoverable.
        // Once canonical authority reaches this suffix, losing exclusive teardown proof would
        // strand both the candidate and the old closed registry row, so fail closed.
        candidate.client.tryAcquireClientSlotTeardownExclusive() catch
            process_seal_service.fatalIntegrity(.proof_loss);
        if (!candidate.client.tryDeinitClientSlotExclusiveHeld())
            process_seal_service.fatalIntegrity(.proof_loss);
        switch (candidate.cleanup_registry.tryDeinit()) {
            .cleaned => {},
            else => @panic("replacement cleanup registry abort drifted"),
        }
        switch (candidate.batch_registry.tryDeinit()) {
            .cleaned => {},
            else => @panic("replacement batch registry abort drifted"),
        }
        candidate.pin_owner.state = .terminal;
        switch (candidate.accounting_ledger.tryDeinit()) {
            .cleaned => {},
            else => @panic("replacement accounting abort drifted"),
        }
        self.node_allocator.destroy(candidate);
        self.abortRegisteredExclusiveTeardown(.{
            .registry_entry = .{
                .live = true,
                .ready = false,
                .slot_addr = @intFromPtr(self),
                .node_addr = prepared.old_node_addr,
                .slot_incarnation = self.incarnation.tagged,
                .node_incarnation = prepared.old_node_incarnation,
                .owner_thread_incarnation = self.operation_owner_thread_incarnation,
            },
            .node = self.current,
        });
        prepared.lifecycle = .cancelled;
        prepared.seal = self.clientReplacementSeal(prepared);
    }

    pub fn publishClientReplacementNoFail(
        self: *ClientSlot,
        prepared: *PreparedClientReplacement,
    ) void {
        self.preflightClientReplacement(prepared) catch
            @panic("CR3b R2c replacement candidate drifted before publication");
        const candidate: *ClientNode = @ptrFromInt(prepared.new_node_addr);
        const expected: ClientSlotRegistryEntry = .{
            .live = true,
            .ready = false,
            .slot_addr = @intFromPtr(self),
            .node_addr = prepared.old_node_addr,
            .slot_incarnation = self.incarnation.tagged,
            .node_incarnation = prepared.old_node_incarnation,
            .owner_thread_incarnation = self.operation_owner_thread_incarnation,
        };
        const replacement: ClientSlotRegistryEntry = .{
            .live = true,
            .ready = true,
            .slot_addr = @intFromPtr(self),
            .node_addr = prepared.new_node_addr,
            .slot_incarnation = self.incarnation.tagged,
            .node_incarnation = prepared.new_node_incarnation,
            .owner_thread_incarnation = self.operation_owner_thread_incarnation,
        };
        if (!publishClientSlotReplacement(self, expected, replacement, candidate))
            @panic("CR3b R2c registry/current atomic publication drifted");
        prepared.lifecycle = .published;
        prepared.seal = self.clientReplacementSealAfterPublish(prepared);
    }

    /// CR3c의 cross-owner publication이 stable screen writer gate에 들어가기 전에
    /// R2c prepared authority와 candidate 전체를 mutation 없이 재검증한다.
    pub fn preflightClientReplacement(
        self: *ClientSlot,
        prepared: *const PreparedClientReplacement,
    ) ClientReplacementError!void {
        if (!self.preparedClientReplacementValid(prepared, .prepared))
            return error.InvalidOwner;
        const candidate: *const ClientNode = @ptrFromInt(prepared.new_node_addr);
        const candidate_digest = clientReplacementCandidateDigest(candidate);
        if (!std.crypto.timing_safe.eql(owner_seal.Digest, candidate_digest, prepared.candidate_digest) or
            candidate.incarnation.tagged != prepared.new_node_incarnation or
            candidate.connection_generation != prepared.next_connection_generation or
            candidate.admission_lifecycle != .open or candidate.retirement_lifecycle != .live or
            candidate.placeholder_generation != 0 or candidate.client.host_id != self.current.client.host_id or
            candidate.client.fd < 0 or candidate.client.unusable)
            return error.InvalidOwner;
    }

    /// CR3c1은 R2c publication이 이미 끝난 뒤 이 receipt로 exact old/new
    /// connection generation과 current/retired node를 다시 결속한다.
    pub fn preflightPublishedClientReplacement(
        self: *ClientSlot,
        published: *const PreparedClientReplacement,
    ) ClientReplacementError!void {
        if (!preparedClientReplacementLifecycleRawValid(&published.lifecycle) or
            !self.valid() or !operationThreadMatches(self.operation_owner_thread_incarnation) or
            published.lifecycle != .published or published.self_addr != @intFromPtr(published) or
            published.pid != self.pid or published.process_nonce != self.process_nonce or
            published.owner_thread_incarnation != self.operation_owner_thread_incarnation or
            published.slot_addr != @intFromPtr(self) or
            published.slot_incarnation != self.incarnation.tagged or
            published.new_node_addr != @intFromPtr(self.current) or
            published.new_node_incarnation != self.current.incarnation.tagged or
            published.next_connection_generation != self.current.connection_generation or
            published.expected_connection_generation == 0 or
            published.next_connection_generation <= published.expected_connection_generation)
            return error.InvalidOwner;
        var old_found = false;
        for (self.retired) |entry| if (entry) |node| {
            if (@intFromPtr(node) == published.old_node_addr and
                node.incarnation.tagged == published.old_node_incarnation and
                node.connection_generation == published.expected_connection_generation)
            {
                old_found = true;
                break;
            }
        };
        if (!old_found or !std.crypto.timing_safe.eql(
            process_seal_service.CleanupSeal,
            self.clientReplacementSealAfterPublish(published),
            published.seal,
        )) return error.InvalidOwner;
    }

    fn clientReplacementSealAfterPublish(
        self: *const ClientSlot,
        prepared: *const PreparedClientReplacement,
    ) process_seal_service.CleanupSeal {
        return process_seal_service.preparedClientReplacementSeal(self.pid, self.process_nonce, .{
            .self_addr = @intCast(prepared.self_addr),
            .thread_id = prepared.owner_thread_incarnation,
            .slot_addr = @intCast(prepared.slot_addr),
            .slot_incarnation = prepared.slot_incarnation,
            .old_node_addr = @intCast(prepared.old_node_addr),
            .old_node_incarnation = prepared.old_node_incarnation,
            .new_node_addr = @intCast(prepared.new_node_addr),
            .new_node_incarnation = prepared.new_node_incarnation,
            .expected_connection_generation = prepared.expected_connection_generation,
            .next_connection_generation = prepared.next_connection_generation,
            .cleanup_seal = prepared.cleanup_seal,
            .candidate_digest = prepared.candidate_digest,
            .lifecycle_raw = @intFromEnum(prepared.lifecycle),
        }) catch @panic("CR3b R2c published replacement seal service unavailable");
    }

    pub const RetiredClientReclaimError = error{
        InvalidOwner,
        NotReady,
        DestinationOccupied,
    };

    fn retiredClientReclaimSeal(
        self: *const ClientSlot,
        prepared: *const PreparedRetiredClientReclaim,
    ) process_seal_service.CleanupSeal {
        return process_seal_service.preparedRetiredClientReclaimSeal(self.pid, self.process_nonce, .{
            .self_addr = @intCast(prepared.self_addr),
            .thread_id = prepared.owner_thread_incarnation,
            .slot_addr = @intCast(prepared.slot_addr),
            .slot_incarnation = prepared.slot_incarnation,
            .retired_index = prepared.retired_index,
            .node_addr = @intCast(prepared.node_addr),
            .node_incarnation = prepared.node_incarnation,
            .connection_generation = prepared.connection_generation,
            .node_digest = prepared.node_digest,
            .lifecycle_raw = @intFromEnum(prepared.lifecycle),
        }) catch @panic("CR3b R3 retired reclaim seal service unavailable");
    }

    fn preparedRetiredClientReclaimValid(
        self: *const ClientSlot,
        prepared: *const PreparedRetiredClientReclaim,
        lifecycle: PreparedRetiredClientReclaim.Lifecycle,
    ) bool {
        if (!preparedRetiredClientReclaimLifecycleRawValid(&prepared.lifecycle) or
            prepared.lifecycle != lifecycle or prepared.self_addr != @intFromPtr(prepared) or
            prepared.pid != self.pid or prepared.process_nonce != self.process_nonce or
            prepared.owner_thread_incarnation != self.operation_owner_thread_incarnation or
            prepared.slot_addr != @intFromPtr(self) or
            prepared.slot_incarnation != self.incarnation.tagged or
            prepared.retired_index >= max_retired_clients or prepared.node_addr == 0 or
            prepared.node_incarnation == 0 or prepared.connection_generation == 0)
            return false;
        return std.crypto.timing_safe.eql(
            process_seal_service.CleanupSeal,
            self.retiredClientReclaimSeal(prepared),
            prepared.seal,
        );
    }

    fn retiredNodeReadyForReclaim(self: *const ClientSlot, index: usize) bool {
        if (!self.retiredNodeValidAt(index)) return false;
        const node = self.retired[index].?;
        return node.stack_borrows == 0 and node.active_operation_generation == 0 and
            node.rpc_free_evidence.emptyExact() and
            node.pin_owner.cleanup_pin_count == 0 and node.pin_owner.active_cleanup == 0 and
            node.cleanup_registry.preflightDeinit() == .cleaned and
            node.batch_registry.preflightDeinit() == .cleaned and
            node.accounting_ledger.preflightDeinit() == .cleaned and
            node.client.canRetireFromGenerationNode();
    }

    pub fn prepareRetiredClientReclaim(
        self: *ClientSlot,
        out: *PreparedRetiredClientReclaim,
    ) RetiredClientReclaimError!void {
        if (!std.meta.eql(out.*, PreparedRetiredClientReclaim{}))
            return error.DestinationOccupied;
        if (!self.valid() or self.pid != currentPid() or
            !operationThreadMatches(self.operation_owner_thread_incarnation) or
            rangesOverlapTyped(out, self) or rangesOverlapTyped(out, self.current) or
            self.overlapsRetiredNode(out))
            return error.InvalidOwner;
        const node = self.retired[0] orelse return error.NotReady;
        if (!self.retiredNodeReadyForReclaim(0)) return error.NotReady;
        const node_digest = retiredClientNodeDigest(node);
        if (!self.retiredNodeReadyForReclaim(0)) return error.NotReady;
        out.* = .{
            .self_addr = @intFromPtr(out),
            .pid = self.pid,
            .process_nonce = self.process_nonce,
            .owner_thread_incarnation = self.operation_owner_thread_incarnation,
            .slot_addr = @intFromPtr(self),
            .slot_incarnation = self.incarnation.tagged,
            .retired_index = 0,
            .node_addr = @intFromPtr(node),
            .node_incarnation = node.incarnation.tagged,
            .connection_generation = node.connection_generation,
            .node_digest = node_digest,
            .lifecycle = .prepared,
        };
        out.seal = self.retiredClientReclaimSeal(out);
    }

    pub fn commitRetiredClientReclaimNoFail(
        self: *ClientSlot,
        prepared: *PreparedRetiredClientReclaim,
    ) void {
        self.preflightRetiredClientReclaim(prepared) catch
            @panic("CR3b R3 retired reclaim authority drifted");
        const node = self.retired[prepared.retired_index] orelse
            @panic("CR3b R3 retired reclaim node disappeared");
        if (@intFromPtr(node) != prepared.node_addr or
            node.incarnation.tagged != prepared.node_incarnation or
            node.connection_generation != prepared.connection_generation or
            !std.crypto.timing_safe.eql(
                owner_seal.Digest,
                retiredClientNodeDigest(node),
                prepared.node_digest,
            ))
            @panic("CR3b R3 retired reclaim node drifted");
        if (!node.client.tryDeinitClientSlotExclusiveHeld())
            @panic("CR3b R3 retired Client teardown proof lost");
        if (node.cleanup_registry.tryDeinit() != .cleaned or
            node.batch_registry.tryDeinit() != .cleaned)
            @panic("CR3b R3 retired registry teardown drifted");
        node.pin_owner.state = .terminal;
        if (node.accounting_ledger.tryDeinit() != .cleaned)
            @panic("CR3b R3 retired accounting teardown drifted");
        const reclaimed_addr = @intFromPtr(node);
        self.node_allocator.destroy(node);
        var index: usize = prepared.retired_index;
        while (index + 1 < max_retired_clients) : (index += 1)
            self.retired[index] = self.retired[index + 1];
        self.retired[max_retired_clients - 1] = null;
        for (&self.current.guarded_allocator.retired_node_starts, &self.current.guarded_allocator.retired_node_ends) |*start, *end| {
            if (start.* == reclaimed_addr) {
                start.* = 0;
                end.* = 0;
            }
        }
        prepared.lifecycle = .reclaimed;
        prepared.seal = self.retiredClientReclaimSeal(prepared);
    }

    pub fn preflightRetiredClientReclaim(
        self: *ClientSlot,
        prepared: *const PreparedRetiredClientReclaim,
    ) RetiredClientReclaimError!void {
        if (self.pid != currentPid() or
            !operationThreadMatches(self.operation_owner_thread_incarnation))
            return error.InvalidOwner;
        if (!self.preparedRetiredClientReclaimValid(prepared, .prepared) or !self.valid())
            return error.InvalidOwner;
        if (!self.retiredNodeReadyForReclaim(prepared.retired_index)) return error.NotReady;
        const node = self.retired[prepared.retired_index] orelse return error.NotReady;
        if (@intFromPtr(node) != prepared.node_addr or
            node.incarnation.tagged != prepared.node_incarnation or
            node.connection_generation != prepared.connection_generation or
            !std.crypto.timing_safe.eql(
                owner_seal.Digest,
                retiredClientNodeDigest(node),
                prepared.node_digest,
            ))
            return error.InvalidOwner;
    }

    pub const RetirementDetachError = error{
        InvalidOwner,
        InvalidGeneration,
        GenerationExhausted,
        Busy,
    };

    /// R2a의 fallible preflight. durable mutation과 proxy writer 진입 전에 모든 Client 권위를 닫는다.
    pub fn preflightRetirementDetach(
        self: *ClientSlot,
        permit: *PreparedAdmissionClose,
        expected_placeholder_generation: u64,
        next_placeholder_generation: u64,
    ) RetirementDetachError!void {
        if (!self.admissionClosePermitValid(permit, .committed)) return error.InvalidOwner;
        const operation = self.beginRegisteredClientOperation() catch |err| return switch (err) {
            error.MovedOrCopied => error.InvalidOwner,
            error.AdminBusy => error.Busy,
        };
        defer self.endRegisteredClientOperation(operation);
        if (!self.admissionClosePermitValid(permit, .committed) or operation.node != self.current)
            return error.InvalidOwner;
        if (operation.node.admission_lifecycle != .closed or
            operation.node.retirement_lifecycle != .live or
            operation.node.placeholder_generation != 0 or operation.node.stack_borrows != 0 or
            operation.node.active_operation_generation != 0 or
            operation.node.pin_owner.active_cleanup != 0)
            return error.Busy;
        if (expected_placeholder_generation == 0 or next_placeholder_generation == 0)
            return error.InvalidGeneration;
        if (expected_placeholder_generation == std.math.maxInt(u64))
            return error.GenerationExhausted;
        if (next_placeholder_generation != expected_placeholder_generation + 1)
            return error.InvalidGeneration;
    }

    pub fn preflightRetirementDetachBeforeAdmissionClose(
        self: *ClientSlot,
        permit: *const PreparedAdmissionClose,
        expected_placeholder_generation: u64,
        next_placeholder_generation: u64,
    ) RetirementDetachError!void {
        if (!self.admissionClosePermitValid(permit, .prepared)) return error.InvalidOwner;
        const operation = self.beginRegisteredClientOperation() catch |err| return switch (err) {
            error.MovedOrCopied => error.InvalidOwner,
            error.AdminBusy => error.Busy,
        };
        defer self.endRegisteredClientOperation(operation);
        if (!self.admissionClosePermitValid(permit, .prepared) or operation.node != self.current)
            return error.InvalidOwner;
        if (operation.node.admission_lifecycle != .open or
            operation.node.retirement_lifecycle != .live or
            operation.node.placeholder_generation != 0 or operation.node.stack_borrows != 0 or
            operation.node.active_operation_generation != 0 or
            operation.node.pin_owner.active_cleanup != 0)
            return error.Busy;
        if (expected_placeholder_generation == 0 or next_placeholder_generation == 0)
            return error.InvalidGeneration;
        if (expected_placeholder_generation == std.math.maxInt(u64))
            return error.GenerationExhausted;
        if (next_placeholder_generation != expected_placeholder_generation + 1)
            return error.InvalidGeneration;
    }

    /// stable proxy writer gate 안에서만 호출하는 callback/allocation 없는 suffix다.
    pub fn commitRetirementDetachNoFail(
        self: *ClientSlot,
        permit: *PreparedAdmissionClose,
        expected_placeholder_generation: u64,
        next_placeholder_generation: u64,
    ) void {
        self.preflightRetirementDetach(
            permit,
            expected_placeholder_generation,
            next_placeholder_generation,
        ) catch @panic("CR3b R2a retirement detach authority drifted after preflight");
        self.current.retirement_lifecycle = .detached;
        self.current.placeholder_generation = next_placeholder_generation;
        permit.lifecycle = .consumed;
        permit.seal = self.admissionCloseSeal(permit);
    }

    pub fn validateRetirementPlaceholder(
        self: *ClientSlot,
        expected_placeholder_generation: u64,
    ) RetirementDetachError!void {
        if (expected_placeholder_generation == 0 or !self.valid() or
            !operationThreadMatches(self.operation_owner_thread_incarnation))
            return error.InvalidOwner;
        const operation = self.beginRegisteredClientOperation() catch |err| return switch (err) {
            error.MovedOrCopied => error.InvalidOwner,
            error.AdminBusy => error.Busy,
        };
        defer self.endRegisteredClientOperation(operation);
        if (operation.node != self.current or operation.node.admission_lifecycle != .closed or
            operation.node.retirement_lifecycle != .detached or
            operation.node.placeholder_generation != expected_placeholder_generation or
            operation.node.stack_borrows != 0 or operation.node.active_operation_generation != 0 or
            operation.node.pin_owner.active_cleanup != 0)
            return error.InvalidOwner;
    }

    pub fn logicalClientConst(self: *const ClientSlot) *const client_mod.Client {
        if (!self.valid()) @panic("invalid session-host ClientSlot");
        return &self.current.client;
    }

    pub fn transportOwnerSeal(
        self: *ClientSlot,
        reservation: AttachmentBindingReservation,
    ) BindingError!*contract.TransportOwnerSeal {
        if (!self.valid() or
            !operationThreadMatches(self.operation_owner_thread_incarnation))
            return error.MovedOrCopied;
        return self.current.cleanup_registry.transportOwnerSeal(
            reservation.cleanup,
            reservation.identity,
        );
    }

    fn beginCanonicalAuthorityAccess(
        self: *ClientSlot,
    ) BindingError!RegisteredClientOperation {
        // These methods protect the canonical input authority itself, so they cannot rely on the
        // caller having reached them through GenerationTransport. Reject fork/thread aliases
        // before node dereference, then pin the exact registered node against concurrent teardown.
        if (self.pid != currentPid() or
            !operationThreadMatches(self.operation_owner_thread_incarnation))
            return error.MovedOrCopied;
        return self.beginRegisteredClientOperation() catch |err| switch (err) {
            error.MovedOrCopied => error.MovedOrCopied,
            error.AdminBusy => error.AdminBusy,
        };
    }

    pub fn controllerAuthorityLive(
        self: *ClientSlot,
        reservation: AttachmentBindingReservation,
        stream_id: u64,
    ) BindingError!bool {
        const operation = try self.beginCanonicalAuthorityAccess();
        defer self.endRegisteredClientOperation(operation);
        if (!self.valid() or operation.node != self.current) return error.MovedOrCopied;
        return operation.node.cleanup_registry.controllerAuthorityLive(
            reservation.cleanup,
            reservation.identity,
            stream_id,
        );
    }

    pub fn preflightAttachmentControllerPromotion(
        self: *ClientSlot,
        binding: *contract.PreparedAttachmentBinding,
        reservation: AttachmentBindingReservation,
        stream_id: u64,
    ) BindingError!contract.BindingIdentity {
        const operation = try self.beginCanonicalAuthorityAccess();
        defer self.endRegisteredClientOperation(operation);
        if (!self.valid() or operation.node != self.current or
            operation.node.active_operation_generation != 0 or
            !binding.validAtFinalAddress() or binding.lifecycle != .committed)
            return error.MovedOrCopied;
        const observer_identity = binding.identity orelse return error.InvalidIdentity;
        if (!observer_identity.matches(reservation.identity) or
            observer_identity.binding_storage_addr != @intFromPtr(binding))
            return error.InvalidIdentity;
        return operation.node.cleanup_registry.preflightControllerPromotion(
            reservation.cleanup,
            observer_identity,
            stream_id,
        );
    }

    pub fn promoteAttachmentControllerNoFail(
        self: *ClientSlot,
        binding: *contract.PreparedAttachmentBinding,
        reservation: *AttachmentBindingReservation,
        stream_id: u64,
    ) void {
        const controller_identity = self.preflightAttachmentControllerPromotion(
            binding,
            reservation.*,
            stream_id,
        ) catch @panic("ClientSlot authority changed after controller-promotion preflight");
        const operation = self.beginCanonicalAuthorityAccess() catch
            @panic("ClientSlot owner changed after controller-promotion preflight");
        defer self.endRegisteredClientOperation(operation);
        const promoted = operation.node.cleanup_registry.promoteControllerNoFail(
            reservation.cleanup,
            reservation.identity,
            stream_id,
        );
        if (!promoted.matches(controller_identity))
            @panic("cleanup registry promoted a different controller identity");
        binding.identity = promoted;
        reservation.identity = promoted;
    }

    pub fn controllerRevokePending(
        self: *ClientSlot,
        reservation: AttachmentBindingReservation,
        stream_id: u64,
    ) BindingError!bool {
        const operation = try self.beginCanonicalAuthorityAccess();
        defer self.endRegisteredClientOperation(operation);
        if (!self.valid() or operation.node != self.current) return error.MovedOrCopied;
        return operation.node.cleanup_registry.controllerRevokePending(
            reservation.cleanup,
            reservation.identity,
            stream_id,
        );
    }

    pub fn beginControllerRevoke(
        self: *ClientSlot,
        reservation: AttachmentBindingReservation,
        stream_id: u64,
    ) BindingError!void {
        const operation = try self.beginCanonicalAuthorityAccess();
        defer self.endRegisteredClientOperation(operation);
        if (!self.valid() or operation.node != self.current) return error.MovedOrCopied;
        try operation.node.cleanup_registry.beginControllerRevoke(
            reservation.cleanup,
            reservation.identity,
            stream_id,
        );
    }

    pub fn finishControllerRevoke(
        self: *ClientSlot,
        reservation: AttachmentBindingReservation,
        stream_id: u64,
    ) BindingError!void {
        const operation = try self.beginCanonicalAuthorityAccess();
        defer self.endRegisteredClientOperation(operation);
        if (!self.valid() or operation.node != self.current) return error.MovedOrCopied;
        try operation.node.cleanup_registry.finishControllerRevoke(
            reservation.cleanup,
            reservation.identity,
            stream_id,
        );
    }

    pub fn responseOwnerSeal(
        self: *ClientSlot,
        reservation: AttachmentBindingReservation,
    ) BindingError!*contract.ExecutedResponseOwnerSeal {
        if (!self.valid()) return error.MovedOrCopied;
        return self.current.cleanup_registry.responseOwnerSeal(
            reservation.cleanup,
            reservation.identity,
        );
    }

    pub fn reserveAttachmentBindingForTest(
        self: *ClientSlot,
        binding_out: *contract.PreparedAttachmentBinding,
        lease_out: *lease_mod.ConnectionLease,
        runtime_id: u128,
    ) BindingError!AttachmentBindingReservation {
        if (!builtin.is_test) unreachable;
        return self.reserveAttachmentBinding(
            binding_out,
            lease_out,
            runtime_id,
            .controller,
        );
    }

    pub const AttachmentBatchRead = union(enum) {
        committed: batch_registry_mod.Token,
        idle,
        terminal,
    };

    pub const BatchError = client_mod.ClientError || batch_registry_mod.Error;

    pub const GenerationBatchAdapterIdentity = struct {
        slot_incarnation: u64,
        node_incarnation: u64,
        pid: u32,
        process_nonce: u64,
    };

    /// Final-address GUI batch adapter가 raw node/Client 포인터를 보관하지 않고도 exact slot을
    /// 매 호출 재검증할 수 있는 pointer-free identity다.
    pub fn generationBatchAdapterIdentity(
        self: *ClientSlot,
    ) error{MovedOrCopied}!GenerationBatchAdapterIdentity {
        if (!self.valid()) return error.MovedOrCopied;
        return .{
            .slot_incarnation = self.incarnation.tagged,
            .node_incarnation = self.current.incarnation.tagged,
            .pid = self.pid,
            .process_nonce = self.process_nonce,
        };
    }

    pub fn matchesGenerationBatchAdapterIdentity(
        self: *ClientSlot,
        identity: GenerationBatchAdapterIdentity,
    ) bool {
        return self.valid() and self.incarnation.tagged == identity.slot_incarnation and
            self.current.incarnation.tagged == identity.node_incarnation and
            self.pid == identity.pid and self.process_nonce == identity.process_nonce;
    }

    pub fn poisonAttachmentConnection(
        self: *ClientSlot,
        reason: @import("client_poison.zig").ConnectionReason,
    ) error{MovedOrCopied}!void {
        if (!self.valid()) return error.MovedOrCopied;
        self.current.client.poison(reason);
    }

    pub fn failCloseAttachmentConnection(
        self: *ClientSlot,
        reason: @import("client_poison.zig").ConnectionReason,
    ) error{ MovedOrCopied, InvalidTerminalConnection }!@import("client_poison.zig").ConnectionReason {
        if (!self.valid()) return error.MovedOrCopied;
        self.current.client.poison(reason);
        const canonical = self.current.client.firstPoisonReason() orelse
            return error.InvalidTerminalConnection;
        try self.preflightAttachmentConnectionFailedClosed(canonical);
        return canonical;
    }

    /// Published replacement 뒤 candidate prepare가 실패한 host job이 같은 current Client의
    /// exact fail-close provenance를 재검증할 때만 쓰는 닫힌 projection이다.
    pub fn preflightAttachmentConnectionFailedClosed(
        self: *const ClientSlot,
        reason: @import("client_poison.zig").ConnectionReason,
    ) error{ MovedOrCopied, InvalidTerminalConnection }!void {
        if (!self.valid()) return error.MovedOrCopied;
        const client = &self.current.client;
        if (client.fd != -1 or !client.unusable or client.pending_outbound != null or
            client.firstPoisonReason() != reason)
            return error.InvalidTerminalConnection;
    }

    pub fn preflightAttachmentConnectionUsable(
        self: *const ClientSlot,
    ) error{ MovedOrCopied, InvalidUsableConnection }!void {
        if (!self.valid()) return error.MovedOrCopied;
        const client = &self.current.client;
        if (client.fd < 0 or client.unusable or client.pending_outbound != null or
            client.firstPoisonReason() != null)
            return error.InvalidUsableConnection;
    }

    pub fn attachmentConnectionFailureReason(
        self: *const ClientSlot,
    ) ?@import("client_poison.zig").ConnectionReason {
        if (!self.valid()) return null;
        const reason = self.current.client.firstPoisonReason() orelse return null;
        self.preflightAttachmentConnectionFailedClosed(reason) catch return null;
        return reason;
    }

    /// Client의 allocator callback TLS는 node-local mutation 진입점들이 같은 방식으로 읽는다.
    fn generationAllocatorCallbackActive(self: *const ClientSlot) bool {
        self.current.client.rejectGenerationAllocatorCallbackReentry() catch return true;
        return false;
    }

    pub const InitialSnapshotRead = struct {
        bytes: []u8,
        allocator: std.mem.Allocator,
    };

    pub fn prepareInitialSnapshotPermit(
        self: *ClientSlot,
        owner_addr: usize,
        transport_incarnation: u64,
        binding: contract.BindingIdentity,
    ) error{ InvalidSnapshotPermit, AdminBusy, IdentityExhausted }!InitialSnapshotPermit {
        return self.prepareStreamOperationPermit(
            .initial_snapshot,
            owner_addr,
            transport_incarnation,
            binding,
        ) catch |err| switch (err) {
            error.InvalidStreamOperationPermit => error.InvalidSnapshotPermit,
            error.AdminBusy => error.AdminBusy,
            error.IdentityExhausted => error.IdentityExhausted,
        };
    }

    pub fn prepareStreamOperationPermit(
        self: *ClientSlot,
        kind: StreamOperationKind,
        owner_addr: usize,
        transport_incarnation: u64,
        binding: contract.BindingIdentity,
    ) error{ InvalidStreamOperationPermit, AdminBusy, IdentityExhausted }!StreamOperationPermit {
        if (client_mod.generationAllocatorCallbackActive()) return error.AdminBusy;
        const operation = self.beginRegisteredClientOperation() catch |err| return switch (err) {
            error.AdminBusy => error.AdminBusy,
            error.MovedOrCopied => error.InvalidStreamOperationPermit,
        };
        defer self.endRegisteredClientOperation(operation);
        if (!self.valid() or
            !operationThreadMatches(self.operation_owner_thread_incarnation) or
            kind == .none or owner_addr == 0 or transport_incarnation == 0 or
            binding.slot_incarnation != self.incarnation.tagged or
            binding.node_incarnation != self.current.incarnation.tagged or
            binding.host_id != self.current.client.host_id or
            binding.connection_generation != self.current.connection_generation or binding.pid != self.pid or
            binding.process_nonce != self.process_nonce)
            return error.InvalidStreamOperationPermit;
        if (batch_release_callback_active or self.current.active_operation_generation != 0 or
            self.current.pin_owner.active_cleanup != 0)
            return error.AdminBusy;
        const generation = self.current.next_operation_generation;
        const next_generation = std.math.add(u64, generation, 1) catch
            return error.IdentityExhausted;
        const owner_thread_incarnation = self.operation_owner_thread_incarnation;
        const permit = try registerStreamOperationPermit(.{
            .slot = self,
            .registry_index = 0,
            .registry_id = 0,
            .slot_incarnation = self.incarnation.tagged,
            .node_incarnation = self.current.incarnation.tagged,
            .generation = generation,
            .kind = kind,
            .owner_thread_incarnation = owner_thread_incarnation,
            .owner_addr = owner_addr,
            .transport_incarnation = transport_incarnation,
            .binding = binding,
        });
        self.current.next_operation_generation = next_generation;
        self.current.active_operation_generation = generation;
        self.current.active_operation_kind = kind;
        self.current.active_operation_owner_thread_incarnation = owner_thread_incarnation;
        self.current.active_operation_owner_addr = owner_addr;
        self.current.active_operation_transport_incarnation = transport_incarnation;
        self.current.active_operation_binding = binding;
        return permit;
    }

    pub fn initialSnapshotPermitLive(
        self: *const ClientSlot,
        permit: InitialSnapshotPermit,
    ) bool {
        return streamOperationPermitRawTagsValid(&permit) and
            permit.kind == .initial_snapshot and self.streamOperationPermitLive(permit);
    }

    pub fn streamOperationPermitLive(
        self: *const ClientSlot,
        permit: StreamOperationPermit,
    ) bool {
        if (!streamOperationPermitRawTagsValid(&permit)) return false;
        if (!operationThreadMatches(permit.owner_thread_incarnation)) return false;
        if (!streamOperationPermitRegistryLive(permit)) return false;
        return self.valid() and permit.slot == self and
            permit.slot_incarnation == self.incarnation.tagged and
            permit.node_incarnation == self.current.incarnation.tagged and
            permit.generation != 0 and
            permit.generation == self.current.active_operation_generation and
            permit.kind != .none and permit.kind == self.current.active_operation_kind and
            permit.owner_thread_incarnation == self.operation_owner_thread_incarnation and
            permit.owner_thread_incarnation == self.current.active_operation_owner_thread_incarnation and
            permit.owner_addr == self.current.active_operation_owner_addr and
            permit.transport_incarnation == self.current.active_operation_transport_incarnation and
            std.meta.eql(permit.binding, self.current.active_operation_binding);
    }

    pub fn abortInitialSnapshotPermit(
        self: *ClientSlot,
        permit: InitialSnapshotPermit,
    ) error{InvalidSnapshotPermit}!void {
        if (!self.initialSnapshotPermitLive(permit)) return error.InvalidSnapshotPermit;
        self.abortStreamOperationPermit(permit) catch return error.InvalidSnapshotPermit;
    }

    pub fn consumeInitialSnapshotPermit(
        self: *ClientSlot,
        permit: InitialSnapshotPermit,
    ) error{InvalidSnapshotPermit}!void {
        if (!self.initialSnapshotPermitLive(permit)) return error.InvalidSnapshotPermit;
        self.consumeStreamOperationPermit(permit) catch return error.InvalidSnapshotPermit;
    }

    pub fn initialSnapshotPermitIdle(self: *const ClientSlot) bool {
        return self.streamOperationPermitIdle();
    }

    pub fn abortStreamOperationPermit(
        self: *ClientSlot,
        permit: StreamOperationPermit,
    ) error{InvalidStreamOperationPermit}!void {
        if (!self.streamOperationPermitLive(permit)) return error.InvalidStreamOperationPermit;
        if (batch_release_callback_active or self.current.pin_owner.active_cleanup != 0)
            return error.InvalidStreamOperationPermit;
        if (self.generationAllocatorCallbackActive())
            return error.InvalidStreamOperationPermit;
        try unregisterStreamOperationPermit(permit);
        self.clearStreamOperationPermit();
    }

    pub fn consumeStreamOperationPermit(
        self: *ClientSlot,
        permit: StreamOperationPermit,
    ) error{InvalidStreamOperationPermit}!void {
        if (!self.streamOperationPermitLive(permit)) return error.InvalidStreamOperationPermit;
        if (batch_release_callback_active or self.current.pin_owner.active_cleanup != 0)
            return error.InvalidStreamOperationPermit;
        if (self.generationAllocatorCallbackActive())
            return error.InvalidStreamOperationPermit;
        try unregisterStreamOperationPermit(permit);
        self.clearStreamOperationPermit();
    }

    fn consumeStreamOperationPermitNoFail(
        self: *ClientSlot,
        permit: StreamOperationPermit,
    ) void {
        self.consumeStreamOperationPermit(permit) catch
            @panic("validated stream operation permit consume failed");
    }

    fn prepareStreamOperationPermitConsume(
        self: *ClientSlot,
        permit: StreamOperationPermit,
        out: *PreparedStreamOperationPermitConsume,
    ) error{ InvalidStreamOperationPermit, DestinationOccupied }!void {
        if (!streamOperationPermitRawTagsValid(&permit) or self.pid != currentPid() or
            !operationThreadMatches(permit.owner_thread_incarnation))
            return error.InvalidStreamOperationPermit;
        if (!std.meta.eql(out.*, PreparedStreamOperationPermitConsume{}))
            return error.DestinationOccupied;
        const index: usize = permit.registry_index;
        if (index >= stream_operation_registry.len or permit.registry_id == 0 or
            !self.valid() or permit.slot != self or
            permit.slot_incarnation != self.incarnation.tagged or
            permit.node_incarnation != self.current.incarnation.tagged or
            permit.generation == 0 or
            permit.generation != self.current.active_operation_generation or
            permit.kind == .none or permit.kind != self.current.active_operation_kind or
            permit.owner_thread_incarnation != self.operation_owner_thread_incarnation or
            permit.owner_thread_incarnation !=
                self.current.active_operation_owner_thread_incarnation or
            permit.owner_addr != self.current.active_operation_owner_addr or
            permit.transport_incarnation != self.current.active_operation_transport_incarnation or
            !std.meta.eql(permit.binding, self.current.active_operation_binding))
            return error.InvalidStreamOperationPermit;

        while (!stream_operation_registry_mutex.tryLock()) std.atomic.spinLoopHint();
        defer stream_operation_registry_mutex.unlock();
        const entry = &stream_operation_registry[index];
        if (entry.state.load(.acquire) !=
            @intFromEnum(StreamOperationRegistryEntry.State.live) or
            entry.id != permit.registry_id or !std.meta.eql(entry.permit, permit))
            return error.InvalidStreamOperationPermit;
        if (entry.state.cmpxchgStrong(
            @intFromEnum(StreamOperationRegistryEntry.State.live),
            @intFromEnum(StreamOperationRegistryEntry.State.consume_reserved),
            .acq_rel,
            .acquire,
        ) != null) return error.InvalidStreamOperationPermit;
        out.* = .{
            .self_addr = @intFromPtr(out),
            .registry_index = permit.registry_index,
            .registry_id = permit.registry_id,
            .slot_addr = @intFromPtr(self),
            .slot_incarnation = permit.slot_incarnation,
            .node_incarnation = permit.node_incarnation,
            .operation_generation = permit.generation,
            .permit_seal = streamOperationPermitSeal(permit),
            .lifecycle = .prepared,
        };
    }

    fn consumeStreamOperationPermitUnchecked(
        self: *ClientSlot,
        prepared: *PreparedStreamOperationPermitConsume,
    ) bool {
        if (self.pid != currentPid() or
            !operationThreadMatches(self.operation_owner_thread_incarnation))
            return false;
        const index: usize = prepared.registry_index;
        const lifecycle_raw = @as(*const u8, @ptrCast(&prepared.lifecycle)).*;
        if (index >= stream_operation_registry.len or
            lifecycle_raw != @intFromEnum(PreparedStreamOperationPermitConsume.Lifecycle.prepared) or
            prepared.self_addr != @intFromPtr(prepared) or
            prepared.registry_id == 0 or prepared.slot_addr != @intFromPtr(self) or
            prepared.slot_incarnation != self.incarnation.tagged or
            prepared.node_incarnation != self.current.incarnation.tagged or
            prepared.operation_generation == 0 or
            prepared.operation_generation != self.current.active_operation_generation)
            return false;
        const entry = &stream_operation_registry[index];
        if (entry.state.load(.acquire) !=
            @intFromEnum(StreamOperationRegistryEntry.State.consume_reserved) or
            entry.id != prepared.registry_id or
            !streamOperationPermitRawTagsValid(&entry.permit) or
            !std.mem.eql(
                u8,
                &prepared.permit_seal,
                &streamOperationPermitSeal(entry.permit),
            ) or
            entry.permit.slot != self or
            entry.permit.slot_incarnation != prepared.slot_incarnation or
            entry.permit.node_incarnation != prepared.node_incarnation or
            entry.permit.generation != prepared.operation_generation or
            entry.permit.kind != self.current.active_operation_kind or
            entry.permit.owner_thread_incarnation !=
                self.current.active_operation_owner_thread_incarnation or
            entry.permit.owner_addr != self.current.active_operation_owner_addr or
            entry.permit.transport_incarnation !=
                self.current.active_operation_transport_incarnation or
            !std.meta.eql(entry.permit.binding, self.current.active_operation_binding))
            return false;
        if (entry.state.cmpxchgStrong(
            @intFromEnum(StreamOperationRegistryEntry.State.consume_reserved),
            @intFromEnum(StreamOperationRegistryEntry.State.consumed),
            .acq_rel,
            .acquire,
        ) != null) return false;
        self.clearStreamOperationPermit();
        prepared.lifecycle = .consumed;
        return true;
    }

    pub fn streamOperationPermitIdle(self: *const ClientSlot) bool {
        return self.valid() and streamOperationNodeIdle(self.current);
    }

    pub fn prepareEndedPurge(
        self: *ClientSlot,
        transport_incarnation: u64,
        reservation: AttachmentBindingReservation,
        target_stream: u64,
        hint: client_mod.EndedEventHint,
        scratch: *client_mod.EndedPurgeScratch,
        out: *EndedPurgePreparation,
    ) EndedPurgePreparationError!void {
        // A fork child must reject from caller-owned slot storage before touching a process-global
        // mutex that may have been inherited locked by a vanished sibling thread.
        if (self.pid != currentPid()) return error.InvalidOwner;
        const registry_entry = clientSlotRegistryEntry(@intFromPtr(self)) orelse
            return error.InvalidOwner;
        if (!operationThreadMatches(registry_entry.owner_thread_incarnation))
            return error.InvalidOwner;
        if (!self.valid() or registry_entry.node_addr != @intFromPtr(self.current) or
            registry_entry.slot_incarnation != self.incarnation.tagged or
            registry_entry.node_incarnation != self.current.incarnation.tagged or
            registry_entry.owner_thread_incarnation != self.operation_owner_thread_incarnation)
            return error.InvalidOwner;
        if (endedPurgeOwnersAlias(registry_entry, reservation, scratch, out))
            return error.InvalidOwner;
        if (endedPurgeAliasesClientOwnedBacking(&self.current.client, scratch, out))
            return error.InvalidOwner;
        if (out.lifecycle != .empty or out.self_addr != 0 or out.target_stream != 0 or
            !std.mem.allEqual(u8, &out.authority_seal, 0) or
            !std.meta.eql(out.inventory, client_mod.PreparedEndedPurgeInventory{}))
            return error.DestinationOccupied;
        self.current.cleanup_registry.preflightBoundDrop(
            reservation.cleanup,
            reservation.identity,
            target_stream,
        ) catch return error.InvalidOwner;
        const idle_before = self.current.batch_registry.streamIdle(target_stream) catch {
            return poisonEndedPurgeCorrupt(self);
        };
        if (!idle_before) return error.Busy;
        const permit = self.prepareStreamOperationPermit(
            .ended_purge,
            @intFromPtr(out),
            transport_incarnation,
            reservation.identity,
        ) catch |err| return switch (err) {
            error.InvalidStreamOperationPermit => error.InvalidOwner,
            error.AdminBusy => error.Busy,
            error.IdentityExhausted => error.IdentityExhausted,
        };
        errdefer self.abortStreamOperationPermit(permit) catch
            @panic("ended purge preparation permit rollback failed");
        const idle = self.current.batch_registry.streamIdle(target_stream) catch {
            return poisonEndedPurgeCorrupt(self);
        };
        if (!idle) return error.Busy;
        self.current.client.prepareEndedPurgeInventory(
            target_stream,
            hint,
            scratch,
            &out.inventory,
        ) catch |err| switch (err) {
            error.DestinationOccupied => return error.DestinationOccupied,
            error.InvalidHint,
            error.InvalidSource,
            error.InvalidAlias,
            error.ArithmeticOverflow,
            => return poisonEndedPurgeCorrupt(self),
        };
        out.self_addr = @intFromPtr(out);
        out.target_stream = target_stream;
        out.permit = permit;
        out.lifecycle = .prepared;
        out.authority_seal = endedPurgePreparationSeal(out);
    }

    pub fn commitEndedPurge(
        self: *ClientSlot,
        scratch: *client_mod.EndedPurgeScratch,
        preparation: *EndedPurgePreparation,
    ) EndedPurgeCommitError!EndedPurgeResult {
        // Fork children must reject before touching either inherited process-global registry.
        const pid = currentPid();
        if (pid == 0 or self.pid != pid or process_runtime_pid.load(.acquire) != pid)
            return error.InvalidOwner;
        const registry_entry = clientSlotRegistryEntry(@intFromPtr(self)) orelse
            return error.InvalidOwner;
        if (!operationThreadMatches(registry_entry.owner_thread_incarnation) or
            !self.valid() or registry_entry.node_addr != @intFromPtr(self.current) or
            registry_entry.slot_incarnation != self.incarnation.tagged or
            registry_entry.node_incarnation != self.current.incarnation.tagged or
            !preparation.rawTagsValid() or preparation.lifecycle != .prepared or
            preparation.self_addr != @intFromPtr(preparation) or
            preparation.target_stream == 0 or
            preparation.permit.owner_addr != @intFromPtr(preparation) or
            preparation.inventory.scratch_addr != @intFromPtr(scratch) or
            !std.mem.eql(
                u8,
                &preparation.authority_seal,
                &endedPurgePreparationSeal(preparation),
            ) or
            !self.streamOperationPermitLive(preparation.permit))
            return error.InvalidOwner;

        self.current.client.tryAcquireEndedPurgeExclusive() catch |err| return switch (err) {
            error.AdminBusy => error.Busy,
            error.InvalidOwner => error.InvalidOwner,
            error.InvalidState => error.InvalidState,
        };
        var release_exclusive = true;
        defer if (release_exclusive and
            !self.current.client.releaseEndedPurgeExclusiveClean())
            @panic("ended purge precommit exclusive rollback failed");

        var client_prepared: client_mod.PreparedEndedPurgeCommit = .{};
        self.current.client.prepareEndedPurgeCommit(
            preparation.target_stream,
            preparation.permit.generation,
            scratch,
            &preparation.inventory,
            &client_prepared,
        ) catch |err| return switch (err) {
            error.InvalidOwner => error.InvalidOwner,
            error.InvalidState => error.Busy,
            error.Corrupt => error.Corrupt,
            error.ArithmeticOverflow => error.ArithmeticOverflow,
            error.DestinationOccupied => error.DestinationOccupied,
        };

        const quarantine_registry = &(ended_purge_quarantine_registry orelse
            @panic("ended purge quarantine registry missing after process bootstrap"));
        var quarantine_reservation: ended_purge_quarantine.Reservation = .{};
        quarantine_registry.reserve(
            self.current.incarnation.tagged,
            preparation.permit.generation,
            client_prepared.complete_owned_extent_bytes,
            &quarantine_reservation,
        ) catch |err| {
            scratch.lifecycle = .inventory_prepared;
            client_prepared = .{};
            return switch (err) {
                error.InvalidOwner => error.InvalidOwner,
                error.ArithmeticOverflow => error.ArithmeticOverflow,
                error.InvalidState, error.CapacityExceeded => error.QuarantineUnavailable,
            };
        };

        var permit_consume: PreparedStreamOperationPermitConsume = .{};
        self.prepareStreamOperationPermitConsume(
            preparation.permit,
            &permit_consume,
        ) catch |err| {
            if (!quarantine_registry.release(&quarantine_reservation))
                @panic("ended purge quarantine rollback failed");
            scratch.lifecycle = .inventory_prepared;
            client_prepared = .{};
            return switch (err) {
                error.InvalidStreamOperationPermit => error.InvalidOwner,
                error.DestinationOccupied => error.DestinationOccupied,
            };
        };
        if (!preparation.sealForCommit(self))
            @panic("ended purge transport receipt seal failed after permit consume reservation");

        const outcome = self.current.client.commitEndedPurgePrepared(
            preparation.permit.generation,
            scratch,
            &preparation.inventory,
            &client_prepared,
        );
        switch (outcome) {
            .clean => {
                if (!quarantine_registry.release(&quarantine_reservation))
                    @panic("ended purge clean quarantine release failed");
            },
            .drift_pending_finalize => {
                var commit_receipt: ended_purge_quarantine.CommitReceipt = .{};
                if (!quarantine_registry.commit(&quarantine_reservation, &commit_receipt))
                    @panic("ended purge quarantine commit failed");
                var proof: ended_purge_quarantine.ConsumedCommitProof = .{};
                if (!quarantine_registry.consumeCommitted(&commit_receipt, &proof))
                    @panic("ended purge quarantine proof consume failed");
                self.current.client.finalizeEndedPurgeNoFreePoison(
                    preparation.permit.generation,
                    &client_prepared,
                    proof,
                );
                release_exclusive = false;
            },
        }
        if (!self.consumeStreamOperationPermitUnchecked(&permit_consume))
            @panic("ended purge node permit consume failed");
        preparation.consumeAfterPermit(self);
        return .purged;
    }

    fn clearStreamOperationPermit(self: *ClientSlot) void {
        self.current.active_operation_generation = 0;
        self.current.active_operation_kind = .none;
        self.current.active_operation_owner_thread_incarnation = 0;
        self.current.active_operation_owner_addr = 0;
        self.current.active_operation_transport_incarnation = 0;
        self.current.active_operation_binding = undefined;
    }

    pub fn readInitialSnapshotGuarded(
        self: *ClientSlot,
        stream_id: u64,
        owner_addr: usize,
        owner_size: usize,
        out_addr: usize,
        out_size: usize,
    ) (client_mod.ClientError || batch_registry_mod.Error || error{
        AliasedAllocation,
        InvalidDestination,
    })!InitialSnapshotRead {
        return self.readInitialSnapshotGuardedInternal(
            stream_id,
            owner_addr,
            owner_size,
            out_addr,
            out_size,
            null,
        ) catch |err| switch (err) {
            error.DeadlineExceeded => unreachable,
            else => |typed| typed,
        };
    }

    pub fn readInitialSnapshotGuardedUntil(
        self: *ClientSlot,
        stream_id: u64,
        owner_addr: usize,
        owner_size: usize,
        out_addr: usize,
        out_size: usize,
        deadline: client_deadline.AbsoluteDeadline,
    ) (client_mod.DeadlineClientError || batch_registry_mod.Error || error{
        AliasedAllocation,
        InvalidDestination,
    })!InitialSnapshotRead {
        return self.readInitialSnapshotGuardedInternal(
            stream_id,
            owner_addr,
            owner_size,
            out_addr,
            out_size,
            deadline,
        );
    }

    fn readInitialSnapshotGuardedInternal(
        self: *ClientSlot,
        stream_id: u64,
        owner_addr: usize,
        owner_size: usize,
        out_addr: usize,
        out_size: usize,
        deadline: ?client_deadline.AbsoluteDeadline,
    ) (client_mod.DeadlineClientError || batch_registry_mod.Error || error{
        AliasedAllocation,
        InvalidDestination,
    })!InitialSnapshotRead {
        if (!self.valid()) return error.MovedOrCopied;
        if (stream_id == 0 or owner_addr == 0 or owner_size == 0 or out_addr == 0 or out_size == 0)
            return error.InvalidDestination;
        const owner_end = std.math.add(usize, owner_addr, owner_size) catch
            return error.InvalidDestination;
        const out_end = std.math.add(usize, out_addr, out_size) catch
            return error.InvalidDestination;
        var allocator_scope: client_mod.Client.GenerationAllocatorScope = .{};
        const guard = &self.current.guarded_allocator;
        if (guard.snapshot_guard_active) return error.AdminBusy;
        const scope_ranges = [_]GenerationGuardedAllocator.OperationRangeInput{
            .{
                .start = @intFromPtr(&allocator_scope),
                .len = @sizeOf(client_mod.Client.GenerationAllocatorScope),
            },
        };
        if (!guard.beginOperationGuard(&scope_ranges)) return error.AdminBusy;
        defer guard.endOperationGuard();
        guard.snapshot_owner_start = owner_addr;
        guard.snapshot_owner_end = owner_end;
        guard.snapshot_out_start = out_addr;
        guard.snapshot_out_end = out_end;
        guard.snapshot_alias_rejected = false;
        guard.snapshot_guard_active = true;
        defer {
            guard.snapshot_guard_active = false;
            guard.snapshot_owner_start = 0;
            guard.snapshot_owner_end = 0;
            guard.snapshot_out_start = 0;
            guard.snapshot_out_end = 0;
        }
        const allocator = guard.allocator();
        try self.current.client.beginGenerationAllocatorScope(
            allocator,
            .initial_snapshot,
            &allocator_scope,
        );
        defer self.current.client.restoreGenerationAllocatorScope(&allocator_scope) catch
            @panic("generation allocator scope restore drifted");
        const bytes = (if (deadline) |absolute|
            self.current.client.readSnapshotUntil(stream_id, absolute)
        else
            self.current.client.readSnapshot(stream_id)) catch |err| {
            if (guard.snapshot_alias_rejected or guard.operation_alias_rejected) {
                self.current.client.poison(.local_invariant_violation);
                return error.AliasedAllocation;
            }
            return err;
        };
        if (guard.snapshot_alias_rejected or guard.operation_alias_rejected) {
            self.current.client.poison(.local_invariant_violation);
            return error.AliasedAllocation;
        }
        return .{ .bytes = bytes, .allocator = allocator };
    }

    /// Registry entry를 먼저 ingress로 고정한 뒤 Client queue/parser owner를 옮긴다.
    pub fn readAttachmentBatch(
        self: *ClientSlot,
        stream_id: u64,
    ) BatchError!AttachmentBatchRead {
        return self.readAttachmentBatchInternal(stream_id);
    }

    pub fn readAttachmentCatchupBarrierPlanUntil(
        self: *ClientSlot,
        stream_id: u64,
        expected: catchup_barrier_contract.CatchupIdentity,
        deadline: client_deadline.AbsoluteDeadline,
    ) client_mod.DeadlineClientError!client_mod.Client.CatchupBarrierPlan {
        if (!self.valid()) return error.ProtocolError;
        if (self.current.active_operation_generation != 0 or
            terminal_drain_callback_binding.continuation_addr != 0)
            return error.AdminBusy;
        return self.current.client.readCatchupBarrierPlanUntil(stream_id, expected, deadline);
    }

    pub fn requestAttachmentCatchupUntil(
        self: *ClientSlot,
        stream_id: u64,
        runtime_id: u128,
        request_nonce: u128,
        deadline: client_deadline.AbsoluteDeadline,
    ) client_mod.DeadlineClientError!catchup_barrier_contract.CatchupIdentity {
        if (!self.valid() or stream_id == 0 or runtime_id == 0 or request_nonce == 0)
            return error.ProtocolError;
        if (self.current.active_operation_generation != 0 or
            terminal_drain_callback_binding.continuation_addr != 0)
            return error.AdminBusy;
        var nonce_buf: [32]u8 = undefined;
        const nonce_text = std.fmt.bufPrint(&nonce_buf, "{x:0>32}", .{request_nonce}) catch
            return error.OutOfMemory;
        var params_buf: [112]u8 = undefined;
        const params = std.fmt.bufPrint(
            &params_buf,
            "{{\"stream_id\":{d},\"request_nonce\":\"{s}\"}}",
            .{ stream_id, nonce_text },
        ) catch return error.OutOfMemory;
        const response = self.current.client.callUntil("runtime.catchup", params, deadline) catch |err| {
            if (err == error.OutOfMemory)
                self.current.client.poison(.local_resource_exhausted);
            return err;
        };
        defer self.current.client.allocator.free(response);
        var parsed = std.json.parseFromSlice(
            std.json.Value,
            self.current.client.allocator,
            response,
            .{},
        ) catch |err| {
            self.current.client.poison(if (err == error.OutOfMemory)
                .local_resource_exhausted
            else
                .peer_contract_violation);
            return if (err == error.OutOfMemory) error.OutOfMemory else error.ProtocolError;
        };
        defer parsed.deinit();
        var semantic_valid = false;
        defer if (!semantic_valid) self.current.client.poison(.peer_contract_violation);
        const root = switch (parsed.value) {
            .object => |object| object,
            else => return error.ProtocolError,
        };
        if (root.count() != 1) return error.ProtocolError;
        const result_value = root.get("result") orelse return error.ProtocolError;
        const result = switch (result_value) {
            .object => |object| object,
            else => return error.ProtocolError,
        };
        if (result.count() != 8) return error.ProtocolError;
        const catchup = result.get("catchup") orelse return error.ProtocolError;
        const status = switch (catchup) {
            .string => |text| text,
            else => return error.ProtocolError,
        };
        if (!std.mem.eql(u8, status, "armed") and !std.mem.eql(u8, status, "idempotent"))
            return error.ProtocolError;
        const response_stream = switch (result.get("stream_id") orelse return error.ProtocolError) {
            .integer => |value| std.math.cast(u64, value) orelse return error.ProtocolError,
            else => return error.ProtocolError,
        };
        const parseHex = struct {
            fn value(comptime T: type, field: std.json.Value) ?T {
                const text = switch (field) {
                    .string => |value_text| value_text,
                    else => return null,
                };
                return std.fmt.parseInt(T, text, 16) catch null;
            }
        }.value;
        const response_nonce = parseHex(u128, result.get("request_nonce") orelse return error.ProtocolError) orelse
            return error.ProtocolError;
        const response_host = parseHex(u128, result.get("host_id") orelse return error.ProtocolError) orelse
            return error.ProtocolError;
        const response_runtime = parseHex(u128, result.get("runtime_id") orelse return error.ProtocolError) orelse
            return error.ProtocolError;
        const subscription = parseHex(u64, result.get("subscription_id") orelse return error.ProtocolError) orelse
            return error.ProtocolError;
        const connection_id = parseHex(u64, result.get("connection_id") orelse return error.ProtocolError) orelse
            return error.ProtocolError;
        const connection_generation = parseHex(u64, result.get("connection_generation") orelse return error.ProtocolError) orelse
            return error.ProtocolError;
        const identity: catchup_barrier_contract.CatchupIdentity = .{
            .subscription = .{ .value = subscription },
            .runtime_id = response_runtime,
            .connection = .{
                .monotonic_id = connection_id,
                .slot_generation = connection_generation,
            },
            .host_id = response_host,
            .request_nonce = response_nonce,
        };
        if (response_stream != stream_id or response_nonce != request_nonce or
            response_host != self.current.client.host_id or response_runtime != runtime_id or
            !identity.valid())
            return error.ProtocolError;
        semantic_valid = true;
        return identity;
    }

    pub fn beginReadPumpPoisonCapture(
        self: *ClientSlot,
        capture: *incident_publication_contract.ReadPumpPoisonCapture,
    ) bool {
        return self.valid() and
            self.current.active_operation_generation == 0 and
            capture.slot_addr == @intFromPtr(self) and
            capture.client_addr == @intFromPtr(&self.current.client) and
            self.current.client.beginReadPumpPoisonCapture(capture);
    }

    pub fn endReadPumpPoisonCapture(
        self: *ClientSlot,
        capture: *incident_publication_contract.ReadPumpPoisonCapture,
    ) void {
        if (!self.valid() or capture.slot_addr != @intFromPtr(self) or
            capture.client_addr != @intFromPtr(&self.current.client))
            @panic("read pump poison slot authority drifted");
        self.current.client.endReadPumpPoisonCapture(capture);
    }

    fn readAttachmentBatchInternal(
        self: *ClientSlot,
        stream_id: u64,
    ) BatchError!AttachmentBatchRead {
        if (!self.valid()) return error.MovedOrCopied;
        if (self.current.active_operation_generation != 0) return error.AdminBusy;
        if (terminal_drain_callback_binding.continuation_addr != 0) return error.AdminBusy;
        // buffered payload의 free callback에서는 allocation 없는 exact pending sibling만 허용한다.
        // miss를 parser/socket으로 내리면 parent allocator callback 안에서 wire와 allocator를 재진입한다.
        if (batch_release_callback_active)
            try self.current.client.requireBufferedGenerationBatch(stream_id);
        // allocator callback 재진입은 registry generation을 예약하기 전에 막는다. 이 순서가 뒤집히면
        // 최종 entry를 abort해도 재진입만으로 checked-monotonic generation이 소모된다.
        var allocator_scope: client_mod.Client.GenerationAllocatorScope = .{};
        const guard = &self.current.guarded_allocator;
        const scope_ranges = [_]GenerationGuardedAllocator.OperationRangeInput{
            .{
                .start = @intFromPtr(&allocator_scope),
                .len = @sizeOf(client_mod.Client.GenerationAllocatorScope),
            },
        };
        if (!guard.beginOperationGuard(&scope_ranges)) return error.AdminBusy;
        defer guard.endOperationGuard();
        try self.current.client.beginGenerationAllocatorScope(
            guard.allocator(),
            .attachment_batch,
            &allocator_scope,
        );
        defer self.current.client.restoreGenerationAllocatorScope(&allocator_scope) catch
            @panic("generation allocator scope restore drifted");
        const reservation = try self.current.batch_registry.reserve(stream_id);
        var reservation_live = true;
        defer if (reservation_live)
            self.current.batch_registry.abort(reservation) catch
                @panic("generation batch reservation rollback drifted");
        try self.current.batch_registry.prepareIngress(reservation);
        var owned: batch_registry_mod.OwnedBatch = .{};
        switch (self.current.client.readGenerationBatch(
            &owned,
            stream_id,
            reservation.entry_generation,
        ) catch |err| {
            if (guard.operation_alias_rejected) {
                self.current.client.poison(.local_invariant_violation);
                return error.ProtocolError;
            }
            return err;
        }) {
            .idle => return .idle,
            .terminal => return .terminal,
            .committed => {
                // allocator가 payload를 slot/node/stack owner와 alias하면 어느 descriptor도 안전한
                // free 권위를 증명할 수 없다. strict GUI adapter는 registry publication 전에 fail-stop한다.
                if (generationBatchOwnerAliases(self, &owned))
                    @panic("generation batch payload aliases canonical owner");
                const token = self.current.batch_registry.commitIngressUnchecked(
                    reservation,
                    &owned,
                );
                reservation_live = false;
                return .{ .committed = token };
            },
        }
    }

    pub fn borrowAttachmentBatch(
        self: *ClientSlot,
        token: batch_registry_mod.Token,
    ) batch_registry_mod.Error!batch_registry_mod.BatchView {
        if (!self.valid()) return error.MovedOrCopied;
        return self.current.batch_registry.borrow(token);
    }

    /// Accounting consume까지 callback 전에 검증한 뒤 free→consume→entry settle을 무실패로 끝낸다.
    pub fn releaseAttachmentBatch(
        self: *ClientSlot,
        token: batch_registry_mod.Token,
    ) BatchError!void {
        const result = try self.releaseAttachmentBatchResult(token);
        if (result != .completed) return error.AdminBusy;
    }

    pub fn releaseAttachmentBatchResult(
        self: *ClientSlot,
        token: batch_registry_mod.Token,
    ) BatchError!batch_registry_mod.GenerationReleaseResult {
        // terminal drain callback은 같은 Client의 모든 batch release를 mutation 없이 닫는다.
        // teardown이 registry owner를 내린 뒤 operation을 잡으면 Busy 대신 copied-owner 오류가 샌다.
        if (terminal_drain_callback_binding.continuation_addr != 0) return error.AdminBusy;
        const operation = try self.beginRegisteredClientOperation();
        defer self.endRegisteredClientOperation(operation);
        if (!self.valid()) return error.MovedOrCopied;
        if (self.current.active_operation_generation != 0) return error.AdminBusy;
        if (batch_release_callback_active) return error.AdminBusy;
        if (self.generationAllocatorCallbackActive()) return error.AdminBusy;
        var prepared: batch_registry_mod.PreparedRelease = .{};
        try self.current.batch_registry.prepareRelease(token, &prepared);
        const decision = self.current.batch_registry.releaseDecision(&prepared);
        if (decision != .completed) {
            self.current.batch_registry.abortPreparedReleaseUnchecked(&prepared);
            return decision;
        }
        var cleanup: batch_registry_mod.OwnedBatch = .{};
        const accounting = try self.current.client.prepareGenerationAccountingConsume(prepared.accounting);
        self.current.batch_registry.beginPreparedReleaseUnchecked(&prepared, &cleanup);
        {
            batch_release_callback_active = true;
            defer batch_release_callback_active = false;
            cleanup.allocator.?.free(cleanup.bytes);
        }
        self.current.client.consumeGenerationAccountingUnchecked(accounting);
        cleanup.bytes = &.{};
        cleanup.allocator = null;
        cleanup.accounting = .{ .client_addr = 0, .transfer_id = 0, .byte_count = 0 };
        cleanup.completeCleanupUnchecked();
        self.current.batch_registry.finishPreparedReleaseUnchecked(&prepared, &cleanup);
        return .completed;
    }

    pub fn terminalAttachmentBatchKind(
        self: *ClientSlot,
        token: batch_registry_mod.Token,
    ) batch_registry_mod.Error!@import("terminal_cleanup_handoff_contract.zig").TerminalRowKind {
        if (!self.valid()) return error.MovedOrCopied;
        return self.current.batch_registry.terminalTokenKind(token);
    }

    pub fn preflightTerminalAttachmentBatch(
        self: *ClientSlot,
        token: batch_registry_mod.Token,
    ) batch_registry_mod.Error!batch_registry_mod.TerminalTokenSummary {
        if (!self.valid()) return error.MovedOrCopied;
        const kind = try self.current.batch_registry.terminalTokenKind(token);
        return self.current.batch_registry.preflightTerminalToken(token, kind);
    }

    pub fn prepareTerminalCleanupSummary(
        self: *ClientSlot,
        token_count: u32,
        digest: @import("terminal_cleanup_handoff_contract.zig").Digest,
        surviving: u32,
        quarantined: u32,
        accounting_bytes: u64,
        out: *batch_registry_mod.TerminalCleanupHandoff,
    ) batch_registry_mod.Error!void {
        if (!self.valid()) return error.MovedOrCopied;
        return self.current.batch_registry.prepareTerminalCleanupSummary(
            token_count,
            digest,
            surviving,
            quarantined,
            accounting_bytes,
            out,
        );
    }

    pub fn beginTerminalCleanupPublicationNoFail(
        self: *ClientSlot,
        prepared: *batch_registry_mod.TerminalCleanupHandoff,
        stream_id: u64,
    ) void {
        if (!self.valid() or stream_id == 0)
            @panic("terminal cleanup ClientSlot proof was lost");
        self.current.batch_registry.beginTerminalCleanupPublicationNoFail(prepared, .{
            .pid = self.pid,
            .process_nonce = self.process_nonce,
            .thread_id = @intCast(std.Thread.getCurrentId()),
            .node_addr = @intFromPtr(self.current),
            .node_incarnation = self.current.incarnation.tagged,
            .connection_generation = self.incarnation.tagged,
            .stream_id = stream_id,
        });
    }

    pub fn publishTerminalAttachmentBatchNoFail(
        self: *ClientSlot,
        token: batch_registry_mod.Token,
        kind: @import("terminal_cleanup_handoff_contract.zig").TerminalRowKind,
    ) void {
        if (!self.valid()) @panic("terminal cleanup ClientSlot proof was lost");
        self.current.batch_registry.publishTerminalTokenNoFail(token, kind);
    }

    pub fn tryDeinit(self: *ClientSlot) DeinitOutcome {
        if (self.lifecycle == .dead) return .already_dead;
        if (self.lifecycle == .deinit_reserved) return .busy;
        if (self.reserved_replacement_addr != 0) return .busy;
        // Teardown shares the canonical operation thread with admission. This closes the gap
        // between a registry liveness snapshot and the first node dereference without adding a
        // second cross-thread lifetime protocol. PID is checked before the process-global mutex so
        // a fork child cannot spin on a lock inherited from a vanished sibling thread.
        if (self.pid != currentPid() or
            !operationThreadMatches(self.operation_owner_thread_incarnation)) return .corrupt;
        const reserved_registry_entry = self.beginRegisteredExclusiveTeardown() catch |err|
            return switch (err) {
                error.AdminBusy => .busy,
                error.MovedOrCopied => .corrupt,
            };
        var exclusive_reserved = true;
        defer if (exclusive_reserved)
            self.abortRegisteredExclusiveTeardown(reserved_registry_entry);
        const node = reserved_registry_entry.node;
        if (!self.valid()) return if (self.lifecycle == .deinit_reserved) .busy else .corrupt;
        if (self.retired[0] != null) return .busy;
        if (batch_release_callback_active) return .busy;
        if (self.generationAllocatorCallbackActive()) return .busy;
        if (node.active_operation_generation != 0) return .busy;
        if (node.batch_registry.terminalHandoffPublished()) return .terminal_handoff;
        if (!node.rpc_free_evidence.emptyExact()) return .busy;
        if (node.pin_owner.cleanup_pin_count != 0 or
            node.pin_owner.active_cleanup != 0)
            return .busy;
        // 두 registry 중 하나를 먼저 dead로 만든 뒤 다른 쪽 busy/corrupt를 발견하면 재시도할 수 없다.
        // 둘의 전체 entry를 먼저 검증한 뒤에만 mutation suffix에 들어간다.
        const cleanup_ready = node.cleanup_registry.preflightDeinit();
        const batch_ready = node.batch_registry.preflightDeinit();
        const accounting_ready = node.accounting_ledger.preflightDeinit();
        if (cleanup_ready == .busy or batch_ready == .busy or accounting_ready == .busy)
            return .busy;
        if (cleanup_ready != .cleaned or batch_ready != .cleaned or accounting_ready != .cleaned)
            return .corrupt;
        // Client teardown owns the cross-thread operation fence. It must succeed before any slot
        // registry becomes terminal; otherwise a concurrent shared Client operation would make
        // tryDeinit return false and freeing the node would turn that retry signal into a UAF.
        if (!node.client.tryDeinitClientSlotExclusiveHeld()) return .busy;
        exclusive_reserved = false;
        switch (node.cleanup_registry.tryDeinit()) {
            .cleaned => {},
            .busy, .corrupt, .already_dead => @panic("fenced ClientSlot cleanup registry teardown drifted"),
        }
        switch (node.batch_registry.tryDeinit()) {
            .cleaned => {},
            .busy, .corrupt, .already_dead => @panic("fenced ClientSlot batch registry teardown drifted"),
        }
        self.lifecycle = .deinit_reserved;
        if (!unregisterClientSlot(reserved_registry_entry.registry_entry))
            @panic("preflighted ClientSlot registry teardown drifted");
        node.pin_owner.state = .terminal;
        switch (node.accounting_ledger.tryDeinit()) {
            .cleaned => {},
            .busy, .corrupt, .already_dead => @panic("preflighted generation accounting teardown drifted"),
        }
        self.node_allocator.destroy(node);
        self.lifecycle = .dead;
        return .cleaned;
    }

    /// 게시된 terminal handoff만 배타적 teardown fence 아래에서 drain한다. 모든 row와
    /// accounting receipt를 먼저 검증하므로 첫 allocator callback 뒤에는 실패 가능한 분기가 없다.
    pub fn tryDeinitWithTerminalCleanup(self: *ClientSlot) DeinitOutcome {
        if (self.lifecycle == .dead) return .already_dead;
        if (self.pid != currentPid() or
            !operationThreadMatches(self.operation_owner_thread_incarnation)) return .corrupt;
        const reserved = self.beginRegisteredExclusiveTeardown() catch |err| return switch (err) {
            error.AdminBusy => .busy,
            error.MovedOrCopied => .corrupt,
        };
        var reserved_live = true;
        defer if (reserved_live) self.abortRegisteredExclusiveTeardown(reserved);
        const node = reserved.node;
        if (!self.valid() or reserved.node != self.current) return .corrupt;
        if (!node.batch_registry.terminalHandoffPublished()) return .corrupt;
        if (batch_release_callback_active or self.generationAllocatorCallbackActive()) return .busy;
        if (node.active_operation_generation != 0 or node.pin_owner.cleanup_pin_count != 0 or
            node.pin_owner.active_cleanup != 0 or !node.rpc_free_evidence.emptyExact()) return .busy;

        var descriptors: [batch_registry_mod.max_entries]batch_registry_mod.TerminalDrainDescriptor = undefined;
        var accounting_permits: [batch_registry_mod.max_entries]client_mod.Client.PreparedGenerationAccountingConsume = undefined;
        var row_count: u32 = 0;
        var accounting_bytes: u64 = 0;
        for (0..batch_registry_mod.max_entries) |slot| {
            const descriptor = node.batch_registry.terminalDrainDescriptor(slot) catch return .corrupt;
            if (descriptor) |item| {
                if (!node.accounting_ledger.canConsume(item.accounting)) return .corrupt;
                descriptors[row_count] = item;
                row_count += 1;
                accounting_bytes = std.math.add(u64, accounting_bytes, @intCast(item.accounting.byte_count)) catch
                    return .corrupt;
            }
        }
        const handoff = &node.batch_registry.terminal_handoff;
        if (row_count != handoff.token_count or row_count != handoff.accounting_count or
            accounting_bytes != handoff.accounting_bytes) return .corrupt;

        // 첫 pass가 모든 row와 accounting을 검증했으므로 여기부터는 callback이나 allocation 없이
        // releasing permit만 만든다. 이 suffix에서 실패하면 앞 permit을 되돌릴 수 없으므로 proof loss다.
        for (descriptors[0..row_count], 0..) |descriptor, index| {
            accounting_permits[index] = node.client.prepareGenerationAccountingConsume(
                descriptor.accounting,
            ) catch terminalDrainProofLoss("terminal drain accounting preparation drifted");
        }

        node.batch_registry.beginTerminalDrainNoFail();
        const ready = process_seal_service.currentReadyIdentity() catch
            terminalDrainProofLoss("terminal drain process identity drifted");
        var continuation: TerminalDrainContinuation = undefined;
        for (descriptors[0..row_count], accounting_permits[0..row_count], 0..) |descriptor, accounting, index| {
            continuation = .{
                .identity = .{
                    .self_addr = @intFromPtr(&continuation),
                    .pid = ready.pid,
                    .process_nonce = ready.process_nonce,
                    .thread_id = @intCast(std.Thread.getCurrentId()),
                    .node_addr = @intFromPtr(node),
                    .node_incarnation = node.incarnation.tagged,
                    .registry_incarnation = node.batch_registry.incarnation,
                    .handoff_identity_seal = node.batch_registry.terminal_handoff.state.identity_seal,
                    .handoff_state_seal = node.batch_registry.terminal_handoff.state.state_seal,
                    .handoff_state_generation = node.batch_registry.terminal_handoff.state.state_generation,
                    .row_slot = descriptor.row_slot,
                    .row_kind_raw = @intFromEnum(descriptor.kind),
                    .row_generation = descriptor.row_generation,
                    .accounting_client_addr = descriptor.accounting.client_addr,
                    .accounting_transfer_id = descriptor.accounting.transfer_id,
                    .accounting_byte_count = descriptor.accounting.byte_count,
                    .payload_addr = if (descriptor.bytes.len == 0) 0 else @intFromPtr(descriptor.bytes.ptr),
                    .payload_len = descriptor.bytes.len,
                    .allocator_ptr = if (descriptor.allocator) |allocator| @intFromPtr(allocator.ptr) else 0,
                    .allocator_vtable = if (descriptor.allocator) |allocator| @intFromPtr(allocator.vtable) else 0,
                    .callback_ordinal = @intCast(index + 1),
                },
                .state = .{
                    .identity_seal = [_]u8{0} ** 32,
                    .lifecycle_raw = @intFromEnum(terminal_contract.TerminalDrainLifecycle.prepared),
                    .state_generation = 1,
                    .state_seal = [_]u8{0} ** 32,
                },
                .descriptor = descriptor,
                .accounting = accounting,
            };
            continuation.state.identity_seal = process_seal_service.terminalDrainIdentitySeal(
                ready.pid,
                ready.process_nonce,
                terminalDrainIdentitySealInput(&continuation),
            ) catch terminalDrainProofLoss("terminal drain identity seal failed");
            continuation.state.state_seal = process_seal_service.terminalDrainStateSeal(
                ready.pid,
                ready.process_nonce,
                terminalDrainStateSealInput(&continuation),
            ) catch terminalDrainProofLoss("terminal drain state seal failed");
            if (!terminalDrainContinuationCurrent(&continuation, .prepared, 1))
                terminalDrainProofLoss("terminal drain prepared continuation drifted");
            if (continuation.descriptor.kind == .surviving_descriptor) {
                if (builtin.is_test and terminal_drain_test_hook.stage == .pre_callback and
                    terminal_drain_test_hook.target_ordinal == continuation.identity.callback_ordinal)
                {
                    terminal_drain_test_hook = .{};
                    writeEventReleaseDeathMarker(0x47);
                    continuation.state.state_seal[0] ^= 1;
                }
                if (!std.meta.eql(terminal_drain_callback_binding, TerminalDrainCallbackBinding{}))
                    terminalDrainProofLoss("terminal drain callback binding was not pristine");
                advanceTerminalDrainContinuationNoFail(&continuation, .prepared, .callback_active);
                terminal_drain_callback_binding = .{
                    .continuation_addr = @intFromPtr(&continuation),
                    .continuation_seal = continuation.state.state_seal,
                    .node_addr = continuation.identity.node_addr,
                    .row_slot = continuation.identity.row_slot,
                    .callback_ordinal = continuation.identity.callback_ordinal,
                };
                batch_release_callback_active = true;
                continuation.descriptor.allocator.?.free(continuation.descriptor.bytes);
                batch_release_callback_active = false;
                if (builtin.is_test and terminal_drain_test_hook.stage == .post_callback and
                    terminal_drain_test_hook.target_ordinal == continuation.identity.callback_ordinal)
                {
                    terminal_drain_test_hook = .{};
                    writeEventReleaseDeathMarker(0x47);
                    continuation.state.state_seal[0] ^= 1;
                }
                if (!terminalDrainContinuationCurrent(&continuation, .callback_active, 2) or
                    terminal_drain_callback_binding.continuation_addr != @intFromPtr(&continuation) or
                    !std.crypto.timing_safe.eql(terminal_contract.Digest, terminal_drain_callback_binding.continuation_seal, continuation.state.state_seal) or
                    terminal_drain_callback_binding.node_addr != continuation.identity.node_addr or
                    terminal_drain_callback_binding.row_slot != continuation.identity.row_slot or
                    terminal_drain_callback_binding.callback_ordinal != continuation.identity.callback_ordinal)
                    terminalDrainProofLoss("terminal drain callback proof drifted");
                terminal_drain_callback_binding = .{};
                advanceTerminalDrainContinuationNoFail(&continuation, .callback_active, .callback_returned);
            }
            if (!terminalDrainContinuationCurrent(
                &continuation,
                if (continuation.descriptor.kind == .surviving_descriptor) .callback_returned else .prepared,
                if (continuation.descriptor.kind == .surviving_descriptor) 3 else 1,
            )) terminalDrainProofLoss("terminal drain consume proof drifted");
            node.client.consumeGenerationAccountingUnchecked(continuation.accounting);
            node.batch_registry.consumeTerminalDrainNoFail(continuation.identity.row_slot);
            advanceTerminalDrainContinuationNoFail(
                &continuation,
                if (continuation.descriptor.kind == .surviving_descriptor) .callback_returned else .prepared,
                .consumed,
            );
        }
        node.batch_registry.finishTerminalCleanupNoFail();
        reserved_live = false;
        self.abortRegisteredExclusiveTeardown(reserved);
        return self.tryDeinit();
    }

    pub fn deinit(self: *ClientSlot) void {
        if (self.tryDeinit() != .cleaned)
            @panic("session-host ClientSlot teardown invariant violated");
    }
};

test "C3-3b2a product bootstrap publishes pins and closes a sealed capability" {
    try ClientSlot.initializeProcessRuntime();
    try ClientSlot.initializeProcessRuntime();
    const pid = currentPid();
    const nonce = process_issuer.?.process_nonce;
    const thread_incarnation = try operation_thread_identity.acquire();
    var receipt: operation_thread_identity.MintReceipt = .{};
    try operation_thread_identity.issueMintReceipt(
        &receipt,
        1,
        2,
        pid,
        nonce,
        thread_incarnation,
    );
    defer if (receipt.live) std.debug.assert(operation_thread_identity.abortMintReceipt(&receipt));
    const handle = try operation_thread_identity.publishCapability(.{
        .capability_addr = 3,
        .publication_identity = 4,
        .operation_identity = 2,
        .client_addr = 1,
        .fence_generation = 5,
        .fence_incarnation = 6,
        .owner_process_id = pid,
        .owner_process_nonce = nonce,
        .owner_thread_id = @intCast(std.Thread.getCurrentId()),
        .owner_thread_incarnation = thread_incarnation,
    });
    var pin: operation_thread_identity.CapabilityPin = .{};
    try std.testing.expect(operation_thread_identity.pinCapability(handle, &pin));
    try std.testing.expect(operation_thread_identity.closeCapability(&pin));
}

